--            sha256 = bf1a59eb5e35d0485deca8cdae6f810b0d839e4fa285c918a3040a0ba7e94117
--  设计依据：docs/策划案.md（v1，2026-10-31）
--  规则依据：tools_work/perft/engine_proto.lua（perft 深度 3 与 python-chess 标准答案全部一致）
--
--  运行环境：Lua 5.3。不可用：io.* / coroutine.* / string.dump /
--            os.*（仅 os.time/os.date/os.clock/os.difftime）/ debug.*（仅 debug.traceback）
--  单文件模式（用户身份：萌新）。分区顺序与初始化顺序一致：
--    第 1 区  CONFIG      编辑器侧常量（用户需填 3 个值）
--    第 2 区  LOG         日志与故障块
--    第 3 区  RULES       走法规则引擎（已验证）
--    第 4 区  LAYOUT      唯一坐标换算入口
--    第 5 区  FACTORY     控件工厂（固定创建顺序）
--    第 6 区  UI          界面构建
--    第 7 区  GAME        业务状态与流程
--    第 8 区  INPUT       输入（原生命中，不读坐标）
--    第 9 区  NET         联机（能力探测 + 降级）
--    第 10 区 LIFECYCLE   生命周期与清理
--    第 11 区 SELFTEST    自检入口（不参与玩法）
-- =============================================================================

-- =============================================================================
-- 第 1 区：CONFIG
-- =============================================================================
--  【交付版】本文件是交给用户的正式稿：下面 CONFIG 的 4 个模板索引保持 0，
--  由用户在真机编辑器里按自己搭的控件逐个填写（容器节点 / 文本框 / 光标检测区 / 图片）。
--  0 表示「还没配」：脚本会直接报「界面零件还没配好」并停机，不做无意义重试。
local CONFIG = {
  -- ===== 必须由用户在编辑器里填的真实值 =====
  -- 三项为 0 时脚本会立即报「界面零件还没配好」并停止，不做无意义重试。
  CONTAINER_NODE_INDEX = 0,      -- 容器节点索引：脚本挂载点，所有控件以它为父级
  PREFAB_TEXT_BOX      = 0,      -- 文本框模板索引：棋盘格 / 棋子 / 面板 / 按钮 全靠它
  PREFAB_CURSOR_AREA   = 0,      -- 光标检测区域模板索引：64 个棋盘格的点击检测
  PREFAB_IMAGE         = 0,      -- 图片控件模板索引：**必填**。棋子全部用图元绘制，缺此项棋盘上不会有棋子

  -- ===== 棋子（单一档：图元拼）=====
  -- 【为什么不用「上传自己的棋子图」】
  -- 千星奇域的图片控件只支持 StaticReference（官方固定白名单）与 Prefab（元件图标），
  -- 没有任何上传自定义图片的入口（已全量核查 1517 个白名单素材，无国际象棋棋子）。
  -- 所以棋子用「基础图元拼」：矩形/圆/三角 拼出 cburnett(en-croissant) 轮廓。
  -- 只用下面这三个官方预设图元，无需任何素材配置，开箱即用。
  PIECE_ASSET = {
    RECT    = 100001,   -- 实心矩形图元（可染色、可拉伸）
    CIRCLE  = 100002,   -- 实心圆图元（可染色、可拉伸成椭圆）
    TRI     = 100003,   -- 实心三角图元（可染色、可旋转）
  },
  PIECE_IMAGE_SOURCE = "StaticReference",   -- 图片来源枚举名（见 API 文档 §11(17) L556-567 Enum.ImageSource）
  -- 棋盘上同时最多 32 枚棋子（开局 32 枚，升变不增加总数），故棋子槽位池按 32 建
  PIECE_MAX_SLOTS = 32,
  -- 【棋子图元预算】每枚棋子的图元控件数上限（启动时按 PIECE_ART 实际值校正）。
  -- v1.9 起走「en-croissant / cburnett 剪影拟合 + 分层渲染」：
  --   每枚 6~17 个形状；控件数 = 2×外形 + 2×镂空 + 1×细节线 ≈ 12~34 个/枚（v1.11 去投影）
  --   32 枚约 400~1100 个控件（v1.6 那套 400 图元方案是 1280）。
  PIECE_PRIM_BUDGET = 64,
  -- 外形层每个形状向外长的量（描边宽度 = pad × 棋子方框边长）。
  -- 【取值依据，模拟器实测】
  --   0.030 → 描边 ~2.4px，黑方鬃毛/冠尖糊成大片浅斑（离中心远的形状外移过多）
  --   0.012 → ~1px，干净但**白棋在浅木格上几乎看不见**（白填充 250,248,242
  --           与浅格 240,217,181 太接近，1px 的深边不足以把轮廓拉出来）
  --   0.020 → ~1.6px，深边够粗，白棋在浅格上也能一眼看清轮廓。当前值。
  PIECE_OUTLINE_PAD = 0.020,
  -- 【细长形状的描边上限】描边量是相对棋子方框的正方形外扩量（+pad 到宽、+pad 到高）。
  -- 对一根 0.05 宽的鬃毛线，0.020 方框外扩 = 该形状自身宽度的 80%，直接糊成一团色斑。
  -- 所以再按「该形状短边 × 本比例」夹一道上限：短边越窄，允许外扩越小。
  PIECE_PAD_THIN_RATIO = 0.22,
  -- 可选（缺省 0 表示不使用）
  PREFAB_CONTAINER     = 0,      -- 容器节点模板索引（需要分组管理时用；本项目不用）

  -- ===== 沙箱/真机能力差异开关 =====
  -- 【为什么需要这个开关】
  -- `raycastTarget` 是 API 文档 §18(1) L908（光标检测区域）/ §17(1) L886（预设按钮）声明的字段，
  -- 真机上必须设它才能接收光标事件。但体外沙箱**未实现该字段的读写**，读取会被记为
  -- unsupported-api 并导致沙箱判定 fail。
  -- 【另一条前置条件】容器节点还必须 `showCursor = true`（API 文档 §24(1) L1031：
  --   「CursorEvent 相关方法都需设置该参数为真后才可正常使用」）。
  --   该条由 build_all_ui 里的 enable_show_cursor() 负责，与 raycastTarget 无关，两者都要满足。
  -- 因此：正式交付文件保持 true（真机生效）；沙箱验收副本由
  -- tools_work/make_sandbox_copy.mjs 改成 false（跳过该字段，沙箱才能 pass）。
  -- 交付说明里必须如实写明这条差异，不能把「沙箱 pass」说成「真机已通过」。
  --
  -- 【模拟器实测修正，2026-11-01 runtime=simulator】
  -- 早先把该开关置 false 后，界面能正常建出来（794 控件、无报错），但**所有点击全部失效**：
  -- 光标检测区域不设 raycastTarget 就收不到任何光标事件。探针对照实验：
  --   直接实例化并写 raycastTarget=true 的光标区 → 点击回调正常触发；
  --   同一脚本里走 create_cursor_area（被开关跳过）的区域 → 完全无反应。
  -- 结论：raycastTarget 是**命中开关本身**，不是可选项。正确写法是「赋值包 pcall」：
  -- 未实现该字段的环境（体外沙箱）会抛错被 pcall 吞掉、其余逻辑照常；
  -- 实现该字段的环境（模拟器/真机）正常生效。开关保留仅为对照实验用。
  ENABLE_RAYCAST_FIELD = true,

  SCRIPT_SHORT_NAME    = "levelScript",  -- 挂载脚本短名，用于启动身份核对

  -- ===== 联机信号（与用户搭的节点图必须同名同参数顺序）=====
  SIGNAL_NAME = "ChessSync",
  -- eventType 取值
  EV_MOVE     = 0,   -- 走子：a=起点格  b=终点格  c=升变(0/1Q/2R/3B/4N)  fen=""
  EV_NEWGAME  = 1,   -- 新开一局：a=发起方(0/1)
  -- 【v2.0 块 5：EV_RESIGN 复用，用 c 区分两种语义】
  --   c=0 认输（对局中主动认输）      → 对端结算「XX认输，YY胜」
  --   c=1 弃局（返回主菜单放弃对局）  → 对端结算「对手已离开本局」
  -- 为什么不新增 13 号事件：服务端节点图已经按 eventType 分发，加新号要同时改节点图；
  --   而 EV_RESIGN 的 c 参数本来空着，正好承载这个区分。改动面最小。
  EV_RESIGN   = 2,   -- 认输/弃局：a=认输方(0/1)  b=0  c=0认输/1弃局
  EV_DRAW_REQ = 3,   -- 求和：a=请求方(0/1)
  EV_DRAW_ACC = 4,   -- 同意和棋：a=同意方(0/1)
  EV_JOIN     = 5,   -- 请求加入：全 0
  EV_ROLE     = 6,   -- 身份分配（服务端回发）：a=0 白方 / 1 黑方
  EV_DRAW_NO  = 7,   -- 拒绝和棋：a=拒绝方(0/1)

  -- ===== v2.0 块 5 新增事件（8 起，与用户搭的节点图同名同参数顺序）=====
  -- 【参数约定】服务端信号固定 5 槽：ChessSync(eventType, a, b, c, fen)
  EV_READY     = 8,  -- 准备/取消准备：a=0取消/1准备  b=档位号(1~4)  c=0  fen=""
                     --   【b 带档位号就是「先选者生效」的载体】收到时若本地未锁定则采用并锁定。
  EV_START     = 9,  -- 开局：b=档位号  a=0  c=0  fen=""
                     --   【语义】收到即进 playing，跳过本地倒数；已在 playing 则忽略。
  EV_UNDO_REQ  = 10, -- 悔棋请求：a=发起方(0/1)
  EV_UNDO_ACC  = 11, -- 悔棋同意：a=同意方(0/1)
                     --   【关键】这是**唯一**的执行时机 —— 发起方绝不能本地先撤。
  EV_UNDO_NO   = 12, -- 悔棋拒绝：a=拒绝方(0/1)
  -- 【v3.2】结算后的协同选择：双方都选了同一个才执行（用户要求「同时选择才轮换黑白」）
  --   a = 我的选择（1=再来一局 / 2=复盘）  b = 我的身份（0=白 1=黑）
  EV_RESULT    = 13,

  -- ===== 布局（唯一来源，其他位置不得出现这些数字）=====
  -- 与 docs/策划案.md 10.1 逐项一致
  BOARD_SIDE_RATIO  = 0.78,   -- 棋盘边长 = 画布高 * 0.78
  PANEL_WIDTH_RATIO = 0.22,   -- 侧面板宽 = 画布宽 * 0.22
  FRAME_PAD_RATIO   = 0.16,   -- 棋盘暖木外框厚度 = 格宽 * 0.16（棋盘外框/提示条/坐标共用）

  -- ===== 数值 =====
  -- 【v2.0 重要：这两项现在是「档位 3（快棋）的别名」，不再是唯一取值的来源】
  --   实际取值走下面的 CONFIG.TIME_CONTROLS，由 GAME.tcInitial / GAME.tcIncrement 承载。
  --   **不要删、不要改这两个值**，两个原因：
  --   ① 默认档位就是 3，所以「不选档位」的路径与 v1.12 逐位一致（零回归）；
  --   ② tools_work/consistency_check.cjs 第 65-72 行仍拿这两个键与 Demo 逐字比对，
  --      删掉或改值会让那道门禁直接变红。
  INITIAL_TIME_SEC  = 900,    -- 每方初始 15:00（= TIME_CONTROLS 档位 3 的 initial）
  INCREMENT_SEC     = 10,     -- 每步加秒（= TIME_CONTROLS 档位 3 的 inc）
  CLOCK_REFRESH_SEC = 0.25,   -- 棋钟文本刷新间隔
  DRAW_COOLDOWN_SEC = 30,     -- 同一方两次求和最小间隔
  MOVE_LOG_LINES    = 6,      -- 面板显示的最近步数
  CLOCK_LOW_SEC     = 60,     -- 低于此值棋钟变红

  -- ===== 走时档（v2.0，4 档，无自定义）=====
  -- 【硬契约，用户已拍板】超快棋 60+0 / 闪电战 180+2 / 快棋 900+10 / 慢棋 5400+30
  --   写法是「首钟秒 + 每步加秒」。**这四组数字是契约，不许改。**
  -- 【n 是协议字段】档位号会随联机信号下发（EV_START 的 b 参数）。
  --   改 n 的数值 = 改协议，必须同步 docs/tech-architecture.md 第七节与节点图。
  -- 【est 只用于显示】预估单局时长给玩家做选择参考，不参与任何计算。
  TIME_CONTROLS = {
    { n = 1, name = "超快棋", initial = 60,   inc = 0,  est = "1–3 分钟"   },
    { n = 2, name = "闪电战", initial = 180,  inc = 2,  est = "5–12 分钟"  },
    { n = 3, name = "快棋",   initial = 900,  inc = 10, est = "15–40 分钟" },
    { n = 4, name = "慢棋",   initial = 5400, inc = 30, est = "60–120 分钟" },
  },
  -- 默认选中档位。**必须是 3**：它对应 v1.12 的 900+10，默认路径零回归。
  DEFAULT_TIME_CONTROL = 3,

  -- ===== 待机室（v2.0 块 2）=====
  -- 双方就绪后的倒数秒数。**H-6 硬契约 = 3 秒**，不许改。
  LOBBY_COUNTDOWN_SEC = 3,
  -- 多久没收到对方任何信号，就从「等待加入…」降级为「没等到另一位玩家」提示。
  -- 取 15 秒的依据（gdd 5.1）：服务端信号最低 100ms 延迟，握手 2 包最坏 200ms，
  -- 15 秒是 75 倍余量 —— 既不会一进来就报，也不会让人干等。
  LOBBY_PEER_TIMEOUT_SEC = 15,
  -- 待机室按钮的触摸目标下限（px）。手机 720 高时 0.098×720 = 70.6 已够，
  -- 但「直接开始」所在行只有 0.078×720 = 56.2，仍高于 44；这里留成可断言的常量。
  LOBBY_TOUCH_MIN = 44,

  -- ===== 联机快速开局（v3.0，用户 2026-11 需求）=====
  -- 【需求原文】① 双人进入后不应有待机室，双方玩家选择时间后自动把两人拉进对战；
  --             ② 界面要提示对方选了哪个时间；两人不同给 5 秒等待，都不改就在两种里随机选；
  --             ③ 进对局后随机分黑白，视角也要跟着换（黑方看黑棋在下），棋子保持正立。
  -- 【为什么删掉待机室流程】待机室要求「双方各点一次准备」= 多一步操作 + 多一个可能卡死的界面。
  --   现在「在初始界面点一个时间档」本身就是参战动作：双方都点了就自动开局。
  --   待机室的开关代码仍留在文件里（build_lobby 等，已无任何入口调用），
  --   只是为了不破坏既有自检断言（12-l / 12-p / 12-q 仍按 screen="lobby" 验证旧语义）。
  MATCH_DIFF_WAIT_SEC  = 5,     -- 两人档位不同时，给多少秒改选（硬契约：用户指定 5 秒）
  MATCH_HEARTBEAT_SEC  = 0.9,   -- 把我已选好的档位重复广播的间隔（抗丢包；对端靠它判在线）
  MATCH_PEER_FRESH_SEC = 3.0,   -- 多久没收到对方包就认为对端已离开（只影响文案/是否判定）
  MATCH_CONFLICT_EPS   = 0.0,   -- 冲突窗口的浮点余量（保留字段，勿删：文档/断言引用过）
  -- 标识字符串前缀。放在信号的 fen 槽（第 5 槽，旧版恒空）。
  MATCH_ID_PREFIX      = "P",

  -- 【v2.0 方案 T：LOBBY_START_GRACE_SEC 已删除】
  -- 原设计是「倒数跑完后等对端 EV_START，最多 1.5 秒，超时自己开局」。
  -- 该逻辑有两个问题：
  --   ① 把 EV_START 当成开局的前置条件 → 对端掉线时本端卡在「等待超时」中间态
  --   ② 1.5 秒对「对方正在点准备」来说太短
  -- 现在改成「倒数结束 → **立即本地开局** → fire-and-forget 通知对端」，
  -- EV_START 退化为纯通知，不再是条件，所以这个宽限期常量失去了全部引用。
  -- 【为什么不留着】死常量比没常量更误导 —— 后来读代码的人会以为还有等待逻辑。

  -- ===== 文本排版唯一算式（v2.0 块 2 收口）=====
  -- 【为什么要有这两个函数】「文本框可用高不够 → 整行被吞」在本项目已经踩了 6 次
  -- （v1.10 结算标题、v2.0 块1 档位名、gdd 的 72 号倒数、块2 的 TITLE/FOOTER/HINT、
  --  以及 Demo 侧 26 处）。根因是同一个：**手写字号字面量，没和板高绑在一起**。
  -- 现在把所有「字号 ↔ 板高」换算收进这一对互逆函数，新增文本控件一律从它们取值，
  -- 则该类 bug 在数学上不可能发生。
  -- 依据：平台「可用高 ≈ 板高 − 0.9×字号，行高 ≈ 1.2×字号」⇒ 板高 ≥ 2.1×字号。
  V2_H_RATIO = 2.1,

  -- ===== 悔棋（v3.2 语义改写，用户 2026-11 明确要求）=====
  -- 【硬契约 H-4】每方每局限 3 次。**不许改成累计到下一局** —— 悔棋是单局资源。
  UNDO_PER_SIDE = 3,
  -- 一次悔棋撤回的**半步数（plies）**。
  --
  -- 【v3.2 用户改写：1 步，不再是成对撤回 2 步】
  --   新规则原文：「只能在对方未走出下一步时申请悔棋，即轮到自己走时不允许悔棋，
  --             悔棋造成的时间损失由自己承担」。
  --   ⇒ 悔棋只能发生在「我刚走完、对方还在想」这个窗口，撤掉的正是**我自己刚走的那一手**。
  --   ⇒ 撤回 1 步后轮次回到我（因为轮到对方），与被撤掉的那手之前一致，不会错乱。
  --
  -- 【为什么必须改】旧语义「双方各退一步」在这个窗口里是**矛盾的**：
  --   对方还没应手，没有「对方的下一步」可退；硬退 2 步会撤掉对方上一手已经确认的棋。
  UNDO_PLIES = 1,
  -- 联机悔棋请求超时（秒）。超时视同拒绝，解冻棋钟、不扣次数。
  UNDO_REQUEST_TIMEOUT_SEC = 15,
  -- 【v3.2】悔棋是否把棋钟退回。用户裁决：**只返还对方的时间，自己的不返还**
  --   （「悔棋造成的时间损失由自己承担」的字面执行）。
  --   false = 双方棋钟都保持撤回前读数（更干净）；true = 对方棋钟退回快照值。
  UNDO_REFUND_PEER_CLOCK = true,

  -- ===== 复盘动作条（v2.0 块 4）=====
  -- 棋盘下方单行两键的**最小**高度。实际取值 = max(本值, fit_h(FONT.BUTTON))。
