  -- ===== 初始界面纵向排布（v2.0）=====
  -- 【为什么单独一张表，不并进 PANEL_LAYOUT】
  --   tools_work/consistency_check.cjs 第 215-231 行会把 `CONFIG.PANEL_LAYOUT` 与
  --   Demo 的 `const PL` 取键并集逐项比对，**任一侧缺项即 FAIL**。
  --   初始界面是 Lua 独有的（Demo 侧结构不同），若塞进 PANEL_LAYOUT 会让那道门禁必红。
  --   所以这里独立成表，同样遵守「任何两项 y 区间互不相交」的纪律。
  -- y = 相对画布高度的下边缘比例（0 = 画布底），h = 高度比例。千星原点左下、Y 向上。
  START_LAYOUT = {
    FOOTER   = { y = 0.055, h = 0.045 },   -- 底部版本号 + 提示
    ENTRY_R1 = { y = 0.175, h = 0.098 },   -- 入口行 1：双人·联机对战（主入口，通栏）
    ENTRY_R2 = { y = 0.290, h = 0.098 },   -- 入口行 2：单人·复盘研习（v3.2 起也通栏）
    -- 【v2.0 修：档位卡高度 0.190 → 0.248】模拟器截图实测「档位名整行不显示」。
    -- 根因是文本框的**可用高 ≈ 控件高 − 0.9×字号，行高 ≈ 1.2×字号**（D-02 陷阱）：
    --   字号 28 的档位名需要 ≥ 1.2×28 + 0.9×28 = 58.8px，而旧卡高 0.190×900 = 171px
    --   只分给档位名 0.24×171 = 41px < 58.8 → 文字被整行吞掉（和 v1.10 结算标题同一种 bug）。
    -- 现在卡高 223.2px，档位名分到 67px、三行说明各 42.4px，四项都过线（逐个算过，见 build_start_screen）。
    -- 纵向改由「下边 0.400 / 上边 0.648」夹住：下距入口行 2 顶边 0.388 留 0.012，
