    -- 现在总宽 0.80 × canvasW 居中（左右各留 0.10 边距 ≥ 0.04 的触摸安全边）。
    TC_CARDS_X = 0.10,
    TC_CARDS_W = 0.80,
    TC_HINT  = { y = 0.655, h = 0.048 },   -- 档位选择说明行（联机才补「先选者为准」）
    -- 【v2.0 收口：SUBTITLE 字号 24 → 22，板高 0.052 → 0.056】
    --   原：板高 46.8px / 字号 24 → 比值 1.950 < 2.1（差 5.2px，属未验证灰区）
    --   现：板高 50.4px / 字号 22 → fit_h(22)=48 ≤ 50.4 ✅
    SUBTITLE = { y = 0.705, h = 0.056 },   -- 副标题（联机时显示「你选了…/对手选了…」）
    -- ===== v3.1：标题下加一句固定标语「将杀即为终点」=====
    -- 【为什么要把标题上移】原 TITLE 0.775..0.890、SUBTITLE 顶 0.761，中间只有 0.014（12.6px），
    -- 塞不进一行（20 号字至少需要 42px）。所以整体重排：
    --   SUBTITLE 0.705..0.761 → TAGLINE 0.770..0.822 → TITLE 0.830..0.965
    -- 字号/板高核算（**两档画布都要算**，只看 PC 会踩手机画布的字号缩放坑）：
    --   pc-16-9：标语板高 0.052×900=46.8px，字号 20 → fit_h(20)=43 ≤ 46.8 ✅
    --   mobile-16-9：板高 0.052×720=37.4px，字号 floor(20×0.8)=16 → fit_h(16)=35 ≤ 37.4 ✅
    --     （旧值 0.048 在手机上只有 34.56px < 35，会被整行吞掉 —— 所以这里取 0.052）
    --   标题板高 0.135×900=121.5px / 64 号 → 比值 1.898，比原 1.617 更宽松
    -- 任意两项 y 区间互不相交（间隙 0.009 / 0.008），顶部仍留 0.035。
    TAGLINE  = { y = 0.770, h = 0.052 },   -- 标语「将杀即为终点」
    TITLE    = { y = 0.830, h = 0.135 },   -- 主标题「国际象棋」
