  -- ===== 待机室纵向排布（v2.0 块 2）=====
  -- 【数值来源】docs/gdd-v2.md §5.2，逐项照抄，不得自行调整。
  -- 【不变量】任意两项 y 区间 [y, y+h] 必须互不相交（gdd 已核算间隙 0.010~0.050 全 > 0）。
  -- 【与 START_LAYOUT 一样独立成表的原因】待机室是 Lua 独有的界面，
  --   塞进 PANEL_LAYOUT 会让 consistency_check 的「Lua↔Demo 键集合比对」变红。
  -- y = 相对画布高度的下边缘比例（原点左下、Y 向上），h = 高度比例。
  LOBBY_LAYOUT = {
    FOOTER    = { y = 0.055, h = 0.045 },   -- 底部：双方都点准备后开始 / 只有你一个人
    SOLO_BTN  = { y = 0.150, h = 0.078 },   -- 直接开始（单人兜底）
    READY_BTN = { y = 0.255, h = 0.098 },   -- 准备 / 取消准备
    HINT      = { y = 0.375, h = 0.045 },   -- 提示条
    PLAYER2   = { y = 0.440, h = 0.080 },   -- 对手行
    PLAYER1   = { y = 0.530, h = 0.080 },   -- 你 行
    ROOM_TC   = { y = 0.625, h = 0.050 },   -- 时间档 + 谁选定
    COUNTDOWN = { y = 0.700, h = 0.115 },   -- 倒数大数字
    TITLE     = { y = 0.830, h = 0.085 },   -- 联机·待机室
  },

  -- ===== 字号（1600x900 基准下的整数，与 docs/策划案.md 10.7 一致）=====
  -- ===== 性能计量开关（issue #1 第 6 条）=====
  -- 打开后 GetRepaintStats() 会给出「控件属性写次数 / 被缓存跳过的次数」，
  -- 用于量化性能优化的实际效果。关掉可省掉两次整数比较（收益极小，
  -- 默认开是为了让任何人拿到脚本都能自己复测，而不是只有我相信我自己的数字）。
  TRACK_CONTROL_WRITES = true,

  -- 缩放规则：实际字号 = 基准字号 × (canvasH / 900)，向下取整；下限 16。
  FONT = {
    COORD        = 22,
    PIECE        = 52,
    PANEL_TITLE  = 32,
    PANEL_BODY   = 20,   -- 轮次 / 被吃子 / 走子记录
    CLOCK        = 28,   -- v1.11：棋钟改成并排两格，每格只有半宽，36 会顶满被换行截断
    BUTTON       = 24,
    HINT         = 24,
    RESULT_TITLE = 44,
    RESULT_SUB   = 24,
    PROMO_OPTION = 24,
    MIN_FONT     = 16,   -- 缩放后下限
    -- ===== 初始界面（v2.0）=====
    -- 【命名】带 START_/TC_ 前缀，不与上面被 consistency_check.cjs 逐项比对的
    -- 10 个字号键撞名（撞名会拿新值去比 Demo 的旧值 → 假 FAIL）。
    -- 【START_TITLE = 64 是本项目对 2.1 规则的**唯一显式例外**，理由如下】
    --   实测值：START_LAYOUT.TITLE = { y=0.775, h=0.115 } → 板高 0.115×900 = **103.5px**
    --   fit_h(64) = ceil(64×2.1)+1 = **136px**  →  103.5 < 136，按规则「装不下」
    --   实际比值 = 103.5 / 64 = **1.617**（Lead 表里那个 1.617 就是这个数，核对一致）
    --
    --   但模拟器实测（Lead 三张截图逐张核对）：「黑白棋局」四个字**完整显示、无截断**。
    --   原因推断：2.1 这个系数是从**多行/长文本**的失败样本反推的保守上界，
    --   而主标题是**单行 4 个汉字、无换行压力**，实际可用高远大于公式假设。
    --
    --   裁决（Lead 2026-11-07）：**信实测，保 64**。理由：
    --     · 它承载整个游戏的第一印象，降到 48 视觉损失明显；
    --     · 实测已证明它渲染正确，此时「规则」应让位于「证据」。
    --   ⚠️ 若将来把标题改长（超过 6~8 个汉字）或改成多行，**必须重新实测** ——
    --      那时 2.1 规则会重新生效，103.5px 装不下两行。
    START_TITLE  = 64,   -- 主标题「国际象棋」（2.1 规则的唯一显式例外，见上）
    -- 副标题：原 24 号 / 板高 46.8px = 比值 1.950（差 5.2px，灰区）
    --   → 降到 22 号，并把板高从 0.052 提到 0.056（50.4px），fit_h(22)=48 ≤ 50.4 ✅
    START_SUB    = 22,   -- 副标题
    -- ===== v3.1：标题下的标语「将杀即为终点」=====
    -- 板高 0.048×900 = 43.2px；20 号需要 fit_h(20)=43 ≤ 43.2 ✅（刚好过线，
    -- 再大一号（21）就要 45px，会被整行吞掉 —— 改字号前先算 h×900 ≥ 2.1×字号+1）。
    START_TAGLINE = 20,  -- 标语
    TC_NAME      = 28,   -- 档位卡：档位名
    TC_META      = 19,   -- 档位卡：首钟 / 加秒 / 预估（三行，字号必须小）
    START_ENTRY  = 28,   -- 三个入口按钮
    START_FOOTER = 18,   -- 底部提示（v3.1 起只放「点一个入口开始」，版本号已删）
    -- ===== 待机室（v2.0 块 2）=====
    -- 【字号全部由「板高 ≥ 2.1×字号」反算，不是拍脑袋】（h 来自 LOBBY_LAYOUT，1600×900 基准）
    --   TITLE    h=0.085×900 = 76.5px → 最大 36（gdd 9.3 写 40 会溢出，见下）
    --   BODY     h=0.080×900 = 72.0px → 最大 34；取 24（玩家行/准备键）
    --   SMALL    h=0.045×900 = 40.5px → 最大 19；取 18（提示条/底部/身份标注）
    --   ROOM_TC  h=0.050×900 = 45.0px → 最大 21；SMALL=18 也在其内 OK
    --   COUNTDOWN h=0.115×900 = 103.5px → 最大 49；取 48
    --
    -- 【TITLE 为什么不是 gdd 的 40】板高 0.085×900 = 76.5px，
    --   fit_h(40) = ceil(40×2.1)+1 = 85 > 76.5 → **整行会被吞掉**。
    --   font_for_h(76.5) = floor(76.5/2.1) = 36，但 fit_h(36) = ceil(75.6)+1 = **77 > 76.5** ——
    --   36 仍差 0.5px！所以取 **35**（fit_h(35)=ceil(73.5)+1=75 ≤ 76.5 ✅）。
    --   这就是 +1 缓冲的用处：光看 floor 会漏掉这一档，必须两个函数交叉验证。
    --   （D-02 陷阱第 4 次；前三次：v1.10 结算标题、块1 档位名、gdd 的 72 号倒数）
    LOBBY_TITLE     = 35,  -- 待机室标题（gdd 写 40 → 36 → 实测 35 才真装得下）
    LOBBY_BODY      = 24,  -- 玩家行 / 准备键
    LOBBY_SMALL     = 18,  -- 时间档行 / 提示条 / 底部（gdd 写 20，40.5px 板高需 42 → 改 18）
    -- 【倒数大数字：gdd §5.6 写 72，实测算下来放不下，故取 48】
    -- 平台文本布局：可用高 ≈ 控件高 − 0.9×字号，行高 ≈ 1.2×字号
    --   ⇒ 板高必须 ≥ 2.1 × 字号
    -- gdd §5.2 给 COUNTDOWN 的板高 = 0.115 × 900 = 103.5px
    --   ⇒ 最大字号 = 103.5 / 2.1 = 49.3px
    --   72 号字需要 151.2px —— 差 47.7px，**整行会被吞掉**。
    -- 把板高顶到 0.125（上边 0.825，与 TITLE 底 0.830 留 0.005）也只能到 53.6px，
    -- 仍远不够 72。所以取 **48**：需要 100.8px ≤ 103.5px ✅，是能容下的最大整字号。
    LOBBY_COUNTDOWN = 48,
    -- 【悔棋按钮专用字号 24，比其它面板按钮(28)小 4 号 —— 因为文案更长】
    -- 「悔棋（剩 3）」逐字符拆开：5 全角（悔/棋/（/剩/））+ 2 半角（空格/3）
    --   保守估算宽度 = 5×字号 + 2×字号×0.55 = 6.1 × 字号
    --   字号 28 → 170.8px；字号 26 → 158.6px；字号 25 → 152.5px
    --   左半格宽 = 面板宽 0.22×1600 = 352 × 0.42 = **147.8px**
    --   ⇒ 只有 **字号 24**（146.4px）能放进 147.8px（余 1.4px）
    --   字号 25 就已超 4.7px → 会换行。换行后半宽按钮里只剩半个「悔棋」，比没字更难看。
    -- proto-lead 在 Demo 侧独立实测「需 146 / 可用 146，差 1px 就换行」，与此吻合。
    -- ⚠️ 余量只有 1.4px，非常紧。若将来改文案（比如「悔棋（剩余 3 次）」）必须先算宽度。
    UNDO_BTN     = 24,
    -- ===== 吃子成就区标签（v3.2）=====
    -- 板高 = max(2.2×字号, CAP_AREA 高的 14%)，18 号需要 38px；
    -- CAP_AREA 高 0.218×900=196.2px，14% = 27.5px < 38 → 实际取 38px（见 build_panel）。
    CAP_LABEL    = 18,
  },
