-- =============================================================================
-- 棋子形状表（v1.9：算法拟合的矩形/椭圆/三角形并集）
-- -----------------------------------------------------------------------------
-- 【数据来源】tools_work/fit_pieces.py 的算法拟合产物，**不要手改**。
--   产物与对照图：docs/pieces-fit-generated.lua / .json / pieces-fit-preview.png
--   报告：docs/pieces-fit-report.md
--   参考素材：out/棋子素材-en-croissant/png/256/{KW,QW,RW,BW,NW,PW}.png
--             （cburnett，Colin M.L. Burnett，CC BY-SA 3.0，经 en-croissant 分发）
--
-- 【为什么是算法拟合而不是手调】
--   手调坐标试了三轮都「一团糊」—— 根因不是调参不够，而是没人能用眼睛
--   准确估出十几个图元的中心/宽高。算法路径：提取实心剪影 → 轮廓驱动的贪心集合覆盖
--   （内接圆盘 + 最大内接矩形 + apex-up 三角）→ IoU 坐标下降 → 迭代局部搜索。
--   光栅化语义与游戏端完全一致，所以 IoU 是可信的。
--
-- 【拟合质量】IoU 0.9835~0.9980（六枚均值 0.9938），97 个图元，无越界。
--
-- 【相对大小】整幅 256×256 直接映射到棋子方框，**不做逐枚裁剪** ——
--   所以兵仍然明显比王矮，六枚共享同一比例与基线。
--   不要改成按每枚自己的 bbox 裁切，那会把兵放大到和王一样高。
--
-- 【白黑共用同一份形状】cburnett 的白子是细黑描边、黑子是实心填充，
--   但两者的**实心剪影相同**（提取时对白子做泛洪填充得到描边内部本体）。
--   形状只存一份，区别只在渲染颜色：白子=白填充+深描边，黑子=深填充+浅描边。
--
-- 【数据格式】
--   PIECE_ART[kind] = { { shape, cx, cy, w, h, rot, role }, ... }
--     shape  0=矩形 1=椭圆 2=三角（尖朝上）
--     cx,cy  ∈[0,1] 图元**中心**，左下原点、Y 向上
--     w,h    ∈[0,1] 相对棋子方框边长（方框 = 棋格宽 × 0.92）
--     rot    旋转角（度），**逆时针为正**
--     role   0=外形 / 1=镂空 / 2=细节线
--
-- 【六层渲染】paint_slot 的顺序固定，与数据表顺序无关：
--   ① 投影椭圆 → ② 外形描边（每形外扩 pad）→ ③ 外形填充 →
--   ④ 镂空描边 → ⑤ 镂空填充（该格棋格色）→ ⑥ 细节线（对比色）
-- =============================================================================

