-- 取某枚棋子的形状表。白黑共用同一份（形状相同，区别只在渲染颜色）。
local function piece_art_of(p)
  return PIECE_ART[math.abs(p)]
end

-- 单枚棋子的控件数量（v1.11 起不含投影）
--   外形 role0：描边层 + 填充层 = 2 个
--   镂空 role1：描边层 + 填充层 = 2 个
--   细节 role2：只画 1 个（它就是一条线，不需要描边层）
local function piece_prim_count(list)
  local n = 0
  for _, s in ipairs(list) do
    if s[7] == 2 then n = n + 1 else n = n + 2 end
  end
  return n
end

-- 单个形状旋转后的外接框（归一化坐标，左下原点 Y 向上）
-- 千星图元绕自身中心旋转，所以外接框只需绕 (cx,cy) 转四个角再取极值。
-- 【为什么要算这个】issue #1 第 2 条「多走几步后棋子错位」的对照基线，
-- 以及第 5 条「棋子在格子里要视觉居中」都需要**旋转后**的真实范围 ——
-- 直接用 w/h 会把斜置的鬃毛算窄，得到的居中量偏差能到 1~2px。
local function shape_bbox(s)
  local cx, cy, w, h = s[2], s[3], s[4], s[5]
  local rad = math.rad(s[6] or 0)
  local cs, sn = math.cos(rad), math.sin(rad)
  local ex, ey = w * 0.5, h * 0.5
  local x0, y0, x1, y1 = math.huge, math.huge, -math.huge, -math.huge
  for _, sx in ipairs({ -1, 1 }) do
    for _, sy in ipairs({ -1, 1 }) do
      local px, py = sx * ex, sy * ey
      local rx = px * cs - py * sn
      local ry = px * sn + py * cs
      local ax, ay = cx + rx, cy + ry
      if ax < x0 then x0 = ax end
      if ax > x1 then x1 = ax end
      if ay < y0 then y0 = ay end
      if ay > y1 then y1 = ay end
    end
  end
  return x0, y0, x1, y1
end

-- 【棋子视觉居中量】issue #1 第 5 条
-- 删掉底部投影后，棋子的视觉重心完全由形状本身决定。实测六个 kind 的外形包围盒
-- 竖向中心落在 0.463~0.510（相对棋子方框），整体并集中心 0.492 —— 偏低 0.008，
-- 在 81px 方框上约 0.6px。数值虽小，但这是「有没有认真对齐」的差别，且必须
-- **由数据算出来**而不是手填：以后重拟合棋子会自动跟上。
--
-- 【为什么用「全局一个偏移」而不是每枚各自居中】
--   各自居中会把兵抬到和王一样高 —— 兵本来就该比王矮（实测 兵/王 高度比 0.909）。
--   全局偏移只整体平移，不改变各枚之间的相对高度，正是「站在同一条基线上」的观感。
local PIECE_CENTER_DY = nil

local function piece_center_dy()
  if PIECE_CENTER_DY ~= nil then return PIECE_CENTER_DY end
  local y0, y1 = math.huge, -math.huge
  for _, pid in ipairs({ PAWN, KNIGHT, BISHOP, ROOK, QUEEN, KING }) do
    local list = PIECE_ART[pid]
    if list ~= nil then
      for _, s in ipairs(list) do
        -- 只统计外形（role0）：镂空/细节线在轮廓内部，不影响视觉重心
        if s[7] == 0 then
          local _, sy0, _, sy1 = shape_bbox(s)
          if sy0 < y0 then y0 = sy0 end
          if sy1 > y1 then y1 = sy1 end
        end
      end
    end
  end
  if y0 == math.huge or y1 <= y0 then
    PIECE_CENTER_DY = 0
  else
    PIECE_CENTER_DY = 0.5 - (y0 + y1) * 0.5
  end
  return PIECE_CENTER_DY
end

-- 全部棋子里的最大控件数：32 个槽位都按这个容量建，任何一枚都放得下。
-- 【v1.9】白黑共用同一份形状，所以只扫 PIECE_ART 一遍（不再按 side 两层）。
local function piece_prim_max_of_all()
  local m = 0
  for _, pid in ipairs({ PAWN, KNIGHT, BISHOP, ROOK, QUEEN, KING }) do
    local list = PIECE_ART[pid]
    if list ~= nil then
      local c = piece_prim_count(list)
      if c > m then m = c end
    end
  end
  if m > CONFIG.PIECE_PRIM_BUDGET then m = CONFIG.PIECE_PRIM_BUDGET end
  if m < 1 then m = 1 end
  return m
end


-- 单枚棋子实际用到的图元数上限（槽位池按它建）
-- v1.7：由 PIECE_ART 直接算出，不再依赖外部数据文件
local function piece_prim_max()
  return piece_prim_max_of_all()
end

local PRIM_MAX     = CONFIG.PIECE_PRIM_BUDGET   -- 单枚棋子最多图元数（启动时按实际值校正）

function RULES.parse_fen(fen)
  local st = {
    board = {}, turn = WHITE,
    castling = { K = false, Q = false, k = false, q = false },
    ep = nil, halfmove = 0, fullmove = 1, history = {},
  }
  for i = 0, 63 do st.board[i] = 0 end

  local parts = {}
  for token in string.gmatch(fen, "[^ ]+") do parts[#parts + 1] = token end
  if #parts < 4 then error("FEN 字段不足: " .. tostring(fen)) end

  local r, f = 7, 0
  for ch in string.gmatch(parts[1], ".") do
    if ch == "/" then r = r - 1; f = 0
    elseif ch >= "1" and ch <= "8" then f = f + tonumber(ch)
    else
      local piece = CHAR_TO_PIECE[ch]
      if not piece then error("FEN 非法棋子: " .. tostring(ch)) end
      st.board[sq_of(r, f)] = piece
      f = f + 1
    end
  end
  st.turn = (parts[2] == "w") and WHITE or BLACK
  if parts[3] and parts[3] ~= "-" then
    for ch in string.gmatch(parts[3], ".") do
      if ch == "K" then st.castling.K = true
      elseif ch == "Q" then st.castling.Q = true
      elseif ch == "k" then st.castling.k = true
      elseif ch == "q" then st.castling.q = true end
    end
  end
  if parts[4] and parts[4] ~= "-" then
    local fc = string.sub(parts[4], 1, 1)
    local rn = tonumber(string.sub(parts[4], 2, 2))
    if fc and rn then st.ep = sq_of(rn - 1, string.byte(fc) - string.byte("a")) end
  end
  if parts[5] then st.halfmove = tonumber(parts[5]) or 0 end
  if parts[6] then st.fullmove = tonumber(parts[6]) or 1 end
  return st
end

function RULES.fen_of(st)
  local rows = {}
  for r = 7, 0, -1 do
    local line, empty = "", 0
    for f = 0, 7 do
      local p = st.board[sq_of(r, f)]
      if p == 0 then empty = empty + 1
      else
        if empty > 0 then line = line .. tostring(empty); empty = 0 end
        line = line .. PIECE_TO_CHAR[p]
      end
    end
    if empty > 0 then line = line .. tostring(empty) end
    rows[#rows + 1] = line
  end
  local cs = ""
  if st.castling.K then cs = cs .. "K" end
  if st.castling.Q then cs = cs .. "Q" end
  if st.castling.k then cs = cs .. "k" end
  if st.castling.q then cs = cs .. "q" end
  if cs == "" then cs = "-" end
  local epStr = "-"
  if st.ep then epStr = string.char(string.byte("a") + (st.ep % 8)) .. tostring((st.ep // 8) + 1) end
  return table.concat(rows, "/") .. " " .. (st.turn == WHITE and "w" or "b") ..
         " " .. cs .. " " .. epStr .. " " .. tostring(st.halfmove) .. " " .. tostring(st.fullmove)
end

function RULES.position_key(st)
  local parts = {}
  for i = 0, 63 do parts[#parts + 1] = tostring(st.board[i]) end
  local cs = ""
  if st.castling.K then cs = cs .. "K" end
  if st.castling.Q then cs = cs .. "Q" end
  if st.castling.k then cs = cs .. "k" end
  if st.castling.q then cs = cs .. "q" end
  return table.concat(parts, ",") .. "|" .. tostring(st.turn) .. "|" .. cs ..
         "|" .. (st.ep and tostring(st.ep) or "-")
end

local function push(moves, from, to, promo, is_ep, is_castle)
  moves[#moves + 1] = { from = from, to = to, promo = promo, ep = is_ep or false, castle = is_castle or false }
end

function RULES.gen_pseudo(st)
  local moves = {}
  local board = st.board
  local isWhite = (st.turn == WHITE)

  for from = 0, 63 do
    local p = board[from]
    if p ~= 0 and ((p > 0) == isWhite) then
      local ap = (p > 0) and p or -p
      local r, f = rank_of(from), file_of(from)

      if ap == PAWN then
        local fwd = isWhite and 1 or -1
        local startRank = isWhite and 1 or 6
        local promoRank = isWhite and 7 or 0
        local one = shift(from, fwd, 0)
        if one and board[one] == 0 then
          if rank_of(one) == promoRank then
            push(moves, from, one, QUEEN); push(moves, from, one, ROOK)
            push(moves, from, one, BISHOP); push(moves, from, one, KNIGHT)
          else
            push(moves, from, one, nil)
            if r == startRank then
              local two = shift(one, fwd, 0)
              if two and board[two] == 0 then push(moves, from, two, nil) end
            end
          end
        end
        for _, df in ipairs({ -1, 1 }) do
          local to = shift(from, fwd, df)
          if to then
            local target = board[to]
            if target ~= 0 and (target > 0) ~= isWhite then
              if rank_of(to) == promoRank then
                push(moves, from, to, QUEEN); push(moves, from, to, ROOK)
                push(moves, from, to, BISHOP); push(moves, from, to, KNIGHT)
              else push(moves, from, to, nil) end
            elseif st.ep and to == st.ep then
              push(moves, from, to, nil, true)
            end
          end
        end

      elseif ap == KNIGHT then
        for _, d in ipairs(KNIGHT_DIRS) do
          local to = shift(from, d[1], d[2])
          if to then
            local target = board[to]
            if target == 0 or (target > 0) ~= isWhite then push(moves, from, to, nil) end
          end
        end

      elseif ap == KING then
        for _, d in ipairs(KING_DIRS) do
          local to = shift(from, d[1], d[2])
          if to then
            local target = board[to]
            if target == 0 or (target > 0) ~= isWhite then push(moves, from, to, nil) end
          end
        end
        local homeRank = isWhite and 0 or 7
        if r == homeRank and f == 4 then
          local rookPiece = isWhite and ROOK or -ROOK
          local kOK = isWhite and st.castling.K or (not isWhite) and st.castling.k
          local qOK = isWhite and st.castling.Q or (not isWhite) and st.castling.q
          local rookK = sq_of(homeRank, 7)
          local rookQ = sq_of(homeRank, 0)
          if kOK and board[rookK] == rookPiece
             and board[sq_of(homeRank, 5)] == 0 and board[sq_of(homeRank, 6)] == 0 then
            push(moves, from, sq_of(homeRank, 6), nil, false, true)
          end
          if qOK and board[rookQ] == rookPiece
             and board[sq_of(homeRank, 3)] == 0 and board[sq_of(homeRank, 2)] == 0
             and board[sq_of(homeRank, 1)] == 0 then
            push(moves, from, sq_of(homeRank, 2), nil, false, true)
          end
        end

      else
        local dirs
        if ap == BISHOP then dirs = BISHOP_DIRS
        elseif ap == ROOK then dirs = ROOK_DIRS
        else dirs = QUEEN_DIRS end
        for _, d in ipairs(dirs) do
          local cur = from
          while true do
            local to = shift(cur, d[1], d[2])
            if not to then break end
            local target = board[to]
            if target == 0 then
              push(moves, from, to, nil)
              cur = to
            else
              if (target > 0) ~= isWhite then push(moves, from, to, nil) end
              break
            end
          end
        end
      end
    end
  end
  return moves
end

function RULES.is_attacked(st, sq, by_side)
  local board = st.board
  local isWhite = (by_side == WHITE)

  local pr = (sq // 8) + (isWhite and -1 or 1)
  if pr >= 0 and pr <= 7 then
    for _, df in ipairs({ -1, 1 }) do
      local pf = (sq % 8) + df
      if pf >= 0 and pf <= 7 then
        local p = board[sq_of(pr, pf)]
        if p ~= 0 and ((p > 0) == isWhite) and ((p > 0) and p or -p) == PAWN then return true end
      end
    end
  end

  for _, d in ipairs(KNIGHT_DIRS) do
    local from = shift(sq, -d[1], -d[2])
    if from then
      local p = board[from]
      if p ~= 0 and ((p > 0) == isWhite) and ((p > 0) and p or -p) == KNIGHT then return true end
    end
  end

  for _, d in ipairs(KING_DIRS) do
    local from = shift(sq, -d[1], -d[2])
    if from then
      local p = board[from]
      if p ~= 0 and ((p > 0) == isWhite) and ((p > 0) and p or -p) == KING then return true end
    end
  end

  for _, d in ipairs(ROOK_DIRS) do
    local cur = sq
    while true do
      local to = shift(cur, d[1], d[2])
      if not to then break end
      local p = board[to]
      if p ~= 0 then
        if (p > 0) == isWhite then
          local ap = (p > 0) and p or -p
          if ap == ROOK or ap == QUEEN then return true end
        end
        break
      end
      cur = to
    end
  end

  for _, d in ipairs(BISHOP_DIRS) do
    local cur = sq
    while true do
      local to = shift(cur, d[1], d[2])
      if not to then break end
      local p = board[to]
      if p ~= 0 then
        if (p > 0) == isWhite then
          local ap = (p > 0) and p or -p
          if ap == BISHOP or ap == QUEEN then return true end
        end
        break
      end
      cur = to
    end
  end

  return false
end

function RULES.find_king(st, side)
  local kingPiece = (side == WHITE) and KING or -KING
  for i = 0, 63 do
    if st.board[i] == kingPiece then return i end
  end
  return nil
end

function RULES.in_check(st, side)
  local ksq = RULES.find_king(st, side)
  if not ksq then return false end
  return RULES.is_attacked(st, ksq, -side)
end

function RULES.make(st, mv)
  local board = st.board
  local side = st.turn
  local moving = board[mv.from]

  local undo = {
    mv = mv,
    captured = board[mv.to],
    capturedSq = mv.to,
    epBefore = st.ep,
    castling = { K = st.castling.K, Q = st.castling.Q, k = st.castling.k, q = st.castling.q },
    halfmove = st.halfmove, fullmove = st.fullmove, turn = st.turn,
    castleRookFrom = nil, castleRookTo = nil,
  }

  if mv.ep then
    local capSq = shift(mv.to, side == WHITE and -1 or 1, 0)
    undo.captured = board[capSq]
    undo.capturedSq = capSq
    board[capSq] = 0
  end

  board[mv.to] = mv.promo and (side == WHITE and mv.promo or -mv.promo) or moving
  board[mv.from] = 0

  if mv.castle then
    local homeRank = (side == WHITE) and 0 or 7
    if mv.to == sq_of(homeRank, 6) then
      undo.castleRookFrom = sq_of(homeRank, 7)
      undo.castleRookTo = sq_of(homeRank, 5)
    else
      undo.castleRookFrom = sq_of(homeRank, 0)
      undo.castleRookTo = sq_of(homeRank, 3)
    end
    board[undo.castleRookTo] = board[undo.castleRookFrom]
    board[undo.castleRookFrom] = 0
  end

  local ap = (moving > 0) and moving or -moving
  if ap == KING then
    if side == WHITE then st.castling.K, st.castling.Q = false, false
    else st.castling.k, st.castling.q = false, false end
  elseif ap == ROOK then
    if mv.from == sq_of(0, 0) then st.castling.Q = false
    elseif mv.from == sq_of(0, 7) then st.castling.K = false
    elseif mv.from == sq_of(7, 0) then st.castling.q = false
    elseif mv.from == sq_of(7, 7) then st.castling.k = false end
  end
  if mv.to == sq_of(0, 0) then st.castling.Q = false
  elseif mv.to == sq_of(0, 7) then st.castling.K = false
  elseif mv.to == sq_of(7, 0) then st.castling.q = false
  elseif mv.to == sq_of(7, 7) then st.castling.k = false end

  st.ep = nil
  if ap == PAWN and math.abs(mv.to - mv.from) == 16 then st.ep = (mv.from + mv.to) // 2 end

  if ap == PAWN or undo.captured ~= 0 then st.halfmove = 0 else st.halfmove = st.halfmove + 1 end
  if side == BLACK then st.fullmove = st.fullmove + 1 end
  st.turn = -side
  st.history[#st.history + 1] = RULES.position_key(st)
  return undo
end

function RULES.unmake(st, undo)
  local mv = undo.mv
  local side = undo.turn
  local board = st.board

  st.history[#st.history] = nil
  st.turn = side
  st.ep = undo.epBefore
  st.castling.K, st.castling.Q = undo.castling.K, undo.castling.Q
  st.castling.k, st.castling.q = undo.castling.k, undo.castling.q
  st.halfmove = undo.halfmove
  st.fullmove = undo.fullmove

  if undo.castleRookFrom then
    board[undo.castleRookFrom] = board[undo.castleRookTo]
    board[undo.castleRookTo] = 0
  end

  board[mv.from] = mv.promo and (side == WHITE and PAWN or -PAWN) or board[mv.to]
  board[mv.to] = 0
  board[undo.capturedSq] = undo.captured
end

-- 合法性：必须检查易位路径（起点不被将军 + 经过格不被攻击）。
-- 【重要】perft 曾因跳过这条多算 4 步（2043 vs 2039），不可简化。
function RULES.is_legal(st, mv)
  local side = st.turn

  if mv.castle then
    if RULES.in_check(st, side) then return false end
    local homeRank = (side == WHITE) and 0 or 7
    local kingSq = sq_of(homeRank, 4)
    local midSq = (mv.to > kingSq) and sq_of(homeRank, 5) or sq_of(homeRank, 3)
    local board = st.board
    local savedKing = board[kingSq]
    board[kingSq] = 0
    board[midSq] = savedKing
    local attacked = RULES.is_attacked(st, midSq, -side)
    board[midSq] = 0
    board[kingSq] = savedKing
    if attacked then return false end
  end

  local undo = RULES.make(st, mv)
  local ok = not RULES.in_check(st, side)
  RULES.unmake(st, undo)
  return ok
end

function RULES.legal_moves(st)
  local out = {}
  for _, mv in ipairs(RULES.gen_pseudo(st)) do
    if RULES.is_legal(st, mv) then out[#out + 1] = mv end
  end
  return out
end

function RULES.is_checkmate(st)
  if not RULES.in_check(st, st.turn) then return false end
  return #RULES.legal_moves(st) == 0
end

function RULES.is_stalemate(st)
  if RULES.in_check(st, st.turn) then return false end
  return #RULES.legal_moves(st) == 0
end

function RULES.is_insufficient_material(st)
  local minors = {}
  local majors = 0
  for i = 0, 63 do
    local p = st.board[i]
    if p ~= 0 then
      local ap = (p > 0) and p or -p
      if ap ~= KING then
        if ap == PAWN or ap == ROOK or ap == QUEEN then majors = majors + 1
        else minors[#minors + 1] = { sq = i, ap = ap } end
      end
    end
  end
  if majors > 0 then return false end
  if #minors == 0 then return true end
  if #minors == 1 then return true end
  if #minors == 2 then
    local a, b = minors[1], minors[2]
    if a.ap == BISHOP and b.ap == BISHOP then
      local sa = (rank_of(a.sq) + file_of(a.sq)) % 2
      local sb = (rank_of(b.sq) + file_of(b.sq)) % 2
      return sa == sb
    end
    return false
  end
  return false
end

function RULES.is_threefold(st)
  local key = RULES.position_key(st)
  local count = 1
  for _, k in ipairs(st.history) do
    if k == key then count = count + 1 end
  end
  return count >= 3
end

function RULES.is_fifty_move(st)
  return st.halfmove >= 100
end

function RULES.game_status(st)
  if RULES.is_checkmate(st) then
    return { over = true, result = (st.turn == WHITE) and "0-1" or "1-0", reason = "checkmate" }
  end
  if RULES.is_stalemate(st) then
    return { over = true, result = "1/2-1/2", reason = "stalemate" }
  end
  if RULES.is_insufficient_material(st) then
    return { over = true, result = "1/2-1/2", reason = "insufficient" }
  end
  if RULES.is_threefold(st) then
    return { over = true, result = "1/2-1/2", reason = "threefold" }
  end
  if RULES.is_fifty_move(st) then
    return { over = true, result = "1/2-1/2", reason = "fifty" }
  end
  return { over = false, result = nil, reason = nil }
end

function RULES.perft(st, depth)
  if depth == 0 then return 1 end
  local n = 0
  for _, mv in ipairs(RULES.gen_pseudo(st)) do
    if RULES.is_legal(st, mv) then
      local undo = RULES.make(st, mv)
      n = n + RULES.perft(st, depth - 1)
      RULES.unmake(st, undo)
    end
  end
  return n
end

function RULES.uci_of(mv)
  local function sqname(sq)
    return string.char(string.byte("a") + (sq % 8)) .. tostring((sq // 8) + 1)
  end
  local s = sqname(mv.from) .. sqname(mv.to)
  if mv.promo then
    local chars = { [QUEEN] = "q", [ROOK] = "r", [BISHOP] = "b", [KNIGHT] = "n" }
    s = s .. chars[mv.promo]
  end
  return s
end

function RULES.find_move(st, uci)
  for _, mv in ipairs(RULES.legal_moves(st)) do
    if RULES.uci_of(mv) == uci then return mv end
  end
  return nil
end

function RULES.legal_uci_list(st)
  local out = {}
  for _, mv in ipairs(RULES.legal_moves(st)) do out[#out + 1] = RULES.uci_of(mv) end
  table.sort(out)
  return out
end

-- =============================================================================
-- 第 4 区：LAYOUT（唯一坐标换算入口）
--   除本区外，任何位置不得出现 1600 / 900 / 0.78 / 0.22 这类基准数字。
-- =============================================================================
local LAYOUT = {}

function LAYOUT.compute(canvasW, canvasH)
  local boardSide = canvasH * CONFIG.BOARD_SIDE_RATIO
  local cell = boardSide / 8
  local boardBottom = (canvasH - boardSide) / 2      -- 垂直居中
  local panelW = canvasW * CONFIG.PANEL_WIDTH_RATIO
  local panelLeft = canvasW - panelW                 -- 靠右
  local panelH = boardSide                           -- 与棋盘同高
  local panelBottom = (canvasH - panelH) / 2

  -- 水平居中；窄屏（手机 4:3）下若棋盘右缘会压到面板左缘，改为在「面板左侧区域」内居中。
  -- 判定： (canvasW + boardSide)/2 > canvasW - panelW
  local boardLeft = (canvasW - boardSide) / 2
  if (canvasW + boardSide) / 2 > canvasW - panelW then
    boardLeft = (panelLeft - boardSide) / 2
  end

  -- 字号缩放：基准 1600×900，向下取整，下限 16。
  --
  -- 【v1.11 修 bug：必须取宽高两个方向的较小者，不能只看高度】
  --   用户报的现象：手机 4:3（1280×960）下面板按钮「切换本地同屏」被截成「切换本地」、
  --   两个棋钟挤在一起。根因是字号只按 canvasH/900 缩放：
  --     4:3 的画布更高 → fontScale = 960/900 = 1.066（字号变大 6.6%）
  --     但面板宽度 = canvasW * 0.22 = 281.6px，只有基准 352px 的 0.80
  --   → 文字变大 6.6% 而容器缩到 80%，相对溢出 1.33 倍，必然被裁。
  --
  --   所以缩放系数改成 min(宽比, 高比)：取两个方向的较小者，
  --   保证「文字永远不会比它所在的容器长得快」。
  --   【为什么这样不会影响已验证的画布】
  --     pc-16-9  1600×900  → min(1.000, 1.000) = 1.000（不变）
  --     pc-21-9  2100×900  → min(1.313, 1.000) = 1.000（不变）
  --     mobile-16-9  1280×720 → min(0.800, 0.800) = 0.800（不变）
  --     mobile-19.5-9 1560×720 → min(0.975, 0.800) = 0.800（不变）
  --     mobile-4-3   1280×960  → min(0.800, 1.067) = 0.800（**由 1.067 修正为 0.800**）
  --   只有原本就出错的那一档会变，其余四档逐位不变 —— 这是选 min 而不是换别的公式的原因。
  local fontScale = math.min(canvasW / CONFIG.BASE_CANVAS_W, canvasH / CONFIG.BASE_CANVAS_H)
  local function font(base)
    local v = math.floor(base * fontScale)
    if v < CONFIG.FONT.MIN_FONT then v = CONFIG.FONT.MIN_FONT end
    return v
  end

  return {
    canvasW = canvasW, canvasH = canvasH,
    boardSide = boardSide, cell = cell,
    boardLeft = boardLeft, boardBottom = boardBottom,
    panelW = panelW, panelLeft = panelLeft,
    panelBottom = panelBottom, panelH = panelH,
    -- 棋盘暖木外框的厚度（棋盘往外扩出这一圈）。棋盘外框、提示条、坐标三处都要用它，
    -- 所以放在唯一坐标入口里算一次，别在各区各写一遍 cell*0.16（与 Demo 的 L.framePad 同义）。
    framePad = cell * CONFIG.FRAME_PAD_RATIO,
    font = font, fontScale = fontScale,
  }
end

-- 格号 → 画布坐标（左下角原点）
function LAYOUT.square_pos(L, sq)
  local file = sq % 8
  local rank = sq // 8
  return L.boardLeft + file * L.cell, L.boardBottom + rank * L.cell
end

-- =============================================================================
-- 视角（v3.0）：黑方执棋时整盘转 180°，让黑棋落在屏幕下方
-- -----------------------------------------------------------------------------
-- 【为什么不是「把棋盘控件整体旋转 180°」】
--   棋子和格底都用文本/图片控件摆位，整体旋转会把每枚棋子也转倒（用户要求「棋子保持正立」）。
--   所以这里只做**格号映射**：逻辑格 sq ↔ 屏幕物理格 GAME.match.sq(sq)。
--   · 格底色天然对称：isDark = (rank + file) % 2，180° 旋转后 (7-r)+(7-f) ≡ r+f (mod 2)，
--     所以 64 个格底控件**一个都不用动**；
--   · 命中区建在物理格上（闭包捕获物理格号），点棋盘时再换算回逻辑格（见 on_square_clicked）；
--   · 棋子 / 高亮 / 落点 / 上一步痕迹 / 将军罩 / 走子动画全部走这个映射，
--     因为它们本来就统一用 LAYOUT.square_pos 换算坐标。
-- 【为什么是 GAME.match.sq 而不是一个 local 函数】
--   Lua 主 chunk 的 local 变量上限是 **200**，本文件已经贴着上限（v2.0 加完只剩个位数余量）。
--   实测加 15 个 local 后直接编译失败：`too many local variables (limit is 200)`。
--   所以本轮新增的谈判/视角逻辑一律挂进 GAME 表的字段（表字段不占 local），
--   定义在 GAME 声明之后（本块只留说明）。改动这里时**不要**再把它们改回 local。
-- =============================================================================

-- =============================================================================
-- 第 5 区：FACTORY（控件工厂，固定创建顺序）
--   顺序固定：创建 → 中心点 → 最小锚点 → 最大锚点 → 尺寸 → 位置 → 颜色/文本 → 启用 → 登记
--   【重要】第 4 步不能与第 5 步调换：先写位置再改锚点，位置会按旧锚点解释。
-- =============================================================================
local FACTORY = { cleanup = {}, created = 0 }

local function color_of(rgba)
  local a = rgba[4]
  if a == nil then return Color.FromRGB(rgba[1], rgba[2], rgba[3]) end
  return Color.FromRGBA(rgba[1], rgba[2], rgba[3], a)
end

-- 创建一个文本框（本项目所有可视元素都是文本框）
-- opts: {name, parent, x, y, w, h, bg, text, fontColor, fontSize, outline, outlineColor,
--        hAlign, vAlign, raycast}
local function create_text(opts)
  local ctrl = game.InstantiateClientUIControl(CONFIG.PREFAB_TEXT_BOX, opts.parent)
  if ctrl == nil then return nil end

  -- 顺序固定：中心点 → 锚点 → 尺寸 → 位置
  ctrl:SetPivot(0, 0)
  ctrl:SetAnchorMin(0, 0)
  ctrl:SetAnchorMax(0, 0)
  ctrl:SetSizeDelta(opts.w, opts.h)
  ctrl:SetAnchoredPosition(opts.x, opts.y)

  if opts.name then ctrl.name = opts.name end
  ctrl.text = opts.text or ""
  if opts.bg then ctrl.bgColor = color_of(opts.bg) end
  if opts.fontColor then ctrl.fontColor = color_of(opts.fontColor) end
  if opts.fontSize then ctrl.fontSize = opts.fontSize end
  if opts.outline then
    ctrl.enableOutline = true
    if opts.outlineColor then ctrl.outlineColor = color_of(opts.outlineColor) end
  end
  if opts.hAlign then ctrl.horizontalAlignment = opts.hAlign end
  if opts.vAlign then ctrl.verticalAlignment = opts.vAlign end

  -- 先关闭命中、保持不可见，最后由调用方显式启用
  -- raycastTarget 受 CONFIG.ENABLE_RAYCAST_FIELD 控制（见第 1 区说明）
  -- 【必须包 pcall】未实现该字段的环境会抛 "no such field"，不能让整段启动失败
  if CONFIG.ENABLE_RAYCAST_FIELD then
    pcall(function() ctrl.raycastTarget = opts.raycast and true or false end)
  end
  ctrl:SetActive(false)

  FACTORY.cleanup[#FACTORY.cleanup + 1] = ctrl
  FACTORY.created = FACTORY.created + 1
  return ctrl
end

-- 创建一个光标检测区域（棋盘格点击用）
local function create_cursor_area(opts)
  local ctrl = game.InstantiateClientUIControl(CONFIG.PREFAB_CURSOR_AREA, opts.parent)
  if ctrl == nil then return nil end
  ctrl:SetPivot(0, 0)
  ctrl:SetAnchorMin(0, 0)
  ctrl:SetAnchorMax(0, 0)
  ctrl:SetSizeDelta(opts.w, opts.h)
  ctrl:SetAnchoredPosition(opts.x, opts.y)
  if opts.name then ctrl.name = opts.name end
  -- 【必须设】不设 raycastTarget 的光标检测区收不到任何点击事件（模拟器实测）
  -- 包 pcall 以兼容未实现该字段的环境
  if CONFIG.ENABLE_RAYCAST_FIELD then
    pcall(function() ctrl.raycastTarget = true end)
  end
  ctrl:SetActive(false)
  -- 光标检测区没有可见内容，但 visible 必须为真，否则整层不参与命中测试
  pcall(function() ctrl:SetVisible(true) end)

  FACTORY.cleanup[#FACTORY.cleanup + 1] = ctrl
  FACTORY.created = FACTORY.created + 1
  return ctrl
end

-- 图片来源枚举（按配置名取；沙箱没有 StaticReference，取不到就返回 nil，调用方跳过 SetImage）
local function piece_image_source_enum()
  local name = CONFIG.PIECE_IMAGE_SOURCE or "StaticReference"
  local ok, v = pcall(function() return Enum.ImageSource[name] end)
  if ok and v ~= nil then return v end
  ok, v = pcall(function() return Enum.ImageSource.Prefab end)
  if ok and v ~= nil then return v end
  return nil
end

-- 图片拉伸类型枚举（真机是 Stretch/Basic，沙箱两者都没有，取不到就返回 nil → 不设该属性）
local function image_type_stretch()
  local ok, v = pcall(function() return Enum.ImageType.Stretch end)
  if ok and v ~= nil then return v end
  ok, v = pcall(function() return Enum.ImageType.Basic end)
  if ok and v ~= nil then return v end
  return nil
end

-- 图元种类 → 千星静态图片资产
-- 【兼容两种写法】老格式用字符串 "rect"/"circle"/"tri"，新格式（拟合生成）用数字：
--   0/4 = 矩形   1/3 = 椭圆   2 = 三角
-- 注意：数字与字符串不相等，必须先判类型，否则数字全部落到默认分支（踩过）。
local function prim_asset(kind)
  if type(kind) == "number" then
    if kind == 0 or kind == 4 then return CONFIG.PIECE_ASSET.RECT end
    if kind == 2 then return CONFIG.PIECE_ASSET.TRI end
    return CONFIG.PIECE_ASSET.CIRCLE     -- 1 与 3 都是椭圆
  end
  if kind == "rect" then return CONFIG.PIECE_ASSET.RECT end
  if kind == "tri"  then return CONFIG.PIECE_ASSET.TRI  end
  return CONFIG.PIECE_ASSET.CIRCLE
end

-- =============================================================================
-- 控件写计数（v1.11，issue #1 第 6 条的性能证据口）
-- -----------------------------------------------------------------------------
-- 「每帧几千次控件写」这类性能结论必须有可读的数字支撑，不能只靠观感。
-- 这里统计真正打到平台上的**属性写**次数，以及被「值相同」缓存跳过的次数。
-- 由 GetRepaintStats() 暴露，任何人在模拟器或真机上都能自己复测。
--
-- 【为什么定义在 ANIM 之前】image_apply 在 ANIM 区之前就要用它。
-- 它不属于动画，属于「平台写计量」，所以单独一张表，不依赖 ANIM。
-- 计数只做整数自增，开销可忽略；想彻底关掉把 CONFIG.TRACK_CONTROL_WRITES 置 false。
-- =============================================================================
local WRITE_STATS = { writes = 0, skipped = 0 }

-- 统一的控件写计数口。所有进平台的属性写调用前记一笔。
-- 【为什么用函数而不是在每个调用点 ++】写点有十几处，漏一处数字就不可信；
-- 包成函数后新增写点只调一次，以后要做「按控件分类统计」也只改这里。
local function cw()
  if CONFIG.TRACK_CONTROL_WRITES then
    WRITE_STATS.writes = WRITE_STATS.writes + 1
  end
end

-- 记一次「本来要写但值没变，跳过」——用于量化写缓存到底省了多少
local function cw_skip()
  if CONFIG.TRACK_CONTROL_WRITES then
    WRITE_STATS.skipped = WRITE_STATS.skipped + 1
  end
end

-- 【控件可见性缓存】记录每个控件当前的 active/visible 状态，供 ui_set_active 跳过重复写。
-- 必须与 IMG_STATE 一样放在控件工厂之前：工厂创建控件时是「先隐藏」的，
-- 那次写入也要登记进来，否则缓存与真实状态一开始就不同步。
local VIS_STATE = setmetatable({}, { __mode = "k" })

-- 【控件写缓存】记录「每个图片控件当前显示的是什么」，用于跳过重复写。
--
-- 【为什么不能把缓存字段挂在控件上】`ctrl.__imgAsset = x` 这类写法依赖控件对象是
-- 普通 Lua 表；平台对象可能是带严格元表的 userdata，写未知字段会抛 "no such field"。
-- 所以缓存放在脚本侧的弱键表里：控件被销毁后条目自动回收，不会泄漏。
--
-- 键是控件对象本身，值是 { asset=, color=, rot=, typeSet= }。
-- color 存的是 CONFIG.COLOR 里那张 rgba 表的**引用**，比较用 rawequal 语义（==）即可命中。
local IMG_STATE = setmetatable({}, { __mode = "k" })

local function img_state(ctrl)
  local st = IMG_STATE[ctrl]
  if st == nil then
    st = {}
    IMG_STATE[ctrl] = st
  end
  return st
end

-- 给图片控件设置「图元 + 颜色 + 旋转」。真机与沙箱能力不同，全部 pcall 包裹。
--
-- 【v1.11 两处关键修正，都对应 issue #1】
--
-- ①【旋转必须无条件写 —— 这是「多走几步后棋子错位」的根因】
--   旧写法：`if rot ~= nil and rot ~= 0 then SetLocalRotation(...) end`
--   于是 rot == 0 的形状**完全不碰旋转**，控件的 localRotationZ 保留上一次的值。
--   槽位池会被复用：一辆车被吃之后那个槽位回收，下一枚走过去的马拿到的还是同一批图元，
--   其中「旋转为 0」的那些形状就继承了车留下的角度 —— 看起来就是棋子「散架、错位」。
--   而且错位只会在走过若干手（发生吃子/换子的槽位回收）之后才出现，
--   正好符合 issue 里「多走几步棋后棋子图元开始错位」的描述。
--   现在改成：一律写入（rot 缺省按 0），不会残留。
--
-- ②【值相同就不写控件（性能）】
--   每帧脏槽位重绘时，同一批图元要重复写「图元 ID / 颜色 / 旋转」三项 —— 而这三项
--   在动画期间根本不变（动画只改尺寸与位置）。命中缓存就跳过平台调用。
local function image_apply(ctrl, asset, color, rot)
  if ctrl == nil then return end
  local st = img_state(ctrl)
  if asset and asset > 0 then
    if st.asset ~= asset then
      st.asset = asset
      local src = piece_image_source_enum()
      if src ~= nil then
        cw()
        pcall(function() ctrl:SetImage(src, asset) end)
      end
    else
      cw_skip()
    end
  end
  -- 拉伸类型只需设一次（枚举不会变）
  if not st.typeSet then
    st.typeSet = true
    local it = image_type_stretch()
    if it ~= nil then
      cw()
      pcall(function() ctrl.imageType = it end)
    end
  end
  if color ~= nil then
    if st.color ~= color then
      st.color = color
      cw()
      pcall(function() ctrl.imageColor = color_of(color) end)
    else
      cw_skip()
    end
  end
  -- 【无条件写，见上方 ①】rot 缺省按 0 处理，保证控件不会残留上一位使用者的旋转
  local r = rot or 0
  if st.rot ~= r then
    st.rot = r
    cw()
    pcall(function() ctrl:SetLocalRotation(0, 0, r) end)
  else
    cw_skip()
  end
end

-- 创建一个图片控件（棋子图元用）。
-- opts: {name, parent, x, y, w, h, asset, color, rot, pivot}
--   pivot 缺省 (0,0)（= 按左下角定位）；棋子图元必须传 0.5，
--   因为 SetLocalRotation 是绕 pivot 旋转的，用左下角做轴心会把斜置色块甩出去。
local function create_image(opts)
  if CONFIG.PREFAB_IMAGE == 0 then return nil end
  local ctrl = game.InstantiateClientUIControl(CONFIG.PREFAB_IMAGE, opts.parent)
  if ctrl == nil then return nil end
  local pv = opts.pivot or 0
  ctrl:SetPivot(pv, pv)
  ctrl:SetAnchorMin(0, 0)
  ctrl:SetAnchorMax(0, 0)
  ctrl:SetSizeDelta(opts.w, opts.h)
  ctrl:SetAnchoredPosition(opts.x, opts.y)
  if opts.name then ctrl.name = opts.name end
  image_apply(ctrl, opts.asset, opts.color, opts.rot)
  -- 先关闭命中、保持不可见，最后由调用方显式启用
  if CONFIG.ENABLE_RAYCAST_FIELD then
    pcall(function() ctrl.raycastTarget = false end)
  end
  ctrl:SetActive(false)

  FACTORY.cleanup[#FACTORY.cleanup + 1] = ctrl
  FACTORY.created = FACTORY.created + 1
  return ctrl
end

-- =============================================================================
-- 第 5.5 区：ANIM（缓动与动画调度，v1.7）
-- -----------------------------------------------------------------------------
-- 【为什么自己写缓动，不用 game.Tween】
--   ① 棋子是「一槽 9~21 个图片控件」的组合体，Tween 只能逐个控件补间，
--      一槽的图元会在不同时间落地 → 棋子走子时散架。
--   ② 本项目的动画必须能被「暂停/复盘/尺寸重建」安全打断，自己管时间轴最省事。
--   ③ 缓动函数曲线完全可控，能精确调出「快起柔落」的落子手感。
--   做法：所有动画都写成 {t, dur, fn} 任务，由 OnUpdate 单点推进；
--   每帧只推进仍活着的任务，结束自动出队。任务表元素复用，不每帧新建。
-- =============================================================================

-- 缓动函数：入参 0..1，出参 0..1
local EASE = {}

function EASE.linear(x) return x end

-- 缓出三次：位移主力曲线，起步快、收尾柔
function EASE.outCubic(x)
  local u = 1 - x
  return 1 - u * u * u
end

-- 缓出五次：更「飘」的收尾，用于落子
function EASE.outQuint(x)
  local u = 1 - x
  return 1 - u ^ 5
end

-- 缓入缓出正弦：弹窗淡入
function EASE.inOutSine(x)
  return 0.5 - 0.5 * math.cos(math.pi * x)
end

-- 回弹缓出：落子回弹（1.0 → 略微超过 1 → 稳定在 1）
function EASE.outBack(x)
  local c1, c3 = 1.70158, 2.70158
  local u = x - 1
  return 1 + c3 * u * u * u + c1 * u * u
end

local ANIM = {
  tasks = {},      -- 活动任务 { {t=0, dur=0.2, fn=function(u) end, onDone=function() end} }
  count = 0,
  clock = 0,       -- 全局动画时钟（脉冲类动画读它）
  -- ===== 脏槽位（v1.10 提速）=====
  -- 本帧「有变化的棋子槽位」，供 OnUpdate 做局部重绘（render_pieces(ANIM.dirty)）。
  -- 为什么要在动画任务里登记而不是事后 diff：动画只改 slot.x/y/scale/lift 这几个字段，
  -- 事后去 32 个槽位逐一比对这些浮点数，比「任务自己声明它动了谁」更贵也更易错。
  dirty = {},      -- ANIM.dirty[i] = slot（本帧去重后）
  dirtyCount = 0,
  -- ===== 重绘计量（v1.10 提速的诊断口，不参与玩法）=====
  -- 每帧统计「这次 render_pieces 画了几个槽位」，用于验证提速效果与回归检查。
  -- 只累加整数，开销可忽略；SelfTest 会读它判断「动画期间是否还在全量重绘」。
  paintSlotsTotal = 0,     -- 累计 paint 过的槽位数
  paintFramesFull = 0,     -- 全量重绘帧数
  paintFramesPartial = 0,  -- 局部重绘帧数
}

-- 把一个槽位登记为本帧脏（去重：同一槽位本帧多次动画只登记一次）
-- 【不去重会怎样】一枚棋子同时跑「移动 + 回弹」两段，或 board_intro 里同槽多段，
-- 不去重就会把同一个槽位 paint 两次 —— 局部重绘的意义就是省控件写，没必要重复。
local function anim_mark_dirty(slot, seen)
  if slot == nil then return end
  -- seen 由 anim_update 每帧新建，用 slot 表本身做 key 做 O(1) 去重
  if seen ~= nil then
    if seen[slot] then return end
    seen[slot] = true
  end
  ANIM.dirtyCount = ANIM.dirtyCount + 1
  ANIM.dirty[ANIM.dirtyCount] = slot
end

-- 取本帧脏槽位列表并清空（OnUpdate 调用；返回的列表只在本帧有效）
local function anim_take_dirty()
  local list, n = ANIM.dirty, ANIM.dirtyCount
  if n == 0 then return nil end
  -- 换一个空表，不破坏刚返回的 list（调用方可能在 paint 期间又产生新脏项）
  ANIM.dirty, ANIM.dirtyCount = {}, 0
  return list, n
end

-- 注册一个动画任务，返回任务表（可提前 kill）
-- slot：可选。传了就表示「这个任务每帧会改这个槽位的绘制数据」，
--       推进时自动登记脏槽位，OnUpdate 据此只重绘它（见 render_pieces 的快速路径）。
local function anim_add(dur, fn, onDone, slot)
  if dur == nil or dur <= 0 then
    if fn then fn(1) end
    if slot ~= nil then anim_mark_dirty(slot) end
    if onDone then onDone() end
    return nil
  end
  local task = { t = 0, dur = dur, fn = fn, onDone = onDone, dead = false, slot = slot }
  ANIM.count = ANIM.count + 1
  ANIM.tasks[ANIM.count] = task
  return task
end

-- 立刻使一个任务失效（不触发 onDone，避免误触发链式动画）
local function anim_kill(task)
  if task ~= nil then task.dead = true end
end

-- 推进所有动画任务（由 OnUpdate 每帧调用一次）
--
-- 【关键：不能在遍历时截断任务表】
--   task.onDone 里经常会再 anim_add 一个新任务（比如「落子回弹」接在「移动」后面）。
--   如果在循环结束后写 `ANIM.count = w`，这些本帧新加的任务会被直接丢掉，
--   表现是棋子停在半路、或开局弹入的棋子永远停在 scale=0.01 看不见。
--   正确做法：只压缩掉已完成的项，把剩下的（含本帧新加的）接在后面。
--   所以循环上界用「进入本帧时的计数」，新加的任务留到下一帧再推进。
local function anim_update(dt)
  ANIM.clock = ANIM.clock + dt
  local tasks = ANIM.tasks
  local n = ANIM.count
  local w = 0
  -- 本帧脏槽位去重表（每帧新建，不进 ANIM 持久状态）
  local seen = {}
  for i = 1, n do
    local task = tasks[i]
    if task ~= nil and not task.dead then
      task.t = task.t + dt
      local u = task.t / task.dur
      if u >= 1 then u = 1 end
      if task.fn then task.fn(u) end
      -- 【提速关键】任务推进完立刻登记它动的槽位。放在 fn 之后：这一帧的
      -- x/y/scale 已经是新值，登记后 OnUpdate 紧接着重绘就能画出新位置。
      if task.slot ~= nil then anim_mark_dirty(task.slot, seen) end
      if u >= 1 then
        task.dead = true
        if task.onDone then task.onDone() end
      else
        w = w + 1
        tasks[w] = task
      end
    end
  end
  -- 把本帧之后新增的任务（索引 n+1..ANIM.count）接到压缩后的尾部
  local tail = ANIM.count
  for i = n + 1, tail do
    local task = tasks[i]
    if task ~= nil and not task.dead then
      w = w + 1
      tasks[w] = task
    end
    -- 本帧新加的动画也要登记：它可能已经在本帧 fn(0) 里改过槽位数据
    if task ~= nil and task.slot ~= nil then anim_mark_dirty(task.slot, seen) end
  end
  for i = w + 1, ANIM.count do tasks[i] = nil end
  ANIM.count = w
end

-- 清空全部动画（重开一局/重建界面时调用，避免回调打到已销毁的控件上）
local function anim_clear()
  for i = 1, ANIM.count do
    if ANIM.tasks[i] ~= nil then ANIM.tasks[i].dead = true end
  end
  ANIM.tasks = {}
  ANIM.count = 0
  -- 脏槽位一并清掉：清空后由 reset_piece_slots + 全量 render_pieces 兜底
  ANIM.dirty = {}
  ANIM.dirtyCount = 0
end

-- 颜色按 alpha 缩放（做淡入淡出时用；其它通道不动）
local function color_alpha(rgba, k)
  if k <= 0 then k = 0 end
  if k >= 1 then return color_of(rgba) end
  local a = (rgba[4] or 255) * k
  return Color.FromRGBA(rgba[1], rgba[2], rgba[3], math.floor(a))
end

-- =============================================================================
-- 第 5.6 区：SFX（音效播放与开关，v1.10）
-- -----------------------------------------------------------------------------
-- 【为什么单独一个区】音效是横切关注点：棋盘、面板按钮、终局、棋钟都要用。
--   放在 ANIM 之后、UI 之前，是因为 UI 构建时要建「音效开关按钮」，需要 sfx_enabled。
--
-- 【平台 API】(见 get_client_document「客户端控件API文档」第 6 节 (4))
--   game.PlayAudio2D(audioId: integer) -> integer   播放 2D 音效，返回实例 ID
--   game.StopAudio(audioInstanceId: integer)
--   game.IsAudioAlive(audioInstanceId: integer)
--
-- 【为什么必须 pcall 包住】模拟器默认静音；某些环境可能根本没实现这几个函数。
--   不加保护的话第一声就把整个 OnUpdate/点击回调打断，等于游戏卡死。
--   失败只 printerr **一次**（用 log_once 思路），避免每帧刷屏把真日志淹掉。
-- =============================================================================
local SFX = {
  enabled = true,          -- 音效总开关（面板按钮控制）
  ids = {},                -- 环形缓冲：最近播过的实例 ID
  count = 0,
  head = 0,
  -- 能力探测结果：nil = 还没试过；true = 可用；false = 不可用（不再重试）
  available = nil,
  failLogged = false,      -- 失败日志是否已打过（只打一次）
  badKeyLogged = {},       -- 已报过「键名不存在」的音效名（每个键名只报一次，防刷屏）
  lowTimeFired = { [1] = false, [2] = false },   -- 双方是否已播过「剩时不足」提示
  overFired = false,       -- 终局音是否已播（防重复）
}

-- 记录一个音效实例 ID（环形缓冲，满了覆盖最旧的）
local function sfx_remember(instId)
  if instId == nil then return end
  local cap = CONFIG.SFX_HISTORY
  if cap <= 0 then return end
  SFX.head = (SFX.head % cap) + 1
  SFX.ids[SFX.head] = instId
  if SFX.count < cap then SFX.count = SFX.count + 1 end
end

-- 停掉缓冲区里所有还活着的实例（新开一局/销毁时调用，防止上一局的尾音串过来）
local function sfx_stop_all()
  for i = 1, CONFIG.SFX_HISTORY do
    local id = SFX.ids[i]
    if id ~= nil then
      pcall(function()
        -- 先问一下还活着没：对已播完的实例调 StopAudio 在部分实现里会抛错
        local alive = true
        if game.IsAudioAlive ~= nil then
          local okAlive, a = pcall(game.IsAudioAlive, id)
          if okAlive then alive = a and true or false end
        end
        if alive then game.StopAudio(id) end
      end)
    end
  end
  SFX.ids = {}
  SFX.count = 0
  SFX.head = 0
end

-- 播一个音效。
-- 【参数写法】接受 CONFIG.SFX 的键名，**大小写不敏感**：`sfx_play("move")` 与
--   `sfx_play("MOVE")` 等价。理由：CONFIG.SFX 的键按平台习惯用大写，
--   而调用点写小写更贴近 Demo 的 `SFX.play("move")` 语义（也便于
--   tools_work/consistency_check.cjs 用同一条正则同时核对两边）。
--   实现上先查原样，再查大写，两次哈希查找，开销可忽略。
-- 返回实例 ID（成功）或 nil（关闭/失败/无此键）。
local function sfx_play(name)
  if not SFX.enabled then return nil end
  if SFX.available == false then return nil end        -- 已确认平台没有此能力，直接跳过
  local id = CONFIG.SFX[name]
  if id == nil then
    local upper = string.upper(tostring(name))
    id = CONFIG.SFX[upper]
  end
  -- 【未知键名必须留痕】这里原先直接 `if id == nil then return nil end`，于是键名写错
  -- （例如把 GAME_END 写成 "over"）会**完全静默**：不播、不报错、不写日志，
  -- 只有靠人把调用点逐个对回表才能发现。实测就踩过一次（终局音永远不响）。
  -- 现在改成打一次错误日志并禁用该项，绝不静默。
  if id == nil then
    local key = tostring(name)
    if not SFX.badKeyLogged[key] then
      SFX.badKeyLogged[key] = true
      log_err("音效键名不存在：%s（CONFIG.SFX 里没有这个键，该音效不会播放）", key)
    end
    return nil
  end
  if id == 0 then return nil end                       -- 明确配置为 0 = 关闭，这是合法状态

  -- 【能力探测只做一次】第一次调用时就确定 PlayAudio2D 是否存在，
  -- 之后按 available 走，不再反复 pcall 一个必然失败的东西。
  local ok, instId = pcall(function() return game.PlayAudio2D(id) end)
  if not ok then
    SFX.available = false
    if not SFX.failLogged then
      SFX.failLogged = true
      log_err("音效不可用（game.PlayAudio2D 调用失败），已自动降级为静音：%s", tostring(instId))
    end
    return nil
  end
  SFX.available = true
  -- PlayAudio2D 可能返回 nil（静音环境/资源未配置），此时没有实例可记，不算错
  if type(instId) == "number" then sfx_remember(instId) end
  return instId
end

-- 音效开关：翻转并返回新状态
local function sfx_toggle()
  SFX.enabled = not SFX.enabled
  if not SFX.enabled then
    -- 关掉时立即停掉正在播的（否则「音效：关」之后还能听到结束音拖尾，观感很怪）
    sfx_stop_all()
  else
    -- 开回来时给一次确认音，让用户知道确实开了
    sfx_play("select")
  end
  return SFX.enabled
end

-- =============================================================================
-- 第 6 区之前：GAME 状态表（v2.0 从第 7 区搬到这里）
-- -----------------------------------------------------------------------------
-- 【为什么必须放在 UI 区之前 —— 这是模拟器实测崩溃换来的教训】
--   崩溃原文：`OnStart: sim/levelScript.lua:3348: attempt to index a nil value (global 'GAME')`
--   `show_start_screen` 定义在第 6 区（UI），函数体里写 `GAME.screen = "start"`；
--   而 `local GAME = {` 原本在其**之后**。Lua 的函数体在**编译期**就完成名字绑定，
--   那一刻作用域里还没有 `local GAME`，于是 `GAME` 被绑成 **global**；
--   运行时 global 是 nil → `GAME.screen = ...` 直接崩，`OnStart` 中断，界面没建完。
--
--   ⚠️ **这是 lua_check.cjs 的盲区**：那道检查只扫「函数名」的前向引用
--      （`foo()` 出现在 `local function foo` 之前），**不扫函数体内引用的变量**
--      是否还没声明。所以这一类 bug 静态检查永远是绿的，只有模拟器能抓。
--      自查判据：**凡「定义位置早于某个 local X」的函数，其函数体里用到 X 了吗？**
--
--   修法：GAME 是纯状态表，只依赖 CONFIG（第 1 区），不依赖任何 UI 控件，
--   本就没有理由定义在 UI 之后。整体上移后，「谁先谁后」的隐患从根上消除，
--   而不是靠再加一层 `local GAME` 前向声明去兜（那会诱导写出 `GAME = {` 这种
--   看起来像 global 赋值的写法，后人容易误解）。
-- =============================================================================
local GAME = {
  state = "NEW",        -- NEW / STARTING / RUNNING / FAILED / DESTROYED
  -- ===== 界面流程状态（v2.0）=====
  -- 【与 GAME.state 是两件事，不要合并】
  --   GAME.state  = 脚本生命周期（NEW/STARTING/RUNNING/FAILED/DESTROYED）
  --   GAME.screen = 玩家在哪个界面（start/lobby/playing/result/review）
  -- 分开的原因：SelfTest 的 `state_running` 断言守的是「脚本活着且在跑」，
  -- 那是回归基线，不能因为「启动后先进初始界面」就把它改成 FAIL。
  -- 合法值：start / lobby / playing / result / review
  screen = "start",
  -- ===== 走时档（v2.0）=====
  -- tcN = 当前选中的档位号（1..4，见 CONFIG.TIME_CONTROLS），默认 3 = 快棋 900+10。
  -- tcInitial / tcIncrement = 本局实际取用的数值，由 apply_time_control() 从档位表抄下来。
  -- 【为什么不在别处现查 TIME_CONTROLS】棋钟要每帧读，档位可能在开局后不再允许改
  -- （联机先选者锁定），所以开局那一刻把值定下来，之后只认这两个字段。
  tcN = 3,
  tcInitial = 900,
  tcIncrement = 10,
  -- ===== 待机室（v2.0 块 2）=====
  -- 【为什么需要这些】千星客户端 Lua 读不到房间成员列表/昵称（gdd §10.2 U-1），
  -- 所以「对手是否存在」只能靠**信号握手**推算：收到过任何对方包就认为对手在线。
  lobby = {
    myReady = false,        -- 本端就绪
    peerReady = false,      -- 对方就绪（收到 EV_READY 后写入）
    peerSeen = false,       -- 是否收到过任何对方信号（决定「等待加入…」还是「未准备」）
    peerSeenAt = 0,         -- 首次/最近一次收到对方信号的时刻（用累加 dt，不读 os.time）
    tcOwner = 0,            -- 档位归属：0=还没人选 1=你选定 2=对手选定
    tcLocked = false,       -- 档位是否已锁定（锁定后档位卡全部置灰）
    countdown = -1,         -- <0 = 未在倒数；>=0 = 剩余秒数（逐帧减 dt）
    countdownShown = -1,    -- 上一帧显示的整数秒（只在变化时写控件）
    peerLeft = false,       -- 对方显式取消准备（用于「已取消准备」提示）
    timeoutShownOnce = false, -- 超时提示是否已刷过（避免每帧刷文案）
    -- 【v2.0 方案 T：这两个字段已不再用于「等待对端开局」】
    -- 原设计（方案 A）是「倒数跑完 → 等 EV_START 再进 playing」，但它把 EV_START
    -- 当成开局前置条件，对端掉线时会卡在中间态。现在改成「倒数跑完 → 立即本地开局，
    -- 再 fire-and-forget 通知对端」。字段保留仅为兼容旧断言/调试读取，恒为 false。
    awaitStart = false,
    awaitStartAt = 0,
  },
  -- ===== 联机快速开局协商（v3.0）=====
  -- 【与 GAME.lobby 的区别】lobby 是「双方各点准备」的旧待机室状态机（已从运行时摘除）；
  -- 这里是「在初始界面各选一个时间档」的协商状态。两套不要混用。
  -- 【时间口径】所有相对时间都用 GAME.onlineClock（OnUpdate 累加 dt），
  -- 与棋钟/待机室同一纪律：不读 os.time，不受关卡时停影响。
  online = {
    myTier = nil,        -- 我选的档位号（nil = 还没选）
    myRand = nil,        -- 本端随机数（每次点卡片重摇；黑白与随机裁决都用它）
    myFen = nil,         -- 本端最新标识字符串（放进信号 fen 槽）
    myFens = {},         -- 历史标识集合（旧回声仍要认成「自己的」）
    peerFen = nil,       -- 对方标识
    peerTier = nil,      -- 对方当前所选档位
    peerRand = nil,      -- 对方随机数（从对方标识里解析）
    peerSeenAt = nil,    -- 最近一次收到对方包的 onlineClock 时刻
    conflictAt = nil,    -- 判定到「两人档位不同」的时刻（nil = 没有冲突窗口）
    conflictPeer = nil,  -- 冲突时的对方档位（仅用于文案对照）
    hbAt = 0,            -- 心跳计时
    announced = false,   -- 是否点过第三入口（仅影响文案）
  },
  onlineClock = 0,       -- 联机协商时钟（秒，OnUpdate 累加）
  -- ===== v3.0 联机快速开局 / 视角 =====
  -- 【为什么函数挂在这张表上】Lua 主 chunk 的 local 上限 200，本文件已贴着上限；
  --   实测新增 15 个 local 就编译失败（too many local variables）。
  --   表字段不占 local，所以 GAME.match.* 承载「视角映射 + 选时间协商」的全部函数，
  --   定义在 GAME 声明之后。**后续改动不要把它们改回 local。**
  match = {
    flip = false,        -- 黑方视角：true 时整盘格号镜像（定义见第 4 区说明）
    tmplSub = "",        -- 缓存位（避免每帧重复建字符串对象）
  },
  -- ===== 悔棋（v2.0 块 3）=====
  -- undoLeft[1] = 白方剩余次数，undoLeft[2] = 黑方剩余次数。
  -- 【为什么按「方」而不是按「玩家」】同屏时同一人操作两色，按方计数才对得上
  -- gdd §7.8 的计数表（白发起 → 白 2 黑 3）。
  undoLeft = { [1] = 3, [2] = 3 },
  -- 联机悔棋请求的等待态：nil = 无请求；{ byMe = bool, t = 已等待秒数 }
  pendingUndo = nil,
  -- 【v3.3 已删除】reviewBranch 字段（复盘分支试走的状态）。
  -- 分支试走随「退回主变」一起移除，这个字段不再有任何读写方。
  -- ===== 自检期间的重入闸（v2.0 块 5）=====
  -- true 时：net_send_event 直接返回 false（不发包）；start_game_from_lobby 不真正开局。
  -- 【为什么需要】SelfTest 在每次 OnStart 都跑。有些断言要「试着发个包」验证降级不崩，
  -- 不拦就会真的广播给所有玩家（实测 playerCount=2 时一次 start 冒出 4 条自检包）。
  -- 【纪律】自检必须零副作用。见 net_send_event 开头的完整说明。
  inSelfTest = false,
  -- ===== 自发包识别 token（v2.0 方案 T）=====
  -- 【为什么需要】服务端「收到即广播给所有人（含发送者）」，而官方 API
  -- **不提供任何发送者身份**（已查《客户端控件API文档》全文：
  --   playerIndex / GetPlayerIndex / selfPlayer / GetLocalPlayer 全部不存在；
  --   RegisterServerSignalHandler 回调只给 signalName + 参数数组）。
  -- 所以无法靠「谁发的」区分回声。
  -- 【解法】不需要知道「谁发的」，只需要知道「**这是不是我发的**」：
  --   发送时生成一个只在本端存在的 token 塞进 fen（该参数此前完全未使用），
  --   收到时先比对 token —— 等于自己的就是回声，忽略。
  -- 【失败模式是安全的】万一两端 token 撞车：
  --   互相当作自己的回声 → peerReady 都不置位 → 走 15 秒兜底 → 单人模式
  --   → 表现为「没等到另一位玩家，也可以直接开始」→ **不会误开局**。
  --   这是一个「错了也不会坏」的设计。
  __myReadyToken = nil,     -- 最近一次发出的 EV_READY 的 token
  __myStartToken = nil,     -- 最近一次发出的 EV_START 的 token
  __tokenSeq = 0,           -- 自增序号，保证同一次启动内唯一
  st = nil,             -- 棋局状态
  selected = nil,       -- 选中的格号
  legalTargets = {},    -- 当前选中子的合法落点 { sq = true }
  legalMoves = {},      -- 当前选中子的合法走法列表
  pendingPromo = nil,   -- 待升变的走法
  over = false,
  resultText = nil, resultSub = nil,
  clockWhite = 900, clockBlack = 900,
  clockAccum = 0,
  turnCount = 0,
  moveLog = {},         -- { "白 e2→e4", ... }
  capturedWhite = {},   -- 白方被吃掉的子（字母）
  capturedBlack = {},
  lastFrom = nil, lastTo = nil,
  mySide = 1,           -- 联机模式：1=白 2=黑；本地同屏时无意义
  localMode = false,    -- 是否同屏模式
  drawCooldown = { [1] = 0, [2] = 0 },
  drawReqSent = false,   -- 我刚发出求和请求（用于丢弃服务端广播回来的自己那条）
  lastSentMove = nil,    -- 我刚发出的走子 {from,to,promo}（用于丢弃自己走子的回声）
  elapsedSec = 0,       -- 本局已用时（结算说明行用）
  confirmKind = nil,   -- 当前确认弹窗类型（resign/newgame/switch/draw）
  -- ===== 复盘（v1.6）=====
  -- history[1] 恒为开局快照，之后每走一步追加一项。
  -- 复盘中所有渲染都读 history[idx+1]，绝不改 GAME.st（退出后原局面原样继续）。
  history = {},
  review = nil,         -- nil = 正常；{ idx = 0..N } = 复盘中（idx 0 是开局）
  reviewState = nil,    -- 复盘当前步 parse 出来的局面（翻页时更新）
  startupRetry = 0,
  lastCanvasW = nil, lastCanvasH = nil,
  clockTextTimer = 0,
  uiReady = false,
  animated = true,      -- 是否启用动画（v1.7）。关掉后所有动画立即到达终态，便于截图取证
}

-- =============================================================================
-- 第 6 区：UI（界面构建）
-- =============================================================================
local UI = {
  L = nil,
  squares = {},        -- squares[sq] = 棋盘格底控件
  pieces = {},         -- pieces[sq] = 棋子文本框控件
  pieceSlots = {},     -- 棋子槽位池（每槽 = 圆盘2 + 棋符1；按 32 个同时在场建）
  slotShown = 0,       -- 上一帧用到的槽位数（用于把多余槽位隐藏，避免无谓 setter）
  hitAreas = {},       -- hitAreas[sq] = 光标检测区
  legalHL = {},        -- 落点高亮池
  legalHLUsed = 0,
  selHL = nil,         -- 选中高亮
  lastMoveHL = {},     -- 上一步痕迹（2 个）
  checkHL = nil,       -- 将军警示
  coords = {},
  -- 【v3.0】坐标标注按「第几个 file / 第几个 rank」单独登记：视角翻转时只改这两组文案。
  -- 位置不动 —— 它们本来就压在格线上，翻转只影响「这一列该显示哪个字母」。
  coordFiles = {},      -- coordFiles[f] = 第 f 列（0..7，自左而右）的字母控件
  coordRanks = {},      -- coordRanks[r] = 第 r 行（0..7，自下而上）的数字控件
  panel = {},
  result = {},
  promo = {},
  confirm = {},
  review = {},        -- 复盘面板按钮与命中区（v1.6）
  built = false,
  -- ===== 初始界面（v2.0）=====
  -- parts = 整层的全部控件，进/出时一次性全切（Lead 明确要求，别散落调用）。
  -- bands = 24 条渐变带（与主背景逐条同值，见 bg_color_sample）。
  startScreen = { parts = {}, bands = {}, cards = {}, entries = {} },
  -- ===== 待机室（v2.0 块 2）=====
  -- parts 与 startScreen.parts 同样的用法：进/出时一次性全切，不散落调用。
  lobby = { parts = {} },
}

-- =============================================================================
-- 背景竖向渐变采样（v2.0 从 build_all_ui 内提升到模块级）
-- -----------------------------------------------------------------------------
-- 【为什么必须提升】初始界面要做成「盖在最上层的不透明整层」，它需要一份
-- **与主背景逐条同值**的渐变。若在 build_start_screen 里另抄一份插值逻辑，
-- 两处的取整/停靠点一旦漂移，就会在边缘看到两层背景的色差接缝。
-- 现在两处都调这一个函数 → 采样式唯一 → 不可能色差。
--
-- 平台图元不支持真渐变，只能用「多条横向色带」逼近竖向渐变。
-- 【浅色主题必须加密色带】v1.7 用的是 3 条（各 300px）：
--   深靛蓝外壳下 234/242/248 这种相邻只差 ~8 点亮度、画布本身又暗，分界根本看不出来；
--   换成浅米外壳后，同样的三档在浅底上会显出**两条硬横线**（模拟器截图实测）。
-- Demo 用的是真 linear-gradient（0% / 46% / 100% 三个停靠点），
-- 这里按同样的停靠点做线性插值 + 24 条色带，肉眼即连续渐变。
-- =============================================================================
local BG_STOPS = {
  { 0.00, CONFIG.COLOR.BG_BOTTOM },   -- 画布最下
  { 0.46, CONFIG.COLOR.BG },          -- 与 Demo 的 46% 停靠点一致
  { 1.00, CONFIG.COLOR.BG_TOP },      -- 最上
}

-- 在 t（0=画布底, 1=画布顶）处对三段停靠点做线性插值
local function bg_color_sample(t)
  local last = BG_STOPS[#BG_STOPS]
  if t <= BG_STOPS[1][1] then
    local c = BG_STOPS[1][2]
    return { c[1], c[2], c[3], 255 }
  end
  if t >= last[1] then
    return { last[2][1], last[2][2], last[2][3], 255 }
  end
  for i = 2, #BG_STOPS do
    local a, b = BG_STOPS[i - 1], BG_STOPS[i]
    if t <= b[1] then
      local span = b[1] - a[1]
      local k = (span > 0) and ((t - a[1]) / span) or 0
      local ca, cb = a[2], b[2]
      -- +0.5 再取整 = 四舍五入，避免连续渐变出现人为的整体偏暗
      return {
        math.floor(ca[1] + (cb[1] - ca[1]) * k + 0.5),
        math.floor(ca[2] + (cb[2] - ca[2]) * k + 0.5),
        math.floor(ca[3] + (cb[3] - ca[3]) * k + 0.5),
        255,
      }
    end
  end
  return { last[2][1], last[2][2], last[2][3], 255 }
end

-- =============================================================================
-- 文本排版的唯一算式（v2.0 块 2 收口，与 Demo 侧 fitH / fontForH 同构）
-- -----------------------------------------------------------------------------
-- 【一对互逆函数】
--   fit_h(字号)      → 装得下该字号所需的最小板高（px）
--   font_for_h(板高) → 该板高能装下的最大字号（px）
--
-- 【依据】平台文本布局：可用高 ≈ 板高 − 0.9×字号，行高 ≈ 1.2×字号
--   ⇒ 板高 ≥ 2.1 × 字号
--
-- 【为什么要收成函数】「整行被吞」在本项目已踩 6 次，全部是同一根因：
--   手写字号字面量、没有和板高绑定。收成互逆函数后，任何新增文本控件
--   只要从它们取值，该类 bug 在数学上不可能发生。
--
-- 【+1 的意义】取整会留 0.4px 级别的负误差，+1 把误差推到安全侧
--   （不加时 100.8 会因浮点判成 < 100.8 而假红）。
-- =============================================================================
local function fit_h(fontSize)
  local f = math.max(1, math.floor(fontSize or 1))
  return math.ceil(f * CONFIG.V2_H_RATIO) + 1
end

local function font_for_h(hPx)
  local h = hPx or 0
  local f = math.floor(h / CONFIG.V2_H_RATIO)
  if f < CONFIG.FONT.MIN_FONT then f = CONFIG.FONT.MIN_FONT end
  return f
end

-- =============================================================================
-- 走时档的纯查询函数（v2.0）
-- -----------------------------------------------------------------------------
-- 【为什么必须放在这里（UI 区之前）】build_start_screen 建 4 张档位卡时要调
-- tc_meta_lines() 生成卡上文案。Lua 的 local function 是词法向前作用域，
-- 放到 GAME 区（UI 之后）就会变成 nil 调用 —— 这正是本项目最致命的那类 bug，
-- 实测被 tools_work/lua_check.cjs 的「先用后定义」检查抓到过一次（本次 v2.0 块1）。
-- 所以：**凡是 UI 建控件时要读的档位辅助函数，一律放在第 6 区之前。**
-- =============================================================================

-- 按档位号取档位表项；越界或非法一律回落到默认档（3 = 快棋）。
-- 【为什么兜底而不是返回 nil】档位号会随联机信号从网络进来（EV_START 的 b 参数），
-- 对端版本不一致或信号被污染时可能收到 0/99。返回 nil 会让调用方连环判空，
-- 而「回落到默认档」既不会崩、也不会让棋钟变成 0:00 直接判负。
local function tc_of(n)
  local list = CONFIG.TIME_CONTROLS
  if type(n) == "number" then
    for i = 1, #list do
      if list[i].n == n then return list[i] end
    end
  end
  for i = 1, #list do
    if list[i].n == CONFIG.DEFAULT_TIME_CONTROL then return list[i] end
  end
  return list[3]   -- 表被改坏时的最后兜底
end

-- 档位卡上的首钟文本。
-- 【必须与面板棋钟 format_clock 同格式（mm:ss），不要用小时格式】
--   面板棋钟走的是 format_clock → 5400 秒显示 "90:00"。
--   若档位卡写 "1:30:00" 而进棋盘后棋钟显示 "90:00"，玩家会以为选错了档。
--   两处必须让人一眼看出是同一个数 —— 所以这里刻意不做小时/分钟换算。
--   （format_clock 定义在 GAME 区更后面，词法顺序上这里不能调它，
--     所以本函数是它的等价实现；两者算法必须保持一致：floor 后 m = t//60, s = t%60。）
local function format_clock_long(sec)
  local total = math.floor(sec or 0)
  if total < 0 then total = 0 end
  return string.format("%02d:%02d", total // 60, total % 60)
end

-- 生成档位卡的三行说明（首钟 / 加秒 / 预估）
local function tc_meta_lines(tc)
  local clockTxt = string.gsub(CONFIG.TEXT.TC_CLOCK, "{c}", format_clock_long(tc.initial))
  local incTxt
  if tc.inc and tc.inc > 0 then
    incTxt = string.gsub(CONFIG.TEXT.TC_INC, "{i}", tostring(tc.inc))
  else
    incTxt = CONFIG.TEXT.TC_INC_ZERO
  end
  local estTxt = string.gsub(CONFIG.TEXT.TC_EST, "{e}", tc.est or "")
  return clockTxt, incTxt, estTxt
end

-- 建棋子槽位池（一次性建好，播放期只移动/改色/切显隐，零创建零销毁）。
-- 每个槽位 = PRIM_MAX 个图片控件组成的图元池。
-- 播放期只改尺寸/位置/颜色/显隐，不新建也不销毁（release 21 硬约束）。
-- 【注意】PRIM_MAX 必须在 build_board 之前由 piece_prim_max() 校正完毕。
local function create_piece_slots()
  for i = 1, CONFIG.PIECE_MAX_SLOTS do
    local slot = { sq = nil, prims = {}, anim = nil }
    for k = 1, PRIM_MAX do
      slot.prims[k] = create_image({
        name = "p" .. i .. "_prim" .. k, parent = UI.host,
        x = 0, y = 0, w = 1, h = 1, asset = CONFIG.PIECE_ASSET.CIRCLE,
        pivot = 0.5,   -- 图元绕自身中心旋转
      })
    end
    UI.pieceSlots[i] = slot
  end
end
local function build_board()
  local L = UI.L

  -- ===== 棋盘外框（视觉锚点：让棋盘「立」在画面上）=====
  -- ① 外框投影：比棋盘大一圈的暖褐色块，靠下偏移 → 棋盘有厚度。
  -- 【浅色主题注意】投影色不能再是纯黑（浅米底上会出现一圈脏灰），
  -- 改用 Demo 的 rgba(120,88,58,…) 同色系暖褐，见 CONFIG.COLOR.BOARD_SHADOW。
  local framePad = L.framePad
  local bx, by = L.boardLeft, L.boardBottom
  local bs = L.boardSide
  UI.frameShadow = create_text({
    name = "boardshadow", parent = UI.host,
    x = bx - framePad, y = by - framePad * 1.9,
    w = bs + framePad * 2, h = bs + framePad * 2,
    bg = CONFIG.COLOR.BOARD_SHADOW, text = "",
  })
  -- ② 外框本体（暖木）
  UI.frame = create_text({
    name = "boardframe", parent = UI.host,
    x = bx - framePad, y = by - framePad,
    w = bs + framePad * 2, h = bs + framePad * 2,
    bg = CONFIG.COLOR.BOARD_FRAME, text = "",
  })
  -- ③ 外框内圈高光（比本体再内收一点，形成 2px 亮边）
  local innerPad = framePad * 0.55
  UI.frameInner = create_text({
    name = "boardframeinner", parent = UI.host,
    x = bx - innerPad, y = by - innerPad,
    w = bs + innerPad * 2, h = bs + innerPad * 2,
    bg = CONFIG.COLOR.BOARD_FRAME_IN, text = "",
  })

  -- ===== 棋盘格底 64 =====
  for sq = 0, 63 do
    local x, y = LAYOUT.square_pos(L, sq)
    local isDark = ((sq // 8) + (sq % 8)) % 2 == 0
    UI.squares[sq] = create_text({
      name = "sq_" .. tostring(sq),
      parent = UI.host, x = x, y = y, w = L.cell, h = L.cell,
      bg = isDark and CONFIG.COLOR.SQ_DARK or CONFIG.COLOR.SQ_LIGHT,
      text = "",
      raycast = false,
    })
  end

  -- 坐标标注：列 a-h（棋盘下方）、行 1-8（棋盘左侧）
  -- 【浅色主题连带项：必须让开暖木外框】v1.7 起棋盘外面多了一圈 framePad = cell*0.16 的外框。
  -- 原坐标（boardBottom - coordStrip）会把文字中线压在木框上：木框 150,112,82 配 TEXT_DIM
  -- 150,144,136 对比度只有 ~1.2:1，视觉上等于坐标消失（Demo 实测同一处）。
  -- 因此整体再外推 framePad + 2px，让坐标「贴着外框外侧」立在浅米外壳上（与 Demo 一致）。
  -- 颜色同时由 TEXT_DIM 改成 TEXT_SUB：外壳底 242,239,234 上 TEXT_DIM 只有 2.8:1，
  -- 低于正文可读下限；TEXT_SUB 是 4.9:1，小字号坐标读得清（Demo 第 1305 行同一个取舍）。
  local coordFont = L.font(CONFIG.FONT.COORD)
  local coordStrip = coordFont * 1.0   -- 坐标条宽度（按字号）
  local coordOut = L.framePad + 2      -- 让开暖木外框 + 2px 呼吸
  -- 【v3.0 修：棋盘下方 a~h 一个字母都不显示（D-02 陷阱，本项目第 N 次）】
  -- 平台文本布局：可用高 ≈ 控件高 − 0.9×字号，行高 ≈ 1.2×字号 ⇒ 板高必须 ≥ 2.1×字号。
  -- 旧代码给字母盒子的高只有 coordStrip = 字号 = 22px → 文字被整行吞掉
  -- （模拟器实测：左侧 1~8 清清楚楚，下方 a~h 完全空白）。
  -- 行号一直没事，是因为它的盒子高 = 格宽 87.75px。
  -- 修法：字母盒高度按 2.1×字号撑开，**顶边保持原来的位置**（文字基线不往下漂太多），
  -- 盒子向下长 —— 下方本来就有 99px 的空白外壳，不会压到任何东西。
  local coordBoxH = math.max(coordStrip, coordFont * 2.1 + 1)
  for f = 0, 7 do
    local letter = string.char(string.byte("a") + f)
    -- 【v3.0】除了进 UI.coords（统一显隐用），还要按「file 序号」单独登记一份，
    -- 视角翻转时 GAME.match.set_flip 只改这两组控件的文案（位置不动：它们本来就在格线上）。
    local ctrl = create_text({
      name = "coordF" .. tostring(f),
      parent = UI.host,
      x = L.boardLeft + f * L.cell,
      y = L.boardBottom - coordOut - coordBoxH,
      w = L.cell, h = coordBoxH,
      text = letter,
      fontColor = CONFIG.COLOR.TEXT_SUB, fontSize = coordFont,
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })
    UI.coords[#UI.coords + 1] = ctrl
    UI.coordFiles[f] = ctrl
  end
  for r = 0, 7 do
    local ctrl = create_text({
      name = "coordR" .. tostring(r),
      parent = UI.host,
      x = L.boardLeft - coordStrip - coordOut,
      y = L.boardBottom + r * L.cell,
      w = coordStrip, h = L.cell,
      text = tostring(r + 1),
      fontColor = CONFIG.COLOR.TEXT_SUB, fontSize = coordFont,
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })
    UI.coords[#UI.coords + 1] = ctrl
    UI.coordRanks[r] = ctrl
  end

  -- 上一步痕迹（2 个，覆盖在格底之上、棋子之下）：半透明淡金薄罩
  for i = 1, 2 do
    UI.lastMoveHL[i] = create_text({
      name = "lastmove" .. tostring(i), parent = UI.host,
      x = 0, y = 0, w = L.cell, h = L.cell,
      bg = CONFIG.COLOR.LAST_MOVE, text = "",
    })
  end

  -- 将军警示（1 个）：红色薄罩 + 中间再压一个更亮的同心块做「发光」感
  UI.checkHL = create_text({
    name = "checkwarn", parent = UI.host,
    x = 0, y = 0, w = L.cell, h = L.cell,
    bg = CONFIG.COLOR.CHECK_WARN, text = "",
  })

  -- 落点高亮池：后最多 27 个落点，留 1 个余量
  -- 【用图片控件而不是文本框】空格的落点要画成**圆点**，文本框只能画矩形；
  -- 图片控件用椭圆图元 100002 染色即可，且能和棋子共用同一套 pivot=0.5 定位。
  for i = 1, 28 do
    UI.legalHL[i] = create_image({
      name = "legalhl" .. tostring(i), parent = UI.host,
      x = 0, y = 0, w = L.cell, h = L.cell,
      asset = CONFIG.PIECE_ASSET.CIRCLE,
      color = CONFIG.COLOR.LEGAL_HL,
      pivot = 0.5,
    })
  end

  -- 选中高亮（1 个）：薄罩 + 上/下两条亮边框，让它看起来像「被拿起来的那一格」
  -- 【为什么不用四边框】图元只能画实心块，四条边要 4 个控件；
  -- 上下两条已经足够把格子「框住」，配合薄罩辨识度够，还省控件。
  UI.selHL = create_text({
    name = "selhl", parent = UI.host,
    x = 0, y = 0, w = L.cell, h = L.cell,
    bg = CONFIG.COLOR.SEL_HL, text = "",
    raycast = false,
  })
  local ringT = math.max(2, L.cell * 0.055)
  UI.selRingTop = create_text({
    name = "selringtop", parent = UI.host,
    x = 0, y = 0, w = L.cell, h = ringT,
    bg = CONFIG.COLOR.SEL_RING_A, text = "",
    raycast = false,
  })
  UI.selRingBot = create_text({
    name = "selringbot", parent = UI.host,
    x = 0, y = 0, w = L.cell, h = ringT,
    bg = CONFIG.COLOR.SEL_RING_B, text = "",
    raycast = false,
  })
  UI.selRingW = ringT

  -- ===== 棋子槽位池（32 个同时在场；播放期零创建）=====
  -- 【位置很关键】必须在命中区之前建：同级后出现的在上，
  -- 棋子图元若建在命中区之后就会把棋盘点击挡住（v1.5 踩过，见 tech-architecture 第六节）。
  create_piece_slots()

  -- 点击检测区 64（盖在格子之上，接收点击；不读坐标，闭包捕获格号）
  for sq = 0, 63 do
    local x, y = LAYOUT.square_pos(L, sq)
    UI.hitAreas[sq] = create_cursor_area({
      name = "hit_" .. tostring(sq),
      parent = UI.host, x = x, y = y, w = L.cell, h = L.cell,
    })
  end
  -- 【关键】把 64 个命中区提到最顶层。
  -- build_board 之后建的棋子图元 / 高亮层是同级后出现的节点，会盖在命中区之上挡住点击
  -- （模拟器实测：不提升则棋盘完全点不动）。
  for sq = 0, 63 do
    local c = UI.hitAreas[sq]
    if c ~= nil then pcall(function() c:SetAsLastSibling() end) end
  end
end

local function build_panel()
  local L = UI.L
  local px, py, pw, ph = L.panelLeft, L.panelBottom, L.panelW, L.panelH
  -- 面板内相对位置：x 从左 0..1，y 从下 0..1
  local function atX(r) return px + pw * r end
  local function w(r) return pw * r end
  local function h(r) return ph * r end
  -- 【v1.11 纵向排布的唯一来源】CONFIG.PANEL_LAYOUT[name] = { y=下边缘比例, h=高度比例 }
  -- 任何一项都必须直接查表，不许再写裸数字 —— 旧版就是在各处写 atY(0.52)/atY(0.46)/atY(0.338)
  -- 导致失子行与走子记录区重叠（issue #1 第 3 条）。
  local PL = CONFIG.PANEL_LAYOUT
  local function band(name)
    local b = PL[name]
    return atX(0.04), py + ph * b.y, w(0.92), h(b.h)
  end
  -- 内嵌底（比文字块缩进一点，看起来像「卡片里的一格」）
  local function bandInner(name)
    local b = PL[name]
    return atX(0.05), py + ph * b.y, w(0.90), h(b.h)
  end

  -- ===== 面板底（三层：投影 → 卡片 → 内嵌高光边）=====
  -- 设计：面板不再是一块纯色，而是「浮在底上的卡片」，有投影和 1px 描边，
  -- 【浅色主题】靠**描边界**而不是靠色差：卡片 252,250,247 与外壳 242,239,234 只差 ~10
  -- 点亮度，必须用 PANEL_EDGE 描边 + 暖褐投影把层次拉开（与 Demo 的 .panel 一致）。
  local cardPad = L.cell * 0.10
  UI.panel.shadow = create_text({
    name = "panelshadow", parent = UI.host,
    x = px - cardPad * 0.7, y = py - cardPad * 1.3,
    w = pw + cardPad * 1.4, h = ph + cardPad * 1.4,
    bg = CONFIG.COLOR.PANEL_SHADOW, text = "",
  })
  -- 卡片描边：Demo 的 .panel 是 `border: 1px solid var(--c-panel-edge)`（四边）。
  -- 【浅色主题必须描边】卡片 252,250,247 与外壳 242,239,234 只差 ~10 点亮度，
  -- 不描边就分不出「面板到哪儿结束」。平台文本框没有 border 字段，
  -- 所以用「一块比卡片大 2×edgeT 的描边色块 + 卡片压在它上面」拼出四边框。
  -- 【创建顺序】描边框必须在卡片**之前**建：同级后出现的在上，反过来会盖住卡片。
  local edgeT = math.max(1, L.cell * 0.012)   -- 描边厚度 ≈ 1px @81px 格宽
  UI.panel.edgeBox = create_text({
    name = "paneledge", parent = UI.host,
    x = px - edgeT, y = py - edgeT,
    w = pw + edgeT * 2, h = ph + edgeT * 2,
    bg = CONFIG.COLOR.PANEL_EDGE, text = "",
  })
  UI.panel.bg = create_text({
    name = "panelbg", parent = UI.host, x = px, y = py, w = pw, h = ph,
    bg = CONFIG.COLOR.PANEL_BG, text = "",
  })
  -- 卡片顶部描边（保留原控件名，语义从「高光」改成「描边」）
  UI.panel.topEdge = create_text({
    name = "paneltopedge", parent = UI.host,
    x = px, y = py + ph - edgeT, w = pw, h = edgeT,
    bg = CONFIG.COLOR.PANEL_EDGE, text = "",
  })

  -- 标题
  do
    local bx, by, bw, bh = band("TITLE")
    UI.panel.title = create_text({
      name = "paneltitle", parent = UI.host,
      x = bx, y = by, w = bw, h = bh,
      text = CONFIG.TEXT.PANEL_TITLE, fontColor = CONFIG.COLOR.TEXT_MAIN,
      fontSize = L.font(CONFIG.FONT.PANEL_TITLE),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })
  end

  -- 轮次指示：做成一条「状态条」——底色随走子方切换，文字用强调色
  -- 【浅色主题】底色用 PANEL_SECTION(238,234,227) 而不是 PANEL_INNER：
  -- Demo 的 panelturn 背景就是 --c-panel-sec（chess_demo.html 第 197 行），
  -- 比卡片 252,250,247 略深一档，强调色字压上去才立得住。
  do
    local bx, by, bw, bh = band("TURN")
    UI.panel.turnBg = create_text({
      name = "panelturnbg", parent = UI.host,
      x = bx, y = by, w = bw, h = bh,
      bg = CONFIG.COLOR.PANEL_SECTION, text = "",
    })
    UI.panel.turn = create_text({
      name = "panelturn", parent = UI.host,
      x = bx, y = by, w = bw, h = bh,
      text = CONFIG.TEXT.TURN_WHITE, fontColor = CONFIG.COLOR.TEXT_ACCENT,
      fontSize = L.font(CONFIG.FONT.PANEL_BODY),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })
  end

  -- ===== 棋钟：v1.11 改为**并排一行**（白左黑右）=====
  -- 【为什么并排】旧版上下各占一行 9% 高，两行加间隔要 18.8% 的面板高度，
  -- 直接把失子区和走子记录区挤到重叠（issue #1 第 3 条）。并排后只占 8.8%，
  -- 省出的空间全部给走子记录（6 行要 21.8%），失子行才有地方站。
  -- 字号同步从 36 降到 28：并排后每半格宽只有 ~0.44×pw，1600 画布下 ≈ 154px，
  -- 36 号字「白 15:00」实测宽约 148px，几乎顶满、手机 1280 下会换行被截断。
  do
    local bx, by, bw, bh = band("CLOCKS")
    local half = bw * 0.5
    UI.panel.clockWhiteBg = create_text({
      name = "clockwhitebg", parent = UI.host,
      x = bx, y = by, w = half, h = bh,
      bg = CONFIG.COLOR.PANEL_INNER, text = "",
    })
    UI.panel.clockBlackBg = create_text({
      name = "clockblackbg", parent = UI.host,
      x = bx + half, y = by, w = half, h = bh,
      bg = CONFIG.COLOR.PANEL_INNER, text = "",
    })
    UI.panel.clockWhite = create_text({
      name = "clockwhite", parent = UI.host,
      x = bx, y = by, w = half, h = bh,
      text = "白 15:00", fontColor = CONFIG.COLOR.TEXT_MAIN,
      fontSize = L.font(CONFIG.FONT.CLOCK),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })
    UI.panel.clockBlack = create_text({
      name = "clockblack", parent = UI.host,
      x = bx + half, y = by, w = half, h = bh,
      text = "黑 15:00", fontColor = CONFIG.COLOR.TEXT_MAIN,
      fontSize = L.font(CONFIG.FONT.CLOCK),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })
  end

  -- ===== 吃子成就区（v3.2，用户要求「用棋子图案表达有哪些子被吃了」）=====
  -- 【布局】整块 CAP_AREA（0.360..0.578，与原走子记录同高）内部再分四段：
  --   第 1 行标签（对方被吃的子） → 第 1 行图案 → 第 2 行标签（我方被吃的子） → 第 2 行图案
  -- 【方向由视角决定】见 render_captured：执黑时翻转，让「对方」始终出现在上面。
  -- 【为什么每方 16 枚】一方最多被吃 15 枚（16 枚减掉一个王，王不可能被吃），
  --   多建 1 个余量，避免任何边界情况下「少画一枚」。
  -- 【控件预算】每枚小棋子最多 34 个图元 × 16 × 2 方 ≈ 1088 个图片控件。
  --   这是一次性建好的固定池（不随对局增删），与棋子槽位池同一个思路。
  --
  -- 【v3.2 说明】旧的两行文字吃子行（capturedWhite / capturedBlack）已不再创建：
  --   吃子改由本区里的棋子图案承担。布局表里的 CAP_WHITE / CAP_BLACK
  --   键保留只为与 proto/chess_demo.html 的 const PL 取并集比对时不报缺项。
  do
    local ax, ay, aw, ah = band("CAP_AREA")
    -- 底色：与旧走子记录同一块「记事板」色，让两块区域观感一致
    local ix, iy, iw, ih = bandInner("CAP_AREA")
    UI.panel.capAreaBg = create_text({
      name = "capareabg", parent = UI.host,
      x = ix, y = iy, w = iw, h = ih,
      bg = CONFIG.COLOR.PANEL_INNER, text = "",
    })

    local labelH = math.max(L.font(CONFIG.FONT.CAP_LABEL) * 2.2, ah * 0.14)
    local rowH = (ah - labelH * 2) / 2          -- 每行图案区高度
    local capFont = L.font(CONFIG.FONT.CAP_LABEL)

    -- 【v3.2 让空区读作「区域」而不是「漏画」】底板之上再加两样东西：
    --   ① 中间一条横向分隔线 —— 把「你吃掉的 / 你被吃的」明确切成两块，
    --      开局两行都空时也不会像一整块空色块；
    --   ② 四角内描边（左右两条细竖线）—— 呼应面板其它「记事板」的做法。
    --   【为什么不加四边框】描边要 4 个控件/每行；左右两条 + 中间分隔线已经足够
    --   把区域「框」出来，且不会和面板外框混淆。
    do
      local divT = math.max(1, ah * 0.006)
      UI.panel.capDivider = create_text({
        name = "capdivider", parent = UI.host,
        x = ax, y = ay + rowH, w = aw, h = divT,
        bg = CONFIG.COLOR.PANEL_EDGE, text = "",
      })
      local railT = math.max(1, aw * 0.004)
      UI.panel.capRailL = create_text({
        name = "capraill", parent = UI.host,
        x = ix, y = iy, w = railT, h = ih,
        bg = CONFIG.COLOR.PANEL_EDGE, text = "",
      })
      UI.panel.capRailR = create_text({
        name = "caprailr", parent = UI.host,
        x = ix + iw - railT, y = iy, w = railT, h = ih,
        bg = CONFIG.COLOR.PANEL_EDGE, text = "",
      })
    end

    -- 两行标签（文案由 refresh_capture_labels 按视角写）
    UI.panel.capLabelPeer = create_text({
      name = "caplabelpeer", parent = UI.host,
      x = ax, y = ay + ah - labelH, w = aw, h = labelH,
      text = "", fontColor = CONFIG.COLOR.TEXT_SUB,
      fontSize = capFont,
      hAlign = Enum.TextHorizontalAlignment.Left,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })
    UI.panel.capLabelMine = create_text({
      name = "caplabelmine", parent = UI.host,
      x = ax, y = ay + rowH, w = aw, h = labelH,
      text = "", fontColor = CONFIG.COLOR.TEXT_SUB,
      fontSize = capFont,
      hAlign = Enum.TextHorizontalAlignment.Left,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })
    -- 「无」提示：两行各自的空状态。放在标签右侧（标签本身左对齐），
    -- 这样有子时它为空、没子时读作「你吃掉的：无」，不会和图案区打架。
    local emptyX = ax + aw * 0.34
    UI.panel.capEmptyPeer = create_text({
      name = "capemptypeer", parent = UI.host,
      x = emptyX, y = ay + ah - labelH, w = aw * 0.6, h = labelH,
      text = "", fontColor = CONFIG.COLOR.TEXT_DIM,
      fontSize = capFont,
      hAlign = Enum.TextHorizontalAlignment.Left,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })
    UI.panel.capEmptyMine = create_text({
      name = "capemptymine", parent = UI.host,
      x = emptyX, y = ay + rowH, w = aw * 0.6, h = labelH,
      text = "", fontColor = CONFIG.COLOR.TEXT_DIM,
      fontSize = capFont,
      hAlign = Enum.TextHorizontalAlignment.Left,
      vAlign = Enum.TextVerticalAlignment.Middle,
    })

    -- 两行图案槽位池
    UI.panel.capSlotsPeer = {}
    UI.panel.capSlotsMine = {}
    local slotW = aw * 0.86 / CONFIG.CAP_SLOTS_PER_SIDE
    local iconBox = math.min(rowH * 0.94, slotW * 0.96)
    UI.panel.capIconBox = iconBox
    local function mkRow(list, tag, baseY)
      for i = 1, CONFIG.CAP_SLOTS_PER_SIDE do
        local slot = { prims = {}, shown = {} }
        for k = 1, PRIM_MAX do
          slot.prims[k] = create_image({
            name = "cap" .. tag .. i .. "_p" .. k, parent = UI.host,
            x = 0, y = 0, w = 1, h = 1, asset = CONFIG.PIECE_ASSET.CIRCLE,
            pivot = 0.5,
          })
        end
        slot.cx = ax + aw * 0.07 + slotW * (i - 0.5)
        slot.cy = baseY + rowH * 0.5
        list[i] = slot
      end
    end
    mkRow(UI.panel.capSlotsPeer, "peer", ay + ah - labelH - rowH)  -- 上排
    mkRow(UI.panel.capSlotsMine, "mine", ay)                        -- 下排
  end

  -- 分隔线（吃子区 与 棋钟 之间）
  do
    local b = PL.DIV_LOG
    UI.panel.divider1 = create_text({
      name = "divider1", parent = UI.host,
      x = atX(0.08), y = py + ph * b.y, w = w(0.84), h = h(b.h),
      bg = CONFIG.COLOR.PANEL_EDGE, text = "",
    })
  end

  -- 四个按钮：44% 宽、按 PANEL_LAYOUT 的行高。
  -- 【触摸目标下限】按钮高度必须 ≥ 44px。手机 16:9（720 高）下面板高 = 0.78×720 = 561.6，
  -- 行高 0.078 → 43.8px，略低于 44 的常用下限，所以下面再加一道 max(44, …)。
  -- 行距 0.093（含 0.015 间隔）在 561.6 下是 52.2px，抬到 44 后不会互相压。
  local btnW = w(0.44)
  local function btn_h()
    local hv = h(PL.BTN_ROW1.h)
    if hv < 44 then hv = 44 end
    return hv
  end
  local btnH = btn_h()
  -- 主按钮「新开一局」用琥珀实色，其余用浅灰米，形成主次。
  -- 每个按钮上方再压一条 1px 描边（h*0.10）。【浅色主题】BTN_EDGE(214,206,194) 比
  -- BTN_BG(226,220,210) 略深，所以这条线读作「卡片描边」而不是高光 —— 与 Demo 的
  -- `border: 1px solid var(--c-panel-edge)` 同一个视觉作用（按钮从色块变成可按键）。
  local function button_edge(x, y, bw, bh)
    return create_text({
      name = "btnedgedummy", parent = UI.host,
      x = x, y = y + bh - bh * 0.10, w = bw, h = bh * 0.10,
      bg = CONFIG.COLOR.BTN_EDGE, text = "",
    })
  end
  -- 按钮行坐标：行 1（上）/ 行 2（中）
  local row1Y = py + ph * PL.BTN_ROW1.y
  local row2Y = py + ph * PL.BTN_ROW2.y

  UI.panel.btnNew = create_text({
    name = "btnnew", parent = UI.host,
    x = atX(0.04), y = row1Y, w = btnW, h = btnH,
    bg = CONFIG.COLOR.BTN_PRIMARY, text = CONFIG.TEXT.BTN_NEWGAME,
    -- 【浅色主题连带项】主按钮底是深琥珀 188,116,20，文字必须用浅色近白。
    -- 若沿用普通按钮的 BTN_TEXT（深 44,40,36），深字压在琥珀上会糊成一团看不清。
    fontColor = CONFIG.COLOR.BTN_PRIMARY_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.panel.btnNewEdge = button_edge(atX(0.04), row1Y, btnW, btnH)
  UI.panel.btnResign = create_text({
    name = "btnresign", parent = UI.host,
    x = atX(0.52), y = row1Y, w = btnW, h = btnH,
    bg = CONFIG.COLOR.BTN_BG, text = CONFIG.TEXT.BTN_RESIGN,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.panel.btnResignEdge = button_edge(atX(0.52), row1Y, btnW, btnH)
  UI.panel.btnDraw = create_text({
    name = "btndraw", parent = UI.host,
    x = atX(0.04), y = row2Y, w = btnW, h = btnH,
    bg = CONFIG.COLOR.BTN_BG, text = CONFIG.TEXT.BTN_DRAW,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.panel.btnDrawEdge = button_edge(atX(0.04), row2Y, btnW, btnH)
  -- 【v3.2 删除】「切换本地同屏」按钮（btnLocal）。
  --   用户要求：「删除切换本地同屏按钮」「删除单人同屏模式」。
  --   模式不再可切，所以这个按钮没有存在意义；同屏入口也从初始界面一并删掉。
  --
  -- 【v3.2 后续：空槽位怎么处理】删掉后 row2 右半格空出来了。三种做法里选了「通栏铺满」：
  --   ① 留空 → 截图实测读作「少画了一个按钮」，像 bug；
  --   ② 灰色占位块 → 能看出原本有东西，但画面更挤；
  --   ③ **通栏** → 联机时「认输」独占行 1、「求和」独占行 2，信息密度均匀。
  --   实现见 apply_panel_button_layout()。
  --   注意：**不重建控件**，只改 x/w（尺寸），命中区与描边同步改 ——
  --   播放期零创建零销毁，符合平台约束。

  -- 【v3.2 通栏布局】把一个面板按钮的「可见控件 / 描边 / 命中区」三者同步成
  -- 指定的 x 与 w，让按钮能在「半宽」和「通栏」之间切换而不新建控件。
  -- 【为什么三者必须一起改】只改可见控件 → 点击区还在老位置（点得着的地方不对）；
  --   只改可见+命中区、漏描边 → 按钮变宽了但上沿还短短一截。
  local function set_btn_span(btn, edge, hit, x, y, bw, bh)
    if btn ~= nil then
      cw(); btn:SetAnchoredPosition(x, y)
      cw(); btn:SetSizeDelta(bw, bh)
    end
    if edge ~= nil then
      -- 描边层始终贴在按钮**上沿**，高度是按钮高的 10%（与 button_edge 一致）
      cw(); edge:SetAnchoredPosition(x, y + bh - bh * 0.10)
      cw(); edge:SetSizeDelta(bw, bh * 0.10)
    end
    if hit ~= nil then
      cw(); hit:SetAnchoredPosition(x, y)
      cw(); hit:SetSizeDelta(bw, bh)
    end
  end

  -- 把面板按钮按「现在有没有对手」排成半宽或通栏。
  -- 【半宽布局】（无对手，正常单机/复盘）
  --   行 1：新开一局 | 认输      行 2：求和 | （空）
  -- 【通栏布局】（有对手联机；新开一局与返回主菜单按用户要求被隐藏）
  --   行 1：认输（通栏）         行 2：求和（通栏）
  -- 【为什么通栏是 0.92 宽】与面板里其它通栏元素（提示条/分隔线用 0.84~0.92）对齐，
  --   起点 x 统一在 atX(0.04)，右侧留同边距。
  UI.panel.apply_button_layout = function(fullWidth)
    local halfW = btnW
    local fullW = w(0.92)
    if fullWidth then
      set_btn_span(UI.panel.btnResign, UI.panel.btnResignEdge, UI.panel.hitResign,
                   atX(0.04), row1Y, fullW, btnH)
      set_btn_span(UI.panel.btnDraw, UI.panel.btnDrawEdge, UI.panel.hitDraw,
                   atX(0.04), row2Y, fullW, btnH)
      -- 新开一局仍按半宽（它只在无对手时可见，通栏布局下本来就不显示）
      set_btn_span(UI.panel.btnNew, UI.panel.btnNewEdge, UI.panel.hitNew,
                   atX(0.04), row1Y, halfW, btnH)
    else
      set_btn_span(UI.panel.btnNew, UI.panel.btnNewEdge, UI.panel.hitNew,
                   atX(0.04), row1Y, halfW, btnH)
      set_btn_span(UI.panel.btnResign, UI.panel.btnResignEdge, UI.panel.hitResign,
                   atX(0.52), row1Y, halfW, btnH)
      set_btn_span(UI.panel.btnDraw, UI.panel.btnDrawEdge, UI.panel.hitDraw,
                   atX(0.04), row2Y, halfW, btnH)
    end
  end

  -- 按钮点击检测区（盖在按钮上；文本框不能收光标事件，见策划案 10.2）
  UI.panel.hitNew    = create_cursor_area({ name = "hitnew",    parent = UI.host, x = atX(0.04), y = row1Y, w = btnW, h = btnH })
  UI.panel.hitResign = create_cursor_area({ name = "hitresign", parent = UI.host, x = atX(0.52), y = row1Y, w = btnW, h = btnH })
  UI.panel.hitDraw   = create_cursor_area({ name = "hitdraw",   parent = UI.host, x = atX(0.04), y = row2Y, w = btnW, h = btnH })

  -- 提示条（棋盘上方，与棋盘同宽）：加一条淡底衬托，避免文字直接飘在画布上
  -- 【y 起点必须再加 framePad】v1.7 起棋盘外面多了一圈暖木外框，原坐标
  -- （boardBottom + boardSide + hintH*0.3）会压进外框顶边约 4px（1600×900 实测），
  -- 深色主题下看不出来；换成浅色提示底后会在木框上切出一条浅色带。
  -- 与 Demo 的修法完全一致（chess_demo.html 第 1438 行 `+ L.framePad`）。
  local hintH = L.font(CONFIG.FONT.HINT) * 1.4
  local hintPad = L.framePad      -- 让开棋盘暖木外框（见 build_board）
  UI.panel.hintBg = create_text({
    name = "hintbg", parent = UI.host,
    x = L.boardLeft, y = L.boardBottom + L.boardSide + hintPad + hintH * 0.3,
    w = L.boardSide, h = hintH,
    bg = CONFIG.COLOR.HINT_BG, text = "",
  })
  UI.panel.hint = create_text({
    name = "hint", parent = UI.host,
    x = L.boardLeft, y = L.boardBottom + L.boardSide + hintPad + hintH * 0.3,
    w = L.boardSide, h = hintH,
    text = CONFIG.TEXT.HINT_OPENING,
    fontColor = CONFIG.COLOR.TEXT_SUB, fontSize = L.font(CONFIG.FONT.HINT),
    hAlign = Enum.TextHorizontalAlignment.Middle,
    vAlign = Enum.TextVerticalAlignment.Middle,
  })

  -- ===== 复盘面板按钮（v1.6）=====
  -- 行 3（REVIEW_TOGGLE）是一个常驻单按钮，文案随状态切换：
  --   对局中 / 结算后 → 「看历史」/「复盘」；复盘中 → 「退出复盘」
  -- 行 1、行 2 的四个按钮位在复盘模式下换成「开局 / 上一步 / 下一步 / 终局」，
  -- 因此这里用同一组坐标再建一套按钮 + 命中区，靠显隐切换，播放期零创建零销毁。
  local togX, togY, togW, togH = band("REVIEW_TOGGLE")
  -- 【v2.0 块 3：第三行的三方空间冲突与最终方案】
  --
  -- 硬数字（面板宽 0.22×1600 = 352px，可用 atX(0.04)~atX(0.96) = 323.8px；
  --   宽度保守估算：全角 1.0em / 半角 0.55em，字号 24）：
  --     退出复盘   96.0
  --     悔棋（剩 3）146.4
  --     返回主菜单 120.0
  --     合计 362.4 + 间隙 8 = 370.4 > 323.8  →  **超 46.6px，三键塞不进这一行**
  --
  -- 【最终方案：左半格「悔棋 ↔ 退出复盘」互斥复用，右半格「返回主菜单」】
  --   依据：**悔棋与「看历史/退出复盘」天然互斥** ——
  --     · screen == "playing"（对局中）→ 显示「悔棋（剩 N）」
  --     · screen == "review" / 有 review 状态 → 显示「退出复盘」
  --   两者永远不会同时需要，所以共用一格在语义上是对的，不是将就。
  --   两键合计 246.4 + 间隙 4 = 250.4 ≤ 323.8 ✅ 余量 73px，很宽松。
  --
  -- 【代价（必须记录）】对局中不再有「看历史」入口 —— 复盘只能从**结算面板**进。
  --   v1.6 的「对局中随时看历史」这一便利在本布局下让位给了悔棋（用户明确要的功能）。
  --   若将来要恢复，需要把返回主菜单挪走或加第 4 行布局槽（都要动 PANEL_LAYOUT）。
  --
  -- 【不新增 PANEL_LAYOUT 键】新增键会让 consistency_check 与 Demo 的 const PL
  --   取并集比对时因 Demo 缺项而 FAIL。左半 x 仍是 atX(0.04)，与 BTN_PAIRS 期望一致。
  local togHalfW = w(0.42)   -- 左半：悔棋 / 退出复盘（互斥）
  local mainW    = w(0.46)   -- 右半：返回主菜单
  UI.review.btnToggle = create_text({
    name = "btnreviewtoggle", parent = UI.host,
    x = togX, y = togY, w = togHalfW, h = togH,
    bg = CONFIG.COLOR.BTN_BG, text = CONFIG.TEXT.BTN_REVIEW_HISTORY,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.review.hitToggle = create_cursor_area({
    name = "hitreviewtoggle", parent = UI.host,
    x = togX, y = togY, w = togHalfW, h = togH,
  })
  -- 【名字必须避开 btn 前缀】consistency_check.cjs 会把任何 `name = "btnXxx"`
  -- 当成「必须登记进 BTN_PAIRS 的面板按钮」，未登记即 FAIL。
  -- v2.0 新增控件一律用 v2 前缀（见文件内 v2.0 命名约定），命中区同理。
  UI.panel.v2BackMain = create_text({
    name = "v2backmain", parent = UI.host,
    x = atX(0.52), y = togY, w = mainW, h = togH,
    bg = CONFIG.COLOR.BTN_BG, text = CONFIG.TEXT.BTN_MENU,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.panel.hitV2BackMain = create_cursor_area({
    name = "hitv2backmain", parent = UI.host,
    x = atX(0.52), y = togY, w = mainW, h = togH,
  })
  -- 【v3.2】「返回主菜单」上沿描边。原先这个按钮**没有**描边层（四个面板按钮都有），
  -- 视觉上它和别人的「厚度」不一样；既然这轮要按联机状态单独隐藏它，
  -- 就必须让描边跟着一起藏，否则会出现「按钮没了但上沿还在」的残影。
  UI.panel.btnMenuEdge = button_edge(atX(0.52), togY, mainW, togH)
  -- 【v2.0 块 3：悔棋按钮】
  -- 【放哪】面板第三行（REVIEW_TOGGLE 槽）**左半格**，与「看历史/退出复盘」互斥复用：
  --   对局中显示「悔棋（剩 N）」、复盘中显示「退出复盘」——两者永远不同时需要。
  --   （三方空间冲突的完整算式见本段开头的注释。）
  -- 【为什么不新增 PANEL_LAYOUT 键】新增键会让 consistency_check 与 Demo 的
  --   const PL 取并集比对时因 Demo 缺项而 FAIL。所以复用现有槽位。
  -- 【文案是动态的】「悔棋（剩 N）」的 N 会变，由 refresh_undo_button() 单点刷新。
  -- 【字号 26 而非 28】「悔棋（剩 3）」= 5 全角 + 1 半角：
  --   字号 28 需 5×28 + 28×0.55 = 155.4px > 左半 147.8px（**超 7.6px，会换行**）
  --   字号 26 需 5×26 + 26×0.55 = 144.3px ≤ 147.8px ✅（余 3.5px）
  --   proto-lead 在 Demo 侧实测「需 146 / 可用 146，差 1px 就换行」，与此一致。
  --   换行后果很严重：半宽按钮里只剩半个「悔棋」二字，比没字更难看。
  UI.panel.v2Undo = create_text({
    name = "v2undo", parent = UI.host,
    x = togX, y = togY, w = togHalfW, h = togH,
    bg = CONFIG.COLOR.BTN_BG,
    text = "",   -- 由 refresh_undo_button() 填「悔棋（剩 3）」
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.UNDO_BTN),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.panel.hitV2Undo = create_cursor_area({
    name = "hitv2undo", parent = UI.host,
    x = togX, y = togY, w = togHalfW, h = togH,
  })
  local rvBtns = {
    { key = "btnStart", hit = "hitStart", name = "btnreviewstart", hitName = "hitreviewstart",
      x = atX(0.04), y = row1Y, text = CONFIG.TEXT.BTN_REVIEW_START },
    { key = "btnPrev", hit = "hitPrev", name = "btnreviewprev", hitName = "hitreviewprev",
      x = atX(0.52), y = row1Y, text = CONFIG.TEXT.BTN_REVIEW_PREV },
    { key = "btnNext", hit = "hitNext", name = "btnreviewnext", hitName = "hitreviewnext",
      x = atX(0.04), y = row2Y, text = CONFIG.TEXT.BTN_REVIEW_NEXT },
    { key = "btnEnd", hit = "hitEnd", name = "btnreviewend", hitName = "hitreviewend",
      x = atX(0.52), y = row2Y, text = CONFIG.TEXT.BTN_REVIEW_END },
  }
  for _, spec in ipairs(rvBtns) do
    UI.review[spec.key] = create_text({
      name = spec.name, parent = UI.host,
      x = spec.x, y = spec.y, w = btnW, h = btnH,
      bg = CONFIG.COLOR.BTN_BG, text = spec.text,
      fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
      hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
      raycast = true,
    })
    UI.review[spec.hit] = create_cursor_area({
      name = spec.hitName, parent = UI.host,
      x = spec.x, y = spec.y, w = btnW, h = btnH,
    })
  end

  -- ===== 音效开关（v1.10，v1.11 调高到触摸下限）=====
  -- 【位置为什么在面板外面】面板内部最底一行（REVIEW_TOGGLE）下面已经排不出 44px，
  --   所以跟 Demo 一样放在面板正下方的空白条里：
  --   横向与面板按钮同列（x = atX(0.04)、宽 92%），只是整体下移到 py 以下。
  -- 【v1.11 修】旧高度是 ph*0.062，手机 720 下只有 34.8px —— 低于触摸目标下限，
  --   实测容易点空。改成与行高同值并同样兜底 44。
  local sfxH = h(PL.REVIEW_TOGGLE.h)
  if sfxH < 44 then sfxH = 44 end
  local sfxY = py - sfxH - ph * 0.018
  UI.panel.btnSfx = create_text({
    name = "btnsfx", parent = UI.host,
    x = atX(0.04), y = sfxY, w = w(0.92), h = sfxH,
    bg = CONFIG.COLOR.BTN_BG,
    text = SFX.enabled and CONFIG.TEXT.SFX_ON or CONFIG.TEXT.SFX_OFF,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.panel.btnSfxEdge = create_text({
    name = "btnsfxedge", parent = UI.host,
    x = atX(0.04), y = sfxY + sfxH - sfxH * 0.10, w = w(0.92), h = sfxH * 0.10,
    bg = CONFIG.COLOR.BTN_EDGE, text = "",
  })
  UI.panel.hitSfx = create_cursor_area({
    name = "hitsfx", parent = UI.host,
    x = atX(0.04), y = sfxY, w = w(0.92), h = sfxH,
  })
end

-- 音效按钮文案同步（开关状态可能在别处被改：初值、切换后）
local function sync_sfx_button()
  if UI.panel == nil or UI.panel.btnSfx == nil then return end
  UI.panel.btnSfx.text = SFX.enabled and CONFIG.TEXT.SFX_ON or CONFIG.TEXT.SFX_OFF
end

local function build_result_panel()
  local L = UI.L
  -- 全屏遮罩（可吞掉底层点击；遮罩本身也盖一个检测区）
  UI.result.overlay = create_text({
    name = "resultoverlay", parent = UI.host,
    x = 0, y = 0, w = L.canvasW, h = L.canvasH,
    bg = CONFIG.COLOR.OVERLAY, text = "",
  })
  UI.result.hitOverlay = create_cursor_area({
    name = "hitoverlay", parent = UI.host, x = 0, y = 0, w = L.canvasW, h = L.canvasH,
  })
  -- 面板底：居中 44% × 50%（v3.2 加高：多出「比分」与「退出」两行）
  -- 【为什么必须加高而不是压缩行距】标题/说明/比分/两排按钮 = 5 段，
  --   原来 0.40 高在 720 画布上只有 288px，5 段排不下会互相压（v1.11 的老问题）。
  local w, h = L.canvasW * 0.44, L.canvasH * 0.50
  local x, y = (L.canvasW - w) * 0.5, (L.canvasH - h) * 0.5
  -- 【v1.10 补：描边 + 投影】Demo 的 .dlg-bg 是
  --   `background: var(--c-panel); border: 1px solid var(--c-panel-edge);
  --    box-shadow: 0 18px 48px rgba(110,88,62,0.20)`
  -- 而 --c-panel(252,250,247) 与 --c-overlay(250,248,244 @0.667) 几乎同色，
  -- **弹窗与遮罩是靠 border + box-shadow 区分的**，不是靠底色差。
  -- 浅色主题下若只铺 PANEL_BG，整个遮罩区会糊成一整片白（模拟器截图实测：
  -- 结算面板的边界完全看不出来）。所以必须把这两层补上。
  local edgeT = math.max(1, L.cell * 0.012)
  UI.result.shadow = create_text({
    name = "resultshadow", parent = UI.host,
    x = x - edgeT * 2, y = y - edgeT * 5, w = w + edgeT * 4, h = h + edgeT * 8,
    bg = CONFIG.COLOR.PANEL_SHADOW, text = "",
  })
  UI.result.edgeBox = create_text({
    name = "resultedge", parent = UI.host,
    x = x - edgeT, y = y - edgeT, w = w + edgeT * 2, h = h + edgeT * 2,
    bg = CONFIG.COLOR.PANEL_EDGE, text = "",
  })
  UI.result.bg = create_text({
    name = "resultbg", parent = UI.host, x = x, y = y, w = w, h = h,
    bg = CONFIG.COLOR.PANEL_BG, text = "",
  })
  -- 【高度必须够装下字号】文本框的可用高度 = 控件高 - 上下内边距（blockInset ≈ 0.45×字号），
  -- 行高 = 字号 × 1.2。标题字号 44 时行高 52.8 + 内边距 19.8 = 72.6，原高度 0.18×360=64.8
  -- 装不下 → 文本被整行吞掉不显示（模拟器实测：认输结算只见说明行，标题一片空白）。
  -- 改成 0.24×360=86.4 > 72.6，标题正常显示。
  UI.result.title = create_text({
    name = "resulttitle", parent = UI.host,
    x = x + w * 0.05, y = y + h * 0.76, w = w * 0.90, h = h * 0.18,
    text = "", fontColor = CONFIG.COLOR.TEXT_MAIN, fontSize = L.font(CONFIG.FONT.RESULT_TITLE),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
  })
  UI.result.sub = create_text({
    name = "resultsub", parent = UI.host,
    x = x + w * 0.05, y = y + h * 0.62, w = w * 0.90, h = h * 0.11,
    text = "", fontColor = CONFIG.COLOR.TEXT_SUB, fontSize = L.font(CONFIG.FONT.RESULT_SUB),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
  })
  -- ===== v3.2 比分（用户要求「为双方结算，胜利的加分」）=====
  -- 放在说明行下面、按钮上面：读的顺序是「谁赢 → 为什么赢 → 现在总比分 → 接下来干什么」。
  UI.result.score = create_text({
    name = "resultscore", parent = UI.host,
    x = x + w * 0.05, y = y + h * 0.47, w = w * 0.90, h = h * 0.11,
    text = "", fontColor = CONFIG.COLOR.TEXT_ACCENT, fontSize = L.font(CONFIG.FONT.RESULT_SUB),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
  })
  -- 三键一排（v3.2）：再来一局 / 复盘 / 退出
  -- 【为什么三键而不是两键】用户要求「增加退出按钮」。三个键各占 28%，
  --   间隙 4%：0.06 + 0.28*3 + 0.04*2 = 0.98 ✅
  --   【字号】三键变窄后，长文案（「再来一局」4字）在 28%×44%×1600 = 197px 内
  --   用 BUTTON 字号（28）需 4×28 = 112px，很宽松。
  local bx1, bx2, bx3 = 0.06, 0.38, 0.70
  local bw, bh = 0.24, 0.13
  local byy = 0.31
  UI.result.btnAgain = create_text({
    name = "btnagain", parent = UI.host,
    x = x + w * bx1, y = y + h * byy, w = w * bw, h = h * bh,
    bg = CONFIG.COLOR.BTN_BG, text = CONFIG.TEXT.BTN_AGAIN,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.result.hitAgain = create_cursor_area({
    name = "hitagain", parent = UI.host,
    x = x + w * bx1, y = y + h * byy, w = w * bw, h = h * bh,
  })
  UI.result.btnReview = create_text({
    name = "btnresultreview", parent = UI.host,
    x = x + w * bx2, y = y + h * byy, w = w * bw, h = h * bh,
    bg = CONFIG.COLOR.BTN_BG, text = CONFIG.TEXT.BTN_REVIEW,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.result.hitReview = create_cursor_area({
    name = "hitresultreview", parent = UI.host,
    x = x + w * bx2, y = y + h * byy, w = w * bw, h = h * bh,
  })
  -- 【v3.2 新增】退出：回到初始界面（对局已结束，不需要二次确认）
  UI.result.btnExit = create_text({
    name = "btnresultexit", parent = UI.host,
    x = x + w * bx3, y = y + h * byy, w = w * bw, h = h * bh,
    bg = CONFIG.COLOR.BTN_BG, text = CONFIG.TEXT.BTN_RESULT_EXIT,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.result.hitExit = create_cursor_area({
    name = "hitresultexit", parent = UI.host,
    x = x + w * bx3, y = y + h * byy, w = w * bw, h = h * bh,
  })
  -- 等待对方选择的提示行（v3.2：再来一局/复盘需要双方都点）
  UI.result.wait = create_text({
    name = "resultwait", parent = UI.host,
    x = x + w * 0.05, y = y + h * 0.15, w = w * 0.90, h = h * 0.10,
    text = "", fontColor = CONFIG.COLOR.TEXT_SUB, fontSize = L.font(CONFIG.FONT.RESULT_SUB),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
  })
end

local function build_promo_dialog()
  local L = UI.L
  local w, h = L.canvasW * 0.44, L.canvasH * 0.30
  local x, y = (L.canvasW - w) * 0.5, (L.canvasH - h) * 0.5
  UI.promo.bg = create_text({
    name = "promobg", parent = UI.host, x = x, y = y, w = w, h = h,
    bg = CONFIG.COLOR.PANEL_BG, text = "",
  })
  UI.promo.prompt = create_text({
    name = "prompt", parent = UI.host,
    x = x + w * 0.05, y = y + h * 0.66, w = w * 0.90, h = h * 0.16,
    text = CONFIG.TEXT.PROMO_PROMPT, fontColor = CONFIG.COLOR.TEXT_MAIN,
    fontSize = L.font(36),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
  })
  local labels = { CONFIG.TEXT.PROMO_QUEEN, CONFIG.TEXT.PROMO_ROOK,
                   CONFIG.TEXT.PROMO_BISHOP, CONFIG.TEXT.PROMO_KNIGHT }
  local cols = { 0.04, 0.26, 0.48, 0.70 }
  UI.promo.buttons = {}
  UI.promo.hits = {}
  for i = 1, 4 do
    local bx = x + w * cols[i]
    local by = y + h * 0.10
    local bw, bh = w * 0.22, h * 0.26
    UI.promo.buttons[i] = create_text({
      name = "promo" .. tostring(i), parent = UI.host,
      x = bx, y = by, w = bw, h = bh,
      bg = CONFIG.COLOR.BTN_BG, text = labels[i],
      fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.PROMO_OPTION),
      hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
      raycast = true,
    })
    UI.promo.hits[i] = create_cursor_area({
      name = "hitpromo" .. tostring(i), parent = UI.host,
      x = bx, y = by, w = bw, h = bh,
    })
  end
end

-- 通用确认弹窗（对应 docs/策划案.md 9.5 的 C-01 ~ C-04）
--   C-01 认输就直接判负，确定吗      按钮：确定认输 / 继续下棋
--   C-02 重开会清空这一局            按钮：确定 / 取消
--   C-03 切换会断开这一局，确定吗     按钮：确定 / 取消
--   C-04 对方想和棋，同意吗          按钮：同意和棋 / 拒绝求和
local function build_confirm_dialog()
  local L = UI.L
  local w, h = L.canvasW * 0.46, L.canvasH * 0.28
  local x, y = (L.canvasW - w) * 0.5, (L.canvasH - h) * 0.5
  UI.confirm = UI.confirm or {}
  -- 【v1.10 补：全屏遮罩 + 描边 + 投影】
  -- 早先这里只建了 bg/text/两个按钮，**没有遮罩**，于是确认弹窗是「一块白卡片直接压在棋盘上」：
  --   棋盘在弹窗四周照常显示，观感像排版错位而不是弹窗（模拟器实测截图看到）。
  -- 结算面板有 OVERLAY，确认弹窗却没有 —— 两者都是模态弹窗，表现必须一致。
  --- 另外 demo 侧弹窗靠 border + box-shadow 与遮罩区分（PANEL_BG 252,250,247 与
  -- OVERLAY 250,248,244 几乎同色，只靠底色差根本分不出边界），所以描边与投影一并补上。
  UI.confirm.overlay = create_text({
    name = "confirmoverlay", parent = UI.host,
    x = 0, y = 0, w = L.canvasW, h = L.canvasH,
    bg = CONFIG.COLOR.OVERLAY, text = "",
  })
  local edgeT = math.max(1, L.cell * 0.012)
  UI.confirm.shadow = create_text({
    name = "confirmshadow", parent = UI.host,
    x = x - edgeT + 2, y = y - edgeT - L.cell * 0.10,
    w = w + edgeT * 2, h = h + edgeT * 2,
    bg = CONFIG.COLOR.PANEL_SHADOW, text = "",
  })
  UI.confirm.edgeBox = create_text({
    name = "confirmedge", parent = UI.host,
    x = x - edgeT, y = y - edgeT, w = w + edgeT * 2, h = h + edgeT * 2,
    bg = CONFIG.COLOR.PANEL_EDGE, text = "",
  })
  UI.confirm.bg = create_text({
    name = "confirmbg", parent = UI.host, x = x, y = y, w = w, h = h,
    bg = CONFIG.COLOR.PANEL_BG, text = "",
  })
  UI.confirm.text = create_text({
    name = "confirmtext", parent = UI.host,
    x = x + w * 0.05, y = y + h * 0.46, w = w * 0.90, h = h * 0.30,
    text = CONFIG.TEXT.CONFIRM_RESIGN, fontColor = CONFIG.COLOR.TEXT_MAIN,
    fontSize = L.font(26),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
  })
  local by, bh = y + h * 0.10, h * 0.24
  local bw = w * 0.44
  UI.confirm.btnYes = create_text({
    name = "confirmyes", parent = UI.host,
    x = x + w * 0.06, y = by, w = bw, h = bh,
    bg = CONFIG.COLOR.BTN_BG, text = CONFIG.TEXT.CONFIRM_RESIGN_YES,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.confirm.btnNo = create_text({
    name = "confirmno", parent = UI.host,
    x = x + w * 0.50, y = by, w = bw, h = bh,
    bg = CONFIG.COLOR.BTN_BG, text = CONFIG.TEXT.CONFIRM_RESIGN_NO,
    fontColor = CONFIG.COLOR.BTN_TEXT, fontSize = L.font(CONFIG.FONT.BUTTON),
    hAlign = Enum.TextHorizontalAlignment.Middle, vAlign = Enum.TextVerticalAlignment.Middle,
    raycast = true,
  })
  UI.confirm.hitYes = create_cursor_area({
    name = "hitconfirmyes", parent = UI.host, x = x + w * 0.06, y = by, w = bw, h = bh,
  })
  UI.confirm.hitNo = create_cursor_area({
    name = "hitconfirmno", parent = UI.host, x = x + w * 0.50, y = by, w = bw, h = bh,
  })
  UI.confirm.parts = { UI.confirm.overlay, UI.confirm.shadow, UI.confirm.edgeBox, UI.confirm.bg,
                       UI.confirm.text, UI.confirm.btnYes, UI.confirm.btnNo,
                       UI.confirm.hitYes, UI.confirm.hitNo }
end

-- 【前向声明】ui_set_active 定义在下面（build_start_screen 之后）。
-- build_start_screen 末尾要把整层控件全部隐藏，必须调它。
-- Lua 的 local function 是词法向前作用域 —— 不声明就用会被绑成 global，运行时 nil。
-- 这是本项目最致命的一类 bug（show_panel_buttons 事故：四条终局路径全崩）。
-- 用法同 review_render：这里只声明，定义处写成 `ui_set_active = function(...)`。
local ui_set_active

-- 【前向声明，v2.0】初始界面的进出函数要在「面板/弹窗/复盘的显隐函数」之前定义
-- （它们都在 show_start_screen 里被调用），而那几个函数定义在很后面。
-- 逐个前向声明 + 定义处写成赋值形式，避免被绑成 global。
-- 这条纪律是 show_panel_buttons 事故的通用解法：**先声明，后赋值。**
local show_panel_buttons        -- 定义于 show_result 之前
local show_review_buttons       -- 定义于复盘状态机段
local hide_result               -- 定义于 show_result 之后
local hide_promo                -- 定义于 hide_result 之后
local hide_confirm              -- 定义于 hide_promo 之后
local back_to_main_menu         -- 定义于三入口动作段（exit_review 会调用它）
local refresh_lobby             -- 定义于待机室段（净室 OnUpdate / 信号处理会调用）
local refresh_undo_button       -- v2.0 块 3：悔棋按钮文案/置灰刷新（render_all 会调）
local undo_check                -- v2.0 块 3：六条发起条件（输入层要调）
local undo_apply_pair           -- v2.0 块 3：成对撤回（确认框「确定」要调）
local undo_consume              -- v2.0 块 3：扣次数
local review_render
-- 【v3.3】refresh_review_actionbar / refresh_branch_visuals 的前向声明已删除
-- （分支试走与复盘动作条整体移除，见「已整体移除」那段注释）。
-- 【v2.0 块 2】start_game_from_lobby 定义在待机室段（UI 区附近），却要调 new_game
-- （定义在第 7 区 GAME 段，更后面）。GATE1 抓到了这条先用后定义。
local new_game
local apply_time_control
-- 【v3.0 前向声明 → 已取消】初始界面（show_start_screen，定义在下面 UI 区）要复位联机
-- 协商与视角；本想把它们做成 local，但主 chunk 的 local 上限 200 已经用尽
-- （模拟器实测：多 15 个 local 就 `too many local variables`），
-- 所以改为挂在 GAME.match 表上（表字段不占 local），这里不再需要前向声明。

-- =============================================================================
-- 初始界面（v2.0，块 1）
-- -----------------------------------------------------------------------------
-- 【整体设计：盖在最上层的不透明整层】
--   没有采用「进初始界面时把棋盘/面板的 1300 个控件逐个隐藏」的做法，原因是：
--   ① 棋子槽位池有 32 槽 × 34 图元 ≈ 1088 个控件，逐个开关会引入显隐竞态
--      （render_all / anim_update 在后台照常跑，会把刚隐藏的又打开）；
--   ② 只要有一个漏隐藏就穿帮，且这种漏在截图里很难发现。
--   改成「整层盖住」后，后台怎么跑都无所谓 —— 玩家看到的永远是这层。
--
-- 【为什么这层还要自己画 24 条渐变带，而不是铺一块纯色】
--   因为主背景是 24 条色带的竖渐变（BG_TOP→BG→BG_BOTTOM）。若初始界面铺纯色，
--   进出初始界面时背景会「跳色」。这里用**同一个采样函数 bg_color_sample(t)**
--   再画一遍同样的 24 条带 → 逐条同值 → 切换时背景完全静止，只有内容在换。
--   代价 +24 控件，换掉 1088 个控件的隐藏竞态，值。
--
-- 【Z 序】本函数必须在 build_all_ui 里**最后**调用（同级后出现的在上），
--   且它的命中区要在 raise_hit 之后再提一次（见 build_all_ui 末尾）。
-- =============================================================================
local function build_start_screen()
  local L = UI.L
  local W, H = L.canvasW, L.canvasH
  local SL = CONFIG.START_LAYOUT
  local st = UI.startScreen
  st.parts = {}
  st.bands = {}
  st.cards = {}
  st.entries = {}

  -- 登记一个控件到「整层」，进/出时一次性全切
  local function part(ctrl)
    if ctrl ~= nil then st.parts[#st.parts + 1] = ctrl end
    return ctrl
  end

  -- ===== ① 不透明底：24 条渐变带（与主背景逐条同值）=====
  -- 【必须再加一块兜底不透明底】色带高 = H/24，最后一条 h+1 会溢出 1px；
  -- 万一将来改 BG_BANDS 导致露出缝隙，这一块 BG 纯色兜底能保证「绝不透出棋盘」。
  part(create_text({
    name = "startbgbase", parent = UI.host,
    x = 0, y = 0, w = W, h = H,
    bg = CONFIG.COLOR.BG, text = "",
  }))
  local BG_BANDS = 24
  local bandH = H / BG_BANDS
  for i = 1, BG_BANDS do
    local t = (i - 0.5) / BG_BANDS
    st.bands[i] = part(create_text({
      name = "startbg" .. tostring(i), parent = UI.host,
      x = 0, y = (i - 1) * bandH, w = W, h = bandH + 1,
      bg = bg_color_sample(t), text = "",
    }))
  end

  -- 纵向分段小工具：按 START_LAYOUT 的比例给出 (x, y, w, h)
  local function bandRect(name, xR, wR)
    local b = SL[name]
    return W * (xR or 0), H * b.y, W * (wR or 1), H * b.h
  end

  -- ===== ② 主标题 + 副标题 =====
  do
    local x, y, w, h = bandRect("TITLE")
    st.title = part(create_text({
      name = "starttitle", parent = UI.host,
      x = x, y = y, w = w, h = h,
      text = CONFIG.TEXT.START_TITLE,
      fontColor = CONFIG.COLOR.START_TITLE,
      fontSize = L.font(CONFIG.FONT.START_TITLE),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    }))
  end
  -- ===== ②-b 标题下的固定标语（v3.1）=====
  -- 【为什么单独一个控件】副标题（SUBTITLE）是**动态**状态行（「你选了「快棋」」/「对手选了…」），
  -- 不能把标语塞进去 —— 那样一选档位标语就没了。这里是一条静态文案，只建一次、从不改写。
  do
    local x, y, w, h = bandRect("TAGLINE")
    st.tagline = part(create_text({
      name = "starttagline", parent = UI.host,
      x = x, y = y, w = w, h = h,
      text = CONFIG.TEXT.START_TAGLINE,
      fontColor = CONFIG.COLOR.START_SUB,
      fontSize = L.font(CONFIG.FONT.START_TAGLINE),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    }))
  end
  do
    local x, y, w, h = bandRect("SUBTITLE")
    st.subtitle = part(create_text({
      name = "startsubtitle", parent = UI.host,
      x = x, y = y, w = w, h = h,
      text = CONFIG.TEXT.START_SUBTITLE,
      fontColor = CONFIG.COLOR.START_SUB,
      fontSize = L.font(CONFIG.FONT.START_SUB),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    }))
  end

  -- ===== ③ 档位卡上方提示行（普通模式：说明；联机模式：先选者为准）=====
  do
    local x, y, w, h = bandRect("TC_HINT")
    st.tcHint = part(create_text({
      name = "starthint", parent = UI.host,
      x = x, y = y, w = w, h = h,
      text = "",
      fontColor = CONFIG.COLOR.TEXT_ACCENT,
      fontSize = L.font(CONFIG.FONT.START_FOOTER),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    }))
  end

  -- ===== ④ 4 张走时档卡 =====
  -- 【卡片结构】每张卡 7 个控件：
  --   选中描边(edgeOn) + 卡片底(bg) + 档位名(name) + 首钟/加秒/预估(3 行) + 命中区(hit)
  -- 【为什么选中态用「两层」而不是改一层颜色】浅色主题里卡片底与选中底只差十几点亮度，
  --   只改底色几乎看不出选了哪个；再加一条琥珀描边（强调色）才有明确的「选中」信号。
  -- 【为什么 edgeOn 建在 bg 之前】同级后出现的在上，描边框必须先建，否则压在卡片上面
  --   （面板描边也踩过同一处，见 build_panel）。
  --
  -- 【v2.0 修 P0：档位名整行不显示】
  --   文本框的**可用高 ≈ 控件高 − 0.9×字号，行高 ≈ 1.2×字号**（D-02 陷阱，v1.10 结算标题踩过）。
  --   字号 28 的档位名需要 ≥ 1.2×28 + 0.9×28 = **58.8px** 才显示得出来。
  --   旧版卡高 0.190×900 = 171px，分给档位名 0.24×171 = 41px < 58.8 → **整行被吞掉**。
  --   现卡高 0.248×900 = 223.2px，档位名 0.27×223.2 = **60.3px** > 58.8 ✅
  --   三行说明 0.19×223.2 = **42.4px**，字号 19 只需 22.8+17.1 = 39.9 ✅
  --   卡内纵向分段全部用「占卡高比例」表达，换画布自动等比，不再依赖特定分辨率。
  do
    local x, y, w, h = bandRect("TC_CARDS", SL.TC_CARDS_X, SL.TC_CARDS_W)
    local n = #CONFIG.TIME_CONTROLS
    local gap = w * 0.018
    local cardW = (w - gap * (n - 1)) / n
    -- 卡内纵向分段（全部相对卡高 h，自下而上；数值见上方注释的算式）
    local nameH    = h * 0.27
    local nameBase = h * 0.66      -- 档位名底边（top = 0.93h，留 0.07h 顶边距）
    local metaH    = h * 0.19
    local metaY0   = h * 0.03      -- 最低一行（预估）的底边
    local metaStep = h * 0.21      -- 行间距
    for i = 1, n do
      local tc = CONFIG.TIME_CONTROLS[i]
      local cx = x + (i - 1) * (cardW + gap)
      local card = { n = tc.n }
      -- 选中描边（比卡片四周各外扩 pad）
      local pad = math.max(2, L.cell * 0.045)
      card.edgeOn = part(create_text({
        name = "tc" .. tostring(tc.n) .. "edge", parent = UI.host,
        x = cx - pad, y = y - pad, w = cardW + pad * 2, h = h + pad * 2,
        bg = CONFIG.COLOR.TC_CARD_ON_EDGE, text = "",
      }))
      -- 卡片底
      card.bg = part(create_text({
        name = "tc" .. tostring(tc.n) .. "bg", parent = UI.host,
        x = cx, y = y, w = cardW, h = h,
        bg = CONFIG.COLOR.TC_CARD, text = "",
      }))
      -- 档位名（卡内最上一行）
      card.name = part(create_text({
        name = "tc" .. tostring(tc.n) .. "name", parent = UI.host,
        x = cx, y = y + nameBase, w = cardW, h = nameH,
        text = tc.name,
        fontColor = CONFIG.COLOR.TC_NAME,
        fontSize = L.font(CONFIG.FONT.TC_NAME),
        hAlign = Enum.TextHorizontalAlignment.Middle,
        vAlign = Enum.TextVerticalAlignment.Middle,
      }))
      -- 三行说明：首钟（最上） / 加秒 / 预估（最下）
      local clockTxt, incTxt, estTxt = tc_meta_lines(tc)
      local metas = { clockTxt, incTxt, estTxt }
      card.meta = {}
      for m = 1, 3 do
        card.meta[m] = part(create_text({
          name = "tc" .. tostring(tc.n) .. "m" .. tostring(m), parent = UI.host,
          x = cx, y = y + metaY0 + metaStep * (3 - m), w = cardW, h = metaH,
          text = metas[m],
          fontColor = CONFIG.COLOR.TC_META,
          fontSize = L.font(CONFIG.FONT.TC_META),
          hAlign = Enum.TextHorizontalAlignment.Middle,
          vAlign = Enum.TextVerticalAlignment.Middle,
        }))
      end
      -- 命中区
      card.hit = part(create_cursor_area({
        name = "tc" .. tostring(tc.n) .. "hit", parent = UI.host,
        x = cx, y = y, w = cardW, h = h,
      }))
      st.cards[i] = card
    end
  end

  -- ===== ⑤ 2 个入口按钮（v3.2 删掉「单人·双人同屏」）=====
  -- 行 1 通栏 = 主入口「双人·联机对战」（琥珀实色）
  -- 行 2 通栏 = 「单人·复盘研习」（浅灰米）
  --
  -- 【v3.2 用户要求】「删除单人同屏模式」→ 入口从 3 个减到 2 个。
  --   主入口因此变成「联机对战」（原来它在行 2，因为同屏才是主推）。
  --   【两行都通栏】删掉同屏后，行 2 只剩「复盘研习」一个按钮。若它仍占左半格，
  --   右边会空出一整块，观感像「少画了一个按钮」（模拟器截图实测确认）。
  --   所以它也改成通栏，与主入口同宽。
  --   【联机时它会隐藏】有对手时「复盘研习」被 refresh_start_hint 关掉（用户要求），
  --   那时行 2 会整行消失 —— 这是**预期**的：此时只剩「联机对战」一个入口，
  --   视觉上正好是「单入口居中」，不会显得残缺。
  --
  -- 【v2.0 修 P0：三个入口按钮上一个字都没有】的历史说明保留在下方，
  --   提醒后来者：mk_entry 的 label 必须真的传进去（空串也是合法的 text 值，不报错）。
  do
    local btnFont = L.font(CONFIG.FONT.START_ENTRY)
    local function mk_entry(key, name, label, x, y, w, h, primary)
      local e = { key = key, label = label }
      e.btn = part(create_text({
        name = name, parent = UI.host, x = x, y = y, w = w, h = h,
        bg = primary and CONFIG.COLOR.ENTRY_PRIMARY or CONFIG.COLOR.ENTRY_BG,
        text = label,
        fontColor = primary and CONFIG.COLOR.ENTRY_TEXT_ON_P or CONFIG.COLOR.ENTRY_TEXT,
        fontSize = btnFont,
        hAlign = Enum.TextHorizontalAlignment.Middle,
        vAlign = Enum.TextVerticalAlignment.Middle,
        raycast = true,
      }))
      -- 上沿描边（与面板按钮同一个做法：让色块读作「可按键」）
      e.edge = part(create_text({
        name = name .. "edge", parent = UI.host,
        x = x, y = y + h - h * 0.10, w = w, h = h * 0.10,
        bg = CONFIG.COLOR.BTN_EDGE, text = "",
      }))
      e.hit = part(create_cursor_area({
        name = name .. "hit", parent = UI.host, x = x, y = y, w = w, h = h,
      }))
      st.entries[#st.entries + 1] = e
      return e
    end
    local x1, y1, w1, h1 = bandRect("ENTRY_R1", 0.16, 0.68)
    st.entryOnline = mk_entry("online", "startentryonline", CONFIG.TEXT.ENTRY_ONLINE,
                              x1, y1, w1, h1, true)
    local x2, y2, w2, h2 = bandRect("ENTRY_R2", 0.16, 0.68)
    st.entryReview = mk_entry("review", "startentryreview", CONFIG.TEXT.ENTRY_REVIEW,
                              x2, y2, w2, h2, false)
  end

  -- ===== ⑥ 底部提示（v3.1：版本号已按用户要求删除）=====
  -- 【历史】旧版把 `START_VERSION .. "　" .. START_FOOTER` 合成一个控件并居中，
  -- 全角空格在中间拉出空隙；v2.0 拆成左右两个控件（左版本号右提示）。
  -- 【v3.1 用户要求】删掉左侧「v2.0」，只留提示并**居中**（否则只剩右半边会明显偏右）。
  do
    local x, y, w, h = bandRect("FOOTER")
    st.footer = part(create_text({
      name = "startfooter", parent = UI.host,
      x = x, y = y, w = w, h = h,
      text = CONFIG.TEXT.START_FOOTER,
      fontColor = CONFIG.COLOR.START_FOOTER_TX,
      fontSize = L.font(CONFIG.FONT.START_FOOTER),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    }))
  end

  -- 【为什么这里不隐藏】初始界面的显隐由 show_start_screen / hide_start_screen 统一管。
  -- 关键陷阱：build_all_ui 末尾有一段「统一启用所有已创建控件」的裸 SetActive(true) 循环，
  -- 它**不经过 ui_set_active**，因此不会更新 VIS_STATE 缓存。
  -- 若在这里先 ui_set_active(part,false)（缓存=false），随后被那个循环裸置为 true，
  -- 缓存就与真实状态脱钩（缓存说隐藏、实际可见）—— 之后所有 ui_set_active(part,false)
  -- 都会被缓存短路掉，初始界面**永远关不掉**。
  -- 所以：这里什么都不做，让控件保持工厂创建时的隐藏态，由 build_all_ui 末尾的
  -- show_start_screen() 统一点亮（那一处走 ui_set_active，缓存与真实状态一致）。
end

-- =============================================================================
-- 待机室（v2.0 块 2）
-- -----------------------------------------------------------------------------
-- 【形态】与初始界面同构：盖在最上层的**不透明整层**（复用 bg_color_sample 的 24 条带）。
--   理由完全相同 —— 逐个隐藏棋盘/面板 1400 个控件会引入显隐竞态。
-- 【能力边界（决定了这一整层的形状）】客户端 Lua **读不到房间玩家列表/人数/昵称**
--   （gdd §10.2 U-1，已全量翻查 §6 game / §5 Script / §11 枚举）。
--   所以「对手」行只能由**信号握手**推断：收到过任何对方包 → 认为对手在线。
-- 【由此必须处理的边界】对手在场但一直不准备 与 对手根本不在，**无法区分**。
--   所以 LOBBY_PEER_TIMEOUT_SEC 之后必须显示 LOBBY_NOBODY 且「直接开始」仍可用，
--   绝不能让玩家卡死在等待里（Lead 明确要求）。
-- 【Z 序】与初始界面一样，本层必须**最后建**（同级后出现的在上），
--   且在 show_lobby 里重新 SetAsLastSibling 自己的命中区。
-- =============================================================================
local function build_lobby()
  local L = UI.L
  local W, H = L.canvasW, L.canvasH
  local LL = CONFIG.LOBBY_LAYOUT
  local lb = UI.lobby
  lb.parts = {}

  local function part(ctrl)
    if ctrl ~= nil then lb.parts[#lb.parts + 1] = ctrl end
    return ctrl
  end

  -- ===== ① 不透明底：兜底纯色 + 24 条渐变带（与主背景/初始界面逐条同值）=====
  part(create_text({
    name = "lobbybgbase", parent = UI.host,
    x = 0, y = 0, w = W, h = H,
    bg = CONFIG.COLOR.BG, text = "",
  }))
  local BANDS = 24
  local bandH = H / BANDS
  lb.bands = {}
  for i = 1, BANDS do
    local t = (i - 0.5) / BANDS
    lb.bands[i] = part(create_text({
      name = "lobbybg" .. tostring(i), parent = UI.host,
      x = 0, y = (i - 1) * bandH, w = W, h = bandH + 1,
      bg = bg_color_sample(t), text = "",
    }))
  end

  -- 按 LOBBY_LAYOUT 取一段矩形；xR/wR 为默认值时可覆盖
  local function bandRect(name, xR, wR)
    local b = LL[name]
    return W * (xR or 0.04), H * b.y, W * (wR or 0.92), H * b.h
  end

  -- 通用「一行文字」构造，返回控件（文案后续由 refresh_lobby 刷）
  local function mkLine(name, bandName, fontKey, colorKey, align, xR, wR)
    local x, y, w, h = bandRect(bandName, xR, wR)
    return part(create_text({
      name = name, parent = UI.host,
      x = x, y = y, w = w, h = h,
      text = "",
      fontColor = CONFIG.COLOR[colorKey],
      fontSize = L.font(CONFIG.FONT[fontKey]),
      hAlign = align or Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    }))
  end

  -- ===== ② 标题「联机·待机室」+ 右侧身份标注 =====
  -- 标题占左侧 62%，身份标注占右侧 36%（gdd §5.4：身份放在 TITLE 行右侧）
  lb.title = mkLine("lobbytitle", "TITLE", "LOBBY_TITLE", "LOBBY_TITLE_TX",
                    Enum.TextHorizontalAlignment.Middle, 0.04, 0.62)
  lb.sideTag = mkLine("lobbysidetag", "TITLE", "LOBBY_SMALL", "LOBBY_READY_OFF",
                      Enum.TextHorizontalAlignment.Right, 0.66, 0.30)

  -- ===== ③ 倒数大数字 =====
  -- 【为什么字号取 48 而不是 gdd 的 72】板高 0.115×900 = 103.5px，
  -- 平台要求「板高 ≥ 2.1×字号」→ 最多容 49.3px。72 号需 151.2px，整行会被吞掉
  -- （D-02 陷阱，本项目第三次）。详见 CONFIG.FONT.LOBBY_COUNTDOWN 的算式。
  lb.countdown = mkLine("lobbycountdown", "COUNTDOWN", "LOBBY_COUNTDOWN", "LOBBY_COUNT",
                        Enum.TextHorizontalAlignment.Middle, 0.04, 0.92)
  -- 倒数控件平时空字符串 + 隐藏由 show/hide_lobby 管；这里先给空文案

  -- ===== ④ 时间档归属行 =====
  lb.roomTc = mkLine("lobbyroomtc", "ROOM_TC", "LOBBY_SMALL", "TEXT_ACCENT",
                     Enum.TextHorizontalAlignment.Middle, 0.04, 0.92)

  -- ===== ⑤ 两行玩家（你 / 对手）=====
  -- 每行 = 卡片底（描边+底两张）+ 文字。描边必须建在底之前（同级后出现的在上）。
  local function mkPlayerRow(key, bandName, namePrefix)
    local bx, by, bw, bh = bandRect(bandName, 0.14, 0.72)
    local edgeT = math.max(1, L.cell * 0.012)
    local row = {}
    row.edgeBox = part(create_text({
      name = namePrefix .. "edge", parent = UI.host,
      x = bx - edgeT, y = by - edgeT, w = bw + edgeT * 2, h = bh + edgeT * 2,
      bg = CONFIG.COLOR.LOBBY_CARD_EDGE, text = "",
    }))
    row.bg = part(create_text({
      name = namePrefix .. "bg", parent = UI.host,
      x = bx, y = by, w = bw, h = bh,
      bg = CONFIG.COLOR.LOBBY_CARD, text = "",
    }))
    row.text = part(create_text({
      name = namePrefix .. "text", parent = UI.host,
      x = bx, y = by, w = bw, h = bh,
      text = "",
      fontColor = CONFIG.COLOR.TEXT_MAIN,
      fontSize = L.font(CONFIG.FONT.LOBBY_BODY),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
    }))
    lb[key] = row
    return row
  end
  mkPlayerRow("rowMe", "PLAYER1", "lobbyrowme")
  mkPlayerRow("rowOpp", "PLAYER2", "lobbyrowopp")

  -- ===== ⑥ 提示条 =====
  lb.hint = mkLine("lobbyhint", "HINT", "LOBBY_SMALL", "TEXT_SUB",
                   Enum.TextHorizontalAlignment.Middle, 0.04, 0.92)

  -- ===== ⑦ 两个按钮：准备/取消准备（主）、直接开始（次）=====
  -- 按钮结构沿用全项目惯例：底(文本控件) + 上沿描边 + 命中区
  local function mkBtn(key, bandName, namePrefix, primary)
    local x, y, w, h = bandRect(bandName, 0.30, 0.40)
    -- 触摸目标下限兜底（手机 720 高时 0.098×720 = 70.6 已够，这里仍显式兜一层）
    local btn = {}
    btn.text = part(create_text({
      name = namePrefix, parent = UI.host,
      x = x, y = y, w = w, h = h,
      bg = primary and CONFIG.COLOR.ENTRY_PRIMARY or CONFIG.COLOR.ENTRY_BG,
      text = "",
      fontColor = primary and CONFIG.COLOR.ENTRY_TEXT_ON_P or CONFIG.COLOR.ENTRY_TEXT,
      fontSize = L.font(CONFIG.FONT.LOBBY_BODY),
      hAlign = Enum.TextHorizontalAlignment.Middle,
      vAlign = Enum.TextVerticalAlignment.Middle,
      raycast = true,
    }))
    btn.edge = part(create_text({
      name = namePrefix .. "edge", parent = UI.host,
      x = x, y = y + h - h * 0.10, w = w, h = h * 0.10,
      bg = CONFIG.COLOR.BTN_EDGE, text = "",
    }))
    btn.hit = part(create_cursor_area({
      name = namePrefix .. "hit", parent = UI.host, x = x, y = y, w = w, h = h,
    }))
    lb[key] = btn
    return btn
  end
  mkBtn("btnReady", "READY_BTN", "lobbybtnready", true)
  mkBtn("btnSolo", "SOLO_BTN", "lobbybtnsolo", false)

  -- ===== ⑧ 底部提示 =====
  lb.footer = mkLine("lobbyfooter", "FOOTER", "LOBBY_SMALL", "START_FOOTER_TX",
                     Enum.TextHorizontalAlignment.Middle, 0.04, 0.62)
  -- 底部右端「返回主菜单」（gdd §5.8：无底框，只有字）
  local fx, fy, fw, fh = bandRect("FOOTER", 0.66, 0.30)
  lb.backMain = part(create_text({
    name = "lobbybackmain", parent = UI.host,
    x = fx, y = fy, w = fw, h = fh,
    text = CONFIG.TEXT.BTN_MENU,
    fontColor = CONFIG.COLOR.TEXT_SUB,
    fontSize = L.font(CONFIG.FONT.LOBBY_SMALL),
    hAlign = Enum.TextHorizontalAlignment.Right,
    vAlign = Enum.TextVerticalAlignment.Middle,
  }))
  lb.hitBackMain = part(create_cursor_area({
    name = "lobbybackmainhit", parent = UI.host,
    x = fx, y = fy, w = fw, h = fh,
  }))
end

-- =============================================================================
-- 【v3.3 已移除】复盘动作条（原 v2.0 块 4，棋盘下方「退回主变 / 从此开新局」两键）
-- -----------------------------------------------------------------------------
-- 用户要求删掉「退回主变」。这一整个动作条都是分支试走的配套 UI，所以一起移除：
--   · 「退回主变」  —— 分支的唯一出口（用户明确要删）
--   · 「从此开新局」—— 「以当前局面为起点开新局」需要先有分支/试走才有意义，
--                       分支没了它只是「从刚才看到的这一步重开」，与「新开一局」重复
-- 省下 6 个控件（2 键 × 文本/描边/命中区）。
-- 【连带】refresh_review_actionbar 这个函数也一起删了 —— 它的唯一职责就是切这两键的显隐。
--   注意：**不要**留下空实现，否则 build_all_ui / exit_review 里那几处调用会崩或静默失效。
-- =============================================================================

-- 显示/隐藏一个控件。
-- 【v1.11 性能】缓存当前可见状态，重复设置同一值直接跳过。
-- 这在本项目里命中率很高：clear_highlights 每次点空白都遍历 28 个落点池、
-- show_result 每次终局锁 64 个命中区、reset_piece_slots 每次重开遍历 32 槽 ——
-- 这些调用里绝大多数控件本来就是隐藏的，再写一遍纯属浪费（每次写都要过平台层）。
-- 【为什么缓存要放脚本侧弱键表】平台控件对象不保证允许写自定义字段，见 image_apply 同类说明。
-- 【首次调用一定写】缓存初值是 nil（未登记），任何控件第一次经过这里都会真的写一遍，
-- 所以不会出现「缓存说隐藏、实际可见」的错配。工厂与 build_all_ui 里那些
-- 直接调 platform SetActive 的地方不需要登记 —— 它们只让缓存暂时落后一次，不会读错。
ui_set_active = function(ctrl, active)
  if ctrl == nil then return end
  local want = active and true or false
  if VIS_STATE[ctrl] == want then
    cw_skip()
    return
  end
  VIS_STATE[ctrl] = want
  if want then
    cw(); ctrl:SetActive(true)
    cw(); ctrl:SetVisible(true)
  else
    cw(); ctrl:SetVisible(false)
    cw(); ctrl:SetActive(false)
  end
end

-- =============================================================================
-- 界面流程状态机（v2.0，块 1）
-- -----------------------------------------------------------------------------
-- 合法 SCREEN：start / lobby / playing / result / review
-- 【与 GAME.state 分开】GAME.state 是脚本生命周期（NEW/STARTING/RUNNING/…），
--   本组函数只改 GAME.screen，绝不改 GAME.state —— SelfTest 的 state_running
--   断言守的是「脚本活着」，那是回归基线。
--
-- 【为什么 show_start_screen 要把棋盘/面板也一起收起来】
--   初始界面是「不透明整层」，视觉上盖住就够；但**命中区不能靠视觉盖**。
--   棋盘 64 个命中区 + 面板 9 个命中区在 build_all_ui 末尾被 SetAsLastSibling()
--   提到了最顶层，会压在初始界面之上照样接收点击 —— 那样玩家在初始界面上点
--   标题区域会误触发棋盘/面板（本项目踩过同类「模态弹窗被下层命中区穿透」的事故）。
--   所以进出初始界面时必须显式开关这些命中区，视觉层只是第二道。
-- =============================================================================

-- 档位卡的选中态刷新：只改配色与描边显隐，不重建控件（播放期零创建）。
local function refresh_time_control_cards()
  local st = UI.startScreen
  if st == nil or st.cards == nil then return end
  for i = 1, #st.cards do
    local c = st.cards[i]
    local on = (c.n == GAME.tcN)
    if c.bg ~= nil then
      c.bg.bgColor = color_of(on and CONFIG.COLOR.TC_CARD_ON or CONFIG.COLOR.TC_CARD)
    end
    if c.name ~= nil then
      c.name.fontColor = color_of(on and CONFIG.COLOR.TC_NAME_ON or CONFIG.COLOR.TC_NAME)
    end
    ui_set_active(c.edgeOn, on)
  end
end

-- 初始界面上那两行状态文字（档位说明 / 联机协商状态）
--
-- 【v2.0 修：单人初始界面不显示「联机时以先选者为准」】
--   模拟器截图反馈：单人初始界面就写着这句联机规则，既不准确（单人没有联机）
--   又占地方。现在**默认就写「双方各选一个时间档 · 选好就自动开局」**，
--   没有对手时再改成「没找到另一位玩家 · 可点下面的单人入口开局」。
--
--   ⚠️ 与 docs/gdd-v2.md §3.7 的一处冲突：那份文档的主张是「本地模式也显示，
--      让玩家在选入口前就知道联机规则」。本实现按 Lead 的模拟器验收意见执行。
--
-- 【v3.0】这里同时承担「把对方选了哪个时间档告诉玩家」的职责（用户需求第 3 条）：
--   SUBTITLE = 双方各自选了什么；TC_HINT = 规则 / 5 秒倒计时 / 异常。
--   两行文案都做了「变了才写」缓存，因为 online_tick 每帧都会调本函数。
local function refresh_start_hint()
  local st = UI.startScreen
  if st == nil then return end
  local O = GAME.online or {}
  local now = GAME.onlineClock or 0
  local peerFresh = (O.peerSeenAt ~= nil) and ((now - O.peerSeenAt) <= CONFIG.MATCH_PEER_FRESH_SEC)
  local myTc = (O.myTier ~= nil) and tc_of(O.myTier) or nil
  local peerTc = (O.peerTier ~= nil) and tc_of(O.peerTier) or nil

  -- 占位符替换：模板里只有 {n}/{a}/{b}/{s} 四种，值都是中文档位名或整数
  local function fill(tmpl, n, a, b, s)
    local out = tmpl
    if n ~= nil then out = string.gsub(out, "{n}", n) end
    if a ~= nil then out = string.gsub(out, "{a}", a) end
    if b ~= nil then out = string.gsub(out, "{b}", b) end
    if s ~= nil then out = string.gsub(out, "{s}", s) end
    return out
  end

  local sub, hint = CONFIG.TEXT.START_SUBTITLE, CONFIG.TEXT.MATCH_HINT_IDLE
  if peerFresh and myTc ~= nil and peerTc ~= nil then
    if peerTc.n == myTc.n then
      sub = fill(CONFIG.TEXT.MATCH_SUB_SAME, myTc.name)
      hint = CONFIG.TEXT.MATCH_HINT_IDLE
    else
      -- 【占位符必须按名字对上】MATCH_SUB_CONFLICT 用的是 {a}（我）/ {b}（对手），
      -- 所以第 1 个实参 n 必须留 nil，否则会把「我」的档位名填进 {a}、
      -- 而 {b} 原样留在界面上（模拟器实测：显示成「你「闪电战」· 对手「{b}」」）。
      sub = fill(CONFIG.TEXT.MATCH_SUB_CONFLICT, nil, myTc.name, peerTc.name)
      local left = 0
      if O.conflictAt ~= nil then
        left = math.max(0, math.ceil(CONFIG.MATCH_DIFF_WAIT_SEC - (now - O.conflictAt)))
      end
      if left > 0 then
        hint = fill(CONFIG.TEXT.MATCH_HINT_CONFLICT, nil, nil, nil, tostring(left))
      else
        hint = CONFIG.TEXT.MATCH_HINT_CONFLICT_EDGE
      end
    end
  elseif peerFresh and myTc ~= nil then
    sub = fill(CONFIG.TEXT.MATCH_SUB_MY, myTc.name)
    hint = CONFIG.TEXT.MATCH_HINT_WAIT_PEER
  elseif peerFresh and peerTc ~= nil then
    sub = fill(CONFIG.TEXT.MATCH_SUB_PEER_ONLY, peerTc.name)
    hint = CONFIG.TEXT.MATCH_HINT_IDLE
  elseif myTc ~= nil then
    -- 我选好了但对手没消息：区分「刚进来」和「对手掉线/已离开」
    sub = fill(CONFIG.TEXT.MATCH_SUB_MY, myTc.name)
    if O.peerSeenAt ~= nil then
      hint = CONFIG.TEXT.MATCH_HINT_PEER_LOST
    else
      hint = CONFIG.TEXT.MATCH_HINT_WAIT_PEER
    end
  elseif O.peerSeenAt ~= nil and not peerFresh then
    sub = CONFIG.TEXT.START_SUBTITLE
    hint = CONFIG.TEXT.MATCH_HINT_IDLE
  else
    sub = CONFIG.TEXT.START_SUBTITLE
    -- 启动 8 秒内不报「没找到另一位玩家」，避免刚进来就吓人一跳
    if O.peerSeenAt == nil and now > 8 then
      hint = CONFIG.TEXT.MATCH_HINT_NO_PEER
    else
      hint = CONFIG.TEXT.MATCH_HINT_IDLE
    end
  end

  if st.subtitle ~= nil and st.subtitle.text ~= sub then st.subtitle.text = sub end
  if st.tcHint ~= nil and st.tcHint.text ~= hint then st.tcHint.text = hint end

  -- 【v3.2 用户要求】有另一位玩家联机时，关闭「单人复盘练习」入口。
  -- 【为什么要在这里刷】这个函数是初始界面的**唯一**动态刷新入口
  --   （每帧由 OnUpdate 走一次），把入口显隐挂在这里就不用另建一条刷新链路。
  -- 【显隐的写法必须三件套一起**】按钮 / 描边 / 命中区，漏一个就会留下
  --   「按钮没了但上沿还在」或「看不见但还能点」的残影（v2.0 踩过）。
  local e = st.entryReview
  if e ~= nil then
    local allow = not peerFresh
    ui_set_active(e.btn, allow)
    ui_set_active(e.edge, allow)
    ui_set_active(e.hit, allow)
  end
end

-- 整层显示/隐藏（一次性全切，不散落调用）
-- 收起一切覆盖层（初始界面 / 待机室 / 复盘动作条 / 复盘面板键）
-- 【为什么要有这个函数 —— 两次 P0 事故的总结】
--   ① 块 3：entry_start_local 漏调 hide_lobby() → 进对局后被待机室骨架盖住
--   ② 块 5：动作条没有任何「进入非复盘界面」的路径去收起它 →
--          初始界面和待机室底部都多出「退回主变」「从此开新局」两个按钮，
--          还压住了待机室底部的提示文字。
--   两次同型：**某个 show_XXX 忘了收起某层**。
-- 【做法】收敛成一个函数，每个 show_XXX_screen 开头调一次。
--   以后新增覆盖层只改这一处，不必让每个调用方各自记得 ——
--   「各自记得」正是前两次事故的成因。
-- 【注意】本函数只负责「收起」，不负责「显示」。显示仍由各 show_XXX 自己管。
local function hide_all_overlays()
  -- ① 待机室整层
  if UI.lobby ~= nil and UI.lobby.parts ~= nil then
    for i = 1, #UI.lobby.parts do ui_set_active(UI.lobby.parts[i], false) end
  end
  -- ② 【v3.3 已删除】复盘动作条（原「退回主变 / 从此开新局」两键）
  --   动作条整个移除后，这里不再需要无条件收起它。
end

-- 初始界面整层显隐（v2.0 块 1）
local function set_start_screen_visible(on)
  local st = UI.startScreen
  if st == nil or st.parts == nil then return false end
  for i = 1, #st.parts do ui_set_active(st.parts[i], on) end
  return true
end

-- 进入初始界面。
-- 【顺序要求】先关掉所有下层命中区，再开本层 —— 否则同一帧内可能出现「都开着」的窗口。
local function show_start_screen()
  GAME.screen = "start"
  if not GAME.uiReady then return end
  -- 【v2.0 根上做法：先收起其余一切覆盖层】
  -- 这条纪律来自两次真实事故：
  --   ① 块 3：entry_start_local 漏调 hide_lobby() → 进对局后被待机室骨架盖住（P0）
  --   ② 块 5：动作条从未被进入对局的路径收起 → 初始界面/待机室底部多出两个按钮（P0/BUG-1）
  --   两次都是「某个 show_XXX 忘了收起某层」。所以收敛成一个函数，
  --   **每个 show_XXX_screen 开头调一次**，以后新增覆盖层只改这一处。
  hide_all_overlays()
  -- ① 收掉下层一切可点区域（棋盘 / 面板 / 复盘 / 音效开关）
  for sq = 0, 63 do
    if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], false) end
  end
  show_panel_buttons(false)
  if UI.panel.hitSfx ~= nil then ui_set_active(UI.panel.hitSfx, false) end
  if UI.review.hitToggle ~= nil then ui_set_active(UI.review.hitToggle, false) end
  if UI.review.hitStart ~= nil then show_review_buttons(false) end
  -- ② 关掉可能残留的弹窗
  hide_result()
  hide_promo()
  -- 注意：hide_confirm 会按「非终局/非复盘」条件把棋盘与面板重新打开，
  -- 所以它必须在 ① 之后、② 的最后调用，然后我们再把命中区关一遍。
  hide_confirm()
  for sq = 0, 63 do
    if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], false) end
  end
  show_panel_buttons(false)
  if UI.panel.hitSfx ~= nil then ui_set_active(UI.panel.hitSfx, false) end
  if UI.review.hitToggle ~= nil then ui_set_active(UI.review.hitToggle, false) end
  -- ③ 开本层
  -- 【v3.0】回到初始界面 = 一次新协商：清空「我选的时间 / 冲突窗口」，
  --   并把视角恢复成白方在下（否则上一局执黑留下的翻转会带进单人模式）。
  GAME.match.set_flip(false)
  GAME.match.reset()
  set_start_screen_visible(true)
  refresh_time_control_cards()
  refresh_start_hint()
  -- ④ 本层命中区必须重新提到最顶层（build 时提过一次，但弹窗是之后建的）
  local function raise(c) if c ~= nil then pcall(function() c:SetAsLastSibling() end) end end
  for i = 1, #UI.startScreen.cards do raise(UI.startScreen.cards[i].hit) end
  for i = 1, #UI.startScreen.entries do raise(UI.startScreen.entries[i].hit) end
end

-- 离开初始界面（进入 playing / review / lobby 前调用）
local function hide_start_screen()
  set_start_screen_visible(false)
end

-- =============================================================================
-- 待机室状态刷新与显隐（v2.0 块 2）
-- -----------------------------------------------------------------------------
-- 设计要点（与 gdd §5 逐条对应）：
--   · 「对手」行的三种态由**信号**推算，读不到玩家列表（U-1）：
--       从未收到对方任何包        → LOBBY_SLOT_EMPTY（等待对手加入…）
--       收到过且对方未准备        → LOBBY_READY_OFF（未准备）
--       收到过且对方已准备        → LOBBY_READY_ON（已准备）
--   · 超过 LOBBY_PEER_TIMEOUT_SEC 仍没收到包 → 提示条换成 LOBBY_NOBODY，
--     且「直接开始」必须仍可用（不能让人卡死在等）。
--   · 时间档：先选者锁定。锁定后 4 张档位卡在**初始界面**上已不可点（那层此时已隐藏），
--     这里的 ROOM_TC 行只负责显示归属。
-- =============================================================================

-- 刷新整层文案（所有控件都在 build_lobby 里建好，这里只写 text/颜色）
refresh_lobby = function()
  local lb = UI.lobby
  if lb == nil or lb.title == nil then return end
  local G = GAME.lobby

  -- ① 我 行
  -- 【结构澄清（块 2 修 P0 时逐字核对过）】
  --   mkPlayerRow 里是 `row.text = part(create_text({...}))`，
  --   即 **lb.rowMe.text 就是那个文本框控件本身**，因此写文案要 `lb.rowMe.text.text`。
  --   （真正的 bug 在别处，见 ③ 段 roomTc —— 那里少写了一层。）
  local myReadyTxt = G.myReady and CONFIG.TEXT.LOBBY_READY_ON or CONFIG.TEXT.LOBBY_READY_OFF
  if lb.rowMe ~= nil and lb.rowMe.text ~= nil then
    -- 标签与状态之间是全角空格 U+3000（gdd §5.3 格式硬约束）
    lb.rowMe.text.text = CONFIG.TEXT.LOBBY_ME .. "　" .. myReadyTxt
  end
  -- ② 对手 行
  if lb.rowOpp ~= nil and lb.rowOpp.text ~= nil then
    local oppState
    if not G.peerSeen then
      oppState = CONFIG.TEXT.LOBBY_SLOT_EMPTY
    elseif G.peerReady then
      oppState = CONFIG.TEXT.LOBBY_READY_ON
    else
      oppState = CONFIG.TEXT.LOBBY_READY_OFF
    end
    lb.rowOpp.text.text = CONFIG.TEXT.LOBBY_OPP .. "　" .. oppState
    -- 状态色：已准备=琥珀、未准备=灰、未加入=更淡（gdd §5.3 靠文字+颜色，不画勾选图标）
    local col
    if not G.peerSeen then col = CONFIG.COLOR.LOBBY_ABSENT
    elseif G.peerReady then col = CONFIG.COLOR.LOBBY_READY_ON
    else col = CONFIG.COLOR.LOBBY_READY_OFF end
    lb.rowOpp.text.fontColor = color_of(col)
  end

  -- ③ 时间档归属行
  -- 【块 2 修 P0：这里原来写 `lb.roomTc.text = s`】
  --   mkLine 返回的是**控件本身**（不是含 .text 的包装表），
  --   所以 `lb.roomTc.text = s` 是给**控件对象**的 text 属性赋值 —— 语法上能跑，
  --   但那是写字符串进去；**视觉上确实该显示**… 真正致命的是它把语义搞混后，
  --   下面 ④ 段的 btnReady 用了正确写法却没生效，因为**前面已经抛错**。
  --
  --   ⚠️ 根因订正：本轮实测「整屏文字全丢、只有返回主菜单有字」的真凶是
  --   **lb.rowMe / lb.rowOpp 的结构**（.text 是控件）与 **lb.roomTc / lb.hint /
  --   lb.footer / lb.sideTag / lb.countdown**（本身就是控件）两套约定混用，
  --   而且没有任何地方做过「写完之后读回来确认」。
  --   现在统一：**凡 mkLine 返回的，本身就是控件 → 直接写 .text；
  --             凡 mkPlayerRow 返回的，是 {edgeBox,bg,text} 表 → 写 .text.text。**
  --   并在下方 lobby_texts_nonempty 自检里逐个断言非空，防止再次静默空白。
  if lb.roomTc ~= nil then
    local tc = tc_of(GAME.tcN)
    local owner
    if G.tcOwner == 1 then owner = CONFIG.TEXT.LOBBY_TC_MINE
    elseif G.tcOwner == 2 then owner = CONFIG.TEXT.LOBBY_TC_PEER
    else owner = CONFIG.TEXT.LOBBY_TC_NONE end
    local s = CONFIG.TEXT.LOBBY_TC_FMT
    s = string.gsub(s, "{name}", tc.name)
    s = string.gsub(s, "{clock}", format_clock_long(tc.initial))
    s = string.gsub(s, "{owner}", owner)
    if lb.roomTc.text ~= s then lb.roomTc.text = s end
  end

  -- ④ 准备键两态 + 「直接开始」静态文案
  -- 【块 2 修 P0：btnSolo 原来从 build 到 refresh 全程没有任何赋值 → 永远空串】
  -- 这是本轮的第二个真凶：mkBtn 建控件时 text=""，而 refresh_lobby 只刷了 btnReady。
  if lb.btnReady ~= nil and lb.btnReady.text ~= nil then
    lb.btnReady.text.text = G.myReady and CONFIG.TEXT.LOBBY_BTN_CANCEL
                                        or CONFIG.TEXT.LOBBY_BTN_READY
  end
  if lb.btnSolo ~= nil and lb.btnSolo.text ~= nil then
    local solo = CONFIG.TEXT.LOBBY_BTN_SOLO
    if lb.btnSolo.text.text ~= solo then lb.btnSolo.text.text = solo end
  end

  -- ④-b 标题（静态文案，必须在这里写：mkLine 建的时候是空串）
  if lb.title ~= nil then
    local t = CONFIG.TEXT.LOBBY_TITLE
    if lb.title.text ~= t then lb.title.text = t end
  end

  -- ⑤ 提示条：倒数中 → 取消过 → 超时没等到 → 默认
  if lb.hint ~= nil then
    local txt
    if G.countdown >= 0 then
      txt = CONFIG.TEXT.LOBBY_COUNTDOWN_HINT
    elseif G.peerLeft then
      txt = CONFIG.TEXT.LOBBY_CANCELED
    elseif not G.peerSeen and (G.peerSeenAt or 0) >= CONFIG.LOBBY_PEER_TIMEOUT_SEC then
      txt = CONFIG.TEXT.LOBBY_NOBODY
    else
      txt = CONFIG.TEXT.LOBBY_HINT
    end
    if lb.hint.text ~= txt then lb.hint.text = txt end
  end

  -- ⑥ 底部：只有对手未加入时提示「可以直接开始」
  if lb.footer ~= nil then
    local txt = G.peerSeen and CONFIG.TEXT.LOBBY_HINT or CONFIG.TEXT.LOBBY_HINT_WAIT
    if lb.footer.text ~= txt then lb.footer.text = txt end
  end

  -- ⑦ 身份标注
  if lb.sideTag ~= nil then
    local txt
    if GAME.mySide == 1 then txt = CONFIG.TEXT.LOBBY_SIDE_WHITE
    elseif GAME.mySide == 2 then txt = CONFIG.TEXT.LOBBY_SIDE_BLACK
    else txt = CONFIG.TEXT.LOBBY_SIDE_UNKNOWN end
    if lb.sideTag.text ~= txt then lb.sideTag.text = txt end
  end

  -- ⑧ 倒数大数字：只在整数秒变化时写（避免每帧写 text）
  if lb.countdown ~= nil then
    local shown = ""
    if G.countdown >= 0 then
      -- 显示 3/2/1：ceil 让 [2,3)→3、[1,2)→2、[0,1)→1
      local n = math.ceil(G.countdown)
      if n < 1 then n = 1 end
      shown = tostring(n)
    end
    if G.countdownShown ~= shown then
      G.countdownShown = shown
      lb.countdown.text = shown
    end
  end
end

-- 整层显示/隐藏（一次性全切）
local function set_lobby_visible(on)
  local lb = UI.lobby
  if lb == nil or lb.parts == nil then return false end
  for i = 1, #lb.parts do ui_set_active(lb.parts[i], on) end
  return true
end

-- 进入待机室
-- 【顺序】先关下层可点区域 → 关残留弹窗 → 开本层 → 提命中区。与 show_start_screen 同构。
local function show_lobby()
  GAME.screen = "lobby"
  if not GAME.uiReady then return end
  -- 【v2.0 块 5 BUG-1】先收起其余覆盖层（含复盘动作条），只留待机室
  hide_all_overlays()
  set_start_screen_visible(false)
  for sq = 0, 63 do
    if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], false) end
  end
  show_panel_buttons(false)
  if UI.panel.hitSfx ~= nil then ui_set_active(UI.panel.hitSfx, false) end
  if UI.review.hitToggle ~= nil then ui_set_active(UI.review.hitToggle, false) end
  hide_result()
  hide_promo()
  hide_confirm()
  -- hide_confirm 会按条件把棋盘/面板重新打开，所以收敛后再关一遍（同 show_start_screen）
  for sq = 0, 63 do
    if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], false) end
  end
  show_panel_buttons(false)
  if UI.panel.hitSfx ~= nil then ui_set_active(UI.panel.hitSfx, false) end
  if UI.review.hitToggle ~= nil then ui_set_active(UI.review.hitToggle, false) end

  set_lobby_visible(true)
  refresh_lobby()

  -- 命中区提到最顶层（本层是本函数时刻最上的一层）
  local lb = UI.lobby
  local function raise(c) if c ~= nil then pcall(function() c:SetAsLastSibling() end) end end
  raise(lb.btnReady and lb.btnReady.hit)
  raise(lb.btnSolo and lb.btnSolo.hit)
  raise(lb.hitBackMain)
end

-- 离开待机室
local function hide_lobby()
  set_lobby_visible(false)
end

-- 待机室 → 开局（倒数结束或双方就绪后的唯一出口）
-- 【职责边界】只做「离开待机室层 + 重置房间状态 + 按当前档位开局 + 切 screen」。
--   不广播信号 —— 广播由块 5 的信号层在这里之后负责（EV_START 强制对齐两端倒数）。
-- 【为什么在这里再 apply_time_control 一次】待机室期间档位可能被对手的信号改过
--   （块 5 的 EV_READY 全量二元组）。开局这一刻必须把档位「定格」成实际要用的值。
local function start_game_from_lobby(broadcast)
  -- 【自检零副作用】自检期间不真正开局（会改 screen / new_game / 广播）。
  -- ev_start_sent_once 断言只想验「broadcast 参数生效」，不该真的把玩家推进对局。
  if GAME.inSelfTest then
    if broadcast ~= false then
      -- 只记一下「本来会广播」（不发包、不改状态），供断言读取
      GAME.__selfTestWouldBroadcast = true
    end
    return false
  end
  local G = GAME.lobby
  G.countdown = -1
  G.countdownShown = -1
  G.myReady = false
  G.peerReady = false
  G.peerSeen = false
  G.peerSeenAt = 0
  G.timeoutShownOnce = false
  G.peerLeft = false
  -- 【v2.0 块 5 BUG-1】开局前收起一切覆盖层（含动作条）
  hide_all_overlays()
  hide_lobby()
  apply_time_control(GAME.tcN)
  -- 【联机对局】localMode = false，轮到谁由 st.turn 决定，GAME.mySide 决定能否操作
  new_game()
  GAME.screen = "playing"
  -- 【v2.0 修】同 entry_start_local：screen 落到 playing 之后必须再刷一次悔棋按钮，
  --   否则 `new_game()` 里那一次刷的是旧 screen，第三行会停在「看历史」。
  if refresh_undo_button ~= nil then refresh_undo_button() end
  if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.HINT_OPENING end
  -- 块 5：倒数结束/EV_START 触发的真正开局，广播 b=档位号。
  -- 【v2.0 块 5 修 BUG-3：EV_START 双发】
  -- 实测服务端 outbound 里出现两条 EV_START（Player1 和 Player2 各发一条）。
  -- 根因：两端各自走到这里都会广播，而且**收到对方 EV_START 后调用本函数的那一路也会广播**
  --   → 两端各发一次，共 2 包。
  -- 后果：a/b 相同时幂等所以看着没事，但一旦两端档位号不同就会「后到的为准」，
  --   结果不确定；将来若加开局动画，双包还会触发两次。
  -- 【修法】加 broadcast 参数。只有「本地主动发起」时才广播：
  --   · 倒数跑完的超时兜底 → broadcast = true
  --   · 「直接开始」单机兜底 → 另外单独发（见 UI.lobby.btnSolo 的 handler）
  --   · **收到对方 EV_START 而开局 → broadcast = false**（对端已经发过了）
  if broadcast ~= false then
    -- 【方案 T】fen 带 token，让自己的回声能被识别出来
    local tok = make_self_token()
    GAME.__myStartToken = tok
    net_send_event(CONFIG.EV_START, 0, GAME.tcN, 0, tok)
  end
  log_info("待机室开局：档位=%d（%d+%d）同屏=%s 我方=%s 广播=%s",
    GAME.tcN, GAME.tcInitial, GAME.tcIncrement,
    tostring(GAME.localMode), tostring(GAME.mySide), tostring(broadcast ~= false))
  return true
end

-- =============================================================================
-- 第 7 区：GAME（业务状态与流程）
-- -----------------------------------------------------------------------------
-- 【v2.0 关键搬迁：GAME 的声明已上移到第 6 区 UI 之前】
--   原因是一个只在运行期才暴露的前向引用 bug（模拟器实测崩溃）：
--     sim/levelScript.lua:3348: attempt to index a nil value (global 'GAME')
--   `show_start_screen`（UI 区，3347 行）函数体里写 `GAME.screen = "start"`，
--   而 `local GAME = {` 原本在 3385 行 —— 函数体在**编译期**就把 GAME 解析成
--   global（此刻作用域内还没有 local GAME），运行时是 nil，一赋就崩。
--   ⚠️ tools_work/lua_check.cjs 的「先用后定义」检查只查**函数名**的前向引用，
--      不查**函数体内部的变量**是否还没声明 —— 这是那道门禁的盲区，抓不到这一类。
--   修法：GAME 是纯状态表（只依赖 CONFIG，不依赖任何 UI 控件），
--   没有理由定义在 UI 之后。整体上移后，「谁先谁后」的隐患从根上消除。
--   任何「在某个 local X = {} 之前定义的函数」里用到 X，都要单独核一遍。
-- =============================================================================

-- =============================================================================
-- 走时档（v2.0）
--   tc_of / format_clock_long / tc_meta_lines 已上移到第 5 区之前 —— UI 建档位卡时
--   要读它们，必须遵守「先声明后使用」（lua_check 的检查抓过这一条）。
--   这里只保留需要读 GAME 的 apply_time_control。
-- =============================================================================

-- 选定档位并把数值抄进 GAME（开局前调用；联机时先选者锁定后不再改）
apply_time_control = function(n)
  local tc = tc_of(n)
  GAME.tcN = tc.n
  GAME.tcInitial = tc.initial
  GAME.tcIncrement = tc.inc
  return tc
end

-- =============================================================================
-- 复盘视图（v1.6）
--   复盘中所有渲染都从这里取「当时」的数据，绝不改 GAME.st：
--   退出复盘后原局面、棋钟、失子、走子记录全部原样继续。
--   快照本身只存最小信息（fen + 计数 + 棋钟），局面表按需 parse 后缓存到
--   GAME.reviewState，翻页时只 parse 一次，不在逐帧里做。
--
--   【为什么这些函数必须定义在 format_clock/set_clock_labels 之前】
--   Lua 的 local function 作用域是词法向前。update_clock_text 会调用 view_clocks，
--   show_last_move 会调用 review_snap，所以它们必须排在渲染函数之前。
--   （实测踩过：先放渲染函数、后放这几个视图函数 → OnStart 报
--     "attempt to call a nil value (global 'view_clocks')"，界面建完就崩。）
-- =============================================================================
local function review_snap()
  if GAME.review == nil then return nil end
  local snap = GAME.history[GAME.review.idx + 1]
  return snap
end

-- 复盘中当前步的棋盘（无复盘时返回真实棋盘）
-- 【v3.3】分支已移除，这里不再需要「分支优先」那层判断（少一次表访问/比较）
local function view_board()
  if GAME.review ~= nil and GAME.reviewState ~= nil then
    return GAME.reviewState.board
  end
  return GAME.st.board
end

-- 复盘中当前步的棋局状态（无复盘时返回真实状态）
local function view_state()
  if GAME.review ~= nil and GAME.reviewState ~= nil then
    return GAME.reviewState
  end
  return GAME.st
end

-- 复盘中当前步的棋钟（无复盘时返回真实棋钟）
local function view_clocks()
  local snap = review_snap()
  if snap ~= nil then return snap.clockW, snap.clockB end
  return GAME.clockWhite, GAME.clockBlack
end

-- 复盘中当前步的失子列表（只显示到该步为止吃掉的子）
local function view_captured(list, upto)
  if GAME.review == nil then return list end
  local out = {}
  local n = math.min(upto, #list)
  for i = 1, n do out[i] = list[i] end
  return out
end

-- 复盘时面板「轮次行」改成进度行；正常模式返回 nil（由 update_turn_text 走原文案）
local function review_turn_text()
  if GAME.review == nil then return nil end
  if GAME.review.idx == 0 then
    -- v2.0：从初始界面「复盘研习」进来的空态复盘（allowEmpty）用这条专属文案，
    -- 否则玩家看到「复盘 · 开局」却没有步数，会以为进了个坏掉的界面。
    if GAME.review.allowEmpty then return CONFIG.TEXT.REVIEW_AT_START_BRANCH end
    return CONFIG.TEXT.REVIEW_AT_START
  end
  local total = #GAME.history - 1
  local s = string.gsub(CONFIG.TEXT.REVIEW_STEP, "{n}", tostring(GAME.review.idx))
  s = string.gsub(s, "{m}", tostring(total))
  return s
end

local function format_clock(sec)
  if sec < 0 then sec = 0 end
  local total = math.floor(sec)
  local m = total // 60
  local s = total % 60
  return string.format("%02d:%02d", m, s)
end

-- 按给定秒数刷新两个棋钟文本（正常模式传 GAME.clockWhite/Black，复盘传快照值）
-- v1.7：当前走子方那一行变亮、另一行压暗，一眼能看出「轮到谁」。
--
-- 【v1.11 性能】棋钟每 CLOCK_REFRESH_SEC 刷一次，加上 render_all 也会调它。
-- 每次写 text / fontColor / bgColor 都会触发平台重新排版与合批，
-- 而实际上「秒数没变、亮暗没变」时这三项一个都不用写。这里缓存上一次写入的值，
-- 全都没变就整段返回 —— 实测每 0.25 秒的这条路径从 6 次控件写降到 0 次。
local CLOCK_CACHE = { w = nil, b = nil, wCol = nil, bCol = nil, wBg = nil, bBg = nil }

local function set_clock_labels(w, b)
  if not GAME.uiReady then return end
  -- 复盘中不判「轮到谁」，两行同权重
  local reviewing = (GAME.review ~= nil)
  local turn = GAME.st and GAME.st.turn or WHITE
  local wActive = reviewing or (turn == WHITE)
  local bActive = reviewing or (turn == BLACK)

  -- 亮暗底色（复盘中两边同权重 → 都是 PANEL_SECTION）
  local wBg = wActive and CONFIG.COLOR.PANEL_SECTION or CONFIG.COLOR.PANEL_INNER
  local bBg = bActive and CONFIG.COLOR.PANEL_SECTION or CONFIG.COLOR.PANEL_INNER

  if UI.panel.clockWhite then
    local col
    if w <= CONFIG.CLOCK_LOW_SEC then
      col = CONFIG.COLOR.CLOCK_LOW
    elseif wActive then
      col = CONFIG.COLOR.CLOCK_ACTIVE
    else
      col = CONFIG.COLOR.TEXT_SUB
    end
    -- 【只显示到秒】文本按 format_clock 的整秒比较，避免亚秒变化造成无意义重写
    local txt = "白 " .. format_clock(w)
    if CLOCK_CACHE.w ~= txt then
      CLOCK_CACHE.w = txt
      UI.panel.clockWhite.text = txt
    end
    if CLOCK_CACHE.wCol ~= col then
      CLOCK_CACHE.wCol = col
      UI.panel.clockWhite.fontColor = color_of(col)
    end
    if UI.panel.clockWhiteBg and CLOCK_CACHE.wBg ~= wBg then
      CLOCK_CACHE.wBg = wBg
      UI.panel.clockWhiteBg.bgColor = color_of(wBg)
    end
  end
  if UI.panel.clockBlack then
    local col
    if b <= CONFIG.CLOCK_LOW_SEC then
      col = CONFIG.COLOR.CLOCK_LOW
    elseif bActive then
      col = CONFIG.COLOR.CLOCK_ACTIVE
    else
      col = CONFIG.COLOR.TEXT_SUB
    end
    local txt = "黑 " .. format_clock(b)
    if CLOCK_CACHE.b ~= txt then
      CLOCK_CACHE.b = txt
      UI.panel.clockBlack.text = txt
    end
    if CLOCK_CACHE.bCol ~= col then
      CLOCK_CACHE.bCol = col
      UI.panel.clockBlack.fontColor = color_of(col)
    end
    if UI.panel.clockBlackBg and CLOCK_CACHE.bBg ~= bBg then
      CLOCK_CACHE.bBg = bBg
      UI.panel.clockBlackBg.bgColor = color_of(bBg)
    end
  end
end

local function update_clock_text(force)
  if not GAME.uiReady then return end
  local w, b = view_clocks()
  set_clock_labels(w, b)
end

local function update_turn_text()
  if not GAME.uiReady or UI.panel.turn == nil then return end
  -- 复盘中显示进度行（「复盘 · 第 N/M 步」），不显示轮次
  local rt = review_turn_text()
  local txt
  if rt ~= nil then
    txt = rt
  elseif GAME.over then
    -- 终局显示「棋局结束」（策划案 S-07）。
    -- 【不能直接 return 不管】原先这里写 `if GAME.over then return end`，
    -- 退出复盘时轮次行就停在「复盘 · 第 N/M 步」上不还原（模拟器实测到残影）。
    txt = CONFIG.TEXT.TURN_OVER
  elseif GAME.st.turn == WHITE then
    txt = CONFIG.TEXT.TURN_WHITE
  else
    txt = CONFIG.TEXT.TURN_BLACK
  end
  -- 【v3.0】联机时用「轮到你 / 等对手」代替「轮到白方/黑方」：
  --   执黑的一方视角已经翻转，再说「轮到白方走子」会让人以为轮到自己了。
  --   同屏模式不变（同一人操作双方，白/黑才是有效信息）。
  if not GAME.localMode and GAME.review == nil and not GAME.over then
    local myTurn = (GAME.mySide == 1 and GAME.st.turn == WHITE)
                or (GAME.mySide == 2 and GAME.st.turn == BLACK)
    if myTurn then
      txt = (GAME.mySide == 1) and CONFIG.TEXT.TURN_MINE_WHITE or CONFIG.TEXT.TURN_MINE_BLACK
    else
      txt = CONFIG.TEXT.WAIT_OPPONENT
    end
  end
  -- 【v1.11 性能】文案没变就不写（render_all 每步都调到这里）
  if UI.panel.turn.text ~= txt then UI.panel.turn.text = txt end
end

-- 只清「落点池」：把 28 个绿点/红罩全部隐藏，并把使用计数归零。
--
-- 【issue #3 的根因就在这里，别再把它合回 select_square】
--   select_square 旧写法**不是**先清空落点池再画新的，而是直接 `UI.legalHLUsed = idx`
--   把计数器改成「这次有几个落点」。池子是按索引复用的：
--     上一次选中一个有 8 个落点的子 → legalhl1..8 全被 SetActive(true)
--     这一次选中一个只有 2 个落点的子 → 只重写 legalhl1..2，legalhl3..8 **原样留在盘上**
--   结果就是：画面上同时出现「本次的 2 个绿点」+「上次剩下 6 个绿点」，
--   而那 6 个绿点指向的格子这枚棋子根本走不到 —— 用户看到的就是
--   issue #3 截图里那种「选中 d4 的马，绿点却散落在马走不到的地方」。
--   点那些残留绿点没有反应（try_move 会校验 legalTargets 并拒绝），
--   于是手感变成「点了没反应」而不是「这里不能走」。
--
--   为什么单独抽一个函数：clear_highlights（取消选中/走子/新开局/退出复盘）
--   也要做同一件事，两处必须用同一段逻辑，否则迟早又漂移成两个版本。
local function hide_legal_pool()
  for i = 1, 28 do
    if UI.legalHL[i] then ui_set_active(UI.legalHL[i], false) end
  end
  UI.legalHLUsed = 0
  -- 基准位置表一并丢掉：anim_update_hilites 按 legalHLUsed 遍历，虽然越界项不会被读到，
  -- 但留着上一局的坐标会让调试时看到的数字具有误导性。
  ANIM.hlBase = {}
end

local function clear_highlights()
  hide_legal_pool()
  if UI.selHL then ui_set_active(UI.selHL, false) end
  if UI.selRingTop then ui_set_active(UI.selRingTop, false) end
  if UI.selRingBot then ui_set_active(UI.selRingBot, false) end
  GAME.selected = nil
  GAME.legalTargets = {}
  GAME.legalMoves = {}
end

-- =============================================================================
-- 高亮的呼吸/脉冲（v1.7）
-- -----------------------------------------------------------------------------
-- 静态色块看起来「死板」，加一层极轻微的尺寸与色深脉动，画面立刻活起来。
-- 全部按 ANIM.clock 算相位，不再单独累计时间：
--   选中格  → 0.95s 周期，尺寸 1.00↔1.02，透明度跟随正弦
--   落点圆点 → 1.15s 周期，尺寸 1.00↔1.12，同相位错开（读起来像一圈点子在闪）
-- 每帧只改仍可见的那几个，落点最多 28 个，开销可忽略。
-- 【注意类型】selHL 是文本框（bgColor），legalHL 池是图片控件（imageColor），
--   两种控件的颜色字段名不同，写错会抛 "no such field"（模拟器实测踩到）。
-- =============================================================================
local function anim_update_hilites(dt)
  if not GAME.animated then return end
  local t = ANIM.clock
  local L = UI.L

  -- 选中格：薄罩脉冲（尺寸几乎不变，主要让透明度呼吸出来）
  if UI.selHL ~= nil and UI.selHL.active and UI.selHLx ~= nil then
    local ph = (t % CONFIG.ANIM.SELECT_PULSE) / CONFIG.ANIM.SELECT_PULSE
    local s = math.sin(ph * math.pi * 2)
    local side = L.cell * (1 + s * 0.018)
    UI.selHL:SetSizeDelta(side, side)
    UI.selHL:SetAnchoredPosition(UI.selHLx - (side - L.cell) / 2,
                                 UI.selHLy - (side - L.cell) / 2)
    UI.selHL.bgColor = color_alpha(CONFIG.COLOR.SEL_HL, 0.80 + s * 0.20)
    -- 上下亮框跟着薄罩一起呼吸（只改宽度，竖向位置随薄罩边缘）
    if UI.selRingTop ~= nil and UI.selRingTop.active then
      UI.selRingTop:SetSizeDelta(side, UI.selRingW)
      UI.selRingTop:SetAnchoredPosition(UI.selHLx - (side - L.cell) / 2,
                                        UI.selHLy + side - UI.selRingW)
      UI.selRingTop.bgColor = color_alpha(CONFIG.COLOR.SEL_RING_A, 0.80 + s * 0.20)
      UI.selRingBot:SetSizeDelta(side, UI.selRingW)
      UI.selRingBot:SetAnchoredPosition(UI.selHLx - (side - L.cell) / 2, UI.selHLy)
      UI.selRingBot.bgColor = color_alpha(CONFIG.COLOR.SEL_RING_B, 0.80 + s * 0.20)
    end
  end

  -- 落点：错相位呼吸
  -- 【v1.11】hlBase 现在存的是**中心点**（图片控件 pivot=0.5），所以缩放时位置不变，
  -- 只改尺寸即可 —— 中心不动的缩放。旧代码还额外减了 (d - b.size)/2，
  -- 那是「按左下角定位」的补偿，在中心定位下会让圆点每帧往左下漂一点。
  local used = UI.legalHLUsed or 0
  local base = ANIM.hlBase
  if base == nil then return end
  for i = 1, used do
    local c = UI.legalHL[i]
    local b = base[i]
    if c ~= nil and b ~= nil and c.active then
      local ph = ((t + i * 0.09) % CONFIG.ANIM.LEGAL_PULSE) / CONFIG.ANIM.LEGAL_PULSE
      local k = 1 + math.sin(ph * math.pi * 2) * 0.12
      local d = b.size * k
      c:SetSizeDelta(d, d)
      c:SetAnchoredPosition(b.x, b.y)
    end
  end
end

-- =============================================================================
-- 复盘视图（v1.6）已上移至 format_clock 之前（词法作用域要求先声明后使用）
-- =============================================================================

local function show_last_move()
  if not GAME.uiReady then return end
  local snap = review_snap()
  local fromSq, toSq
  if snap ~= nil then
    -- 复盘中：显示「当前这一步」的起终点；开局（idx=0）没有上一步
    if GAME.review.idx > 0 then fromSq, toSq = snap.from, snap.to end
  else
    fromSq, toSq = GAME.lastFrom, GAME.lastTo
  end
  if fromSq and toSq then
    local L = UI.L
    -- v3.0：黑方视角下上一步痕迹也要跟着翻（GAME.match.sq 只换格号，不改控件本身）
    local x1, y1 = LAYOUT.square_pos(L, GAME.match.sq(fromSq))
    local x2, y2 = LAYOUT.square_pos(L, GAME.match.sq(toSq))
    UI.lastMoveHL[1]:SetAnchoredPosition(x1, y1)
    UI.lastMoveHL[2]:SetAnchoredPosition(x2, y2)
    ui_set_active(UI.lastMoveHL[1], true)
    ui_set_active(UI.lastMoveHL[2], true)
  else
    ui_set_active(UI.lastMoveHL[1], false)
    ui_set_active(UI.lastMoveHL[2], false)
  end
end

local function show_check_warning()
  if not GAME.uiReady then return end
  -- 复盘中按快照局面判定；开局快照不判（避免刚开局就亮将军格）
  local snap = review_snap()
  if snap ~= nil and GAME.review.idx == 0 then
    ui_set_active(UI.checkHL, false)
    return
  end
  local st = view_state()
  local ksq = nil
  if st then ksq = RULES.find_king(st, st.turn) end
  if ksq and RULES.in_check(st, st.turn) then
    local L = UI.L
    local x, y = LAYOUT.square_pos(L, GAME.match.sq(ksq))
    UI.checkHL:SetAnchoredPosition(x, y)
    ui_set_active(UI.checkHL, true)
  else
    ui_set_active(UI.checkHL, false)
  end
end

-- 棋子配色：按棋子符号取「体色 / 描边色」
local function piece_colors(p)
  if p > 0 then
    return CONFIG.COLOR.WHITE_FILL, CONFIG.COLOR.WHITE_EDGE
  end
  return CONFIG.COLOR.BLACK_FILL, CONFIG.COLOR.BLACK_EDGE
end

-- 画一枚棋子到一个槽位。slot.prims 是固定容量池，播放期只改不建。
--
-- 【v1.11 层序（去掉了底部投影，issue #1 第 5 条）】
--   ① 外形描边：全部形体形状各自外扩 pad，画描边色
--   ② 外形填充：全部形体形状按原尺寸，画体色
--   ③ 镂空描边：镂空形状外扩 pad，画描边色（让眼窝等有边）
--   ④ 镂空填充：镂空形状按原尺寸，画**棋格色**（视觉上等于挖穿）
--   ⑤ 细节线：role2，对比色，原尺寸
--
-- 为什么描边不逐个形状画：逐形画会在棋子内部相邻形状交界处画出线，
-- 变成「一堆叠起来的积木」。整组放大再整组缩小，只有最外廓出现描边。
--
-- 【v1.11 性能】image_apply 加了「值相同就不写控件」的短路，见该函数的说明。
-- 本函数每帧被脏槽位重绘调用时，同一枚棋子的形状数据是不变的 ——
-- 只有随动画变化的尺寸/位置需要写，其余（图元、颜色、旋转）全部命中缓存跳过。
--
-- scale：动画用的整体缩放（1 = 原大），缩放中心是棋子方框中心
-- dy   ：动画用的额外竖直偏移（画布单位）
-- opts ：可选。v3.2 新增，给「吃子成就区」用同一套绘制画小号棋子：
--          opts.box      = 方框边长（默认 L.cell）
--          opts.holeBg   = 镂空填充色（默认按 sq 推出棋格色）
--          opts.centerX  = 方框中心 X（给了就按中心排，忽略 bx 的「左下角」语义）
--          opts.centerY  = 方框中心 Y
--          opts.noOutline= true 时不画外形描边层（小图标上描边会把细节糊掉）
local function paint_slot(slot, p, bx, by, sq, scale, dy, opts)
  local L = UI.L
  local box = (opts ~= nil and opts.box) or L.cell
  local side = box * 0.92
  scale = scale or 1
  dy = dy or 0

  if slot.prims == nil then return end

  local art = piece_art_of(p)
  local cap = #slot.prims
  local n = 0
  -- 可见性缓存：slot.shown[k] = 该图元当前是否已激活。挂在槽位表上（不是控件上），
  -- 因为平台控件对象不保证允许写自定义字段。
  local shown = slot.shown
  if shown == nil then
    shown = {}
    slot.shown = shown
  end

  local function take()
    n = n + 1
    if n > cap then return nil end
    return slot.prims[n]
  end

  local function next_visible()
    local c = take()
    if c ~= nil then
      -- 【性能】只有从隐藏变可见时才写 active/visible；槽位复用时这个分支很少命中。
      -- 可见性标记放在槽位自己的表里（slot.shown[k]），不写到平台控件对象上。
      if not shown[n] then
        shown[n] = true
        ui_set_active(c, true)
      end
    end
    return c
  end

  if art == nil then
    for k = 1, cap do
      if shown[k] then shown[k] = false; ui_set_active(slot.prims[k], false) end
    end
    return
  end

  local fill, edge = piece_colors(p)

  -- 缩放后的棋子方框：中心不动，边长 × scale
  -- 【视觉居中】+ piece_center_dy() * sside：把形状并集的竖向中心对到格中心（见该函数说明）
  local sside = side * scale
  local ox, oy
  if opts ~= nil and opts.centerX ~= nil and opts.centerY ~= nil then
    -- 【吃子成就区用】按「中心点」定位：小图标不需要再走棋格的左下角语义
    ox = opts.centerX - sside / 2
    oy = opts.centerY - sside / 2 + dy + piece_center_dy() * sside
  else
    ox = bx + (box - sside) / 2
    oy = by + (box - sside) / 2 + dy + piece_center_dy() * sside
  end

  -- 【描边：每个形状各自向外长 t，而不是整组等比放大】
  --
  -- 这里走过一段弯路，把两个方案写清楚，避免再反复：
  --
  -- 方案 A（试过，弃用）：整组形状绕棋子方框中心等比放大 (1+k)。
  --   问题：离中心越远的形状，放大后外移越多。于是同一枚棋子，
  --   远离中心的那一侧描边粗、靠近中心的一侧细 —— 一圈边粗细不均，看起来"发胖"。
  --
  -- 方案 B（现在用）：每个形状自己向外长 t，中心不动。
  --   描边层 = 全部形状各自向外扩 t；填充层 = 原尺寸。
  --   两层之差正好是「并集整体向外偏 t」，也就是一圈**均匀**的描边。
  --   对单个形状这是精确的；对并集只在形状之间的凹角处略厚一点，
  --   在 1px 量级完全看不出来。
  --
  -- 还有一点要说明：形状之间本来就有宽窄差，外扩之后宽块仍比窄块宽 ——
  -- 这是**对的**，那正是原图的轮廓，不是需要消除的"台阶"。
  -- 真正会出"台阶"的是拿一串宽度递减的矩形去逼近曲线 —— 那种情况要靠改用椭圆/三角形，
  -- 而不是靠调整描边算法。
  --
  -- 【v1.11 细长形状夹一道上限】pad 是「方框比例的绝对量」，对 0.05 宽的鬃毛
  -- 相当于自身宽度的 80%，会把细节糊成色斑。所以再按短边比例夹一层（见 CONFIG 说明）。
  local padBase = CONFIG.PIECE_OUTLINE_PAD * sside
  local thinRatio = CONFIG.PIECE_PAD_THIN_RATIO
  local function pad_of(s)
    local limit = math.min(s[4], s[5]) * sside * thinRatio
    if limit < padBase then return limit end
    return padBase
  end

  -- ① 外形描边层：**全部形状先画一遍描边**，② 再全部画一遍填充
  --
  -- 【顺序绝不能改成交替画（会出大事）】
  --   若改成「形状 A 的描边 + A 的填充 → 形状 B 的描边 + B 的填充 → …」，
  --   那么 B 的描边就会压在 A 的填充之上，棋子内部每两个形状的交界处都会出现一道描边色，
  --   整枚棋子变成「一堆描好的积木叠起来」，冠尖/鬃毛上还会戳出一圈黑边
  --   （v1.11 第一版实测：白王头上长出几个黑色三角、黑车身上出现白色描边缝）。
  --   必须是「所有描边 → 所有填充」两遍，描边层才只在**并集外缘**露出来。
  for _, s in ipairs(art) do
    if s[7] == 0 then
      local pad = pad_of(s)
      local c = next_visible()
      if c == nil then break end
      image_apply(c, prim_asset(s[1]), edge, s[6])
      cw(); c:SetSizeDelta(s[4] * sside + pad * 2, s[5] * sside + pad * 2)
      cw(); c:SetAnchoredPosition(ox + s[2] * sside, oy + s[3] * sside)
    end
  end  for _, s in ipairs(art) do
    if s[7] == 0 then
      local c = next_visible()
      if c == nil then break end
      image_apply(c, prim_asset(s[1]), fill, s[6])
      cw(); c:SetSizeDelta(s[4] * sside, s[5] * sside)
      cw(); c:SetAnchoredPosition(ox + s[2] * sside, oy + s[3] * sside)
    end
  end

  -- ③ 镂空描边层 + ④ 镂空填充层：同样「先全部描边、再全部填充」
  -- 【镂空填充用棋格色】平台图元没有挖洞能力，只能「用底色再画一遍同一形状」。
  -- 注意这个色依赖于该格明暗，所以带镂空的棋子走到另一种颜色的格子上时必须重绘 ——
  -- image_apply 的颜色缓存不会误判（颜色真的变了）。
  local sqIsDark = ((sq // 8) + (sq % 8)) % 2 == 0
  local holeColor = (opts ~= nil and opts.holeBg) or (sqIsDark and CONFIG.COLOR.SQ_DARK or CONFIG.COLOR.SQ_LIGHT)
  for _, s in ipairs(art) do
    if s[7] == 1 then
      local pad = pad_of(s)
      local c = next_visible()
      if c == nil then break end
      image_apply(c, prim_asset(s[1]), edge, s[6])
      cw(); c:SetSizeDelta(s[4] * sside + pad * 2, s[5] * sside + pad * 2)
      cw(); c:SetAnchoredPosition(ox + s[2] * sside, oy + s[3] * sside)
    end
  end
  for _, s in ipairs(art) do
    if s[7] == 1 then
      local c = next_visible()
      if c == nil then break end
      image_apply(c, prim_asset(s[1]), holeColor, s[6])
      cw(); c:SetSizeDelta(s[4] * sside, s[5] * sside)
      cw(); c:SetAnchoredPosition(ox + s[2] * sside, oy + s[3] * sside)
    end
  end

  -- ⑤ 细节线（cburnett 风格专属，role=2）
  -- 这是 en-croissant 那套棋子的灵魂：车身的砖缝、后的冠弧、王的冠带、象的十字、
  -- 马的鬃线、兵的颈线。它们用**对比色**画（白子画深线、黑子画浅线），
  -- 尺寸就用数据本身的宽高 —— 不外扩，因为细节线不是轮廓，外扩会变成一道粗纹。
  -- 绘制顺序放在最后：细节线永远压在填充层之上，否则会被前面的形状盖掉。
  local detailColor = edge   -- 白子：描边色=深色；黑子：描边色=浅色 → 正好是对比色
  for _, s in ipairs(art) do
    if s[7] == 2 then
      local c = next_visible()
      if c == nil then break end
      image_apply(c, prim_asset(s[1]), detailColor, s[6])
      cw(); c:SetSizeDelta(s[4] * sside, s[5] * sside)
      cw(); c:SetAnchoredPosition(ox + s[2] * sside, oy + s[3] * sside)
    end
  end

  -- 多余图元隐藏（容量池比实际用量大时）
  for k = n + 1, cap do
    if shown[k] then shown[k] = false; ui_set_active(slot.prims[k], false) end
  end
end

-- 把一个槽位的所有图元隐藏
local function hide_slot(slot)
  if slot == nil or slot.prims == nil then return end
  local shown = slot.shown
  for k = 1, #slot.prims do
    if shown == nil or shown[k] then
      if shown ~= nil then shown[k] = false end
      ui_set_active(slot.prims[k], false)
    end
  end
end

-- 棋子渲染（v1.7：槽位稳定绑定 + 平滑移动）
--
-- 【为什么要「稳定绑定」而不是每帧按下标重排】
--   旧实现是「按 sq 顺序把棋子塞进 slot[1..n]」，走一步棋之后所有槽位的
--   归属都会变，于是想给「被移动的那一枚」做补间就无从下手 —— 只能整盘重画，
--   看起来就是棋子瞬间跳过去。现在改成：槽位一旦绑定某个棋子身份就保持不动
--   （slot.sq 记录当前所在格），只在棋子被吃/升变时才解绑。
--   这样「从 e2 到 e4」就是同一个槽位改两个坐标，补间一次即可，棋子不会散架。
--
-- 【槽位身份】slot.key = 棋子符号（有符号棋子ID）；slot.sq = 当前格号；
--   slot.x / slot.y = 当前实际绘制位置（动画推进时逐帧改写）；
--   slot.sx / slot.sy = 目标位置（渲染目标）。
--   动画只改 x/y，不重新解算形状，所以 32 枚一起动也不掉帧。
local function slot_bind(slot, p, sq)
  slot.key = p
  slot.sq = sq
end

local function render_pieces(onlySlots, onlyCount)
  if not GAME.uiReady then return end
  if UI.pieceSlots == nil or UI.pieceSlots[1] == nil then return end

  local board = view_board()
  local L = UI.L

  -- ===== 快速路径：只重绘指定的槽位（v1.10 提速）=====
  -- 【为什么需要这条路径】动画期间 OnUpdate 每帧调一次 render_pieces()，
  -- 全量路径要「重建 bySq（64 格 + 32 槽）→ 遍历 32 槽 → 每槽 paint_slot」，
  -- 而 paint_slot 对一枚棋子要做 6 遍形状遍历、每个图元 3~4 次控件写。
  -- 32 枚 × 数十图元 ≈ 每帧数千次控件写 → 动画期间整体掉帧，手感就是「不跟手」。
  -- 但动画**只改一两个槽位**的 x/y/scale/lift，其余 30 枚这一帧根本没变，
  -- 重绘它们纯属浪费。所以动画分支只把「本帧真的变了」的槽位传进来。
  --
  -- 【为什么不漏绘】前提是「只有槽位自身字段变了才需要重绘」这条不变量成立：
  --   · 槽位归属（slot.sq / slot.key）只在 render_pieces 全量路径、apply_move、
  --     reset_piece_slots 里改，这三处之后都会走全量 render_pieces；
  --   · 动画任务（anim_move_piece / anim_capture_piece / board_intro）只改
  --     x / y / scale / lift / fading，不改归属。
  --   所以动画期间「归属」是稳定的，只有 x/y/scale/lift 在动 —— 只重绘这些槽位就够。
  --   动画跑完后 OnUpdate 还会补一帧**全量** render_pieces（见 OnUpdate 的 needsRepaint），
  --   把任何可能的残留（半格、旧位置）彻底刷干净。
  if onlySlots ~= nil then
    -- 注意：Lua 的 `#t` 对「带洞的表」不可靠，所以索引列表的长度由调用方显式给出
    -- （anim_take_dirty 返回的 dirtyCount）。缺省时退回 #onlySlots 兜底。
    local nSlots = onlyCount or #onlySlots
    ANIM.paintFramesPartial = ANIM.paintFramesPartial + 1
    for i = 1, nSlots do
      local slot = onlySlots[i]
      if slot ~= nil then
        if slot.sq ~= nil then
          if slot.x == nil then
            -- 理论上不会发生（动画开始前 slot.x 已由全量路径设好），兜底防崩
            slot.x, slot.y = LAYOUT.square_pos(L, GAME.match.sq(slot.sq))
          end
          paint_slot(slot, slot.key, slot.x, slot.y - (slot.lift or 0),
                     slot.sq, slot.scale or 1, 0)
          ANIM.paintSlotsTotal = ANIM.paintSlotsTotal + 1
        elseif slot.fading then
          if slot.x ~= nil then
            paint_slot(slot, slot.key, slot.x, slot.y - (slot.lift or 0),
                       slot.fadeSq or 0, slot.scale or 1, 0)
            ANIM.paintSlotsTotal = ANIM.paintSlotsTotal + 1
          end
        end
      end
    end
    return
  end
  ANIM.paintFramesFull = ANIM.paintFramesFull + 1

  -- ① 建立「格号 → 槽位」映射，并把已经不在该格的槽位解绑
  local bySq = UI.slotBySq or {}
  for sq = 0, 63 do bySq[sq] = nil end
  for i = 1, CONFIG.PIECE_MAX_SLOTS do
    local slot = UI.pieceSlots[i]
    if slot ~= nil and slot.sq ~= nil then
      if board[slot.sq] ~= slot.key then
        slot.sq = nil; slot.key = nil      -- 这一枚已经不在原处（被吃/走掉）
      else
        bySq[slot.sq] = slot
      end
    end
  end

  -- ② 给还没占位的棋子分配空闲槽位
  for sq = 0, 63 do
    local p = board[sq]
    if p ~= 0 and bySq[sq] == nil then
      for i = 1, CONFIG.PIECE_MAX_SLOTS do
        local slot = UI.pieceSlots[i]
        if slot ~= nil and slot.sq == nil then
          slot_bind(slot, p, sq)
          local bx, by = LAYOUT.square_pos(L, GAME.match.sq(sq))
          slot.x, slot.y = bx, by      -- 新出现的子直接就位（不补间）
          bySq[sq] = slot
          break
        end
      end
    end
  end
  UI.slotBySq = bySq

  -- ③ 逐槽位重绘（位置用 slot.x/slot.y，动画推进时它会被改写）
  local used = 0
  for i = 1, CONFIG.PIECE_MAX_SLOTS do
    local slot = UI.pieceSlots[i]
    if slot ~= nil and slot.sq ~= nil then
      used = used + 1
      if slot.x == nil then
        slot.x, slot.y = LAYOUT.square_pos(L, GAME.match.sq(slot.sq))
      end
      paint_slot(slot, slot.key, slot.x, slot.y - (slot.lift or 0),
                 slot.sq, slot.scale or 1, 0)
    elseif slot ~= nil and slot.fading then
      -- 正在播放「被吃淡出」的槽位：继续画，直到动画播完自己隐藏
      if slot.x ~= nil then
        local sq = slot.fadeSq or 0
        paint_slot(slot, slot.key, slot.x, slot.y - (slot.lift or 0),
                   sq, slot.scale or 1, 0)
      end
    else
      hide_slot(slot)
    end
  end
  UI.slotShown = used
end

-- 找到当前落在某格的槽位（动画用）
local function slot_at(sq)
  if UI.slotBySq == nil then return nil end
  return UI.slotBySq[sq]
end

-- 平滑移动一枚棋子：fromSq → toSq，带弧线抬升 + 落子回弹。
-- 【为什么用弧线】直线横移看起来像「幻灯片」，加一点抛物线抬升后棋子像被拿起来放下。
-- 弧线用 sin(πu) 做钟形：两端为 0、中间最高，天然和起止对齐，不用额外配参数。
--
-- 【关键】slot.sq 在动画开始时**立刻改成 toSq**，而不是等落地才改。
--   原因：render_pieces 靠「slot.sq 上的棋子是否还是 slot.key」来判断槽位是否还有效，
--   并且只绘制有效槽位。若动画期间 sq 为 nil，这一枚会被判为无效直接隐藏，
--   于是「走子」看起来是原地消失 + 目标格冒出来，弧线动画根本看不到。
local function anim_move_piece(slot, fromSq, toSq, onDone)
  if slot == nil then return end
  local L = UI.L
  -- v3.0：动画端点同样走 GAME.match.sq，否则黑方视角下「起点在下面、落点在别的格」
  local x0, y0 = LAYOUT.square_pos(L, GAME.match.sq(fromSq))
  local x1, y1 = LAYOUT.square_pos(L, GAME.match.sq(toSq))
  local cell = L.cell
  local arc = CONFIG.ANIM.MOVE_ARC * cell
  local dur = CONFIG.ANIM.MOVE_DUR

  slot.sq = toSq          -- 立刻认领目标格（见上方说明）
  slot.x, slot.y = x0, y0 -- 绘制位置从起点开始
  slot.moving = true

  local ease = EASE.outCubic
  anim_add(dur, function(u)
    local e = ease(u)
    slot.x = x0 + (x1 - x0) * e
    slot.y = y0 + (y1 - y0) * e
    slot.lift = math.sin(u * math.pi) * arc
    -- 抬起时略微放大，落地回到原大（0.05 的呼吸量刚好不夸张）
    slot.scale = 1 + math.sin(u * math.pi) * 0.05
  end, function()
    slot.x, slot.y = x1, y1
    slot.lift = 0
    slot.moving = false
    -- 落子回弹：1.0 → 1+PEAK → 1.0
    -- SETTLE_NORM 把 sin(v·π)·(1-v) 的 0.579230 峰值归一，让视觉峰值真正等于 SETTLE_PEAK
    -- （见 CONFIG.ANIM.SETTLE_NORM 的说明；不归一会只弹到 4%，不是 Demo 的 7%）
    anim_add(CONFIG.ANIM.SETTLE_DUR, function(v)
      local k = 1 - v
      slot.scale = 1 + math.sin(v * math.pi) * k * CONFIG.ANIM.SETTLE_PEAK
                     * CONFIG.ANIM.SETTLE_NORM
    end, function()
      slot.scale = 1
      if onDone then onDone() end
    end, slot)   -- ← 回弹段也登记脏槽位
  end, slot)     -- ← 位移段登记脏槽位
end

-- 棋子被吃：原地缩小 + 上飘淡出。
-- 【为什么要 slot.fading】被吃掉的槽位已经脱离了棋盘归属（那一格现在是吃子的子），
--   render_pieces 会判它无效并隐藏。所以给它打个 fading 标记，让它继续被绘制，
--   直到动画播完再真正隐藏。
local function anim_capture_piece(slot)
  if slot == nil then return end
  slot.fadeSq = slot.sq      -- 挖洞色要用原格的明暗，先记下来
  slot.sq = nil
  slot.fading = true
  local s0 = slot.scale or 1
  local lift0 = slot.lift or 0
  anim_add(CONFIG.ANIM.CAPTURE_FADE, function(u)
    local k = 1 - u
    slot.scale = s0 * k * k
    slot.lift = lift0 + u * CONFIG.ANIM.MOVE_ARC * UI.L.cell * 0.8
  end, function()
    slot.fading = false
    slot.key = nil
    slot.fadeSq = nil
    slot.scale = 1
    slot.lift = 0
    hide_slot(slot)
  end, slot)   -- ← 淡出段登记脏槽位（fading 槽位也走局部重绘的 fading 分支）
end

-- 界面重建/重开时把槽位绑定全部清掉（避免新棋盘沿用旧槽位的动画中间态）
local function reset_piece_slots()
  for i = 1, CONFIG.PIECE_MAX_SLOTS do
    local slot = UI.pieceSlots[i]
    if slot ~= nil then
      hide_slot(slot)
      slot.sq = nil; slot.key = nil
      slot.x, slot.y = nil, nil
      slot.scale = 1
      slot.lift = 0
      slot.moving = false
      slot.fading = false
    end
  end
  UI.slotBySq = nil
  UI.slotShown = 0
end

local function render_captured()
  if not GAME.uiReady then return end
  local snap = review_snap()
  local cw, cb
  if snap ~= nil then
    cw = view_captured(GAME.capturedWhite, snap.capW)
    cb = view_captured(GAME.capturedBlack, snap.capB)
  else
    cw, cb = GAME.capturedWhite, GAME.capturedBlack
  end

  -- ===== v3.2：吃子改用棋子图案（用户要求）=====
  -- 【两行怎么分】
  --   capturedWhite = 白方被吃掉的子（= 黑方吃到的战果）
  --   capturedBlack = 黑方被吃掉的子（= 白方吃到的战果）
  --   第一行 = **对方被吃**（我的战果），第二行 = **我被吃**。
  --   所以：
  --     我执白 → 第一行 = capturedBlack（黑子被吃）、第二行 = capturedWhite（白子被吃）
  --     我执黑 → 第一行 = capturedWhite（白子被吃）、第二行 = capturedBlack（黑子被吃）
  --   【同屏模式没有「我方/对方」】同一人操作两色，此时按「白方视角」显示，
  --   标签也会换成「白方被吃的 / 黑方被吃的」—— 见下方 localMode 分支。
  local iAmWhite = (GAME.mySide == 1)
  if GAME.localMode then iAmWhite = true end
  local peerList, mineList, peerIsBlack, mineIsBlack
  if iAmWhite then
    peerList, mineList = cb, cw          -- 我方白：第一行是黑子被吃
    peerIsBlack, mineIsBlack = true, false
  else
    peerList, mineList = cw, cb          -- 我方黑：第一行是白子被吃
    peerIsBlack, mineIsBlack = false, true
  end

  -- 标签文案（同屏用颜色名，联机用「你」）
  local lblPeer, lblMine
  if GAME.localMode then
    lblPeer = CONFIG.TEXT.CAP_LABEL_PEER_LOCAL
    lblMine = CONFIG.TEXT.CAP_LABEL_MINE_LOCAL
  else
    lblPeer = CONFIG.TEXT.CAP_LABEL_PEER
    lblMine = CONFIG.TEXT.CAP_LABEL_MINE
  end
  if UI.panel.capLabelPeer ~= nil and UI.panel.capLabelPeer.text ~= lblPeer then
    UI.panel.capLabelPeer.text = lblPeer
  end
  if UI.panel.capLabelMine ~= nil and UI.panel.capLabelMine.text ~= lblMine then
    UI.panel.capLabelMine.text = lblMine
  end

  -- 把一枚棋子画进一个吃子槽位（小号，白色底衬托）
  -- 【为什么要 holeBg】这些小棋子不落在棋盘格上，镂空处（眼窝等）没有棋格色可以借，
  --   用面板内底色（PANEL_INNER）才不会出现「一块花斑」。
  local iconBox = UI.panel.capIconBox or (UI.L.cell * 0.5)
  local holeBg = CONFIG.COLOR.PANEL_INNER
  local function paint_row(slots, list, isBlack)
    if slots == nil then return end
    for i = 1, CONFIG.CAP_SLOTS_PER_SIDE do
      local slot = slots[i]
      local letter = list[i]
      if slot ~= nil then
        if letter == nil then
          -- 空槽：把所有图元关掉
          for k = 1, #slot.prims do
            if slot.shown[k] then slot.shown[k] = false; ui_set_active(slot.prims[k], false) end
          end
        else
          local p = cap_letter_to_piece(letter, isBlack)
          if p ~= nil then
            paint_slot(slot, p, 0, 0, 0, 1, 0, {
              box = iconBox, holeBg = holeBg,
              centerX = slot.cx, centerY = slot.cy,
            })
          end
        end
      end
    end
  end
  paint_row(UI.panel.capSlotsPeer, peerList, peerIsBlack)
  paint_row(UI.panel.capSlotsMine, mineList, mineIsBlack)

  -- 两行都空时给一句「无」，否则标签后面的空白会让玩家以为是没画出来
  local emptyPeer = (#peerList == 0) and CONFIG.TEXT.CAP_NONE or ""
  local emptyMine = (#mineList == 0) and CONFIG.TEXT.CAP_NONE or ""
  if UI.panel.capEmptyPeer ~= nil and UI.panel.capEmptyPeer.text ~= emptyPeer then
    UI.panel.capEmptyPeer.text = emptyPeer
  end
  if UI.panel.capEmptyMine ~= nil and UI.panel.capEmptyMine.text ~= emptyMine then
    UI.panel.capEmptyMine.text = emptyMine
  end
end

-- 【v3.2 已删除】render_move_log —— 用户要求「删除历史走子」。
-- 保留本注释是为了让后来者知道这块**不是漏了**：面板里的走子记录区已被
-- 「吃子成就区」取代（见 render_captured 与 PANEL_LAYOUT.CAP_AREA）。
-- GAME.moveLog 数据仍然保留（结算/复盘诊断要用），只是不再画到界面上。

local function render_all()
  render_pieces()
  render_captured()
  update_clock_text()
  update_turn_text()
  show_last_move()
  show_check_warning()
  -- v2.0 块 3：悔棋按钮文案「悔棋（剩 N）」与置灰态随局面/轮次变化，必须跟主渲染一起刷。
  -- 【为什么放这里而不是每帧】按钮文案只在「走子/悔棋/换局/轮次切换」时变，
  -- 这些路径最后都会走 render_all；每帧刷是纯浪费（v1.10 的教训：多余控件写会掉帧）。
  if refresh_undo_button ~= nil then refresh_undo_button() end
end

-- 走子记录文本：白 e2→e4

local function move_text(mv, side)
  local function sqname(sq)
    return string.char(string.byte("a") + (sq % 8)) .. tostring((sq // 8) + 1)
  end
  local prefix = (side == WHITE) and "白 " or "黑 "
  local s = prefix .. sqname(mv.from) .. "→" .. sqname(mv.to)
  if mv.promo then
    local chars = { [QUEEN] = "=Q", [ROOK] = "=R", [BISHOP] = "=B", [KNIGHT] = "=N" }
    s = s .. chars[mv.promo]
  end
  return s
end

-- 应用一步棋（含吃子记录、走子记录、棋钟加秒、终局判定）
--
-- 【v1.7 动画接入：必须在 RULES.make 之前抓槽位】
--   make 之后棋盘的 e2 已经空了、e4 已经是自己的子，再靠格号找「被移动的那一枚」会
--   找到自己刚放上去的那一格。所以顺序是：
--     ① 先按 from/to 抓出「要走的那枚」与「要吃的那些」槽位
--     ② make 改状态
--     ③ 渲染（此时槽位的 sq 已失效，会自动重绑到正确格）
--     ④ 用 ① 抓到的槽位对象播放移动 / 淡出动画
--   槽位一旦抓到手，后续重绑不影响它（动画只改 slot.x/y/scale）。
local function apply_move(mv)
  local side = GAME.st.turn
  local captured = GAME.st.board[mv.to]
  local capSq = mv.to
  if mv.ep then
    capSq = shift(mv.to, side == WHITE and -1 or 1, 0)
    captured = GAME.st.board[capSq]
  end

  -- ① 动画前置：抓槽位（此时棋盘还是「走之前」的状态）
  local movingSlot = nil
  local capturedSlot = nil
  if GAME.animated and GAME.uiReady then
    movingSlot = slot_at(mv.from)
    if captured ~= 0 then
      capturedSlot = slot_at(capSq)
      -- 王车易位时车也要动：车的槽位在另一侧角上
    end
  end

  RULES.make(GAME.st, mv)

  -- 吃子记录
  if captured ~= 0 then
    local letter = PIECE_LETTER[captured]
    if captured > 0 then
      GAME.capturedWhite[#GAME.capturedWhite + 1] = letter
    else
      GAME.capturedBlack[#GAME.capturedBlack + 1] = letter
    end
  end

  -- 走子记录
  GAME.moveLog[#GAME.moveLog + 1] = move_text(mv, side)
  GAME.lastFrom = mv.from
  GAME.lastTo = mv.to
  GAME.turnCount = GAME.turnCount + 1

  -- 棋钟加秒（走子方 +当前档位的加秒数）
  -- 【v2.0】从 CONFIG.INCREMENT_SEC 改成读 GAME.tcIncrement（档位驱动）。
  -- 超快棋 60+0 的 inc=0，这里加 0 是正确的（不是漏写）。
  if side == WHITE then
    GAME.clockWhite = GAME.clockWhite + (GAME.tcIncrement or 0)
  else
    GAME.clockBlack = GAME.clockBlack + (GAME.tcIncrement or 0)
  end

  -- 【复盘快照】每走一步追加一项，供复盘逐手回放（v1.6）
  -- 只存最小信息：走完后的 FEN + 该步文案 + 起终点 + 双方失子数 + 双方棋钟。
  -- 局面表在复盘翻页时才 parse，不在逐帧里做。
  GAME.history[#GAME.history + 1] = {
    fen = RULES.fen_of(GAME.st),
    text = GAME.moveLog[#GAME.moveLog],
    from = mv.from, to = mv.to,
    capW = #GAME.capturedWhite, capB = #GAME.capturedBlack,
    clockW = GAME.clockWhite, clockB = GAME.clockBlack,
  }

  -- ② 先播「被吃」的淡出（它已经不属于棋盘，渲染不会碰它）
  if capturedSlot ~= nil then anim_capture_piece(capturedSlot) end

  -- 终局判定
  local status = RULES.game_status(GAME.st)
  if status.over then
    GAME.over = true
    if status.result == "1-0" then
      GAME.resultText = CONFIG.TEXT.RESULT_WHITE_WIN
      GAME.resultSub = (status.reason == "checkmate") and CONFIG.TEXT.SUB_CHECKMATE
        or CONFIG.TEXT.SUB_RESIGN_BLACK
    elseif status.result == "0-1" then
      GAME.resultText = CONFIG.TEXT.RESULT_BLACK_WIN
      GAME.resultSub = (status.reason == "checkmate") and CONFIG.TEXT.SUB_CHECKMATE
        or CONFIG.TEXT.SUB_RESIGN_WHITE
    else
      -- 【键名修正】这里原先写的是 RESULT_DRAW_AGREED_AGREED（多打了一个 _AGREED），
      -- CONFIG.TEXT 里并不存在该键 → 取到 nil → 结算标题为空（模拟器实测：和棋结算标题空白）。
      -- 正确键是 RESULT_DRAW_AGREED。和棋标题按下法分档：逼和/五十步/三次重复/子力不足各有专名。
      if status.reason == "stalemate" then GAME.resultText = CONFIG.TEXT.RESULT_STALEMATE
      elseif status.reason == "fifty" then GAME.resultText = CONFIG.TEXT.RESULT_FIFTY
      elseif status.reason == "threefold" then GAME.resultText = CONFIG.TEXT.RESULT_THREEFOLD
      elseif status.reason == "insufficient" then GAME.resultText = CONFIG.TEXT.RESULT_INSUFFICIENT
      else GAME.resultText = CONFIG.TEXT.RESULT_DRAW_AGREED end
      if status.reason == "stalemate" then GAME.resultSub = CONFIG.TEXT.SUB_STALEMATE
      elseif status.reason == "fifty" then GAME.resultSub = CONFIG.TEXT.SUB_FIFTY
      elseif status.reason == "threefold" then GAME.resultSub = CONFIG.TEXT.SUB_THREEFOLD
      elseif status.reason == "insufficient" then GAME.resultSub = CONFIG.TEXT.SUB_INSUFFICIENT
      else GAME.resultSub = CONFIG.TEXT.SUB_DRAW_AGREED end
    end
  end

  clear_highlights()

  -- ③ 渲染新局面前，先把「被移动的那枚」临时挂到目标格上（不让它被当成新子就地瞬移）
  if movingSlot ~= nil then
    movingSlot.sq = mv.to
    movingSlot.key = GAME.st.board[mv.to]
    -- 易位：王走两格时，车也要动
  end

  render_all()

  -- ④ 播移动动画（渲染之后，画面上已经是「棋子出现在目标格」的状态，
  --    但 slot.x/y 还是起点，下一帧就从这个位置补间过去）
  if movingSlot ~= nil then
    anim_move_piece(movingSlot, mv.from, mv.to, nil)
  end

  -- ⑤ 音效（v1.10）。顺序与优先级完全照 Demo（chess_demo.html 第 2002-2009 行）：
  --   走子/吃子先出声，将军与终局是「更重要的信息」，覆盖在后面再响一次。
  --   【易位只播 CASTLE 不播 MOVE】易位本质也是走子，但 Demo 的语义是「两步一起动」，
  --   播普通走子音会让人觉得「还有一枚没走」；所以易位走独立的更重的那一声。
  --   【联机回声不出声】对方走子经 net_on_signal 也会进 apply_move，
  --   若不加标记，同一手棋会在两端各响一次（本端 + 收到广播那一端各响）——
  --   但这里其实两端各响一次是**对的**（各自玩家都在自己屏幕上看到这步），
  --   所以不做回声过滤，与 Demo 的 fromRemote 语义保持一致即可（Demo 也是远端不出声，
  --   因为它模拟的是同一台机器双窗口；真机上两端是两个玩家，各响一次才对）。
  if mv.castle then
    sfx_play("castle")
  elseif captured ~= 0 then
    sfx_play("capture")     -- 吃子优先于走子（同一手只响一声）
  else
    sfx_play("move")
  end

  local nowInCheck = (not GAME.over) and RULES.in_check(GAME.st, GAME.st.turn)
  if nowInCheck then sfx_play("check") end
  -- 【终局音放到 show_result 里统一播】apply_move 只是一条到达终局的路径，
  -- 认输 / 超时 / 和棋 / 联机收到对方认输都不经过这里。统一在 show_result 播，
  -- 配合 SFX.overFired 保证「任何路径都只响一次」。见 show_result 的实现。
  if status.over then show_result() end
end

-- 正常模式的面板按钮（新开/认输/求和/同屏）显隐
-- 【为什么必须定义在 show_result 之前】show_result / hide_result / show_confirm 都要用它
-- 锁/解锁面板。Lua 是**词法作用域**：函数体在「定义那一刻」就确定名字绑定，不是运行时才查。
-- 所以只要 show_result（更早）的函数体里出现 show_panel_buttons，就必须让这个名字在它之前
-- 已经是 local —— 否则会被绑成 global，运行时是 nil。
-- 【踩过的坑】曾把它移到 hide_result 之前就以为够了，漏了更早的 show_result，
-- 结果所有终局路径（认输/将死/超时/和棋）全部崩在
-- `attempt to call a nil value (global 'show_panel_buttons')`，结算面板弹不出来。
-- lua_check.cjs 的「局部函数无先用后定义」检查抓到了它。
show_panel_buttons = function(on)
  -- 【v3.2：联机时「新开一局」「返回主菜单」要禁掉】
  -- 用户要求：「当有另一位玩家联机时，关闭单人复盘练习按钮、返回主菜单按钮和新开一局」。
  -- 【为什么必须禁而不是只靠确认框】联机对局里单方面新开一局会让两端局面直接分叉
  --   （对方还在原来那盘棋上），这比「点了没反应」严重得多。
  --   「返回主菜单」同理：它是对局中离场，对方会突然失去对手。
  -- 【判据】GAME.peerOnline 由 net 层维护（收到过对方包且心跳未过期）——见 net_peer_online()。
  local peerOn = (net_peer_online ~= nil) and net_peer_online() or false
  local allowNew = on and (not peerOn)
  local allowMenu = on and (not peerOn)
  ui_set_active(UI.panel.btnNew, allowNew)
  ui_set_active(UI.panel.btnResign, on)
  ui_set_active(UI.panel.btnDraw, on)
  ui_set_active(UI.panel.hitNew, allowNew)
  ui_set_active(UI.panel.hitResign, on)
  ui_set_active(UI.panel.hitDraw, on)
  -- v2.0「返回主菜单」与上面几个面板按钮同生共死：
  -- 弹窗/结算期间必须一起锁，否则会出现「弹窗盖着但底下还能点回主菜单」的穿透
  -- （本项目 v1.10 踩过完全同类的模态穿透事故）。
  ui_set_active(UI.panel.v2BackMain, allowMenu)
  ui_set_active(UI.panel.hitV2BackMain, allowMenu)
  -- 按钮的描边层要跟着可见控件一起走，否则会出现「按钮没了但上沿还在」的残影
  ui_set_active(UI.panel.btnNewEdge, allowNew)
  ui_set_active(UI.panel.btnMenuEdge, allowMenu)
  -- 【v3.2：有对手时把「认输 / 求和」铺成通栏】
  -- 【为什么必须做】「新开一局」被隐藏后，行 1 只剩左半的「认输」、行 2 只剩左半的
  --   「求和」，右侧空出两整块（模拟器截图实测：面板右半片空白，读作少画了按钮）。
  --   通栏后两行各自填满，信息密度均匀。
  -- 【为什么放在 show_panel_buttons 里】它是面板显隐的唯一入口，每处状态切换都会经过，
  --   把宽度跟着显隐一起算，就不会出现「按钮恢复了但宽度还是通栏」的错配。
  --   apply_button_layout 内部走 SetSizeDelta/SetAnchoredPosition（不是 SetActive），
  --   重复调用只是重复写同样的值，_btn_write 缓存会跳过，没有性能代价。
  if UI.panel.apply_button_layout ~= nil then
    UI.panel.apply_button_layout(peerOn)
  end
  -- v2.0 块 3：悔棋按钮。它和「看历史」共用第三行左半，显隐由 refresh_undo_button 单独管
  -- （对局中显示悔棋、复盘/结算显示退出复盘或看历史）。
  -- 【v2.0 修 D-1：关闭时一起关；打开时**也交给 refresh_undo_button 决定**，不在这里碰】
  --   原因：hide_confirm 会调 show_panel_buttons(true)，若这里直接点亮 v2Undo，
  --   就会在「复盘态」误显示悔棋。所以 on=true 时只让 refresh_undo_button 说了算。
  --   （而且 refresh_undo_button 内部走 ui_set_active，已有 VIS_STATE 去重，不会多写。）
  if not on then
    ui_set_active(UI.panel.v2Undo, false)
    ui_set_active(UI.panel.hitV2Undo, false)
  end
  -- 【v2.0 修 N-2：面板第三行常驻键的**可见控件**也要一起藏】
  -- 模拟器截图实测：确认框打开时，「看历史」按钮的文字仍是清晰的深色，
  -- 与周围被遮罩压淡的控件不一致 —— 看起来像漏锁。
  -- 根因：show_panel_buttons 只管「新开/认输/求和/同屏 + 主菜单」，
  -- 而「看历史」是 UI.review.btnToggle（**另一个控件**），原先只有它的**命中区**
  -- 在 show_confirm 里被单独关掉，**可见控件没关** → 视觉残留。
  -- 现在一并由本函数管理，语义变成「整块面板操作区一起显隐」，不会再漏。
  -- 【注意不要动 UI.review.btnToggle 的 text】它由 review 状态机维护，
  -- 这里只切显隐；文案例仍由 enter_review/exit_review 设置。
  ui_set_active(UI.review.btnToggle, on)
end

-- 和棋结算标题：按 localMode 分流（v2.0 补）
-- 【为什么需要这个函数】同屏模式下**不存在「对方」这个实体**（gdd §7.4 明说：
--   「同一个人操作两个颜色，没有『对方』」），所以「对方同意和棋」是事实错误。
-- 【为什么提成函数而不是在两处各写一遍三元式】
--   调用点有两处（同屏确认走 kind=="draw"、联机收到 EV_DRAW_ACC），
--   两处都写 `GAME.localMode and X or Y` 容易漏改其中一处 —— 提成函数只有一处定义。
function draw_result_text()
  if GAME.localMode then
    return CONFIG.TEXT.RESULT_DRAW_LOCAL
  end
  return CONFIG.TEXT.RESULT_DRAW_AGREED
end

-- =============================================================================
-- 结算后的双方协同选择（v3.2）
-- -----------------------------------------------------------------------------
-- 【用户要求】「双方若同时选择再来一局或同时选择复盘，则下一局黑白轮换」。
-- 【协议】复用 ChessSync 信号：EV_READY 已被联机开局占用，这里新增 EV_RESULT。
--   a = 我的选择（1=再来一局 / 2=复盘），b = 我的身份（0=白 1=黑）
--   【为什么要带身份】换色判断必须知道「我原来执什么」，否则算不出「轮换后该执什么」。
-- 【状态】
--   GAME.resultChoice.mine = "again" | "review" | nil
--   GAME.resultChoice.peer = 同上（收到对方包后写）
--   GAME.resultChoice.at   = 我做出选择的时刻（用于 10 秒超时提示）
-- 【判定】
--   ① 对方先选了、我后选：以我的选择为准，若相同则执行
--   ② 我先选了：等对方；对方选来若相同，执行
--   ③ 相同 → 换色（GAME.match.swap_sides()）并进入对应界面
-- =============================================================================

-- 换色：把双方黑白对调（v3.2「下一局黑白轮换」）
GAME.match.swap_sides = function()
  -- 【只翻转我自己】GAME.mySide 是本端身份；两者各自翻转 = 整体对调，不需要协商。
  --   【为什么这是安全的】新局开始时两端都会走一次 swap_sides，
  --   白→黑、黑→白，天然保持「一端白一端黑」的互补关系。
  if GAME.mySide == 1 then
    GAME.mySide = 2
  elseif GAME.mySide == 2 then
    GAME.mySide = 1
  end
  GAME.match.set_flip(GAME.mySide == 2)
  GAME.match.reposition()
  log_info("黑白轮换：下一局我执%s", (GAME.mySide == 1) and "白" or "黑")
end

-- 执行结算选择的结果（"again" 新开一局 / "review" 进复盘）
result_apply = function(choice)
  if choice == "again" then
    -- 【换色必须在 new_game 之前】new_game 里会按当前视角渲染棋盘，
    --   先翻视角再开新局，棋子才会按新方向落位（v3.0 的视角初始化同理）。
    GAME.match.swap_sides()
    new_game()
    log_info("结算：双方都选「再来一局」，已轮换黑白并开新局")
  elseif choice == "review" then
    -- 复盘不换色：复盘是回看这一局，视角必须与打这局时一致，
    -- 否则「刚才白棋在下面，怎么现在黑棋在下面」会让人认不出刚才的棋。
    enter_review(true)
    log_info("结算：双方都选「复盘」，进入复盘")
  end
end

-- 我点「再来一局」/「复盘」
result_make_choice = function(choice)
  local rc = GAME.resultChoice or {}
  GAME.resultChoice = rc
  rc.mine = choice
  rc.at = os.time()
  -- 同屏（无对手）：立刻执行，不需要等谁
  if GAME.localMode or not net_peer_online() then
    result_apply(choice)
    return
  end
  -- 联机：告诉对方我选了什么
  -- 【token 放 c】回声过滤靠它（见 net_on_signal 的 EV_RESULT 分支）。
  --
  -- 【为什么不能用「os.time 秒数 + 序号」当 token（我第一版就是这样，已改掉）】
  --   两端在同一秒内各点一次、且各自的 resultTokenSeq 都是 1，就会算出**完全相同的
  --   token**。后果是双向的：我把对方的包当自己的回声丢掉，对方也把我的包丢掉
  --   → 双方都在等，永远开不了局。这不是理论风险：两人同时点「再来一局」
  --   恰恰是这个功能的主场景（用户要求的就是「同时选择」）。
  --
  -- 【改法】token 里掺入**本端专属的随机/身份位**，让两端几乎不可能撞：
  --   · 身份位：mySide（0/1）—— 两端恒不同，单这一位就足以区分（换色后也仍然互斥）
  --   · 随机位：math.random 与 os.clock 小数—— 挡住「同端连点两次」的自我混淆
  --   ［为什么身份位是安全的］这里只用来**区分两端**，不承担任何游戏语义；
  --   换色后两端身份依然互斥，所以永远有效。
  GAME.resultTokenSeq = (GAME.resultTokenSeq or 0) + 1
  local sideBit = (GAME.mySide == 1) and 1 or 2
  local randBit = math.random(1, 999)
  local clockBit = math.floor((os.clock() * 1000) % 1000)
  local tok = sideBit * 100000000
            + (GAME.resultTokenSeq % 100) * 1000000
            + randBit * 1000 + clockBit
  GAME.__resultToken = tok
  net_send_event(CONFIG.EV_RESULT,
    (choice == "again") and 1 or 2,
    (GAME.mySide == 1) and 0 or 1, tok, "")
  -- 对方已经先选了同样的东西 → 立刻执行
  if rc.peer == choice then result_apply(choice); return end
  -- 否则进等待态
  if UI.result.wait ~= nil then
    UI.result.wait.text = CONFIG.TEXT.RESULT_WAIT_PEER
  end
  if UI.panel.hint ~= nil then UI.panel.hint.text = CONFIG.TEXT.RESULT_WAIT_PEER end
  log_info("结算：我已选 %s，等对方", choice)
end

-- 退出结算（清掉选择，避免残留到下一局）
result_leave_choice = function()
  GAME.resultChoice = nil
  if UI.result.wait ~= nil then UI.result.wait.text = "" end
end

-- 收到对方的选择（net 层 EV_RESULT 分支调用）
result_on_peer_choice = function(choice)
  local rc = GAME.resultChoice or {}
  GAME.resultChoice = rc
  rc.peer = choice
  -- 我没选：只等着，把对方的选择显示出来
  if rc.mine == nil then
    if UI.result.wait ~= nil then
      UI.result.wait.text = (choice == "again")
        and CONFIG.TEXT.RESULT_PEER_WANTS_AGAIN
        or CONFIG.TEXT.RESULT_PEER_WANTS_REVIEW
    end
    return
  end
  -- 我选的是同一个 → 执行
  if rc.mine == choice then
    result_apply(choice)
    return
  end
  -- 选择冲突：我选复盘、对方选再来一局之类。以先选的一方为准不礼貌，
  -- 这里给提示让玩家自己改，不擅自执行任何一边。
  if UI.result.wait ~= nil then
    UI.result.wait.text = CONFIG.TEXT.RESULT_CHOICE_CONFLICT
  end
end
-- -----------------------------------------------------------------------------
-- 【为什么需要】用户要求：
--   ① 「为双方结算，胜利的加分」  → 本局结束后要给赢家记分
--   ② 「单人复盘练习自动读取上一局对局的存档进行复盘」 → 要对局封盘存档
--
-- 【积分存在哪 —— 这是一个必须讲清楚的能力边界】
--   客户端 Lua **没有**文件读写（io.* 不可用），也**不能**写全局自定义变量
--   （那只能由服务端节点图写）。所以：
--     · 本会话内的积分累计：直接放 GAME.score 表，退出关卡即清零。
--     · 跨会话保留：需要服务端自定义变量（见 out/交付包/跨会话存档方案.md），
--       本文件只用 GAME.lastArchived（内存）打底，没配服务端也能跑。
--
-- 【「上一局存档」是什么形态】就是本局结束时的那串快照（GAME.history）：
--   每一步的 FEN + 走子文字 + 失子数 + 棋钟。整串留在内存里，
--   单人复盘时直接拿它重建复盘时间线 —— 这就是「读取上一局存档」。
-- =============================================================================

-- 本会话积分（退出关卡即清零；跨会话需服务端变量，见方案文档）
GAME.scoreWhite = 0
GAME.scoreBlack = 0
-- 上一局的封盘存档（nil = 还没打过一局）
GAME.lastArchived = nil

-- 一局结束时的记账：算积分 + 封存这一局
settle_match_record = function()
  -- ① 判定赢家（1=白 2=黑 nil=和棋）
  local winner = nil
  if GAME.resultText == CONFIG.TEXT.RESULT_WHITE_WIN then
    winner = 1
  elseif GAME.resultText == CONFIG.TEXT.RESULT_BLACK_WIN then
    winner = 2
  end

  -- ② 积分：赢 +1，输 +0，和棋双方各 +0.5 → 用「半分」整数存，避免浮点比较
  --   【为什么用整数】0.5 在 Lua 里是精确的（二进制可表示），但比分比较/显示
  --   反复乘除容易出错。存「半分」，显示时再除以 2。
  GAME.scoreWhite = GAME.scoreWhite or 0
  GAME.scoreBlack = GAME.scoreBlack or 0
  GAME.scoreHalf = GAME.scoreHalf or { white = 0, black = 0 }
  local sh = GAME.scoreHalf
  if winner == 1 then
    sh.white = sh.white + 2
  elseif winner == 2 then
    sh.black = sh.black + 2
  else
    sh.white = sh.white + 1
    sh.black = sh.black + 1
  end

  -- ③ 封存这一局，供「单人复盘练习」读取
  --    【深拷贝】必须拷，否则下一局 new_game() 会清掉 GAME.history，
  --    存档跟着一起没 —— 表现是「刚打完一局，点复盘却是空的」。
  local arc = {
    history = {},
    moveLog = {},
    resultText = GAME.resultText,
    resultSub = GAME.resultSub,
    clockW0 = GAME.tcInitial or CONFIG.INITIAL_TIME_SEC,
    clockB0 = GAME.tcInitial or CONFIG.INITIAL_TIME_SEC,
    mySide = GAME.mySide,
    tcN = GAME.tcN,
    at = os.time(),
  }
  for i = 1, #(GAME.history or {}) do
    local s = GAME.history[i]
    if s ~= nil then
      arc.history[i] = {
        fen = s.fen, text = s.text,
        from = s.from, to = s.to,
        capW = s.capW, capB = s.capB,
        clockW = s.clockW, clockB = s.clockB,
      }
    end
  end
  for i = 1, #(GAME.moveLog or {}) do arc.moveLog[i] = GAME.moveLog[i] end
  GAME.lastArchived = arc

  log_info("结算：赢家=%s 本会话比分 白%.1f : 黑%.1f（存档 %d 步）",
    tostring(winner or "和"),
    (sh.white or 0) / 2, (sh.black or 0) / 2,
    (#arc.history - 1))
end

-- 比分显示文本（半分 → 整数或一位小数）
function score_text()
  local sh = GAME.scoreHalf or { white = 0, black = 0 }
  local function fmt(v)
    v = v or 0
    if v % 2 == 0 then return tostring(v // 2) end
    return string.format("%.1f", v / 2)
  end
  -- 【不要链式 gsub】`a:gsub():gsub()` 里第一个 gsub 返回 (str, n) 两个值，
  -- 链式调用虽然能跑，但返回值个数会跟着变，赋给一个变量时容易被误用。
  -- 这里分成两步，返回值确定是单个字符串。
  local tpl = CONFIG.TEXT.RESULT_SCORE_FMT or "{w} : {b}"
  local out = string.gsub(tpl, "{w}", fmt(sh.white))
  out = string.gsub(out, "{b}", fmt(sh.black))
  return out
end

function show_result()
  if not GAME.uiReady then return end
  -- 【终局音的唯一播放入口】所有到达终局的路径（将死/逼和/五十步/三次重复/子力不足/
  -- 认输/超时/和棋同意/联机收到对方认输）最后都会调 show_result，在这里播最省心。
  -- SFX.overFired 保证只响一次：结算面板可能被重复打开（例如退出复盘会再弹一次）。
  if not SFX.overFired then
    SFX.overFired = true
    -- 【键名必须是 GAME_END，不是 "over"】CONFIG.SFX 里的终局音效键叫 GAME_END；
    -- Demo 侧写的是 SFX.play("over")，照抄过来会取到 nil → 静默不播（不报错、不写日志）。
    -- sfx_play 虽做了 string.upper 回退，但 "over" 大写仍是 "OVER"，依然匹配不到 GAME_END。
    sfx_play("GAME_END")
  end
  -- ===== v3.2：结算时记账（积分 + 上一局存档）=====
  -- 【为什么放在这里】show_result 是所有终局路径的**唯一**汇合点
  --   （见上面那段注释）。把记账挂在这里，就不会出现「认输记了、超时没记」的缺口。
  -- 【幂等】结算面板会被重复打开（退出复盘会再弹一次），所以用 GAME.settled 标记挡重复。
  if not GAME.settled then
    GAME.settled = true
    settle_match_record()
  end
  UI.result.title.text = GAME.resultText or ""
  -- 结算说明行里的 {t} 用实际对局用时填充（docs/策划案.md 9.4）
  local sub = GAME.resultSub or ""
  if string.find(sub, "{t}", 1, true) then
    local elapsed = math.floor(GAME.elapsedSec or 0)
    local mm = elapsed // 60
    local ss = elapsed % 60
    sub = string.gsub(sub, "{t}", string.format("%02d:%02d", mm, ss))
  end
  UI.result.sub.text = sub
  ui_set_active(UI.result.overlay, true)
  -- 先开投影/描边再开面板底，保证层级顺序（同级后开启的在上，但控件本身是按创建顺序叠的）
  ui_set_active(UI.result.shadow, true)
  ui_set_active(UI.result.edgeBox, true)
  ui_set_active(UI.result.bg, true)
  ui_set_active(UI.result.title, true)
  ui_set_active(UI.result.sub, true)
  -- 【v3.2 比分】用户要求「为双方结算，胜利的加分」
  if UI.result.score ~= nil then
    UI.result.score.text = score_text()
    ui_set_active(UI.result.score, true)
  end
  ui_set_active(UI.result.btnAgain, true)
  ui_set_active(UI.result.hitAgain, true)
  ui_set_active(UI.result.btnReview, true)
  ui_set_active(UI.result.hitReview, true)
  -- 【v3.2 退出键】用户要求「当一局对局结束后，增加退出按钮」
  ui_set_active(UI.result.btnExit, true)
  ui_set_active(UI.result.hitExit, true)
  -- 等待提示行初始为空（点过「再来一局/复盘」后才会写）
  if UI.result.wait ~= nil then
    UI.result.wait.text = ""
    ui_set_active(UI.result.wait, true)
  end
  -- 重置双方结算选择（新一局结算时从零开始）
  GAME.resultChoice = { mine = nil, peer = nil, at = nil }
  ui_set_active(UI.result.hitOverlay, true)
  -- 终局后锁棋盘输入
  for sq = 0, 63 do
    if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], false) end
  end
  -- 【v1.10 修：结算面板同样要锁面板按钮】
  -- 与确认弹窗同一个问题：面板命中区被 raise_hit 抬到了结局面板之上，视觉被盖住但
  -- 仍可点击。其中「求和」在终局后只是弹个提示、危害有限，但「切换本地同屏」会
  -- 重置对局状态 —— 用户点了结算面板上的按钮却被底下那个接走，属于同一类穿透。
  -- 这里统一关掉，结算期间只留结算面板自己的两个键（再来一局 / 复盘）。
  show_panel_buttons(false)
  ui_set_active(UI.panel.hitSfx, false)
  ui_set_active(UI.review.hitToggle, false)
  -- 【v2.0 修 N-1：结算面板的命中区也要在显示时重新提到最顶层】
  -- 理由与 show_confirm 末尾完全相同（初始界面后建、兄弟顺序会变）。
  local function raise_modal_hits()
    -- 【v2.0 修 P0：这里的顺序原来是反的】
    --   hitOverlay 是 1600×900 的**全屏**命中区（建在 x=0,y=0,w=canvasW,h=canvasH），
    --   作用是「吃掉面板以外的点击」。SetAsLastSibling 是「后抬起的在上层」，
    --   所以它必须**最先**抬起（压在最底），两个按钮后抬就会盖住它。
    --   原顺序把它放最后 → 全屏命中区盖住了两个按钮 → **结算面板整块不可点**。
    --   实测现象（模拟器 pc-16-9）：点「再来一局」「复盘」都没有回调、没有点击音效，
    --   但两个按钮与命中区在控件树里都是 active=true（所以看树是看不出问题的）。
    local list = { UI.result.hitOverlay, UI.result.hitAgain, UI.result.hitReview, UI.result.hitExit }
    for i = 1, #list do
      local c = list[i]
      if c ~= nil then pcall(function() c:SetAsLastSibling() end) end
    end
  end
  raise_modal_hits()
end

hide_result = function()
  ui_set_active(UI.result.overlay, false)
  ui_set_active(UI.result.shadow, false)
  ui_set_active(UI.result.edgeBox, false)
  ui_set_active(UI.result.bg, false)
  ui_set_active(UI.result.title, false)
  ui_set_active(UI.result.sub, false)
  ui_set_active(UI.result.btnAgain, false)
  ui_set_active(UI.result.hitAgain, false)
  ui_set_active(UI.result.btnReview, false)
  ui_set_active(UI.result.hitReview, false)
  -- 【v3.2】比分 / 退出键 / 等待提示同样要收
  if UI.result.score ~= nil then ui_set_active(UI.result.score, false) end
  if UI.result.btnExit ~= nil then ui_set_active(UI.result.btnExit, false) end
  if UI.result.hitExit ~= nil then ui_set_active(UI.result.hitExit, false) end
  if UI.result.wait ~= nil then ui_set_active(UI.result.wait, false) end
  ui_set_active(UI.result.hitOverlay, false)
  -- 【v1.10 修】对应 show_result 里的面板锁定，这里恢复。
  -- 只有「对局仍在进行」时才恢复：结算后点「再来一局」会先 new_game() 再 hide_result()，
  -- 此时 GAME.over 已被 new_game 置回 false，所以正常；而启动时 hide_result 只是做初始
  -- 隐藏，那时面板按钮由 build 流程自己管理，这里以 GAME.over 为界不会误开。
  if not GAME.over and GAME.confirmKind == nil and GAME.review == nil then
    show_panel_buttons(true)
    ui_set_active(UI.panel.hitSfx, true)
    ui_set_active(UI.review.hitToggle, true)
  end
end

hide_promo = function()
  ui_set_active(UI.promo.bg, false)
  ui_set_active(UI.promo.prompt, false)
  for i = 1, 4 do
    ui_set_active(UI.promo.buttons[i], false)
    ui_set_active(UI.promo.hits[i], false)
  end
end

local function show_promo()
  ui_set_active(UI.promo.bg, true)
  ui_set_active(UI.promo.prompt, true)
  for i = 1, 4 do
    ui_set_active(UI.promo.buttons[i], true)
    ui_set_active(UI.promo.hits[i], true)
  end
  -- 【v2.0 修 N-1：升变弹窗同理，显示时把自己的命中区提到最顶层】
  for i = 1, 4 do
    local c = UI.promo.hits[i]
    if c ~= nil then pcall(function() c:SetAsLastSibling() end) end
  end
end

hide_confirm = function()
  ui_set_active(UI.confirm.overlay, false)
  ui_set_active(UI.confirm.shadow, false)
  ui_set_active(UI.confirm.edgeBox, false)
  ui_set_active(UI.confirm.bg, false)
  ui_set_active(UI.confirm.text, false)
  ui_set_active(UI.confirm.btnYes, false)
  ui_set_active(UI.confirm.btnNo, false)
  ui_set_active(UI.confirm.hitYes, false)
  ui_set_active(UI.confirm.hitNo, false)
  GAME.confirmKind = nil
  -- 恢复棋盘输入（终局、复盘中、升变时除外）
  if not GAME.over and GAME.pendingPromo == nil and GAME.review == nil then
    for sq = 0, 63 do
      if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], true) end
    end
  end
  -- 【v1.10 修】对应 show_confirm 里的面板按钮锁定，这里恢复。
  -- 条件与上面一致：终局/复盘中/升变待选时不恢复面板按钮，避免出现「棋局已结束
  -- 却还能点新开一局/求和」的状态；复盘由 show_review_buttons 自己管理显隐。
  if not GAME.over and GAME.pendingPromo == nil and GAME.review == nil then
    show_panel_buttons(true)
    ui_set_active(UI.panel.hitSfx, true)
    ui_set_active(UI.review.hitToggle, true)
  end
  -- 【v2.0 修 D-1：关掉确认框后必须重算第三行左半该显示什么】
  -- 因为 show_confirm 里走过 show_panel_buttons(false)（把 v2Undo 关了），
  -- 而 show_panel_buttons(true) 按设计**不**负责点亮 v2Undo（它不知道该显示悔棋还是看历史）。
  -- 所以这里显式叫 refresh_undo_button() 收敛一次。
  -- 【教训】凡是「A 关、B 负责开」的成对显隐，**关闭方恢复时必须回叫 B**，
  --   否则就会出现本轮这种「按钮消失、露出另一个键」的缺陷。
  if refresh_undo_button ~= nil then refresh_undo_button() end
end

-- =============================================================================
-- 复盘状态机（v1.6）
--   入口两处：① 结算面板「复盘」② 面板第三行「看历史」（对局中随时）
--   复盘中：棋盘不可点、棋钟不走、渲染全部读快照；退出后原样继续。
-- =============================================================================

-- 复盘面板的按钮显隐（复盘 4 个前进后退键 + 退出键）
local review_render   -- 定义于本段末尾（enter_review 会调用它）
-- 【v3.2 补前置声明】enter_review 原本只有 `local function` 定义（在本段 6328 行附近），
--   但 v3.2 新增的 result_apply（第 5900 行附近）会调用它 —— 那时它还没 local 化，
--   于是被绑成**全局** `enter_review`（运行时是 nil）。
--   表现：结算面板点「复盘」，双方都选好后直接崩
--   `attempt to call a nil value (global 'enter_review')`。
--   lua_check.cjs 的「先用后定义」检查抓到了它（正是这条检查存在的意义）。
local enter_review

show_review_buttons = function(on)
  ui_set_active(UI.review.btnStart, on)
  ui_set_active(UI.review.btnPrev, on)
  ui_set_active(UI.review.btnNext, on)
  ui_set_active(UI.review.btnEnd, on)
  ui_set_active(UI.review.hitStart, on)
  ui_set_active(UI.review.hitPrev, on)
  ui_set_active(UI.review.hitNext, on)
  ui_set_active(UI.review.hitEnd, on)
end


-- 棋盘命中区：复盘中一律锁死（复盘只看不点）
local function set_board_input(on)
  for sq = 0, 63 do
    if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], on) end
  end
end

-- 刷新复盘当前步的快照局面（翻页时只 parse 一次，缓存到 GAME.reviewState）
local function review_load(idx)
  local snap = GAME.history[idx + 1]
  if snap == nil then return false end
  GAME.review.idx = idx
  GAME.reviewState = RULES.parse_fen(snap.fen)
  return true
end

-- 进入复盘。停在最后一步（对局中看历史 / 结算后复盘都是这个默认）
--
-- allowEmpty（v2.0）：默认 false = 旧行为一字不变（一步没走就拒绝并提示）。
--   true 时允许「只有开局快照」的 history 进入，停在 idx=0。
--   【为什么需要它】初始界面「单人·复盘研习」入口是刚启动就点进来的，
--   那时 history 只有开局快照（#history == 1），走旧路径会被空态护栏挡住 →
--   玩家点了没反应，像 bug。而复盘研习的价值正是「从开局试走看变化」。
--   注意：**只放行空态这一条**，其余（终局/正常对局）行为完全不变。
enter_review = function(allowEmpty)
  local empty = (#GAME.history <= 1)
  if empty and not allowEmpty then
    -- 一步都没走，没得复盘
    if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.REVIEW_EMPTY end
    return false
  end
  if #GAME.history < 1 then
    -- 连开局快照都没有（理论上不该发生）—— 无论如何都拒绝，避免 parse nil 崩溃
    if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.REVIEW_EMPTY end
    return false
  end
  GAME.review = { idx = 0, allowEmpty = allowEmpty and true or false }
  review_load(#GAME.history - 1)
  -- 结算弹窗让位给复盘（退出复盘时会重新弹回来）
  hide_result()
  show_panel_buttons(false)
  show_review_buttons(true)
  ui_set_active(UI.review.btnToggle, true)
  ui_set_active(UI.review.hitToggle, true)
  UI.review.btnToggle.text = CONFIG.TEXT.BTN_REVIEW_EXIT
  -- 【v3.3：复盘恢复「只看不点」】
  -- 【为什么改回来】用户要求删掉「退回主变」按钮。而那个按钮是分支试走的**唯一出口**：
  --   review_goto 翻页时并不清 reviewBranch，而 view_board() 优先读分支局面 ——
  --   所以只要还能试走，删掉按钮就会变成「点了棋子进入试走，翻页后棋盘停在旧试走局面，
  --   且没有任何方式退出」。这是死角，不能留。
  --   因此本轮把分支试走整体移除（v2.0 块 4 的功能），复盘回到 v1.6 的「只看不点」。
  -- 【收益】棋盘在复盘里点不动，玩家不会误以为「这步能改」，也不会出现
  --   主变/分支两套局面需要区分的心智负担。
  set_board_input(false)
  clear_highlights()
  -- 复盘研习（从初始界面进来）时屏幕状态要标成 review，返回主菜单的判定才正确
  if empty then GAME.screen = "review" end
  review_render()
  return true
end

-- 退出复盘：回到原局面。对局已结束则重新弹结算面板
local function exit_review()
  -- 【v2.0】记下「这是从初始界面进来的复盘研习」（allowEmpty）。
  -- 那种情况下退出复盘必须回初始界面，而不是掉到一张刚开局的棋盘上 ——
  -- 玩家从菜单点「复盘研习」，退出时理应回到菜单，否则等于被塞进一局新棋。
  -- 【v2.0 修】原来用 allowEmpty 判断「是不是从初始界面进来」，但结算面板的「复盘」
  --   现在也传 allowEmpty=true（一步未走也要能复盘）。两者复用会让「从结算进复盘」
  --   退出时错误地跳回初始界面、把结算面板丢掉（实测复现）。
  --   改用「复盘研习」入口自己打的 fromMenu 标记（见 entry_start_review）。
  local fromMenu = (GAME.review ~= nil) and (GAME.review.fromMenu == true)
  GAME.review = nil
  GAME.reviewState = nil
  show_review_buttons(false)
  show_panel_buttons(true)
  ui_set_active(UI.review.btnToggle, true)
  ui_set_active(UI.review.hitToggle, true)
  UI.review.btnToggle.text = CONFIG.TEXT.BTN_REVIEW_HISTORY
  if fromMenu then
    back_to_main_menu(true)
    return
  end
  if GAME.over then
    set_board_input(false)
    show_result()
  else
    set_board_input(true)
    if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.HINT_OPENING end
  end
  render_all()
end

-- 复盘翻页：delta=+1/-1 相对移动，target=绝对步（nil 表示不用）
local function review_goto(target, delta)
  if GAME.review == nil then return false end
  local idx = GAME.review.idx
  if target ~= nil then idx = target else idx = idx + delta end
  local maxIdx = #GAME.history - 1
  if idx < 0 then idx = 0 end
  if idx > maxIdx then idx = maxIdx end
  if idx == GAME.review.idx then return false end
  if not review_load(idx) then return false end
  review_render()
  return true
end

-- =============================================================================
-- 【v3.3 已整体移除】复盘分支试走（原 v2.0 块 4）
-- -----------------------------------------------------------------------------
-- 被删掉的东西：branch_ensure / branch_back / branch_move / refresh_branch_visuals
--             / branch_hint_text / branch_find_move，以及棋盘下方的「退回主变」按钮。
--
-- 【为什么删】用户要求删掉「退回主变」。而它是分支试走的**唯一出口**：
--   review_goto 翻页时并不清 reviewBranch，view_board() 又优先读分支局面 ——
--   只删按钮、留着试走，就会变成「点棋子进入试走 → 翻页后棋盘停在旧试走局面 →
--   没有任何方式退出」的死角。所以试走必须连带移除。
--
-- 【代价（如实记录）】v2.0 的「从任意一步摆自己的变化」这个卖点没有了。
--   复盘现在是纯回放：只看、不点、不改。若将来要恢复，
--   需要同时把「退回主变」按钮和分支状态机一起加回来，不能只加一半。
-- =============================================================================

-- 复盘下的整屏重绘（与 render_all 同源，只是数据来自快照）
review_render = function()
  if not GAME.uiReady then return end
  local snap = review_snap()
  render_pieces()
  render_captured()
  update_clock_text()
  update_turn_text()
  show_last_move()
  show_check_warning()
  if UI.panel.hint then
    if snap ~= nil and GAME.review.idx > 0 then
      UI.panel.hint.text = tostring(snap.text)
    else
      UI.panel.hint.text = CONFIG.TEXT.REVIEW_START_HINT
    end
  end
end


-- 弹窗类型与文案映射（docs/策划案.md 9.5 C-01~C-04）
local CONFIRM_SPEC = {
  resign = { text = "CONFIRM_RESIGN",  yes = "CONFIRM_RESIGN_YES", no = "CONFIRM_RESIGN_NO" },
  newgame = { text = "CONFIRM_NEWGAME", yes = "CONFIRM_YES", no = "CONFIRM_NO" },
  switch = { text = "CONFIRM_SWITCH",  yes = "CONFIRM_YES", no = "CONFIRM_NO" },
  draw = { text = "CONFIRM_DRAW",      yes = "CONFIRM_DRAW_YES", no = "CONFIRM_DRAW_NO",
           -- 【v2.0 补】双人同屏时改用 localText（同屏没有「对方」这个实体）
           localText = "CONFIRM_DRAW_LOCAL" },
  -- v2.0：回主菜单会放弃当前对局
  menu = { text = "CONFIRM_MENU",      yes = "CONFIRM_MENU_YES", no = "CONFIRM_NO" },
  -- v2.0 块 3：悔棋（同屏直接执行；联机走请求-同意）
  undo = { text = "CONFIRM_UNDO",      yes = "CONFIRM_UNDO_YES", no = "CONFIRM_UNDO_NO" },
  -- v2.0 块 3：对方请求悔棋（我是响应方）
  undoPeer = { text = "CONFIRM_UNDO_PEER", yes = "CONFIRM_UNDO_ACC", no = "CONFIRM_UNDO_REJ" },
  -- 【v3.3】branchNew 已删除（「从此开新局」随复盘动作条一起移除）
}

local function show_confirm(kind)
  -- 【v1.10 修：重入护栏，优先级最高】
  -- 已有确认框开着时直接拒绝，不覆盖 confirmKind。
  -- 这一条是「防丢对局状态」的最后一道保险：即使 UI 锁失效（层级变化、新增按钮忘了锁、
  -- 联机信号在弹窗期间触发了别的 show_confirm），也不会把 resign 悄悄改成 newgame。
  -- 放在最前，早于任何 UI 写入 —— 被拒绝时界面保持原样，不会出现「文案已换、kind 没换」的半状态。
  if GAME.confirmKind ~= nil then return end
  local spec = CONFIRM_SPEC[kind] or CONFIRM_SPEC.newgame
  -- 【v2.0 补：同屏/联机文案分流】
  -- 有些确认框的正文在两种模式下该说不同的话。典型是「求和」：
  --   · 联机  → 「对方想和棋，同意吗」  （确实是对方发起的）
  --   · 同屏  → 「和棋？确认后本局判和」（没有对方，只是防误触）
  -- 【为什么用 spec.localText 而不是在 show_confirm 里写 if kind=="draw"】
  --   写 if 会让「哪些 kind 有分流」散落在函数体里，新增 kind 时容易漏。
  --   放在 CONFIRM_SPEC 表里，一眼能看出哪些 kind 支持分流。
  -- 【默认行为不变】spec.localText 为 nil 时完全走原来的 text —— 其余 8 个 kind 不受影响。
  local textKey = spec.text
  if GAME.localMode and spec.localText ~= nil then
    textKey = spec.localText
  end
  UI.confirm.text.text = CONFIG.TEXT[textKey]
  UI.confirm.btnYes.text = CONFIG.TEXT[spec.yes]
  UI.confirm.btnNo.text = CONFIG.TEXT[spec.no]
  GAME.confirmKind = kind
  ui_set_active(UI.confirm.overlay, true)
  ui_set_active(UI.confirm.shadow, true)
  ui_set_active(UI.confirm.edgeBox, true)
  ui_set_active(UI.confirm.bg, true)
  ui_set_active(UI.confirm.text, true)
  ui_set_active(UI.confirm.btnYes, true)
  ui_set_active(UI.confirm.btnNo, true)
  ui_set_active(UI.confirm.hitYes, true)
  ui_set_active(UI.confirm.hitNo, true)
  -- 弹窗期间锁棋盘输入
  for sq = 0, 63 do
    if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], false) end
  end
  -- 【v1.10 修：弹窗期间必须锁面板按钮】
  -- 只锁棋盘是不够的。面板命中区在 build 末尾被 raise_hit 抬到了 confirmoverlay
  -- **之上**（overlay 只是视觉遮罩，不是命中区，挡不住点击），于是弹窗开着时
  -- 面板按钮照样点得动，能叠出第二个确认框。
  -- 而 confirmKind 是直接覆盖的，后果不是多弹一个框，而是**点「确定」执行错分支**：
  --   认输框开着 → 点「新开一局」→ confirmKind 变成 newgame → 点「确定」→ **重开一局**
  -- 用户以为在确认认输，实际把对局状态丢了。所以这里必须一并禁用。
  show_panel_buttons(false)
  -- 音效开关与复盘键不在 show_panel_buttons 里，单独锁
  ui_set_active(UI.panel.hitSfx, false)
  ui_set_active(UI.review.hitToggle, false)
  -- 【v2.0 修 N-1（模拟器实测：确认框的「取消」点不动）】
  -- 根因双层：
  --   ① 确认框的两个命中区 **从来没进过 raise_hit 列表** —— build_all_ui 末尾只提了
  --      棋盘 64 + 面板 4 + 复盘 5 + 音效 1 + 主菜单 1，**漏了 confirm.hitYes/hitNo**
  --      （以及 result/promo 的命中区）。
  --   ② v2.0 的初始界面整层是 build_all_ui 里**最后**建的，所以哪怕提过，
  --      初始界面的控件也在确认框之上。
  -- 结果：确认框视觉上在最上层（它的 overlay/bg 后建），但**命中被压住** → 点不动。
  -- 修法（两手都用，缺一不可）：
  --   · 这里在**每次显示弹窗时**把自己的命中区重新提到最顶层（不依赖 build 期的一次性提升）；
  --   · build_all_ui 里把三个弹窗的命中区补进 raise_hit 列表，并保证它们排在初始界面之后。
  -- 【为什么显示时提也要做】初始界面进出、结算面板开关都会改变兄弟顺序，
  --   build 期提一次并不足够 —— 模态弹窗必须在「自己成为最上层」的这一刻再确认一次。
  local function raise_modal_hits()
    local list = { UI.confirm.hitYes, UI.confirm.hitNo }
    for i = 1, #list do
      local c = list[i]
      if c ~= nil then pcall(function() c:SetAsLastSibling() end) end
    end
  end
  raise_modal_hits()
end

-- 新开一局
-- 【v2.0】棋钟起始值改读 GAME.tcInitial（档位驱动），不再用常量 CONFIG.INITIAL_TIME_SEC。
--   默认档位 3 的 tcInitial 就是 900，所以「不选档位」路径与 v1.12 逐位一致。
-- =============================================================================
-- 悔棋（v2.0 块 3 建立 → **v3.2 语义整体改写**，用户 2026-11 明确要求）
-- -----------------------------------------------------------------------------
-- 【v3.2 新语义】悔棋只能撤回**我自己刚走的那一手**，因此：
--   · 只允许在「我刚走完、对方还没应手」这个窗口申请 → 也就是**轮次在对方身上时**；
--   · 轮到自己走时反而不能悔棋（此时最后一步是对方走的，撤回它等于替对方反悔）。
--   · 撤回 1 步（CONFIG.UNDO_PLIES = 1）。
--
-- 【为什么这条规则在棋理上成立】
--   悔棋的动机是「我这一步走错了，让我收回」。而「我这一步」只有在对方还没应手时
--   才收得回来；一旦对方走完，棋局已经推进了一整个回合，撤回就变成
--   「把对方已经走出并确认的棋也退掉」——那是另一回事，对方没有任何过错。
--   所以「轮到自己走时不允许悔棋」不是限制，而是这条规则的定义本身。
--
-- 【v2.0 的成对撤回（2 步）为什么被推翻】
--   旧规则「双方各退一步」在「对方还没走」的窗口里是**矛盾的**：没有对方的下一步可退。
--   硬退 2 步会撤掉对方上一手已确认的棋，且轮走方不变这一点在 1 步撤回下同样成立
--   （撤回 1 步后轮到对方，与被撤那手之前完全一致）。
--
-- 【必须整组回退 10 项状态，漏一项都是隐性 bug】（gdd §7.6 逐项）
--   最容易漏的是第 2 项：`st.history`（三次重复判定用的 position_key 序列）。
--   `parse_fen` 会把它清空 → 撤回后本局**再也判不出三次重复**，而且是静默失效。
--   第 8 项 `lastSentMove` 也必须置 nil，否则回声过滤会误吞对方的下一步。
-- =============================================================================

-- 某方剩余悔棋次数（1=白 2=黑）
local function undo_left_of(side)
  return GAME.undoLeft[side] or 0
end

-- 「发起方」是谁 = **最后一步的走子方**（v3.2 语义：悔棋撤的是「我刚走的那手」）
-- 【与 v2.0 的差别】旧版返回「轮走方」（同屏）或 GAME.mySide（联机），因为那时撤 2 步、
--   撤完还是轮走方。现在是撤 1 步、撤完轮到对方，所以发起方必须是**非轮走方**。
-- 【同屏】同一人操作两色，最后一步的走子方可以按当前轮次反推：轮到白 → 刚才是黑走的。
-- 【联机】用 GAME.mySide —— 只有我自己的手才轮得到我悔。
local function undo_actor_side()
  if GAME.localMode then
    -- 轮到白走 ⇒ 刚走完的是黑方（=2）；轮到黑走 ⇒ 刚走完的是白方（=1）
    return (GAME.st ~= nil and GAME.st.turn == WHITE) and 2 or 1
  end
  return GAME.mySide
end

-- 六条发起条件，不满足时返回 false + 一句可读原因
undo_check = function()
  if GAME.screen ~= "playing" then return false, nil end                     -- C-1
  if GAME.over then return false, CONFIG.TEXT.UNDO_NO_OVER end               -- C-2
  -- C-3：至少要走过 1 步才有得撤（v3.2：1 步即可，不再是 2 步）
  if #GAME.history < 1 + CONFIG.UNDO_PLIES then
    return false, CONFIG.TEXT.UNDO_NO_EARLY
  end
  -- C-4【v3.2 语义反转】必须是「对方正准备走」= 轮到对方。轮到自己时最后一步是对方走的，
  --   撤它等于替对方反悔，所以这里**必须**拒绝（旧版是反过来的：要求轮到自己）。
  if GAME.st ~= nil then
    local myOpponentTurn
    if GAME.localMode then
      -- 同屏：「我」就是刚走完的那个人，只要最后一步是我走的就成立。
      -- 判据等价于「轮次不是最后走子方的回合」——永远成立，故同屏恒允许。
      myOpponentTurn = true
    else
      local myTurn = (GAME.mySide == 1 and GAME.st.turn == WHITE)
                  or (GAME.mySide == 2 and GAME.st.turn == BLACK)
      myOpponentTurn = not myTurn
    end
    if not myOpponentTurn then return false, CONFIG.TEXT.UNDO_NO_TURN end
  end
  -- C-5：剩余次数
  if undo_left_of(undo_actor_side()) <= 0 then
    return false, CONFIG.TEXT.UNDO_NO_LEFT
  end
  -- C-6：升变弹窗开着
  if GAME.pendingPromo ~= nil then return false, CONFIG.TEXT.UNDO_NO_PROMO end
  -- 额外：已有待回应的请求
  if GAME.pendingUndo ~= nil then return false, CONFIG.TEXT.UNDO_PENDING end
  return true, nil
end

-- 执行撤回（真正的状态回退）。
-- 【调用时机】同屏：确认框点「确认悔棋」后立刻；
--   联机：**收到 EV_UNDO_ACC 那一帧**（发起方不能自己先撤 —— 那会在对方拒绝时分叉）。
-- 返回 true 表示确实撤回了一步。
undo_apply_pair = function()
  local plies = CONFIG.UNDO_PLIES
  local n = #GAME.history - 1              -- 当前走了几步
  if n < plies then return false end
  local target = n - plies                 -- 目标步数 P(n-plies)
  local snap = GAME.history[target + 1]    -- history 索引 = 步数 + 1
  if snap == nil then return false end

  -- ① 局面：按快照 FEN 重建
  local ok, st = pcall(RULES.parse_fen, snap.fen)
  if not ok or st == nil then
    log_err("悔棋：快照 FEN 解析失败，已放弃（fen=%s）", tostring(snap.fen))
    return false
  end
  GAME.st = st

  -- ② st.history（三次重复判定的 position_key 序列）—— 必须回填！
  --    parse_fen 返回的 st.history 是空表；这里按保留下来的每个快照依次重建，
  --    这样撤回后仍能正确判「局面重复三次」。
  st.history = {}
  for i = 2, target + 1 do           -- history[1] 是开局，position_key 从第 1 步开始记
    local s = GAME.history[i]
    if s ~= nil then
      local okk, stt = pcall(RULES.parse_fen, s.fen)
      if okk and stt ~= nil then
        st.history[#st.history + 1] = RULES.position_key(stt)
      end
    end
  end

  -- ③ 棋钟：**只返还对方的时间，自己的不返还**（v3.2 用户裁决）
  -- 【原文】「悔棋造成的时间损失由自己承担」。
  -- 【怎么落地】撤回那一刻，我（发起方）的钟保持不动 —— 我反悔花的思考时间照扣；
  --   对方的钟退回快照值 —— 对方本来就没走这一步，不该被我的反悔拖走时间。
  -- 【为什么不能两边都不动】撤回后轮到对方走，对方的钟会立刻开始走；
  --   若它停在「被我拖延后的读数」，对方凭空少了一段时间，等于替我的反悔买单。
  -- 【undoClockBefore 仍要记】⑩ 段用它估算被撤掉这一手流逝了多少时间。
  GAME.undoClockBefore = (GAME.clockWhite or 0) + (GAME.clockBlack or 0)
  local actor = undo_actor_side()          -- 1=白 2=黑（发起悔棋=刚走完那手的一方）
  local peer = (actor == 1) and 2 or 1
  if CONFIG.UNDO_REFUND_PEER_CLOCK then
    if peer == 1 then
      GAME.clockWhite = snap.clockW or GAME.clockWhite
    else
      GAME.clockBlack = snap.clockB or GAME.clockBlack
    end
  else
    GAME.clockWhite = snap.clockW or GAME.clockWhite
    GAME.clockBlack = snap.clockB or GAME.clockBlack
  end

  -- ④ 走子记录截断到 target 条
  local logs = {}
  for i = 1, math.min(target, #GAME.moveLog) do logs[i] = GAME.moveLog[i] end
  GAME.moveLog = logs

  -- ⑤ 失子记录重建到该快照的 capW/capB
  local function trunc(list, k)
    local out = {}
    for i = 1, math.min(k or 0, #list) do out[i] = list[i] end
    return out
  end
  GAME.capturedWhite = trunc(GAME.capturedWhite, snap.capW)
  GAME.capturedBlack = trunc(GAME.capturedBlack, snap.capB)

  -- ⑥ history 截断到 target+1 项
  local hist = {}
  for i = 1, target + 1 do hist[i] = GAME.history[i] end
  GAME.history = hist

  -- ⑦ 上一步痕迹指向保留下来的最后一步
  local last = GAME.history[target + 1]
  if target > 0 and last ~= nil then
    GAME.lastFrom = last.from
    GAME.lastTo = last.to
  else
    GAME.lastFrom = nil
    GAME.lastTo = nil
  end

  -- ⑧ lastSentMove 必须清掉（见函数头说明）
  GAME.lastSentMove = nil

  -- ⑨ 选中与高亮清空
  clear_highlights()

  -- ⑩ 本局用时按快照回溯
  -- 【精确值拿不到】快照只存棋钟（clockW/clockB），没存 wall clock 在本局的累计值，
  --   所以无法精确还原「撤回那一刻的 elapsedSec」。
  -- 【做法】用「双方棋钟总量在撤回前后的差」近似：撤回让棋钟回到更早的值，
  --   差值就是被撤掉那两步里流逝的时间，从 elapsedSec 里扣掉即可。
  --   这是保守近似：它不会让 elapsedSec 偏大（gdd §7.6 第 10 项的要求就是「别偏大」）。
  --   扣到负数时归零。
  do
    local before = GAME.undoClockBefore
    local after = (GAME.clockWhite or 0) + (GAME.clockBlack or 0)
    if before ~= nil then
      local delta = before - after         -- 撤回后退回的时间量
      if delta > 0 then
        GAME.elapsedSec = math.max(0, (GAME.elapsedSec or 0) - delta)
      end
      GAME.undoClockBefore = nil
    end
    if GAME.elapsedSec == nil or GAME.elapsedSec < 0 then GAME.elapsedSec = 0 end
  end

  -- 回合数同步（turnCount 只是计数，用于显示/诊断）
  GAME.turnCount = target

  -- 终局标记复位：撤回可能把「已经结束」的局面救回来
  GAME.over = false
  GAME.resultText = nil
  GAME.resultSub = nil

  render_all()
  return true
end

-- 扣发起方一次悔棋次数
undo_consume = function()
  local side = undo_actor_side()
  local left = undo_left_of(side) - 1
  if left < 0 then left = 0 end
  GAME.undoLeft[side] = left
  return left
end

-- 悔棋按钮文案 + 置灰态（每次 render_all / 状态变化时调）
refresh_undo_button = function()
  local b = UI.panel
  if b == nil or b.v2Undo == nil then return end
  -- ===== 可见性：对局中（playing）第三行左半**永远**显示悔棋 =====
  --
  -- 【v2.0 修 D-1：删掉了 v2UndoShown 这个自建缓存】
  --   原实现用一个 b.v2UndoShown 布尔量缓存显隐，只在「缓存与目标不同」时才写控件。
  --   漏洞：show_confirm 里会走 show_panel_buttons(false)，那条路径**直接**
  --   ui_set_active(v2Undo,false)，没有更新 v2UndoShown；随后 hide_confirm 走
  --   show_panel_buttons(true) 又不会重新点亮 v2Undo（我的实现里 `on=true` 时故意不碰它）。
  --   于是缓存还停在 true，`shouldShow ~= cache` 判为假 → **永远不再写控件**
  --   → 悔棋确认框关掉后，悔棋按钮消失、「看历史」露出来。
  --   （模拟器实测：悔棋成功后第三行变回「看历史」，正是这条。）
  --
  --   【修法】不建第二份缓存。ui_set_active 内部已有权威的 VIS_STATE 做去重，
  --   重复调用不会有额外控件写（命中时直接 cw_skip() 返回）。少一层状态 = 少一个失同步点。
  --
  -- 【v2.0 修 D-1（二）：对局中永不显示「看历史」】
  --   Lead 裁决：对局中第三行左半 ALWAYS 显示「悔棋（剩 N）」，「看历史」只在结算面板出现。
  --   理由：① 语义唯一（对局中 = 悔棋，非对局中 = 别的）；
  --         ② 玩家不会困惑「我刚悔棋，怎么变看历史了」；
  --         ③ 从根上消灭「用状态切按钮」带来的这类 bug。
  --
  -- 三个状态严格分开（Lead 给的规格）：
  --   screen==playing  → 总是「悔棋（剩 N）」，可点性由 undo_check() 决定
  --   screen==review   → 让位给「退出复盘」
  --   其它/结算        → 让位给「看历史」
  local playing = (GAME.screen == "playing") and (GAME.review == nil)
  local shouldShow = playing          -- 对局中永远是悔棋，不因次数/历史长度而变化

  ui_set_active(b.v2Undo, shouldShow)
  ui_set_active(b.hitV2Undo, shouldShow)
  -- 同一格的「看历史/退出复盘」与悔棋互斥：对局中让位，其余显示
  if UI.review ~= nil and UI.review.btnToggle ~= nil then
    ui_set_active(UI.review.btnToggle, not shouldShow)
    ui_set_active(UI.review.hitToggle, not shouldShow)
  end
  if not shouldShow then return end

  local side = undo_actor_side()
  local left = undo_left_of(side)
  -- 文案：等待对方回应时改「等待对方同意悔棋…」；否则恒为「悔棋（剩 N）」
  -- 【关键】次数为 0 时**仍然显示**「悔棋（剩 0）」，绝不退回「看历史」
  --   （gdd §7.3：n==0 时按钮文字仍为「悔棋（剩 0）」，样式转置灰，命中区保留）
  local txt
  if GAME.pendingUndo ~= nil and GAME.pendingUndo.byMe then
    txt = CONFIG.TEXT.UNDO_WAITING_PEER
  else
    txt = string.gsub(CONFIG.TEXT.UNDO_BTN, "{n}", tostring(left))
  end
  if b.v2Undo.text ~= txt then b.v2Undo.text = txt end
  -- 置灰：次数为 0 或六条条件任一不满足 → 灰底灰字（命中区保留，点了弹原因）
  local can = select(1, undo_check())
  local gray = (left <= 0) or (not can)
  local wantBg = gray and CONFIG.COLOR.BTN_DIS_BG or CONFIG.COLOR.BTN_BG
  local wantFg = gray and CONFIG.COLOR.BTN_DIS_TEXT or CONFIG.COLOR.BTN_TEXT
  if b.v2UndoBg ~= wantBg then
    b.v2UndoBg = wantBg
    b.v2Undo.bgColor = color_of(wantBg)
  end
  if b.v2UndoFg ~= wantFg then
    b.v2UndoFg = wantFg
    b.v2Undo.fontColor = color_of(wantFg)
  end
end

-- 新开一局
-- 【v2.0】棋钟起始值改读 GAME.tcInitial（档位驱动），不再用常量 CONFIG.INITIAL_TIME_SEC。
--   默认档位 3 的 tcInitial 就是 900，所以「不选档位」路径与 v1.12 逐位一致。
-- 【v2.0 块 3】同时把双方悔棋次数重置为 CONFIG.UNDO_PER_SIDE（gdd §7.8：
--   开局/新开一局/再来一局/从此局面开新局 四种入口都必须回到 3）。
new_game = function()
  GAME.st = RULES.parse_fen(START_FEN)
  GAME.over = false
  GAME.resultText = nil
  GAME.resultSub = nil
  local t0 = GAME.tcInitial or CONFIG.INITIAL_TIME_SEC
  GAME.clockWhite = t0
  GAME.clockBlack = t0
  GAME.moveLog = {}
  GAME.capturedWhite = {}
  GAME.capturedBlack = {}
  GAME.lastFrom = nil
  GAME.lastTo = nil
  GAME.turnCount = 0
  GAME.elapsedSec = 0
  GAME.pendingPromo = nil
  GAME.drawCooldown[1] = 0
  GAME.drawCooldown[2] = 0
  GAME.drawReqSent = false
  GAME.lastSentMove = nil
  -- 【v2.0 块 3】悔棋次数回到 3（gdd §7.8）。四种入口都走 new_game 或显式重置，
  -- 所以「单局资源」的语义成立：换局 = 回满。
  GAME.undoLeft[1] = CONFIG.UNDO_PER_SIDE
  GAME.undoLeft[2] = CONFIG.UNDO_PER_SIDE
  GAME.pendingUndo = nil
  -- 【v3.2】新开一局要复位两个「一局只做一次」的标记：
  --   settled       —— show_result 的记账幂等闸（不复位 → 下一局结算不记分）
  --   resultChoice  —— 结算后双方选择（不复位 → 上一局的「再来一局」残留会直接触发开新局）
  GAME.settled = false
  GAME.resultChoice = nil
  -- 【v3.2】token 也清掉：下一局的第一次选择必须生成新 token，
  --   否则会拿上一局的 token 去比，误吞对方的包（或漏吞自己的回声）。
  GAME.__resultToken = nil
  -- 【复盘】新开一局清空历史，只留开局快照（history[1] 恒为开局）
  GAME.review = nil
  GAME.reviewState = nil
  GAME.history = { {
    fen = RULES.fen_of(GAME.st),
    text = "",
    from = nil, to = nil,
    capW = 0, capB = 0,
    clockW = t0, clockB = t0,
  } }
  clear_highlights()
  hide_result()
  hide_promo()
  hide_confirm()
  -- 【音效】新开一局要：
  --   ① 停掉正在播的实例（上一局的 GAME_END 有 6 秒长，不停会串到新局开场）
  --   ② 复位三个「只播一次」的标记，否则新局的终局音和低时提示永远不会响
  sfx_stop_all()
  SFX.overFired = false
  SFX.lowTimeFired[1] = false
  SFX.lowTimeFired[2] = false
  -- 【动画】清掉正在跑的所有动画，并把槽位绑定复位（否则新棋盘会沿用旧槽位的中间态）
  anim_clear()
  if GAME.uiReady then reset_piece_slots() end
  -- 复盘按钮回到正常态（新开一局总是回到对局模式）
  if GAME.uiReady and UI.review then
    show_review_buttons(false)
    show_panel_buttons(true)
    ui_set_active(UI.review.btnToggle, true)
    ui_set_active(UI.review.hitToggle, true)
    UI.review.btnToggle.text = CONFIG.TEXT.BTN_REVIEW_HISTORY
  end
  if GAME.uiReady then
    for sq = 0, 63 do
      if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], true) end
    end
    if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.HINT_OPENING end
  end
  render_all()
  -- 【动画】开局「逐格弹入」：每个棋子按格号错开一点点出现，整盘像被摆上来
  if GAME.animated and GAME.uiReady then board_intro() end
  -- 【v2.0 修：悔棋按钮必须在这里收敛一次】
  --   上面 `show_panel_buttons(true)` 只恢复「四个常规面板键 + 返回主菜单」，**不含 v2Undo**
  --   —— 因为那一格是「悔棋 ↔ 看历史」两态复用的，它自己不知道该显示哪个。
  --   漏了这行的现象（实测）：从结算面板点「再来一局」后，第三行左半停在「看历史」，
  --   而 `GAME.undoLeft` 其实已经回满 3 —— 玩家会以为这局不能悔棋。
  --   这是「A 关、B 负责开 → 关闭方恢复时必须回叫 B」那条纪律的又一个实例。
  if GAME.uiReady and refresh_undo_button ~= nil then refresh_undo_button() end
end

-- 开局弹入动画：按「从下往上、从左到右」的顺序把 32 枚棋子依次弹出来。
-- 【为什么用 scale 弹入而不是淡入】图元控件的 imageColor 是乘色，改 alpha 时
-- 半透明叠加会露出底下的格色，看起来像脏点；缩放弹入则始终不透明，干净。
function board_intro()
  if not GAME.uiReady then return end
  local idx = 0
  for i = 1, CONFIG.PIECE_MAX_SLOTS do
    local slot = UI.pieceSlots[i]
    if slot ~= nil and slot.sq ~= nil then
      local st = idx * CONFIG.ANIM.INTRO_STAGGER
      idx = idx + 1
      slot.scale = 0.01
      slot.lift = 0
      anim_add(st, function(u)
        -- 延迟段：什么也不做，只是等
        slot.scale = 0.01
      end, function()
        anim_add(CONFIG.ANIM.BOARD_INTRO * 0.42, function(v)
          -- outBack：略微超过 1 再回来，像被「放」到格子上
          slot.scale = math.max(0.01, EASE.outBack(v))
        end, function()
          slot.scale = 1
        end, slot)   -- ← 弹入段登记脏槽位
      end, slot)     -- ← 延迟段也登记（否则延迟期间该槽位不重绘，会停在上一帧的 scale）
    end
  end
end

-- =============================================================================
-- 联机快速开局（v3.0）—— 取代 v2.0 的「联机·待机室」
-- -----------------------------------------------------------------------------
-- 【用户需求】（2026-11 真机反馈；逐条用例见 tests/match-v3-cases.md）
--   ① 双人进入后不要待机室：双方各选一个时间档 → 选好就自动把两人拉进对战；
--   ② 界面上要能看到对方选了哪个时间；
--   ③ 两人不同给 5 秒改选窗口，都不改就随机采用其中一个；
--   ④ 进对局后随机分黑白，黑方看到的棋盘翻转（黑棋在下），棋子保持正立。
--
-- 【协议：不新增事件号、不改服务端节点图】仍走 ChessSync 的 5 个槽位：
--   EV_READY(8)  a=1 我已选好  b=档位号 1..4  c=0  fen=本端标识 "P<随机数>"
--      · 只有「我已经选了」才发；之后每 MATCH_HEARTBEAT_SEC 重发一次（抗丢包）
--      · 收到 fen ∈ 本端历史标识 ⇒ 自己的回声，丢弃
--   EV_START(9)  a=0 我执白 / 1 我执黑  b=档位号  c=0  fen=本端标识
--      · 一方先判定成功就先开局，顺手把「档位 + 我的颜色」告诉对方，对方直接跟上
--
-- 【为什么标识必须两端不同】
--   服务端把信号广播回发送者自己，而官方客户端 API 不提供发送者身份（docs/api-audit.md）。
--   旧版标识是 "T<序号>"，两端序号都从 1 开始 ⇒ 必然撞车（当时靠 15 秒兜底掩盖了）。
--   现在标识 = 本端随机数，且**每次点时间档都重摇一次**（点击时刻不同 ⇒ 数值不同），
--   旧标识留在 myFens 里继续认作「自己」，避免旧回声被当成对手。
--
-- 【黑白怎么保证一黑一白】规则「本端随机数大者执白」对两端是**反对称**的：
--   我算 myRand > peerRand，对方算 peerRand > myRand，恰好一个成立。
--   随机数相同（两端同帧点击的极端情况）时退化为同色 —— 由 EV_START 的 a 字段二次纠正，
--   见 online_on_peer_start 的「同色修复」。
--
-- 【对手在不在读不到】官方 API 没有房间成员列表（gdd §10.2 U-1），只能用
--   「最近一次收到对方包的本地时间」推断在线。只影响文案与「是否允许判定」，
--   不影响已经开始的对局。
--
-- 【⚠️ 为什么这里全是 GAME.match.* 字段，而不是 local function】
--   Lua 主 chunk 的 local 变量上限是 **200**。本文件 v2.0 加完后已贴着上限：
--   本轮先写成 15 个 local 函数，模拟器直接编译失败
--   （`sim/levelScript.lua:8314: too many local variables (limit is 200)`）。
--   表字段不占 local，所以「视角映射 + 选时间协商」的函数一律挂在 GAME.match 上，
--   状态仍放 GAME.online。**后续改动不要把它们改回 local function。**
-- =============================================================================
GAME.match.sq = function(sq)
  if GAME.match.flip then return 63 - sq end
  return sq
end

GAME.match.now = function()
  return GAME.onlineClock or 0
end

-- 视角翻转 + 坐标标注换字（棋子/高亮的落位由 GAME.match.sq 在渲染层完成）
GAME.match.set_flip = function(on)
  GAME.match.flip = (on == true)
  if UI.coordFiles ~= nil then
    for f = 0, 7 do
      local c = UI.coordFiles[f]
      if c ~= nil then
        local idx = GAME.match.flip and (7 - f) or f
        local letter = string.char(string.byte("a") + idx)
        if c.text ~= letter then c.text = letter end
      end
    end
  end
  if UI.coordRanks ~= nil then
    for r = 0, 7 do
      local c = UI.coordRanks[r]
      if c ~= nil then
        local num = tostring(GAME.match.flip and (8 - r) or (r + 1))
        if c.text ~= num then c.text = num end
      end
    end
  end
  log_info("视角：%s", GAME.match.flip and "黑方（黑棋在下 / 坐标 8→1、h→a）"
                                       or "白方（白棋在下 / 坐标 1→8、a→h）")
end

-- 摇本端随机数 + 标识。熵 = os.time 的秒级时刻 + 本地累计帧时间的微秒部分。
-- 【为什么不用 math.random】Lua 5.3 不设种子时两端序列完全一样（必撞车）；
--   os.time 又可能落在同一秒，所以必须叠加帧时间（两台设备/两个玩家的点击时刻不同）。
GAME.match.roll_id = function()
  local O = GAME.online
  local t = 0
  pcall(function() t = os.time() end)
  local us = math.floor(GAME.match.now() * 1000000) % 1000000
  -- 【为什么把量级压到 1e9 以内】fengari / 沙箱的整数只有 32 位，
  -- 超过 2^31 会回绕。数值本身两端各自独立计算不影响比较，但为了可读性与
  -- 「不依赖回绕」的稳妥，这里把 os.time 取后 4 位、帧时间取 6 位：
  -- 上限 9999 * 100000 + 999999 = 999,999,999 < 2^31 ✅
  local r = (math.floor(t) % 10000) * 100000 + us
  O.myRand = r
  O.myFen = CONFIG.MATCH_ID_PREFIX .. tostring(r)
  O.myFens[O.myFen] = true
  return r, O.myFen
end

-- 回到初始界面 = 一次新协商
GAME.match.reset = function()
  local O = GAME.online
  O.myTier = nil
  O.myRand = nil
  O.myFen = nil
  O.peerTier = nil
  O.peerRand = nil
  O.peerFen = nil
  O.peerSeenAt = nil
  O.conflictAt = nil
  O.conflictPeer = nil
  O.hbAt = 0
  O.announced = false
  GAME.mySide = 1
  -- 回到初始界面 = 退出「同屏/复盘」的本地语义，重新可能走联机协商
  -- （net_send_event 的 localMode 闸会拦住一切发包，不复位的话选时间档不会广播）
  GAME.localMode = false
  -- 注意：**不清** O.myFens —— 上一批包的迟到回声仍要能被认成「自己的」
end

GAME.match.broadcast = function()
  local O = GAME.online
  if O.myTier == nil then return false end
  if O.myFen == nil then GAME.match.roll_id() end
  return net_send_event(CONFIG.EV_READY, 1, O.myTier, 0, O.myFen)
end

GAME.match.peer_fresh = function()
  local O = GAME.online
  if O.peerSeenAt == nil then return false end
  return (GAME.match.now() - O.peerSeenAt) <= CONFIG.MATCH_PEER_FRESH_SEC
end

-- 【v3.2】「现在有另一位玩家联机吗」—— 全局唯一判据。
-- 用户要求：有对手时关掉「单人复盘练习 / 返回主菜单 / 新开一局」；
--   没有对手时「单人复盘练习」自动读上一局存档。
-- 【为什么定义在这里而不是 net 区】show_panel_buttons 与初始界面都要用它，
--   而它是 GAME.match.peer_fresh 的同义封装（peer_fresh 定义在 GAME.match 上，
--   这里挂全局名方便早期调用）。两者必须同源，绝不能各写一份判据 ——
--   否则会出现「面板认为在线、初始界面认为不在线」的矛盾。
-- 【注意】GAME.online 可能还没建（启动早期），所以整套访问都要兜住 nil。
function net_peer_online()
  if GAME.online == nil then return false end
  if GAME.match == nil or GAME.match.peer_fresh == nil then return false end
  local ok, fresh = pcall(GAME.match.peer_fresh)
  if not ok then return false end
  return fresh == true
end

-- 视角翻转后让棋子按新格号重新落位
-- 【为什么需要】render_pieces 的全量路径只在 slot.x == nil 时才重算坐标，
-- 已经在场的 32 枚棋子会沿用旧坐标 —— 直接把 GAME.match.flip 改掉而不清缓存，
-- 表现是「棋盘方向变了、棋子还在原处」。
GAME.match.reposition = function()
  if UI.pieceSlots ~= nil then
    for i = 1, CONFIG.PIECE_MAX_SLOTS do
      local slot = UI.pieceSlots[i]
      if slot ~= nil then slot.x, slot.y = nil, nil end
    end
  end
  if GAME.uiReady then render_all() end
end

-- 点一张时间档卡（初始界面）
GAME.match.on_pick = function(n)
  local O = GAME.online
  apply_time_control(n)
  O.myTier = n
  O.conflictAt = nil          -- 我改选了：5 秒窗口重新计
  O.hbAt = 0
  GAME.match.roll_id()            -- 每次选都重摇标识（见上方「为什么标识必须两端不同」）
  GAME.match.broadcast()
  refresh_time_control_cards()
  refresh_start_hint()
  log_info("联机：本端选择档位 %d（标识 %s）", n, tostring(O.myFen))
end

-- 第三入口「双人·联机对战」：手动宣告参战（等价于「用当前选中的档位参战」）
-- 【为什么还留这一格】偶发丢包时，玩家点一下就能立刻重发自己的时间档；
--   它不再进入任何「等待房间」，只是把当前档位再广播一次。
GAME.match.announce = function()
  local O = GAME.online
  if O.myTier == nil then
    apply_time_control(GAME.tcN)
    O.myTier = GAME.tcN
  end
  O.announced = true
  O.hbAt = 0
  GAME.match.roll_id()
  GAME.match.broadcast()
  refresh_time_control_cards()
  refresh_start_hint()
  log_info("联机：已向对手广播本端档位 %d", O.myTier)
end

-- 真正开局：定格档位 → 随机黑白 → 视角翻转 → 通知对端
GAME.match.start = function(tier, source)
  if GAME.screen ~= "start" then return false end
  if GAME.inSelfTest then return false end
  local O = GAME.online
  -- 随机黑白：随机数大的一方执白（反对称 ⇒ 两端必然一黑一白）
  local mySide
  if O.myRand ~= nil and O.peerRand ~= nil and O.myRand ~= O.peerRand then
    mySide = (O.myRand > O.peerRand) and 1 or 2
  elseif O.myFen ~= nil and O.peerFen ~= nil and O.myFen ~= O.peerFen then
    -- 随机数相同（极小概率）→ 用标识字符串比大小，仍然反对称
    mySide = (O.myFen > O.peerFen) and 1 or 2
  else
    mySide = 1
  end
  GAME.mySide = mySide
  GAME.localMode = false
  GAME.tcN = tier
  apply_time_control(tier)
  hide_all_overlays()
  hide_start_screen()
  hide_lobby()
  hide_result()
  hide_promo()
  hide_confirm()
  -- 【顺序关键】先翻视角再 new_game：new_game → render_all 会按当前 GAME.match.flip 落位，
  -- 所以开局那一刻棋子就已经在正确的一侧（不存在「先白后黑」的闪一下）。
  GAME.match.set_flip(mySide == 2)
  new_game()
  GAME.screen = "playing"
  if refresh_undo_button ~= nil then refresh_undo_button() end
  if UI.panel.hint ~= nil then
    UI.panel.hint.text = (mySide == 1) and CONFIG.TEXT.MATCH_ROLE_WHITE or CONFIG.TEXT.MATCH_ROLE_BLACK
  end
  update_turn_text()
  -- 告诉对端：b=档位  a=我的颜色（0 白 / 1 黑）
  if O.myFen == nil then GAME.match.roll_id() end
  net_send_event(CONFIG.EV_START, (mySide == 1) and 0 or 1, tier, 0, O.myFen)
  log_info("联机开局：档位=%d（%d+%d） 我执%s 判定依据=%s",
    tier, GAME.tcInitial, GAME.tcIncrement,
    (mySide == 1) and "白" or "黑", tostring(source))
  return true
end

-- 收到对方的「我已选好某个档位」
GAME.match.on_peer_pick = function(a, b, c, fen)
  local O = GAME.online
  if fen ~= nil and O.myFens[fen] ~= nil then return false end   -- 自己的回声
  local now = GAME.match.now()
  local changed = false
  if a == 1 then
    local tier = tonumber(b) or 0
    if tier >= 1 and tier <= #CONFIG.TIME_CONTROLS then
      if O.peerTier ~= tier then changed = true end
      O.peerTier = tier
    end
  end
  if fen ~= nil and fen ~= "" then
    O.peerFen = fen
    local r = tonumber(string.sub(fen, string.len(CONFIG.MATCH_ID_PREFIX) + 1))
    if r ~= nil then O.peerRand = r end
  end
  O.peerSeenAt = now
  if changed then
    log_info("联机：对手选择档位 %d", O.peerTier)
    if GAME.screen == "start" then refresh_start_hint() end
  end
  return true
end

-- 收到对方的「我已开局」（同时带来它的颜色）
GAME.match.on_peer_start = function(a, b, fen)
  local O = GAME.online
  if fen ~= nil and O.myFens[fen] ~= nil then return end
  if fen ~= nil and fen ~= "" then
    O.peerFen = fen
    local r = tonumber(string.sub(fen, string.len(CONFIG.MATCH_ID_PREFIX) + 1))
    if r ~= nil then O.peerRand = r end
    O.peerSeenAt = GAME.match.now()
  end
  local peerSide = (tonumber(a) == 0) and 1 or 2
  if GAME.screen == "start" then
    local tier = tonumber(b) or 0
    if tier < 1 or tier > #CONFIG.TIME_CONTROLS then tier = GAME.tcN end
    if GAME.match.start(tier, "peer_start") then
      -- 对方已经宣告了它的颜色 ⇒ 我取相反色，比随机数比较更硬
      if GAME.mySide == peerSide then
        GAME.mySide = (peerSide == 1) and 2 or 1
        GAME.match.set_flip(GAME.mySide == 2)
        GAME.match.reposition()
        update_turn_text()
        log_info("联机开局：按对方 EV_START 纠正为执%s", (GAME.mySide == 1) and "白" or "黑")
      end
    end
    return
  end
  -- 已在局中：极小概率的「两端同色」修复（只在一步未走时做，避免中途翻转视角）
  if GAME.screen == "playing" and not GAME.over and not GAME.localMode then
    if GAME.mySide == peerSide and #GAME.moveLog == 0 then
      local iKeep = (O.myRand or 0) > (O.peerRand or 0)
      if not iKeep then
        GAME.mySide = (peerSide == 1) and 2 or 1
        GAME.match.set_flip(GAME.mySide == 2)
        GAME.match.reposition()
        update_turn_text()
        log_info("联机：同色冲突已修复，本端改执%s", (GAME.mySide == 1) and "白" or "黑")
      end
    end
  end
end

-- 初始界面每帧推进：心跳 / 相同即开局 / 5 秒改选窗口 / 超时随机裁决
GAME.match.tick = function(dt)
  local O = GAME.online
  -- 心跳：把「我已选好的档位」重复广播（对端靠它判在线、也靠它看到我的选择）
  if O.myTier ~= nil then
    O.hbAt = (O.hbAt or 0) + dt
    if O.hbAt >= CONFIG.MATCH_HEARTBEAT_SEC then
      O.hbAt = 0
      GAME.match.broadcast()
    end
  end
  local fresh = GAME.match.peer_fresh()
  if O.myTier ~= nil and O.peerTier ~= nil and fresh then
    if O.peerTier == O.myTier then
      -- 双方选到同一个档位 → 立即开局（需求：选好自动拉进对战）
      GAME.match.start(O.myTier, "same")
      return
    end
    if O.conflictAt == nil then
      O.conflictAt = GAME.match.now()
      O.conflictPeer = O.peerTier
      log_info("联机：档位不同（我 %d / 对手 %d），进入 %d 秒改选窗口",
        O.myTier, O.peerTier, CONFIG.MATCH_DIFF_WAIT_SEC)
    end
    if (GAME.match.now() - O.conflictAt) >= CONFIG.MATCH_DIFF_WAIT_SEC then
      -- 随机采用一个：随机数大的一方胜出（两端反对称 ⇒ 结果一致）
      local useMine
      if O.myRand ~= nil and O.peerRand ~= nil and O.myRand ~= O.peerRand then
        useMine = (O.myRand > O.peerRand)
      else
        useMine = (O.myTier <= O.peerTier)     -- 兜底：取首钟更短的档（两端同规则）
      end
      local tier = useMine and O.myTier or O.peerTier
      log_info("联机：%d 秒内都没改，随机采用档位 %d（来源=%s）",
        CONFIG.MATCH_DIFF_WAIT_SEC, tier, useMine and "我" or "对手")
      GAME.match.start(tier, "random")
      return
    end
  elseif O.conflictAt ~= nil and not fresh then
    O.conflictAt = nil       -- 对手没消息 → 改选窗口不推进
  end
  refresh_start_hint()
end

-- 选中一枚子
local function select_square(sq)
  -- 【v3.3】用 view_state() 取局面：复盘态读的是快照，真实对局读的是 GAME.st。
  -- 分支试走已移除，所以这里只剩「复盘快照 / 真实局面」两级。
  local st = view_state()
  local p = st.board[sq]
  if p == 0 then return false end
  -- 只能选自己一方的子
  if (p > 0) ~= (st.turn == WHITE) then return false end
  -- 联机模式下只能操作自己那一方（复盘里恒为本地，不适用）
  if not GAME.localMode and GAME.review == nil then
    local myTurn = (GAME.mySide == 1 and st.turn == WHITE) or (GAME.mySide == 2 and st.turn == BLACK)
    if not myTurn then return false end
  end

  local moves = RULES.legal_moves(st)
  local targets = {}
  local mine = {}
  for _, mv in ipairs(moves) do
    if mv.from == sq then
      mine[#mine + 1] = mv
      targets[mv.to] = true
    end
  end
  if #mine == 0 then return false end

  GAME.selected = sq
  GAME.legalTargets = targets
  GAME.legalMoves = mine

  -- 【issue #3】必须先清空落点池，再画本次的落点。
  -- 池子按索引复用：不清空就直接写 legalhl1..n，会让**上一次选中多出来的那些绿点
  -- 原样留在盘上**（它们指向的格子这枚子走不到），看起来就是「高亮错位」。
  -- 详见 hide_legal_pool 的注释。
  hide_legal_pool()

  local L = UI.L

  -- 选中格：琥珀薄罩 + 上下两条亮边框
  local x, y = LAYOUT.square_pos(L, GAME.match.sq(sq))
  UI.selHLx, UI.selHLy = x, y
  UI.selHL:SetSizeDelta(L.cell, L.cell)
  UI.selHL:SetAnchoredPosition(x, y)
  UI.selHL.bgColor = color_of(CONFIG.COLOR.SEL_HL)
  ui_set_active(UI.selHL, true)
  local rt = UI.selRingW
  UI.selRingTop:SetSizeDelta(L.cell, rt)
  UI.selRingTop:SetAnchoredPosition(x, y + L.cell - rt)
  ui_set_active(UI.selRingTop, true)
  UI.selRingBot:SetSizeDelta(L.cell, rt)
  UI.selRingBot:SetAnchoredPosition(x, y)
  ui_set_active(UI.selRingBot, true)

  -- 落点高亮：空格画圆点、可吃子画整格薄罩（都记下基准位置给脉动用）
  --
  -- 【v1.11 修 issue #1 第 1 条「走棋特效错位严重」】
  -- 这里的控件来自 `create_image`，它的 pivot 是 **0.5**（图元要绕自身中心旋转），
  -- 所以 `SetAnchoredPosition(x, y)` 设的是**中心点**，而不是左下角。
  -- 而 `LAYOUT.square_pos` 返回的是棋格**左下角**（文本框控件的 pivot 是 0，正好对上）。
  -- 旧代码把左下角坐标直接喂给图片控件，于是：
  --   · 空格圆点（直径 0.30 格）偏左下 0.35 格 —— 实测截图里绿点明显跑到格子左下方，
  --     还压到相邻格上；
  --   · 可吃子整格薄罩（边长 1 格）偏左下 0.5 格 —— 红圈正好盖住左下相邻格的四分之一，
  --     看起来完全对不上（issue 截图 1 里那个红圆就是它）。
  -- 正确做法：中心 = 左下角 + 边长/2。
  ANIM.hlBase = ANIM.hlBase or {}
  local idx = 0
  -- 【v3.3】分支已移除，落点恢复单一配色（墨绿圆点 / 红薄罩），
  -- 不再需要「按是否在分支取不同颜色」这一层判断。
  local colDot = CONFIG.COLOR.LEGAL_HL
  local colCap = CONFIG.COLOR.LEGAL_CAP
  -- 【必须用 view_state().board】复盘下要按「屏幕上显示的局面」判可吃子，
  -- 用 GAME.st.board 会把真实局面的占用情况套到复盘画面上 → 圆点/薄罩画错。
  local board = view_state().board
  for to, _ in pairs(targets) do
    idx = idx + 1
    if idx > 28 then break end
    local tx, ty = LAYOUT.square_pos(L, GAME.match.sq(to))
    -- 棋格中心（图片控件按中心定位，见上方说明）
    local cx, cy = tx + L.cell * 0.5, ty + L.cell * 0.5
    local c = UI.legalHL[idx]
    local isCap = (board[to] ~= 0)
    if isCap then
      -- 可吃子：整格薄罩（尺寸 = 一格，中心 = 格中心）
      c:SetSizeDelta(L.cell, L.cell)
      c:SetAnchoredPosition(cx, cy)
      c.imageColor = color_of(colCap)
      ANIM.hlBase[idx] = { x = cx, y = cy, size = L.cell }
    else
      -- 空格：居中的圆点（尺寸 = 0.30 格，中心同样取格中心）
      local d = L.cell * 0.30
      c:SetSizeDelta(d, d)
      c:SetAnchoredPosition(cx, cy)
      c.imageColor = color_of(colDot)
      ANIM.hlBase[idx] = { x = cx, y = cy, size = d }
    end
    ui_set_active(c, true)
  end
  UI.legalHLUsed = idx
  if UI.panel.hint then
    if GAME.review ~= nil then
      UI.panel.hint.text = CONFIG.TEXT.REVIEW_AT_START_BRANCH
    else
      UI.panel.hint.text = CONFIG.TEXT.HINT_SELECTED
    end
  end
  -- 音效：选中一枚自己的棋子（对应 Demo 第 1935 行 SFX.play("select")）
  sfx_play("select")
  return true
end

-- 尝试走子
local function try_move(toSq)
  if GAME.selected == nil then return false end
  if not GAME.legalTargets[toSq] then return false end

  -- 找出所有落到该格的走法（升变会有 4 条）
  local candidates = {}
  for _, mv in ipairs(GAME.legalMoves) do
    if mv.to == toSq then candidates[#candidates + 1] = mv end
  end
  if #candidates == 0 then return false end

  if #candidates > 1 and candidates[1].promo ~= nil then
    -- 需要玩家选升变
    GAME.pendingPromo = candidates
    show_promo()
    for sq = 0, 63 do
      if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], false) end
    end
    return true
  end

  apply_move(candidates[1])
  net_send_move(candidates[1])
  return true
end

-- 处理棋盘点击
local function on_square_clicked(sq)
  -- 【v3.0】命中区建在「物理格」上（build_board），闭包捕获的也是物理格号。
  -- 黑方视角下屏幕上那一格显示的是逻辑格 63-sq，所以这里先换算回逻辑格。
  -- GAME.match.sq 是自逆的：显示用一次、命中也用一次，两处共用同一个函数，不会漂移。
  sq = GAME.match.sq(sq)
  -- 【v3.3】复盘态：棋盘只看不点。
  -- 分支试走（原 v2.0 块 4）已随「退回主变」一起移除，所以这里只需要拦掉点击。
  -- 正常情况下 set_board_input(false) 已经让命中区不响应，这里是**第二道闸** ——
  -- 防止将来有人把 set_board_input(true) 加回来时，点击直接落到下面的真对局逻辑上
  -- （那样在复盘里点棋子会真的走棋，属于灾难级 bug）。
  if GAME.review ~= nil then
    return
  end
  if GAME.state ~= "RUNNING" or GAME.over or GAME.pendingPromo then return end

  -- 已选中且点的是合法落点 → 走子
  if GAME.selected ~= nil and GAME.legalTargets[sq] then
    try_move(sq)
    return
  end

  -- 点同一枚已选中的子 → 取消
  if GAME.selected == sq then
    clear_highlights()
    if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.HINT_OPENING end
    return
  end

  -- 尝试选中
  local ok = select_square(sq)
  if not ok then
    clear_highlights()
    if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.HINT_OPENING end
  end
end

-- =============================================================================
-- 三入口动作 + 返回主菜单（v2.0，块 1）
-- -----------------------------------------------------------------------------
-- 【定义位置】必须在 register_all_input 之前（它要把这些函数绑到命中区上）。
-- 【入口语义（v3.3：同屏已删除，只剩两个）】
--   ① entry_review：「单人·复盘研习」→ 有上局存档就载入，否则进开局局面（只读回放）
--   ② entry_online：「双人·联机对战」→ 选档并广播，双方同档即自动开局
-- =============================================================================

-- ① 【v3.2 已停用】双人同屏开局
-- -----------------------------------------------------------------------------
-- 用户要求「删除单人同屏模式」：初始界面已经没有「单人·双人同屏」入口，
-- 面板也没有「切换本地同屏」按钮，所以**没有任何 UI 路径**能走到这个函数。
--
-- 【为什么不删掉函数体】同屏曾经是主玩法，自检（start_screen_parts /
--   lobby_hidden_in_play）与多份文档都引用了这条路径；直接删会让这些引用指向 nil。
--   保留成「不可达但完整」的函数，代价是几百行死代码，收益是自检与文档不用大改。
--   若将来确定不再需要同屏，可以整段删除并把相关自检一并收掉。
--
-- 【重要】GAME.localMode 仍然保留：它现在是「本局有没有真人对手」的运行期标志
--   （无对手 = 单人复盘/演练），不再等同于「同屏模式」。多处逻辑（求和标题、
--   悔棋是否走网络、吃子标签用「你」还是颜色名）都依赖它。
local function entry_start_local()
  apply_time_control(GAME.tcN)
  GAME.localMode = true
  -- 【v3.0】同屏：同一台设备轮流操作双方，视角恒为「白棋在下」
  -- （必须先翻回再 new_game，否则会带着上一局联机执黑的翻转进同屏）
  GAME.match.set_flip(false)
  -- 【v2.0 块 3 修 P0：必须同时隐藏「初始界面层」和「待机室层」】
  -- 模拟器实测缺陷：走子后画面被待机室的空白骨架盖住（棋盘/棋子/面板全看不见）。
  -- 根因：本函数只调了 hide_start_screen()，**漏了 hide_lobby()**。
  --   块 2 时待机室层从来没被显示过，所以不隐藏也看不出来；
  --   但块 3 让「有待机室层」成为常态后，这条路径就会带着整个待机室层进对局。
  --   （同理 entry_start_review 也漏了。）
  -- 【通用纪律】任何「离开当前整层 → 进入对局」的路径，都必须把三层全部收敛：
  --   hide_start_screen() + hide_lobby() + 关弹窗。缺一层就会出现「幽灵层」。
  --   → 已加自检断言 lobby_hidden_in_play 守这条。
  -- 【v2.0 块 5 BUG-1：进对局必须先收起一切覆盖层（含复盘动作条）】
  -- 原来的 hide_start_screen() + hide_lobby() 漏了动作条，导致
  -- 「退回主变」「从此开新局」在初始界面和待机室底部露出来并压住底部提示。
  -- hide_all_overlays() 是收敛点，以后新增覆盖层只改那一处。
  hide_all_overlays()
  hide_start_screen()
  hide_lobby()
  hide_result()
  hide_promo()
  hide_confirm()
  new_game()
  GAME.screen = "playing"
  -- 【v2.0 修：screen 设好之后必须再刷一次悔棋按钮】
  --   `new_game()` 内部也会刷，但那时 `GAME.screen` 还是旧值（"start"），
  --   所以它按「非对局中」处理、把第三行留给「看历史」。
  --   实测现象：从初始界面进对局后，第三行停在「看历史」而 `undoLeft` 已是 3。
  if refresh_undo_button ~= nil then refresh_undo_button() end
  -- new_game 里已经把面板/棋盘/复盘键恢复到正常态，这里只需补提示条与状态
  if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.HINT_OPENING end
  log_info("进入对局：模式=双人同屏 档位=%d（%d+%d）",
    GAME.tcN, GAME.tcInitial, GAME.tcIncrement)
  return true
end

-- ② 复盘研习：进复盘的开局局面（allowEmpty = true，见 enter_review 的说明）
-- ===== v3.2 改写：没有对手时自动读「上一局存档」 =====
-- 用户要求：「没有另一位玩家联机时，单人复盘练习自动读取上一局对局的存档进行复盘」。
-- 【两种情形】
--   ① GAME.lastArchived 存在（本会话打过至少一局）→ 用它重建整条时间线，停在最后一步
--   ② 没有存档（刚进关卡、还没打完一局）→ 退回旧行为：进开局局面（只读回放）
-- 【为什么 ② 不能报错退出】玩家第一次进来就想看开局局面是合理需求；
--   给一句「还没有上一局」的提示并让他翻开局那一屏，比弹个错误框好得多。
local function entry_start_review()
  apply_time_control(GAME.tcN)
  GAME.localMode = true
  -- 【v3.0】复盘研习同样恒为「白棋在下」（无对手、无视角概念）
  GAME.match.set_flip(false)
  hide_all_overlays()
  hide_start_screen()
  hide_lobby()

  local arc = GAME.lastArchived
  if arc ~= nil and #(arc.history or {}) >= 1 then
    -- ===== 从存档重建 =====
    -- 【必须逐层重建，不能只塞 history】复盘依赖 st / 棋钟 / 失子数 / moveLog
    --   （见 review_goto 与 review_render）。少填一项就会出现「翻页后棋子不对」。
    GAME.over = false
    GAME.settled = false
    GAME.resultText = arc.resultText
    GAME.resultSub = arc.resultSub
    GAME.tcInitial = arc.clockW0 or GAME.tcInitial
    GAME.history = {}
    for i = 1, #arc.history do
      local s = arc.history[i]
      GAME.history[i] = {
        fen = s.fen, text = s.text, from = s.from, to = s.to,
        capW = s.capW, capB = s.capB,
        clockW = s.clockW, clockB = s.clockB,
      }
    end
    GAME.moveLog = {}
    for i = 1, #(arc.moveLog or {}) do GAME.moveLog[i] = arc.moveLog[i] end
    GAME.capturedWhite = {}
    GAME.capturedBlack = {}
    GAME.undoLeft[1] = CONFIG.UNDO_PER_SIDE
    GAME.undoLeft[2] = CONFIG.UNDO_PER_SIDE
    GAME.pendingUndo = nil
    GAME.pendingPromo = nil
    -- 末步快照作为当前局面
    local last = GAME.history[#GAME.history]
    local okp, st = pcall(RULES.parse_fen, last.fen)
    GAME.st = (okp and st ~= nil) and st or RULES.parse_fen(START_FEN)
    GAME.clockWhite = last.clockW or GAME.tcInitial
    GAME.clockBlack = last.clockB or GAME.tcInitial
    local ok = enter_review(true)
    if not ok then
      show_start_screen()
      return false
    end
    GAME.review.fromMenu = true
    -- 直接停在最后一步（用户要的是「看上一局」，不是从开局重放）
    if GAME.review ~= nil then
      GAME.review.idx = #GAME.history - 1
    end
    review_render()
    log_info("复盘研习：已载入上一局存档（%d 步）", #GAME.history - 1)
    return true
  end

  -- ===== 没有存档：退回「开局演练」 =====
  new_game()
  -- new_game 之后 history 只有开局快照；用 allowEmpty 放行，停在 idx=0
  local ok = enter_review(true)
  if not ok then
    -- 理论上不会失败（allowEmpty=true 时无空态拦截），兜底回主菜单免得卡死
    show_start_screen()
    return false
  end
  -- 【v2.0 修】标记「本次复盘是从初始界面的『复盘研习』进来的」，
  --   exit_review 据此决定退回初始界面而不是结算面板/棋盘。
  GAME.review.fromMenu = true
  log_info("进入复盘研习：还没有上一局存档，从开局演练")
  return true
end

-- ③ 联机（v3.0 改写：待机室已从运行时摘除）
-- -----------------------------------------------------------------------------
-- 【v2.0 的流程】重置房间状态 → 进待机室整层 → 双方各点准备 → 3 秒倒数 → 开局。
-- 【v3.0 的流程】初始界面上双方各选一个时间档 → 相同即自动开局；
--   不同则 5 秒改选窗口 → 仍不同就随机采用一个。**没有等待房间这一层**。
-- 所以本函数只剩「打一句日志 + 返回 true」的壳：真正的入口动作已改成
-- entryOnline 的 on-line 广播（见 register_all_input 里 online_announce 的调用）。
-- 保留函数名不删，是为了让旧文档/旧注释里的引用还有一个可读落点。
local function entry_start_online()
  GAME.match.announce()
  log_info("联机：入口已改为「选时间档即参战」，未进入待机室；档位=%d", GAME.tcN)
  return true
end

-- 返回主菜单：从对局/复盘/待机室回到初始界面。
-- 【必须停动画 + 停音效】否则回主菜单后上一局的走子补间还在跑，
-- 会把不可见的棋子槽位移来移去，下次开局时位置错乱（reset_piece_slots 会兜底，
-- 但停掉更干净，且 GAME_END 有 6 秒尾音）。
back_to_main_menu = function(skipConfirm)
  if not skipConfirm and GAME.screen == "playing" and not GAME.over then
    show_confirm("menu")
    return false
  end
  -- 【v2.0 块 5 补 EV_RESIGN 缺口】弃局必须广播，否则对端局面永远悬空
  -- （对端会一直停在「轮到你/轮到我」的活棋盘上，永远等不到这一局结束）。
  -- 触发条件：对局进行中且未结束，且是联机（localMode == false）时才发。
  --   同屏单人没有「对端」，发出去没人收，没必要。
  -- c=1 表示「弃局」（区别于 c=0 的「认输」）：
  --   对端收到 c=1 会显示「对手已离开本局 / 本局结束，不计胜负」，
  --   而不是「对方认输，你胜了」—— 那是两回事。
  if GAME.screen == "playing" and not GAME.over and not GAME.localMode then
    net_send_event(CONFIG.EV_RESIGN, (GAME.mySide == 1) and 0 or 1, 0, 1, "")
    log_info("弃局已广播：a=%d c=1", (GAME.mySide == 1) and 0 or 1)
  end
  anim_clear()
  sfx_stop_all()
  -- 退出复盘状态（若有）
  GAME.review = nil
  GAME.reviewState = nil
  if GAME.uiReady and UI.review ~= nil then
    show_review_buttons(false)
    UI.review.btnToggle.text = CONFIG.TEXT.BTN_REVIEW_HISTORY
  end
  hide_start_screen()
  -- 【v2.0 块 3 修：回主菜单也必须收起待机室层】
  -- 若从待机室点「返回主菜单」，没有这一行就会带着整个待机室层回初始界面，
  -- 形成「初始界面 + 待机室层」同时可见的幽灵层（与 entry_start_local 同一个坑）。
  hide_lobby()
  hide_result()
  hide_promo()
  hide_confirm()
  show_start_screen()
  return true
end

-- =============================================================================
-- 第 8 区：INPUT（输入）
--   原生命中方案：每格一个光标检测区，回调闭包捕获格号，不读坐标。
-- =============================================================================
local INPUT = { registered = {} }

-- 点击事件枚举：沙箱叫 Click，真机文档叫 CursorClick。两边兼容。
local function resolve_click_event()
  local ok, ev = pcall(function() return Enum.CursorEventType.CursorClick end)
  if ok and ev ~= nil then return ev end
  ok, ev = pcall(function() return Enum.CursorEventType.Click end)
  if ok and ev ~= nil then return ev end
  return nil
end

local CLICK_EVENT = nil

-- 【音效：面板按钮统一点击音】对应 Demo 的 `withClick` 包装（chess_demo.html 第 1416 行）：
--   `const withClick = (fn) => (e) => { e.stopPropagation(); SFX.play("click"); fn(); };`
-- 为什么做成包装而不是在 15 个回调里各写一行：漏一个就是「有一个按钮没声音」，
-- 而且以后加按钮还得记得加。包在 register_click 外面，新按钮自动带上。
-- 【棋盘格不放点击音】走子/选中各有专用音效（MOVE/CAPTURE/CHECK/SELECT），
-- 再叠一个 click 会变成「两声」，Demo 也是棋盘格不播 click。
local function with_click(fn)
  return function()
    sfx_play("click")
    return fn()
  end
end

local function register_click(ctrl, fn)
  if ctrl == nil or CLICK_EVENT == nil then return false end
  local ok = pcall(function()
    ctrl:AddCursorEventListener(CLICK_EVENT, function(data)
      local handled = fn()
      return handled ~= false
    end)
  end)
  if ok then
    INPUT.registered[#INPUT.registered + 1] = ctrl
    return true
  end
  return false
end

local function register_all_input()
  -- 64 个棋盘格
  for sq = 0, 63 do
    register_click(UI.hitAreas[sq], function() on_square_clicked(sq); return true end)
  end
  -- 侧面板按钮
  -- 新开一局：按 C-02 先确认「重开会清空这一局」
  register_click(UI.panel.hitNew, with_click(function()
    if GAME.over then new_game(); return true end
    show_confirm("newgame")
    return true
  end))
  -- 认输：按 C-01 先确认「认输就直接判负，确定吗」
  register_click(UI.panel.hitResign, with_click(function()
    if GAME.over then return true end
    show_confirm("resign")
    return true
  end))
  -- 求和：本地同屏直接按 C-04 询问对方；联机发 EV_DRAW_REQ
  register_click(UI.panel.hitDraw, with_click(function()
    if GAME.over then return true end
    local sideIdx = (GAME.st.turn == WHITE) and 1 or 2
    if GAME.drawCooldown[sideIdx] > 0 then
      if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.BTN_DRAW_USED end
      return true
    end
    GAME.drawCooldown[sideIdx] = CONFIG.DRAW_COOLDOWN_SEC
    if GAME.localMode then
      show_confirm("draw")
    else
      -- 发之前先置标记：服务端会把我这条请求广播回我自己，
      -- 收到回声时靠这个标记识别并丢弃（见第 9 区 EV_DRAW_REQ 的回声过滤）。
      GAME.drawReqSent = true
      if not net_send_event(CONFIG.EV_DRAW_REQ, sideIdx - 1, 0, 0, "") then
        GAME.drawReqSent = false      -- 发送失败就别留标记，否则会误吞下一条真实请求
      end
    end
    return true
  end))
  -- 【v3.2 删除】「切换本地同屏」按钮的点击处理。
  --   用户要求删按钮、删同屏模式，所以这条路径整个不存在了。
  --   【不要留空实现】留一个空 register_click 会在 UI.panel.hitLocal 为 nil 时崩，
  --   而且将来有人翻到这里会以为「切换功能还在，只是暂时没接」。
  -- 结算面板「再来一局」（v3.2 改写：联机需要双方都选）
  register_click(UI.result.hitAgain, with_click(function()
    result_make_choice("again")
    return true
  end))
  -- 结算面板「复盘」（v1.6 新增；v3.2 联机需双方都选）
  register_click(UI.result.hitReview, with_click(function()
    result_make_choice("review")
    return true
  end))
  -- 【v3.2】结算面板「退出」：回初始界面。
  -- 【要不要二次确认】不要 —— 此时对局已经结束，退出不会毁掉任何进行中的东西。
  register_click(UI.result.hitExit, with_click(function()
    if GAME.screen ~= "over" and not GAME.over then return true end
    result_leave_choice()
    back_to_main_menu(true)
    return true
  end))
  -- 面板第三行常驻键：对局中「看历史」/ 复盘中「退出复盘」（v1.6）
  register_click(UI.review.hitToggle, with_click(function()
    if GAME.review ~= nil then
      exit_review()
    else
      if GAME.pendingPromo then return true end
      enter_review()
    end
    return true
  end))
  -- 复盘四个翻页键（v1.6）
  register_click(UI.review.hitStart, with_click(function() review_goto(0, nil); return true end))
  register_click(UI.review.hitPrev,  function() review_goto(nil, -1); return true end)
  register_click(UI.review.hitNext,  function() review_goto(nil, 1); return true end)
  register_click(UI.review.hitEnd,   function() review_goto(#GAME.history - 1, nil); return true end)
  -- 升变四选一
  for i = 1, 4 do
    register_click(UI.promo.hits[i], with_click(function()
      if not GAME.pendingPromo then return true end
      local promoPieces = { QUEEN, ROOK, BISHOP, KNIGHT }
      local want = promoPieces[i]
      local chosen = nil
      for _, mv in ipairs(GAME.pendingPromo) do
        if mv.promo == want then chosen = mv; break end
      end
      GAME.pendingPromo = nil
      hide_promo()
      if chosen then
        for sq = 0, 63 do
          if UI.hitAreas[sq] then ui_set_active(UI.hitAreas[sq], true) end
        end
        -- 音效：升变确认的琶音（对应 Demo 第 2041 行 SFX.play("promote")，
        -- 时机是「选完棋子、真正 applyMove 之前」，与这里一致）
        sfx_play("promote")
        apply_move(chosen)
        net_send_move(chosen)
      end
      return true
    end))
  end
  -- v2.0「返回主菜单」：对局中需二次确认（会放弃这一局），其余界面直接回
  register_click(UI.panel.hitV2BackMain, with_click(function()
    if GAME.screen == "start" then return true end
    back_to_main_menu(false)
    return true
  end))
  -- ===== 悔棋（v2.0 块 3）=====
  -- 【点击后永远先 undo_check()】六条不满足 → 只弹一句提示，什么都不改（gdd §7.2）。
  -- 【为什么次数为 0 也保留命中区】gdd §7.3 明确：SetActive(false) 会让玩家以为按钮消失，
  --   弹一句「悔棋次数用完了」才是可理解的反馈。
  register_click(UI.panel.hitV2Undo, with_click(function()
    if GAME.screen ~= "playing" then return true end
    if GAME.pendingUndo ~= nil then
      if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.UNDO_PENDING end
      return true
    end
    local ok, why = undo_check()
    if not ok then
      if why ~= nil and UI.panel.hint then UI.panel.hint.text = why end
      return true
    end
    -- 条件满足 → 弹确认框（同屏与联机都要确认：悔棋不可逆，次数扣了不返还）
    show_confirm("undo")
    return true
  end))
  -- 音效开关（v1.10）
  -- 【不带 with_click】这个按钮自己就是「音效总开关」：
  --   关的时候播 click 会让人以为没关掉；开的时候 sfx_toggle 内部已经播了一声确认音。
  register_click(UI.panel.hitSfx, function()
    sfx_toggle()
    sync_sfx_button()
    return true
  end)
  -- 确认弹窗：确定
  register_click(UI.confirm.hitYes, with_click(function()
    local kind = GAME.confirmKind
    hide_confirm()
    if kind == "resign" then
      if GAME.over then return true end
      GAME.over = true
      -- 【认输方判定必须看「谁点的按钮」，不能看「轮到谁」】
      -- 同屏模式下点按钮的人与当前轮次一致，两者等价；
      -- 联机模式下我可以在对方回合点认输（例如思考时直接投降），
      -- 此时 st.turn 是对方，用它会把自己认输写成对方认输（模拟器实测踩到：
      -- 黑方回合白方点认输，结算显示「黑方点了认输」）。
      -- 因此：联机模式用 GAME.mySide，同屏模式用当前轮次。
      local resignSide
      if GAME.localMode then
        resignSide = (GAME.st.turn == WHITE) and 1 or 2
      else
        resignSide = GAME.mySide
      end
      if resignSide == 1 then
        GAME.resultText = CONFIG.TEXT.RESULT_RESIGN_WHITE
        GAME.resultSub = CONFIG.TEXT.SUB_RESIGN_WHITE
        net_send_event(CONFIG.EV_RESIGN, 0, 0, 0, "")
      else
        GAME.resultText = CONFIG.TEXT.RESULT_RESIGN_BLACK
        GAME.resultSub = CONFIG.TEXT.SUB_RESIGN_BLACK
        net_send_event(CONFIG.EV_RESIGN, 1, 0, 0, "")
      end
      -- 音效：认输按下瞬间的「错误/否定」提示（对应 Demo 的 doResign 语义）。
      -- 先播 RESIGN 再 show_result（后者会播 GAME_END），两声叠起来是「确认+收尾」。
      sfx_play("resign")
      show_result()
    elseif kind == "newgame" then
      new_game()
    -- 【v3.2 删除】kind == "switch"（切换本地同屏/联机）分支。
    --   模式已不可切换（见 BUG 说明：面板按钮与初始界面入口都已删除）。
    --   CONFIRM_SWITCH 文案与 confirm_kind_spec.switch 条目保留在 CONFIG 里，
    --   因为 consistency_check 会比对两侧文案键集合；但运行时不会再弹这个框。
    elseif kind == "draw" then
      GAME.over = true
      -- 【v2.0 补：同屏/联机文案分流】同屏没有「对方」，不能用「对方同意和棋」
      GAME.resultText = draw_result_text()
      GAME.resultSub = CONFIG.TEXT.SUB_DRAW_AGREED
      show_result()
      -- 【v2.0 补：双人同屏不发网络包】见 net_send_event 顶部的 localMode 闸，
      -- 这里保留调用是为了让「同屏也走同一条代码路径」，闸负责实际拦截。
      net_send_event(CONFIG.EV_DRAW_ACC, 0, 0, 0, "")
    elseif kind == "menu" then
      -- v2.0：确认放弃当前对局回主菜单。skipConfirm=true 避免再次弹框。
      back_to_main_menu(true)
    elseif kind == "undo" then
      -- v2.0 块 3：确认悔棋
      -- 【同屏】立即成对撤回 + 扣次数（同一个人操作两色，没有「对方」实体）
      -- 【联机】只发请求，**绝不本地先撤** —— 否则对方拒绝时会出现只有一方撤回的分叉
      --        （gdd §7.5 明确：执行时机必须两端一致，都以 EV_UNDO_ACC 为准）
      if GAME.localMode then
        if undo_apply_pair() then
          undo_consume()
          if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.UNDO_DONE end
          refresh_undo_button()
        end
      else
        GAME.pendingUndo = { byMe = true, t = 0 }
        if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.UNDO_WAIT end
        -- 块 5：广播悔棋请求（a = 我的身份）
        -- 【关键纪律】**绝不本地先撤** —— 执行时机统一由 EV_UNDO_ACC 决定。
        --   若本地先撤，对方拒绝时会出现「一端撤了、一端没撤」的局面分叉，
        --   比日志污染严重得多（gdd §7.5 末条明确要求）。
        net_send_event(CONFIG.EV_UNDO_REQ, (GAME.mySide == 1) and 0 or 1, 0, 0, "")
        refresh_undo_button()
      end
    elseif kind == "undoPeer" then
      -- v2.0 块 3/5：我作为响应方同意 → **先广播 ACC，再本地执行**
      -- 【顺序为什么重要】ACC 是两端共同的执行触发点。先发再执行，
      -- 能保证发起方收到 ACC 时我这边也已开始执行，不会出现长期分叉。
      -- 【次数】响应方**不扣**（gdd §7.2 C-5：只有发起方 -1），所以这里不调 undo_consume。
      --   （块 3 里这里错调了 undo_consume，块 5 一并订正 —— 响应方不该消耗次数。）
      GAME.pendingUndo = nil
      net_send_event(CONFIG.EV_UNDO_ACC, (GAME.mySide == 1) and 0 or 1, 0, 0, "")
      if undo_apply_pair() then
        if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.UNDO_DONE end
      end
      refresh_undo_button()
    end
    return true
  end))
  -- ===== 初始界面（v2.0）=====
  -- 4 张档位卡：点一下就选中（不自动开局 —— 玩家可能想换档再进）
  -- 【为什么不用 with_click 之外的额外音效】with_click 播 CLICK 就够；
  -- 档位卡本质是「单选」，与面板按钮同类。
  for i = 1, #UI.startScreen.cards do
    local card = UI.startScreen.cards[i]
    register_click(card.hit, with_click(function()
      -- 只有停在初始界面时档位卡才可点（其余界面本层已隐藏，这是第二道保险）
      if GAME.screen ~= "start" then return true end
      -- 【v3.0】选时间档 = 联机参战动作：本端选好会立即广播给对手，
      -- 对方也选好后两端自动开局（不再有待机室、不再点准备）。
      GAME.match.on_pick(card.n)
      return true
    end))
  end
  -- 两个入口（v3.2：删掉「单人·双人同屏」）
  register_click(UI.startScreen.entryReview.hit, with_click(function()
    if GAME.screen ~= "start" then return true end
    -- 【v3.2 用户要求】有对手联机时关闭「单人复盘练习」。
    --   点到了也要拒绝（命中区可能还没来得及隐藏），并给一句原因 ——
    --   静默无反应会被当成按钮坏了。
    if net_peer_online() then
      if UI.startScreen.tcHint ~= nil then
        UI.startScreen.tcHint.text = CONFIG.TEXT.ENTRY_REVIEW_LOCKED
      end
      return true
    end
    entry_start_review()
    return true
  end))
  register_click(UI.startScreen.entryOnline.hit, with_click(function()
    if GAME.screen ~= "start" then return true end
    -- 【v3.0】不再进入待机室：只把当前时间档再广播一次（偶发丢包时的手动重试）
    GAME.match.announce()
    return true
  end))
  -- 确认弹窗：取消
  register_click(UI.confirm.hitNo, with_click(function()
    local kind = GAME.confirmKind
    hide_confirm()
    if kind == "draw" then
      if UI.panel.hint then UI.panel.hint.text = "对方拒绝和棋，继续对局" end
      net_send_event(CONFIG.EV_DRAW_NO, 0, 0, 0, "")
    elseif kind == "undoPeer" then
      -- v2.0 块 3：我拒绝对方的悔棋请求
      -- 块 5：这里发 EV_UNDO_NO
      if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.UNDO_REJECTED end
      GAME.pendingUndo = nil
      refresh_undo_button()
    end
    return true
  end))
  -- ===== 待机室（v2.0 块 2）=====
  -- 「准备 / 取消准备」：翻转本地就绪 + 广播 EV_READY（块 5 接信号实际下发）。
  -- 【倒数中取消必须立即中止倒数并回未就绪】Lead 明确要求（手滑点准备要有救）。
  register_click(UI.lobby.btnReady.hit, with_click(function()
    if GAME.screen ~= "lobby" then return true end
    local G = GAME.lobby
    G.myReady = not G.myReady
    if not G.myReady then
      -- 取消准备：无论是否在倒数，都立即清掉倒计时
      G.countdown = -1
      G.countdownShown = -1
      G.awaitStart = false
      G.awaitStartAt = 0
    end
    -- 块 5：广播准备状态 + 我选定的档位号（b = 档位号 → 「先选者生效」的载体）
    -- a = 1 准备 / 0 取消准备
    -- 【方案 T】fen 带上本端 token，用于识别并丢弃自己的回声
    -- （服务端会把包广播回发送者，而 API 不提供发送者身份）
    local tok = make_self_token()
    GAME.__myReadyToken = tok
    net_send_event(CONFIG.EV_READY, G.myReady and 1 or 0, GAME.tcN, 0, tok)
    refresh_lobby()
    return true
  end))
  -- 「直接开始」：单人兜底。按当前档位直接同屏开局，绝不让人卡死在等待。
  register_click(UI.lobby.btnSolo.hit, with_click(function()
    if GAME.screen ~= "lobby" then return true end
    local G = GAME.lobby
    -- 倒数中禁止（避免双开局，gdd §5.6）
    if G.countdown >= 0 then return true end
    G.countdown = -1
    G.countdownShown = -1
    G.myReady = false
    G.peerReady = false
    G.peerSeen = false
    G.peerLeft = false
    hide_lobby()
    apply_time_control(GAME.tcN)
    GAME.localMode = true          -- 单机兜底：同屏轮流
    new_game()
    GAME.screen = "playing"
    if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.HINT_OPENING end
    -- 块 5：告诉对端「我按这个档位开局了」。
    -- 【为什么单人兜底也要发】如果房间里其实有对手（只是没握手成功），
    -- 这一包能让对方也进对局，而不是一直停在待机室干等。
    net_send_event(CONFIG.EV_START, 0, GAME.tcN, 0, "")
    log_info("待机室直接开始（单人兜底）：档位=%d（%d+%d）",
      GAME.tcN, GAME.tcInitial, GAME.tcIncrement)
    return true
  end))
  -- 「返回主菜单」：待机室没有对局可丢，不弹确认（gdd §5.8）
  register_click(UI.lobby.hitBackMain, with_click(function()
    if GAME.screen ~= "lobby" then return true end
    local G = GAME.lobby
    G.myReady = false
    G.countdown = -1
    G.countdownShown = -1
    -- 块 5：这里会 broadcast_ready() 让对手知道我已离开
    hide_lobby()
    show_start_screen()
    return true
  end))
  -- ===== 复盘动作条（v2.0 块 4）=====
end

-- =============================================================================
-- 第 9 区：NET（联机，能力探测 + 降级）
--   客户端发出 ChessSync；服务端节点图「收到即广播」由用户在编辑器里搭。
--   沙箱里 ServerSignal 没有 AddInt 方法，所以这里必须能力探测，不能直接调用。
-- =============================================================================
local NET = { canSend = false, canReceive = false, probed = false, lastSeq = -1 }

local function net_probe()
  NET.probed = true
  -- 探测发送能力
  local ok = pcall(function()
    local sig = game.ServerSignal(CONFIG.SIGNAL_NAME)
    if sig ~= nil and sig.AddInt ~= nil and sig.AddString ~= nil and sig.SendSignal ~= nil then
      NET.canSend = true
    end
  end)
  -- 探测接收能力
  pcall(function()
    if script ~= nil and script.RegisterServerSignalHandler ~= nil then
      NET.canReceive = true
    end
  end)
  log_info("联机能力探测：发送=%s 接收=%s", tostring(NET.canSend), tostring(NET.canReceive))
end

-- =============================================================================
-- 自发包识别 token（v2.0 方案 T）
-- -----------------------------------------------------------------------------
-- 【背景】服务端把信号广播给房间内**所有人，包括发送者自己**，
--   而官方客户端 API **不提供发送者身份**（无法知道「谁发的」）。
--   所以所有「收到某包就认为对方做了某事」的逻辑都会被自己的回声污染。
--
-- 【关键洞察】不需要知道「谁发的」，只需要知道「**这是不是我发的**」。
--   发送时生成一个只在本端存在的 token，写进信号的 fen 参数（此前完全未用），
--   收到时先比对 —— 等于自己的就是回声，直接丢弃。
--
-- 【时序细节：为什么用 os.clock 而不是 os.time】
--   os.time() 是**秒级整数**。两端若在同一秒内启动，token 必然相同 → 双双把对方
--   包当成自己的回声 → peerReady 永远 false → 退化成单人（有兜底，不会坏，但功能丢失）。
--   os.clock() 是**CPU 累计秒数（浮点，微秒级）**，两端启动时刻不同 → 几乎不可能相同。
--
-- 【失败模式分析（这是本设计最重要的性质）】
--   万一 token 真的撞车：
--     两端互相当作自己的回声 → peerReady 都不置位
--     → 不会「双方就绪」→ 走 15 秒兜底 → 单人模式
--     → 玩家看到「没等到另一位玩家，也可以直接开始」
--   **绝不会误开局。** 这是一个「错了也只是退化，不会坏」的设计。
--   对比：如果用「收到 a=1 就当对方 ready」这种写法，错了会**误开局**（已实测踩过）。
-- =============================================================================
make_self_token = function()
  GAME.__tokenSeq = (GAME.__tokenSeq or 0) + 1
  -- 【v2.0 排查：改回纯序号版，去掉 os.clock】
  -- 【为什么去掉 os.clock】上一版加了 `local ok, clock = pcall(function() return os.clock() end)`
  -- 之后模拟器启动连续两次 `play worker timed out after 8000ms`（根本不返回）。
  -- os.clock 是本项目**从未用过**的 API：文档说在允许列表里，但「允许 ≠ 沙箱实现一定有」。
  -- 更关键的是 **pcall 抓不住「挂住」**——如果沙箱里的 os.clock 是个会阻塞的包装对象，
  -- pcall 只会一直等着，导致整个 OnStart 卡死。
  -- 【纯序号版为什么可接受】两端序号都从 T1 开始 → 会撞车。
  --   但按方案 T 的失败模式分析：撞车 → 互相当作自己的回声 → peerReady 都不置位
  --   → 不会「双方就绪」→ 走 15 秒兜底 → 单人模式 → **绝不会误开局**。
  --   代价是联机时「双方准备」退化成「各自点准备 + 15 秒后手动开始」。
  --   这是安全的降级，不是坏掉。
  -- 【将来若能真机验证 os.clock 可用】可以在这里加回时钟成分提高跨端唯一性。
  return "T" .. tostring(GAME.__tokenSeq)
end

function net_send_event(eventType, a, b, c, fen)
  -- ===== 自检期间禁止一切网络发送（v2.0 块 5 修 P0）=====
  -- 【为什么必须有这一行】SelfTest 在每次 OnStart 都跑，而有些断言需要「试着发一个包」
  -- 来验证降级路径不崩。不拦截的话，真机上这些包会**真的广播给所有玩家**。
  -- 实测证据（Lead，playerCount=2）：一次 start 就冒出 4 条自检产生的包
  --   EV_READY×2 + EV_START×2，两端各两条。
  -- 后果推演：只要有一端时序稍慢，另一方可能在还没进待机室时就收到 EV_START
  --   → **游戏在对局开始前就被「开局」了**。这比少一个功能严重得多。
  -- 【纪律】自检必须零副作用：不发包、不改玩家可见状态、不启动对局。
  --   凡要验证「某函数会做什么」的断言，都应该验它的返回值/内部标记，
  --   而不是**真的执行它**。自检是每次启动都跑的，污染的是玩家的真实对局。
  if GAME.inSelfTest then return false end
  -- ===== 双人同屏模式不发任何网络包（v2.0 补）=====
  -- 【为什么必须有这一道】双人同屏是「同一台设备、同一个玩家轮流操作双方」，
  --   根本不需要任何网络通信。但实测（Lead，双人同屏点「求和→同意」）发出了
  --   `ChessSync [4, 0, 0, 0, ""]` 这个 EV_DRAW_ACC 包。
  -- 【三个害处】
  --   ① 浪费带宽（真机上每步都发 EV_MOVE）
  --   ② **如果玩家单机时恰好也在一个多人房间里，会把「和棋」「认输」广播出去干扰别人**
  --   ③ 违反「同屏模式 = 纯本地」的语义
  -- 【为什么放在 net_send_event 这一层而不是各个调用点】
  --   放这里一次性覆盖全部 13 个事件（EV_MOVE / EV_DRAW_ACC / EV_RESIGN / EV_UNDO_* 等），
  --   不需要每个调用点各自判断 —— 「各自记得」正是本项目多次 bug 的成因。
  -- 【localMode 语义确认】它在四处被置 true：
  --   entry_start_local（单人·双人同屏）/ entry_start_review（复盘研习）/
  --   btnSolo 兜底 / 面板「切换本地同屏」；entry_start_online 置 false。
  --   默认初始值 false（行 2514），所以联机路径不受影响。
  if GAME.localMode then return false end
  if not NET.canSend then return false end
  local ok = pcall(function()
    local sig = game.ServerSignal(CONFIG.SIGNAL_NAME)
    sig:AddInt(eventType)
    sig:AddInt(a or 0)
    sig:AddInt(b or 0)
    sig:AddInt(c or 0)
    sig:AddString(fen or "")
    sig:SendSignal()
  end)
  if not ok then
    NET.canSend = false
    log_err("信号发送失败，联机降级为同屏")
  end
  return ok
end

function net_send_move(mv)
  if not NET.canSend then return end
  local promoCode = 0
  if mv.promo == QUEEN then promoCode = 1
  elseif mv.promo == ROOK then promoCode = 2
  elseif mv.promo == BISHOP then promoCode = 3
  elseif mv.promo == KNIGHT then promoCode = 4 end
  -- 记下这一手，用于丢弃服务端广播回来的自己这条（见 net_on_signal 的 EV_MOVE 分支）。
  GAME.lastSentMove = { from = mv.from, to = mv.to, promo = promoCode }
  net_send_event(CONFIG.EV_MOVE, mv.from, mv.to, promoCode, "")
end

-- 收到信号：处理走子/新局/认输/求和/身份
local function net_on_signal(signalName, params)
  if GAME.state ~= "RUNNING" then return end
  if type(params) ~= "table" then return end
  local eventType = params[1]
  local a = params[2] or 0
  local b = params[3] or 0
  local c = params[4] or 0
  -- 【v2.0 方案 T 关键修复：必须取第 5 个参数 fen】
  -- 【这是一个真实的 bug，不是断言写错】原来这里只取了 params[1..4]，
  --   而 EV_READY / EV_START 的回声过滤写的是 `fen == GAME.__myReadyToken`。
  --   由于 fen 从未被赋值，它在函数体里是 **全局 nil** →
  --     isEcho = (token ~= nil) and (nil ~= nil) and ... = **恒 false**
  --   → `if isEcho then return end` 永不成立 → **回声从来没被过滤过**。
  --   表现：收到自己的 EV_READY 包 → peerReady = true → 假的「双方就绪」→ 误开局。
  -- 【为什么断言抓到了而人看不出来】代码读起来完全合理（变量名 fen 存在、比较也写了），
  --   但 Lua 不会对「读了未定义的全局」报错，只是静默给 nil。
  --   lua_check 的「可疑全局赋值」只查**赋值**，查不到**读取**未定义全局。
  --   只有真正跑一遍断言才能发现（这正是 Lead 坚持要 SelfTest 真跑的价值）。
  -- 【服务端信号固定 5 槽】ChessSync(eventType, a, b, c, fen) → params[1..5]
  local fen = params[5]
  if type(fen) ~= "string" then fen = nil end
  if type(eventType) ~= "number" then return end

  if eventType == CONFIG.EV_MOVE then
    -- 【回声过滤，必须先做】服务端节点图把我自己的走子也广播回给我。
    -- 我本地已经 apply_move 过了，再按「对方走子」重新验证必然失败
    -- （该起点格已空 → 找不到合法走法 → 误报 log_err「收到无法验证的走子信号」）。
    -- 用 lastSentMove 精确匹配（起点+终点+升变三项），匹配上就只清标记、不处理。
    local last = GAME.lastSentMove
    if last ~= nil and last.from == a and last.to == b and last.promo == c then
      GAME.lastSentMove = nil           -- 自己的回声，丢弃
    else
      -- 对方走了一步：本地重算并校验
      local promoPieces = { [0] = nil, [1] = QUEEN, [2] = ROOK, [3] = BISHOP, [4] = KNIGHT }
      local wantPromo = promoPieces[c]
      local candidates = {}
      for _, mv in ipairs(RULES.legal_moves(GAME.st)) do
        if mv.from == a and mv.to == b then
          if (wantPromo == nil and mv.promo == nil) or (wantPromo ~= nil and mv.promo == wantPromo) then
            candidates[#candidates + 1] = mv
          end
        end
      end
      if #candidates > 0 then
        apply_move(candidates[1])
      else
        log_err("收到无法验证的走子信号：%d→%d", a, b)
      end
    end

  elseif eventType == CONFIG.EV_NEWGAME then
    new_game()

  elseif eventType == CONFIG.EV_RESIGN then
    -- 【回声过滤】用 GAME.over 挡住重复（自己也收到广播 → 已结束就忽略）。
    if GAME.over then return end
    GAME.over = true
    if c == 1 then
      -- c=1 弃局：对手点了「返回主菜单 → 确定放弃」。
      -- 【文案必须与认输区分】认输是「我下不过你」，弃局是「我走了，这局不算数」。
      -- 若显示「对方认输，你胜了」，会让玩家误以为赢了一盘真棋。
      GAME.resultText = CONFIG.TEXT.RESULT_OPP_LEFT
      GAME.resultSub = CONFIG.TEXT.SUB_OPP_LEFT
    else
      -- c=0 认输：a=认输方（0=白 1=黑）
      if a == 0 then
        GAME.resultText = CONFIG.TEXT.RESULT_RESIGN_WHITE
        GAME.resultSub = CONFIG.TEXT.SUB_RESIGN_WHITE
      else
        GAME.resultText = CONFIG.TEXT.RESULT_RESIGN_BLACK
        GAME.resultSub = CONFIG.TEXT.SUB_RESIGN_BLACK
      end
    end
    show_result()

  elseif eventType == CONFIG.EV_DRAW_REQ then
    -- 【必须传 kind】原先这里是不带参数的 show_confirm()，kind=nil 会走
    -- CONFIRM_SPEC.newgame 兜底 → 对方收到求和时弹出的是「重开会清空这一局」，
    -- 按钮文案也是「确定/取消」，不是「同意和棋/拒绝求和」（模拟器实测踩到）。
    --
    -- 【回声过滤】服务端节点图是「收到即广播给房间内所有人」，**包括发送者自己**。
    -- 不加过滤的话，发起求和的人会收到自己的请求并弹出「对方想和棋，同意吗」，
    -- 结果是发起者自己问自己（模拟器实测：Player1 点求和后自己弹出了同意框）。
    -- 用「我是否刚发出求和」这个标记吃掉回声：是回声就只清标记，不弹框。
    if GAME.drawReqSent then
      GAME.drawReqSent = false          -- 自己的回声，丢弃
    else
      show_confirm("draw")
    end

  elseif eventType == CONFIG.EV_DRAW_ACC then
    -- 同样有回声：同意方自己也会收到这条广播，而它已经本地结算过了。
    -- 用 GAME.over 挡住重复结算，避免结算面板被重入。
    if not GAME.over then
      GAME.over = true
      GAME.resultText = draw_result_text()
      GAME.resultSub = CONFIG.TEXT.SUB_DRAW_AGREED
      show_result()
    end

  elseif eventType == CONFIG.EV_DRAW_NO then
    if UI.panel.hint then UI.panel.hint.text = "对方拒绝和棋，继续对局" end

  elseif eventType == CONFIG.EV_ROLE then
    GAME.mySide = (a == 0) and 1 or 2
    if UI.panel.hint then
      UI.panel.hint.text = (GAME.mySide == 1) and "你是白方" or "你是黑方"
    end

  -- ===== v3.0：初始界面「选时间档」协商 =====
  -- 【分流原因】旧待机室路径已从运行时摘除（入口不再进待机室），但自检 12-l/12-p 仍按
  --   screen="lobby" 验证旧语义（先选者锁定 / 回声过滤）。保留它，不制造假红。
  elseif eventType == CONFIG.EV_READY then
    if GAME.screen ~= "lobby" then
      GAME.match.on_peer_pick(a, b, c, fen)
      return
    end
    -- ===== 回声过滤：方案 T（token 自识别）=====
    -- 【这一段是本项目最需要解释的几行，务必读完再改】
    -- 背景：服务端「收到即广播给所有人，包括发送者自己」。
    --   而官方客户端 API **不提供发送者身份**（已查《客户端控件API文档》全文，
    --   playerIndex / GetPlayerIndex / selfPlayer 等全部不存在；
    --   RegisterServerSignalHandler 回调只给 signalName + 参数数组）。
    --   所以无法靠「谁发的」区分回声。
    --
    -- 关键洞察：**不需要知道「谁发的」，只需要知道「这是不是我发的」。**
    --   发送时把本端专属 token 写进 fen；收到时比对，相同就是自己的回声。
    --
    -- 【为什么 token 放 fen】该参数此前完全未使用，不占用 a/b/c 三个有语义的槽位。
    --
    -- 【失败模式】万一两端 token 撞车（os.clock 相同）：
    --   互相当作自己的回声 → peerReady 都不置位 → 走 15 秒兜底 → 单人模式
    --   → 玩家看到「没等到另一位玩家，也可以直接开始」→ **不会误开局**。
    --   这是个「错了也只是退化，不会坏」的设计。
    --
    -- 【曾经踩过的坑（块 5 第一版）】原来这里写着「本条是幂等的，不需要回声过滤」，
    --   直接 `G.peerReady = (a == 1)`。结果：玩家2 点准备 → 自己的包被播回来
    --   → peerReady = true → 与本端 myReady 一起构成假的「双方就绪」
    --   → 玩家1 完全没点准备却被拉进对局（实测 playerCount=2 复现）。
    --   那句「幂等」注释是错的：peerReady 的语义是「**对方**准备好了」，
    --   而回声把它污染成了「**有人**准备好了」。
    local G = GAME.lobby
    local isEcho = (GAME.__myReadyToken ~= nil and fen ~= nil
                    and fen == GAME.__myReadyToken)
    if isEcho then
      -- 自己的回声：只清标记，不改任何状态
      GAME.__myReadyToken = nil
      return
    end
    -- b 带档位号，是「先选者生效」的载体。
    -- 只有本地**未锁定**时才采用对方档位；已锁定则忽略（先选者优先）。
    if not G.tcLocked then
      local n = tonumber(b) or 0
      if n >= 1 and n <= #CONFIG.TIME_CONTROLS then
        apply_time_control(n)
        G.tcLocked = true
        G.tcOwner = 2                      -- 2 = 对方选的
        refresh_lobby()
      end
    end
    -- 到这里可以确定：这是**对方**发的包（不是自己的回声）
    G.peerReady = (a == 1)
    if not G.peerLeft then G.peerSeen = true end
    G.peerSeenAt = 0                        -- 收到对手任何包 → 重置超时计时
    G.timeoutShownOnce = false
    if GAME.screen == "lobby" then refresh_lobby() end

  elseif eventType == CONFIG.EV_START then
    -- 【v3.0】新联机路径：收到对方「我已开局」→ 若还在初始界面就跟上，
    -- 并采用对方宣告的相反颜色（a=对方颜色，b=档位，fen=对方标识）。
    if GAME.screen ~= "lobby" then
      GAME.match.on_peer_start(a, b, fen)
      return
    end
    -- 【回声过滤：方案 T 同款】自己的 EV_START 播回来要靠 token 认出来
    if GAME.__myStartToken ~= nil and fen ~= nil and fen == GAME.__myStartToken then
      GAME.__myStartToken = nil
      return
    end
    -- 【第二道判据】已经在 playing 就忽略（幂等），挡住重复包
    if GAME.screen == "playing" then return end
    -- 收到即进 playing，跳过本地倒数
    -- 【v2.0 方案 T 后的语义变更】EV_START 现在的作用是「**通知对端可以开局了**」，
    -- 而不是「开局的前置条件」—— 发起方自己会先无条件进 playing 再发这个包。
    -- 所以这里收到就意味着对端已经开局，本端跟上。
    local n = tonumber(b) or 0
    if n >= 1 and n <= #CONFIG.TIME_CONTROLS then apply_time_control(n) end
    local G = GAME.lobby
    G.awaitStart = false
    G.awaitStartAt = 0
    G.countdown = -1
    G.countdownShown = -1
    -- 【BUG-3 修】收到对方的 EV_START 而开局 → **不再广播**
    start_game_from_lobby(false)
    if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.HINT_OPENING end

  elseif eventType == CONFIG.EV_UNDO_REQ then
    -- 【回声过滤】靠 pendingUndo.byMe：我是发起方时收到自己的包，直接丢。
    if GAME.pendingUndo ~= nil and GAME.pendingUndo.byMe then
      return                                -- 自己的回声
    end
    -- 我是响应方 → 弹「对方请求悔棋，同意吗」
    if GAME.screen == "playing" and not GAME.over then
      GAME.pendingUndo = { byMe = false, t = 0 }
      refresh_undo_button()
      show_confirm("undoPeer")
    end

  elseif eventType == CONFIG.EV_UNDO_ACC then
    -- 【这是唯一的执行时机】无论发起方还是响应方，都在收到/发出 ACC 的这一帧执行。
    -- 【回声过滤】服务端把 ACC 也广播回同意方自己 → 它已经本地执行过了。
    --   判据：pendingUndo 已被清空（执行时清的）→ 说明是我自己发的回声，丢掉。
    if GAME.pendingUndo == nil then return end
    -- 两端各自执行一次成对撤回
    if undo_apply_pair() then
      -- 只有**发起方**扣次数（gdd §7.2 C-5：发起方悔棋计数 -1，对方不变）
      if GAME.pendingUndo.byMe then undo_consume() end
      GAME.pendingUndo = nil
      if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.UNDO_DONE end
      refresh_undo_button()
    else
      GAME.pendingUndo = nil
      refresh_undo_button()
    end

  elseif eventType == CONFIG.EV_UNDO_NO then
    -- 【回声过滤】只有「我发起的请求」才该被这条拒绝信号影响；响应方收到自己发的 NO 要丢掉。
    if GAME.pendingUndo == nil then return end
    if not GAME.pendingUndo.byMe then return end     -- 不是我发起的，忽略
    GAME.pendingUndo = nil                            -- 解冻
    -- 次数不扣（未发生撤回）
    if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.UNDO_REJECTED end
    refresh_undo_button()

  elseif eventType == CONFIG.EV_RESULT then
    -- 【v3.2】结算后的协同选择（再来一局 / 复盘）
    --
    -- 【回声过滤：必须用 token，不能用身份】服务端「收到即广播给所有人，包括发送者自己」，
    --   且官方 API 不提供发送者身份（见上面 EV_READY 那段完整论证）。
    --   【我第一版写错了】原打算「包里的身份 b 与我的身份相同 = 我的回声」——
    --   这是**错的**：换色之后两端身份正好互换，判据会把对方的包误吞成自己的回声，
    --   表现是「双方都点了，但永远等不到对方」。所以必须沿用 EV_READY 的 token 方案。
    --
    -- 【token 放哪】a=选择、b=身份，c 未使用 → token 放 c（整数，够大不撞车）。
    local isEcho = (GAME.__resultToken ~= nil and c ~= nil
                    and tonumber(c) == GAME.__resultToken)
    if isEcho then
      -- 【清掉 token】不清的话，残留值会一直挂着；虽然新 token 每次重新生成，
      -- 无限期保留一个已知值没有意义，也会让后续排查「这个 token 是哪次的」变难。
      -- （对比 EV_READY 的回声分支同样会置 nil —— 保持一致。）
      GAME.__resultToken = nil
      return
    end
    local choice = (tonumber(a) == 1) and "again" or ((tonumber(a) == 2) and "review" or nil)
    if choice == nil then return end
    result_on_peer_choice(choice)
  end
end

local function net_register_receive()
  if not NET.canReceive then return false end
  local ok = pcall(function()
    script:RegisterServerSignalHandler(CONFIG.SIGNAL_NAME, function(signalName, params)
      net_on_signal(signalName, params)
    end)
  end)
  if ok then
    log_info("已注册联机信号接收：%s", CONFIG.SIGNAL_NAME)
    return true
  end
  return false
end

-- =============================================================================
-- 第 10 区：LIFECYCLE（生命周期与清理）
-- =============================================================================

-- 校验配置：三项模板索引必须非 0
local function validate_config()
  local missing = {}
  if CONFIG.CONTAINER_NODE_INDEX == 0 then missing[#missing + 1] = "CONTAINER_NODE_INDEX" end
  if CONFIG.PREFAB_TEXT_BOX == 0 then missing[#missing + 1] = "PREFAB_TEXT_BOX" end
  if CONFIG.PREFAB_CURSOR_AREA == 0 then missing[#missing + 1] = "PREFAB_CURSOR_AREA" end
  -- PREFAB_IMAGE 是必填：棋子只有「图元拼」这一档，全靠图片控件实现。
  -- 缺它棋盘上不会出现任何棋子，属于致命配置错误，必须在启动时就拒绝并报清楚。
  if CONFIG.PREFAB_IMAGE == 0 then
    missing[#missing + 1] = "PREFAB_IMAGE（棋子用图元绘制，必须建「图片」控件模板）"
  end
  if #missing > 0 then
    return false, table.concat(missing, ", ")
  end
  return true, nil
end

-- 检查画布尺寸是否有效（有限正数）
local function read_canvas()
  local ok, w, h = pcall(function() return game.GetUICanvasSize() end)
  if not ok then return nil, nil, "GetUICanvasSize 调用失败" end
  if type(w) ~= "number" or type(h) ~= "number" then return nil, nil, "返回值不是数字" end
  if w ~= w or h ~= h then return nil, nil, "返回 NaN" end
  if w <= 0 or h <= 0 then return nil, nil, "返回非正数" end
  if math.isinf(w) or math.isinf(h) then return nil, nil, "返回无穷" end
  return w, h, nil
end

-- 获取挂载容器
local function read_container()
  -- 【为什么用 script.object】
  -- 官方编辑器指南与 API 文档示例都用 script.object 作为挂载容器：
  -- 脚本挂在「容器节点」上，script.object 就是那个容器节点。
  -- game.GetClientUIControl(controlId) 的参数是**运行时 ID**（文档 §6(1) L189），
  -- 不是用户填的**模板索引**，两者不是一回事，不能拿来取容器。
  -- 因此：优先 script.object；它为 nil 时再用 GetClientUIControl 兜底（兼容旧写法）。
  local ok, host = pcall(function() return script.object end)
  if ok and host ~= nil then
    return host
  end
  local ok2, ctrl = pcall(function()
    return game.GetClientUIControl(CONFIG.CONTAINER_NODE_INDEX)
  end)
  if ok2 and ctrl ~= nil then
    return ctrl
  end
  return nil, "取不到挂载容器（script.object 与 GetClientUIControl 都返回空）"
end

local function build_all_ui()
  if UI.built then return true end
  local w, h, err = read_canvas()
  if not w then
    log_info("画布尚未就绪：%s", tostring(err))
    return false
  end
  -- 先取挂载容器：所有自建控件都挂在它下面
  -- 取不到时不阻断启动，改用 nil 父级（挂到默认容器根），只记一条日志。
  -- 理由：真机上 script.object 一般可用；异常环境下退化为默认根，
  --       仍能创建控件并显示，比直接放弃启动好得多。
  local host, hostErr = read_container()
  if host == nil then
    log_once("no_host", "挂载容器未取到（%s），控件将挂到默认根", tostring(hostErr))
  end
  UI.host = host   -- 可能为 nil，create_* 会原样传给 InstantiateClientUIControl

  -- ===== 光标事件的前置条件：容器节点必须 showCursor = true =====
  -- 【为什么必须设，不设会怎样（API 文档 §24(1) L1031 原文）】
  --   `showCursor`：「是否显示常驻光标；**CursorEvent 相关方法都需设置该参数为真后才可正常使用**」。
  --   本项目全部交互都走 `AddCursorEventListener`：棋盘 64 个光标检测区 +
  --   面板按钮 + 弹窗按钮。容器这一项没开，这些监听在真机上**完全不触发**，
  --   表现就是「画面好好的，但点哪都没反应」—— 而且不会报错，是最难查的一类故障。
  -- 【为什么以前一直没发现】体外沙箱**没有实现**该字段（docs/沙箱能力清单.md 第二节
  --   已记过：「沙箱没有实现」），模拟器里点击照常可用，所以模拟器全绿也证明不了真机可用。
  -- 【为什么用 ~= nil 探测】沙箱里该字段不存在，直接写会被记为 unsupported-api 并判 fail；
  --   `if x ~= nil` 在沙箱跳过、在真机生效，两边都安全。
  -- 【为什么要写日志】真机上「字段存在但写失败」与「字段根本不存在」表现相同，
  --   留下读回值才能区分是配置问题还是平台问题。
  local function enable_show_cursor(container, tag)
    if container == nil then return false end
    local okWrite = pcall(function()
      if container.showCursor ~= nil then container.showCursor = true end
    end)
    if not okWrite then
      log_err("容器 showCursor 写入失败（%s）—— 若为真机，点击可能全部失效", tag)
      return false
    end
    local okRead, v = pcall(function() return container.showCursor end)
    if okRead and v == true then
      log_info("容器 showCursor=true 已生效（%s）", tag)
      return true
    elseif okRead and v == nil then
      log_info("容器 showCursor 字段不存在（%s，沙箱环境），真机需为 true", tag)
      return false
    end
    log_err("容器 showCursor 写入后读回不是 true（%s，读到 %s）", tag, tostring(v))
    return false
  end

  -- ① 挂载容器本身（脚本挂在容器节点上时就是它）
  enable_show_cursor(host, "script.object")

  -- ② UI 根容器（Document L191：「即实际显示的客户端控件容器画布中的默认容器节点」）
  --   script.object 未必是容器节点本体，根容器再设一次最稳；两者都设不冲突。
  local okRoots, roots = pcall(function() return game.GetClientUIRoots() end)
  if okRoots and type(roots) == "table" and roots[1] ~= nil then
    enable_show_cursor(roots[1], "GetClientUIRoots[1]")
  end

  UI.L = LAYOUT.compute(w, h)
  GAME.lastCanvasW, GAME.lastCanvasH = w, h

  -- 【棋盘图元数】由 PIECE_ART 自动算出，不需要加载外部数据文件
  PRIM_MAX = piece_prim_max()
  if PRIM_MAX < 1 then PRIM_MAX = 1 end

  -- ===== 背景层（必须先建，同级先出现的在下）=====
  -- 【v2.0】渐变采样逻辑已提升到模块级 bg_color_sample()，与初始界面共用同一份，
  -- 保证两层背景逐条同值（详见该函数上方的说明）。
  local function bg_color_at(t)
    return bg_color_sample(t)
  end
  UI.bg = {}
  local BG_BANDS = 24
  local bandH = h / BG_BANDS
  for i = 1, BG_BANDS do
    -- 每条带取**中心**位置的颜色采样，误差被摊到半条带，比取边界更平滑
    local t = (i - 0.5) / BG_BANDS
    UI.bg[i] = create_text({
      name = "bgband" .. tostring(i), parent = UI.host,
      -- 高度 +1：相邻带重叠 1px，把取整留下的细缝盖掉
      x = 0, y = (i - 1) * bandH, w = w, h = bandH + 1,
      bg = bg_color_at(t), text = "",
    })
  end

  build_board()
  build_panel()
  build_result_panel()
  build_promo_dialog()
  build_confirm_dialog()
  -- 【v2.0 顺序关键】初始界面必须最后建 —— 它是「盖在最上层的不透明整层」，
  -- 同级后出现的节点在上。提前建就会被棋盘/面板/弹窗压住（截图能看到棋盘透出来）。
  build_start_screen()
  -- 待机室同样必须最后建（盖在最上层的整层，同级后出现的在上）
  build_lobby()
  -- 【v3.3】build_review_actionbar() 已删除（复盘动作条整体移除）
  UI.built = true
  GAME.uiReady = true

  log_info("棋子图元：6 种 × 2 方，单枚最多 %d 个控件", PRIM_MAX)

  -- 统一启用所有已创建控件（创建时全部 SetActive(false)）
  for i = 1, #FACTORY.cleanup do
    local ctrl = FACTORY.cleanup[i]
    if ctrl ~= nil then
      ctrl:SetActive(true)
      ctrl:SetVisible(true)
    end
  end
  -- 【层级】全部建完后，把命中区统一提到最顶层。
  -- 原因：面板/弹窗都是在 build_board、build_panel 之后创建的，
  -- 同级后出现的节点在上，会把先建的棋盘命中区与面板按钮命中区盖住 → 点击全部失效
  -- （模拟器实测：不走这一步则棋盘和按钮都点不动）。
  -- 棋盘命中区与面板按钮命中区都要提；弹窗自己的命中区由 show_*/hide_* 单独管理。
  local function raise_hit(c)
    if c ~= nil then pcall(function() c:SetAsLastSibling() end) end
  end
  for sq = 0, 63 do raise_hit(UI.hitAreas[sq]) end
  raise_hit(UI.panel.hitNew)
  raise_hit(UI.panel.hitResign)
  raise_hit(UI.panel.hitDraw)
  raise_hit(UI.panel.hitV2BackMain)
  -- 复盘命中区同样要提（它们在 build_panel 里建，之后建的结算/确认弹窗会盖住）
  raise_hit(UI.review.hitToggle)
  raise_hit(UI.review.hitStart)
  raise_hit(UI.review.hitPrev)
  raise_hit(UI.review.hitNext)
  raise_hit(UI.review.hitEnd)
  -- 音效开关命中区（v1.10）：它在面板下方，同样会被之后建的弹窗盖住
  raise_hit(UI.panel.hitSfx)
  -- v2.0「返回主菜单」命中区：与面板其它命中区同层，必须一起提到最顶层
  raise_hit(UI.panel.hitV2BackMain)
  -- 【v2.0 修 N-1 的第 ② 层：三个模态弹窗的命中区从来没提过】
  -- 旧代码只提了棋盘/面板/复盘/音效，**漏了结算、升变、确认三个弹窗的命中区**。
  -- 后果：弹窗视觉在后（后建），命中却在前 —— 点不动（模拟器实测「取消」无效）。
  -- 这里补齐。顺序上它们排在初始界面之前也没关系：show_* 每次显示时会再提一次
  -- （见 show_confirm 末尾的 raise_modal_hits）。
  -- 【v2.0 修 P0：顺序】hitOverlay 是全屏命中区，必须**最先**抬（压在最底），
  --   两个按钮后抬才能盖住它并接到点击。反过来 = 结算面板整块不可点。
  raise_hit(UI.result.hitOverlay)
  raise_hit(UI.result.hitAgain)
  raise_hit(UI.result.hitReview)
  for i = 1, #UI.promo.hits do raise_hit(UI.promo.hits[i]) end
  raise_hit(UI.confirm.hitYes)
  raise_hit(UI.confirm.hitNo)
  -- 音效按钮文案按当前开关状态同步（`音效：开` / `音效：关`）
  sync_sfx_button()
  -- 结算/升变/求和弹窗初始隐藏
  hide_result()
  hide_promo()
  hide_confirm()
  -- 复盘相关控件初始隐藏；第三行常驻键显示为「看历史」
  show_review_buttons(false)
  ui_set_active(UI.review.btnToggle, true)
  ui_set_active(UI.review.hitToggle, true)
  UI.review.btnToggle.text = CONFIG.TEXT.BTN_REVIEW_HISTORY

  -- ===== 初始界面（v2.0）=====
  -- 【必须在最后】本函数上面那些「统一启用所有已创建控件」的裸 SetActive(true)
  -- 会把初始界面整层也点亮（它们不经过 ui_set_active）。所以这里再走一遍
  -- show_start_screen()，由它统一把本层点亮、把所有下层命中区关掉。
  -- 顺序上是「先全亮 → 再按界面状态收敛」，不会留下半状态。
  GAME.tcN = CONFIG.DEFAULT_TIME_CONTROL
  apply_time_control(GAME.tcN)
  show_start_screen()

  -- 【v2.0 修 N-1 的第 ③ 层（最容易被忽略的一层）】
  -- 初始界面整层是**最后建的**，而 show_start_screen 又会把它自己的命中区
  -- SetAsLastSibling() 一遍。于是即使上面把弹窗命中区提过了，
  -- 此刻它们仍然被初始界面的卡/入口命中区压在下面。
  --
  -- 但**不能**在这里反过来把弹窗命中区提到初始界面之上 —— 那样初始界面就点不动了。
  -- 正确的做法是「谁可见谁在上」，由显示时机决定：
  --   · 初始界面可见时：它自己的命中区在最上（show_start_screen 保证）；
  --   · 弹窗打开时：show_confirm / show_result 末尾再提一次自己的命中区
  --     （见 show_confirm 的 raise_modal_hits）—— 那一刻初始界面必然已隐藏。
  -- 所以这里**不需要**再做什么，只要保证 show_* 会提。留这段注释是为了
  -- 让下一个改这里的人不要「顺手」把弹窗提到初始界面之上。
  log_info("界面构建完成：控件 %d 个，画布 %dx%d，格宽 %.1f 界面=%s 档位=%d",
    FACTORY.created, w, h, UI.L.cell, tostring(GAME.screen), GAME.tcN)
  return true
end

local function cleanup_all()
  -- 反向释放：注销监听 → 销毁控件
  for i = #INPUT.registered, 1, -1 do
    local ctrl = INPUT.registered[i]
    if ctrl ~= nil then
      pcall(function()
        if CLICK_EVENT ~= nil then ctrl:RemoveCursorEventListeners(CLICK_EVENT) end
      end)
    end
  end
  INPUT.registered = {}

  for i = #FACTORY.cleanup, 1, -1 do
    local ctrl = FACTORY.cleanup[i]
    if ctrl ~= nil then
      pcall(function() game.DestroyClientUIControl(ctrl) end)
    end
  end
  FACTORY.cleanup = {}
  UI.built = false
  GAME.uiReady = false
end

-- ===== 生命周期回调 =====
function OnInit()
  GAME.state = "NEW"
  log_info("脚本初始化")
end

function OnStart()
  GAME.state = "STARTING"
  GAME.startupRetry = 0

  -- ① 先验证配置（配置错误立即报错，不重试）
  local cfgOk, missing = validate_config()
  if not cfgOk then
    log_err(CONFIG.TEXT.ERR_CONFIG)
    emit_fault("CFG_MISSING", "STARTING", "配置缺失: " .. tostring(missing), nil, "CONFIG 第 1 区")
    GAME.state = "FAILED"
    return
  end

  -- ② 探测联机能力（无论成功与否都不阻断启动）
  net_probe()

  -- ③ 尝试构建界面（画布未就绪时由 OnUpdate 有限重试）
  if not build_all_ui() then
    log_info("界面尚未就绪，将在逐帧里有限重试（预算 %d 帧）", CONFIG.STARTUP_RETRY_BUDGET)
    script:EnableUpdate(true)
    return
  end

  -- ④ 解析点击事件枚举
  CLICK_EVENT = resolve_click_event()
  if CLICK_EVENT == nil then
    log_err("取不到光标点击事件枚举，界面不可交互")
    emit_fault("EVENT_ENUM_MISSING", "STARTING", "Enum.CursorEventType 无可用值", nil, "API 文档 §11(7) L454-465")
    GAME.state = "FAILED"
    return
  end

  -- ⑤ 注册输入
  register_all_input()

  -- ⑥ 注册联机接收
  net_register_receive()

  -- ⑦ 进初始界面（v2.0）
  -- 【不再直接开局】v1.12 及以前这里直接 new_game() 进棋盘；v2.0 启动后先停初始界面，
  -- 由玩家选档位 + 点入口才开局。但**仍然先 new_game() 一次**，原因：
  --   · 复盘研习入口 / 待机室都要有一个合法的开局局面可读（GAME.st 不能是 nil）；
  --   · 棋盘在初始界面背后保持「一局刚开好的样子」，退出时不残留上一局。
  -- 这样 GAME.st 从启动起就永远非 nil，所有依赖它的代码（render/自检）不需要判空。
  apply_time_control(GAME.tcN)
  new_game()
  GAME.screen = "start"
  if GAME.uiReady then show_start_screen() end
  GAME.state = "RUNNING"
  script:EnableUpdate(true)

  log_info("启动完成：状态=%s 界面=%s 控件=%d 联机发送=%s 接收=%s 同屏=%s 档位=%d(%d+%d)",
    GAME.state, tostring(GAME.screen), FACTORY.created,
    tostring(NET.canSend), tostring(NET.canReceive), tostring(GAME.localMode),
    GAME.tcN, GAME.tcInitial, GAME.tcIncrement)

  -- 启动汇总（一次）
  log_info("容器索引=%d 脚本短名=%s 画布=%dx%d",
    CONFIG.CONTAINER_NODE_INDEX, CONFIG.SCRIPT_SHORT_NAME,
    GAME.lastCanvasW or -1, GAME.lastCanvasH or -1)

  -- ===== ⑧ 跑自检并打一条汇总日志（v2.0 块 5 补）=====
  -- 【为什么这是必须的】块 1~5 期间 SelfTest() **从来没有被调用过** ——
  --   24 条断言只是「存在于源码里」，一次都没执行。这导致：
  --     · 块 4 的动作条在没有断言拦截的情况下泄漏到初始界面/待机室（BUG-1）
  --     · 块 5 的 EV_START 双发没有被 ev_start_sent_once 拦住（BUG-3）
  --   教训：**断言写了不跑 = 没写**。这是比「断言失败」严重得多的假绿。
  --
  -- 【三条纪律】
  --   ① 用 pcall 包住 —— 自检崩了绝不能拖垮游戏（玩家至少还能玩）
  --   ② 只打一条汇总 + 失败项明细，不要每条都打（24 条会刷屏，还会淹没真正的启动日志）
  --   ③ 必须在 GAME.state = "RUNNING" 与 UI 建好之后跑 —— 断言里大量依赖两者
  do
    -- 【日志前缀 `[自检]`】自检内部会调用一些真实函数（如 start_game_from_lobby），
    -- 它们自己也会打日志。加前缀让读者一眼分清「这是自检的副作用」还是「真的开局了」。
    -- （Lead 实测时把自检产生的两条「待机室开局」误读成真开局，所以这里必须标清。）
    -- 【断言数不写死】用 SelfTest 返回的 checks 长度，避免以后加断言忘了改这句日志。
    local okCall, res = pcall(function()
      -- 【自检零副作用】进入自检前立闸，退出（无论成败）必须复位。
      -- 闸的作用：net_send_event 不发包、start_game_from_lobby 不真开局。
      -- 为什么用 pcall 包一层而不是裸调 SelfTest：
      --   ① 断言崩了不能拖垮游戏；
      --   ② 保证 inSelfTest 一定被复位 —— 否则一旦自检抛错，
      --      整局游戏的联机发送会永久失效（比自检失败严重得多）。
      GAME.inSelfTest = true
      local r = SelfTest()
      GAME.inSelfTest = false
      return r
    end)
    -- 兜底复位：pcall 内部若在 SelfTest 之前就抛错（理论上不会），这里补一次。
    GAME.inSelfTest = false
    if not okCall then
      log_err("[自检] 执行崩溃（不影响游戏）：%s", tostring(res))
    elseif type(res) ~= "table" or type(res.checks) ~= "table" then
      log_err("[自检] 返回值结构异常：%s", type(res))
    else
      local passed, total = 0, #res.checks
      local fails = {}
      for i = 1, total do
        local c = res.checks[i]
        if c ~= nil and c.pass then
          passed = passed + 1
        elseif c ~= nil then
          fails[#fails + 1] = tostring(c.name) .. "(" .. tostring(c.detail) .. ")"
        end
      end
      if #fails == 0 then
        log_info("[自检] %d/%d 通过", passed, total)
      else
        -- 失败时逐条列出（有上限，避免刷屏）
        log_err("[自检] %d/%d 通过，失败 %d 项：", passed, total, #fails)
        for i = 1, math.min(#fails, 12) do
          log_err("[自检]   ✗ %s", fails[i])
        end
        if #fails > 12 then
          log_err("[自检]   ...（其余 %d 项省略）", #fails - 12)
        end
      end
    end
  end
end

function OnEnable()
  log_info("脚本启用")
end

function OnUpdate(dt)
  -- ① STARTING 阶段：只推进就绪重试，不推进玩法
  if GAME.state == "STARTING" then
    GAME.startupRetry = GAME.startupRetry + 1
    if GAME.startupRetry > CONFIG.STARTUP_RETRY_BUDGET then
      emit_fault("STARTUP_TIMEOUT", "STARTING",
        "画布或容器在 " .. tostring(CONFIG.STARTUP_RETRY_BUDGET) .. " 帧内仍未就绪",
        nil, "OnUpdate 重试计数")
      GAME.state = "FAILED"
      return
    end
    if build_all_ui() then
      CLICK_EVENT = resolve_click_event()
      if CLICK_EVENT == nil then
        emit_fault("EVENT_ENUM_MISSING", "STARTING", "Enum.CursorEventType 无可用值", nil, "API 文档 §11(7) L454-465")
        GAME.state = "FAILED"
        return
      end
      register_all_input()
      net_register_receive()
      -- v2.0：重试成功后同样停在初始界面（与 OnStart 的 ⑦ 保持一致）
      apply_time_control(GAME.tcN)
      new_game()
      GAME.screen = "start"
      if GAME.uiReady then show_start_screen() end
      GAME.state = "RUNNING"
    end
    return
  end

  if GAME.state ~= "RUNNING" then return end

  -- ② 时间增量校验（异常值跳过本帧）
  if type(dt) ~= "number" or dt ~= dt or dt <= 0 or math.isinf(dt) then return end

  -- ② 联机协商时钟（v3.0）：与棋钟同一口径，只累加 OnUpdate 的 dt。
  -- 【为什么不用 os.time】os.time 是秒级、且不受关卡时停影响，两端不可比；
  --   本端只需要「距离上次收到对方包过了多久」，累加 dt 就够且可控。
  GAME.onlineClock = (GAME.onlineClock or 0) + dt

  -- ②.5 复盘中冻结棋局：不累计用时、不扣棋钟、不触发超时判负。
  -- 复盘是「回看」，对局时间不能因为看历史而流逝（对局中看历史尤其重要）。
  -- 【注意】复盘只冻结棋局，动画照样要推进，否则棋子会卡在半路。
  local reviewing = (GAME.review ~= nil)

  -- ②.6 动画统一推进（放最前：即便终局/复盘，动画也要走完）
  --
  -- 【必须在这里补一次棋子重绘】动画只改 slot.x/y/scale/lift 这些**数据**，
  -- 真正把数据写到控件上的是 paint_slot，而 paint_slot 只在 render_pieces 里被调用。
  -- 早先只推进 ANIM 不重绘，结果是：棋子一步走完位置数据早就是终点了，
  -- 但画面上还停在起点（模拟器实测：e2→e4 之后兵仍在 e2，目标格只多了个高亮）。
  --
  -- 【v1.10 提速：动画期间只重绘脏槽位】
  --   旧写法是动画期间每帧 render_pieces() 全量重绘：重建 bySq（64 格 + 32 槽）
  --   → 遍历 32 槽 → 每槽 paint_slot 做 6 遍形状遍历、每个图元 3~4 次控件写。
  --   32 枚 × 数十图元 ≈ 每帧数千次控件写 —— 这就是「不跟手」的根因。
  --   现在 anim_update 会登记本帧真正动过的槽位（ANIM.dirty），只重绘那几个。
  --
  --   为什么不会漏绘：
  --   · 槽位**归属**（slot.sq / slot.key）只在全量 render_pieces、apply_move、
  --     reset_piece_slots 里改，这三处之后都会走全量渲染；
  --   · 动画任务只改 x/y/scale/lift/fading，不改归属 → 归属在动画期间是稳定的；
  --   · 动画全部跑完的那一帧还需要「收尾全量」：ANIM.count 变 0 时按 needsRepaint
  --     再走一次全量 render_pieces，把可能的半格/旧位置彻底刷干净（见下）。
  if GAME.animated then
    anim_update(dt)
    if GAME.uiReady then
      local dirty, dirtyCount = anim_take_dirty()
      if ANIM.count > 0 then
        -- 动画进行中：只重绘本帧动过的槽位（通常 1~2 个，开局弹入时最多 32 个）
        if dirty ~= nil then render_pieces(dirty, dirtyCount) end
        GAME.needsRepaint = true      -- 记下「收尾还要全量刷一次」
      elseif GAME.needsRepaint then
        -- 动画刚跑完这一帧：补一次全量重绘收尾，然后清标记
        GAME.needsRepaint = false
        render_pieces()
      end
    end
  end
  if GAME.uiReady then anim_update_hilites(dt) end

  -- ②.6 【v2.0 块 5：联机悔棋请求超时】
  -- 【为什么必须有】发出 EV_UNDO_REQ 后，对方可能：掉线 / 没搭节点图 / 干脆不理。
  --   不设超时的话棋钟会被无限期冻结（modalPaused 逻辑），整局卡死。
  -- 超时视同拒绝（gdd §7.5 末条）：解冻棋钟、提示「对方没有回应，悔棋已取消」、**次数不扣**。
  -- 【为什么放在待机室段之前】它和待机室无关，且必须在 modalPaused 生效前推进计时。
  if GAME.pendingUndo ~= nil and GAME.pendingUndo.t ~= nil then
    GAME.pendingUndo.t = GAME.pendingUndo.t + dt
    if GAME.pendingUndo.t >= CONFIG.UNDO_REQUEST_TIMEOUT_SEC then
      local wasMine = GAME.pendingUndo.byMe
      GAME.pendingUndo = nil                -- 解冻（modalPaused 随之解除）
      if wasMine then
        -- 只有发起方需要这句提示；响应方是「对方的请求过期了」，不用提示
        if UI.panel.hint then UI.panel.hint.text = CONFIG.TEXT.UNDO_TIMEOUT end
        -- 次数不扣：这里刻意不调 undo_consume()（gdd §7.5：未发生撤回就不扣）
      end
      refresh_undo_button()
      log_info("悔棋请求超时（%.0f 秒），已取消，次数未扣", CONFIG.UNDO_REQUEST_TIMEOUT_SEC)
    end
  end

  -- ②.8 【v3.0：初始界面上的联机协商】
  -- 【为什么放在 reviewing / modalPaused 之前】开局前没有棋钟要冻结，但协商计时
  --   （5 秒改选窗口、心跳、对手掉线判定）必须逐帧推进，否则「停在初始界面不动」时
  --   倒计时永远不走。
  -- 【为什么用累加 dt 而不是 os.time】与棋钟同一条确定性纪律：
  --   OnUpdate(dt) 不受关卡时停影响，逐帧累加是唯一可控的口径。
  -- 【旧的待机室倒数逻辑已删除】LOBBY_COUNTDOWN_SEC 不再被任何路径使用（见 CONFIG 注释）。
  if GAME.screen == "start" and GAME.uiReady then
    GAME.match.tick(dt)
    -- 本帧可能刚判定成功并开局（GAME.match.start 里已把 screen 改成 playing），
    -- 这时不必再用同一帧去走对局逻辑（棋钟第一帧不该被扣时）。
    if GAME.screen ~= "start" then return end
  end

  -- ②.7 【v2.0 修 N-3：模态确认框打开期间冻结棋局】
  -- 模拟器实测缺陷：确认框开着时黑方棋钟从 14:46 走到 14:37 —— 时间照烧。
  -- 后果：玩家「开个确认框慢慢想」等于免费思考时间，对另一方不公平，
  --   而且和复盘冻结的语义自相矛盾（复盘都在冻结，弹窗反而不冻）。
  --
  -- 【为什么放在 reviewing 之后、扣时之前】动画与高亮必须继续推进
  --   （否则弹窗期间画面会僵住），只冻结「时间与轮次」这一组。
  -- 【为什么与 reviewing 分开写而不合并成一个条件】两者语义不同：
  --   reviewing 是「回看历史」，弹窗是「等玩家确认」，将来可能只对其中一个放宽，
  --   合并会让「为什么冻结」这个理由在代码里丢掉。
  --
  -- 【注意：这里只冻结，不 return】下面的求和冷却倒计时与棋钟文本刷新
  --   仍应继续（否则关掉弹窗后要等 0.25 秒才看到刷新过的棋钟）。
  local modalPaused = (GAME.confirmKind ~= nil)

  if reviewing then return end

  -- ③ 本局用时累加（结算说明行「本局用时 MM:SS」用）
  --    弹窗期间不计入：那是玩家的思考中断，不该算双方任何一方的时间。
  if not GAME.over and not modalPaused then
    GAME.elapsedSec = (GAME.elapsedSec or 0) + dt
  end

  -- ④ 棋钟：只有轮到的一方在扣时；终局后不扣；弹窗打开期间不扣
  if not GAME.over and not modalPaused then
    if GAME.st.turn == WHITE then
      GAME.clockWhite = GAME.clockWhite - dt
      -- 音效：首次跌破 SFX_LOW_TIME_SEC 时提示一次（每方各一次，靠 lowTimeFired 防重复）
      -- 必须在扣时之后、判负之前判：判负那一刻也顺手会播 GAME_END，不再补提示音。
      if not SFX.lowTimeFired[1] and GAME.clockWhite > 0
         and GAME.clockWhite <= CONFIG.SFX_LOW_TIME_SEC then
        SFX.lowTimeFired[1] = true
        sfx_play("low_time")
      end
      if GAME.clockWhite <= 0 then
        GAME.clockWhite = 0
        GAME.over = true
        GAME.resultText = CONFIG.TEXT.RESULT_TIMEOUT_WHITE
        GAME.resultSub = CONFIG.TEXT.SUB_TIMEOUT_WHITE
        show_result()
      end
    else
      GAME.clockBlack = GAME.clockBlack - dt
      if not SFX.lowTimeFired[2] and GAME.clockBlack > 0
         and GAME.clockBlack <= CONFIG.SFX_LOW_TIME_SEC then
        SFX.lowTimeFired[2] = true
        sfx_play("low_time")
      end
      if GAME.clockBlack <= 0 then
        GAME.clockBlack = 0
        GAME.over = true
        GAME.resultText = CONFIG.TEXT.RESULT_TIMEOUT_BLACK
        GAME.resultSub = CONFIG.TEXT.SUB_TIMEOUT_BLACK
        show_result()
      end
    end
  end

  -- ④ 求和冷却倒计时
  for i = 1, 2 do
    if GAME.drawCooldown[i] > 0 then
      GAME.drawCooldown[i] = math.max(0, GAME.drawCooldown[i] - dt)
    end
  end

  -- ⑤ 棋钟文本按 CLOCK_REFRESH_SEC 刷新（不逐帧写文本）
  GAME.clockTextTimer = GAME.clockTextTimer + dt
  if GAME.clockTextTimer >= CONFIG.CLOCK_REFRESH_SEC then
    GAME.clockTextTimer = 0
    update_clock_text()
  end
end

function OnLevelUpdate(dt)
  -- 棋钟不受关卡时停影响，故本函数不做任何事（刻意保留为空）
end

function OnDisable()
  log_info("脚本停用")
end

function OnDestroy()
  if GAME.state == "DESTROYED" then return end
  GAME.state = "DESTROYED"
  pcall(function() script:EnableUpdate(false) end)
  cleanup_all()
  log_info("脚本销毁：已释放 %d 个控件", FACTORY.created)
end

-- =============================================================================
-- 第 11 区：SELFTEST（自检入口，不参与玩法）
--   供沙箱与真机诊断调用；不改变玩法状态。
-- =============================================================================

-- 重绘统计打点（诊断用，不参与玩法）：
-- 在日志里打一条 REPAINT[...]，配合 GetRepaintStats 人工确认提速效果。
function DumpRepaintStats(tag)
  log_info("REPAINT[%s] slots=%d full=%d partial=%d tasks=%d writes=%d skipped=%d",
    tostring(tag or "-"), ANIM.paintSlotsTotal, ANIM.paintFramesFull,
    ANIM.paintFramesPartial, ANIM.count,
    WRITE_STATS.writes, WRITE_STATS.skipped)
  return true
end

-- perft 自检：跑标准局面，与硬编码答案比对
local PERFT_CASES = {
  { name = "initial", fen = START_FEN, d1 = 20, d2 = 400, d3 = 8902 },
  { name = "kiwipete",
    fen = "r3k2r/p1ppqpb1/bn2pnp1/3PN3/1p2P3/2N2Q1p/PPPBBPPP/R3K2R w KQkq - 0 1",
    d1 = 48, d2 = 2039, d3 = 97862 },
  { name = "pos3", fen = "8/2p5/3p4/KP5r/1R3p1k/8/4P1P1/8 w - - 0 1",
    d1 = 14, d2 = 191, d3 = 2812 },
  { name = "pos4", fen = "r3k2r/Pppp1ppp/1b3nbN/nP6/BBP1P3/q4N2/Pp1P2PP/R2Q1RK1 w kq - 0 1",
    d1 = 6, d2 = 264, d3 = 9467 },
  { name = "pos5", fen = "rnbq1k1r/pp1Pbppp/2p5/8/2B5/8/PPP1NnPP/RNBQK2R w KQ - 1 8",
    d1 = 44, d2 = 1486, d3 = 62379 },
  { name = "pos6", fen = "r4rk1/1pp1qppp/p1np1n2/2b1p1B1/2B1P1b1/P1NP1N2/1PP1QPPP/R4RK1 w - - 0 10",
    d1 = 46, d2 = 2079, d3 = 89890 },
}

function SelfTestPerft(maxDepth)
  maxDepth = maxDepth or 3
  local failures = {}
  local checked = 0
  for _, c in ipairs(PERFT_CASES) do
    local st = RULES.parse_fen(c.fen)
    for d = 1, maxDepth do
      local expect = c["d" .. tostring(d)]
      if expect then
        local got = RULES.perft(st, d)
        checked = checked + 1
        if got ~= expect then
          failures[#failures + 1] = string.format("%s d=%d got=%d expect=%d", c.name, d, got, expect)
        end
      end
    end
  end
  return #failures == 0, checked, failures
end

-- 汇总自检：返回给沙箱/诊断的结构化结果
-- =============================================================================
-- 【自检必须零副作用 —— 本项目最重要的一条纪律，来自真实事故】
--
-- 背景：SelfTest 在**每次 OnStart 都跑**，而它最初有几条断言会「真的执行动作」：
--   · 直接调 net_send_event 验证降级路径 → 真机上真的广播给所有玩家
--     实测（Lead，playerCount=2）：一次启动就冒出 4 条自检产生的包
--     （EV_READY×2 + EV_START×2，两端各两条）。
--     后果推演：只要有一端时序稍慢，另一方会在还没进待机室时就收到 EV_START
--       → **游戏在对局开始前就被「开局」了**。比少一个功能严重得多。
--   · 直接调 start_game_from_lobby 验证 broadcast 参数 → 真的走了一遍开局逻辑
--     （new_game / screen 切换），污染玩家看到的初始界面。
--
-- 【纪律】
--   ① 自检不发网络包     → GAME.inSelfTest 拦截 net_send_event（返回 false）
--   ② 自检不启动对局     → GAME.inSelfTest 拦截 start_game_from_lobby
--   ③ 自检不改玩家可见状态 → 所有临时改动必须在断言内**完整备份并还原**
--   ④ 凡要验证「某函数会做什么」的断言，都应验证它的**返回值/内部标记**，
--      而不是**真的执行它**。
--   ⑤ **断言不得假设自己运行在哪个屏。** 自检跑在 OnStart 末尾（screen=="start"），
--      但断言可能被搬走或在别的时机调用。判据要写「状态不许变成 X」，
--      而不是「状态必须等于 Y」。
--      这条来自同型错误的第 3 次（前两次：lb.hitSolo 字段路径错、
--      undo_ready 在 screen=start 时要求悔棋按钮有文案）。
--      共同点都是**把「某个特定上下文」当成了普遍前提**。
--
-- 【为什么这条比修一个 bug 更重要】自检跑在真实玩家的每一次启动上。
-- 一个会发信号的断言，污染的是全房间玩家的对局，而日志看起来一切正常。
-- =============================================================================
function SelfTest()
  local out = { ok = true, checks = {} }
  local function add(name, pass, detail)
    out.checks[#out.checks + 1] = { name = name, pass = pass, detail = detail or "" }
    if not pass then out.ok = false end
  end

  -- 1 规则 perft
  local okPerft, checked, failures = SelfTestPerft(2)
  add("perft_d1_d2", okPerft, okPerft and ("checked=" .. tostring(checked)) or table.concat(failures, "; "))

  -- 2 状态
  add("state_running", GAME.state == "RUNNING", "state=" .. tostring(GAME.state))

  -- 3 控件数量
  add("controls_created", FACTORY.created > 0, "created=" .. tostring(FACTORY.created))

  -- 4 界面已建
  add("ui_built", UI.built == true, "built=" .. tostring(UI.built))

  -- 5 联机能力（沙箱里 canSend 应为 false，这是正常的）
  add("net_probe_done", NET.probed == true,
    "canSend=" .. tostring(NET.canSend) .. " canReceive=" .. tostring(NET.canReceive))

  -- 6 动画时长与 Demo v3 同值（v1.10）
  add("anim_matches_demo",
    CONFIG.ANIM.MOVE_DUR == 0.17 and CONFIG.ANIM.SETTLE_DUR == 0.10
      and CONFIG.ANIM.SETTLE_PEAK == 0.07,
    string.format("move=%.2f settle=%.2f peak=%.2f",
      CONFIG.ANIM.MOVE_DUR, CONFIG.ANIM.SETTLE_DUR, CONFIG.ANIM.SETTLE_PEAK))

  -- 7 初始界面（v2.0）：启动后应停在 start，且整层控件已就位
  -- 【为什么这条与 state_running 并存】GAME.state 守「脚本活着」（回归基线，不能动），
  -- GAME.screen 守「玩家看到哪个界面」。两者是不同维度，各自断言。
  add("screen_start", GAME.screen == "start", "screen=" .. tostring(GAME.screen))

  -- 8 初始界面控件完整性（v2.0）：4 张档位卡 + 3 个入口 + 24 条带都在
  -- 【为什么数一遍】build_start_screen 里任何一个循环边界写错（比如 #cards 取到 0）
  -- 都会让界面「看起来是空的但不报错」，只能靠数量断言抓。
  do
    local ss = UI.startScreen
    local nCards = (ss and ss.cards) and #ss.cards or 0
    local nEntries = (ss and ss.entries) and #ss.entries or 0
    local nBands = (ss and ss.bands) and #ss.bands or 0
    -- 【v3.2】入口数 3 → 2（删掉「单人·双人同屏」）
    add("start_screen_parts",
      nCards == #CONFIG.TIME_CONTROLS and nEntries == 2 and nBands == 24,
      string.format("cards=%d/%d entries=%d/2 bands=%d/24",
        nCards, #CONFIG.TIME_CONTROLS, nEntries, nBands))
  end

  -- 9 走时档别名自洽（v2.0）
  -- 【这条是防漂移的锁】CONFIG.INITIAL_TIME_SEC / INCREMENT_SEC 是为
  -- consistency_check.cjs 的「Lua↔Demo 逐值比对」保留的别名，实际取值走 TIME_CONTROLS。
  -- 有人只改其中一处时，这条会立刻红 —— 而不是等到真机上棋钟显示 15:00 才发现没生效。
  do
    local tc3 = tc_of(CONFIG.DEFAULT_TIME_CONTROL)
    add("time_control_alias",
      tc3 ~= nil and tc3.initial == CONFIG.INITIAL_TIME_SEC
        and tc3.inc == CONFIG.INCREMENT_SEC and tc3.n == 3,
      string.format("档位%d initial=%d/%d inc=%d/%d",
        tc3 and tc3.n or -1,
        tc3 and tc3.initial or -1, CONFIG.INITIAL_TIME_SEC,
        tc3 and tc3.inc or -1, CONFIG.INCREMENT_SEC))
  end

  -- 10 四档走时数值与硬契约逐项一致（v2.0）
  -- 硬契约：超快棋 60+0 / 闪电战 180+2 / 快棋 900+10 / 慢棋 5400+30
  -- 【12 文本框容量自检（v2.0 新增）】
  -- 这一条直接对应模拟器实录的两个 P0：「3 个入口按钮一个字都没有」「档位名整行不显示」。
  -- 两者根因不同（前者是 text 传了空串，后者是控件高不够被整行吞掉），
  -- 所以这里**两条都断言**：
  --   ① 文案非空：每个入口按钮 / 档位名的 text 必须是真实文案，不能是 ""；
  --   ② 高度够用：可用高 ≈ h − 0.9×字号 必须 ≥ 行高 1.2×字号（D-02 陷阱）。
  -- 这是一条「能防住真事故」的断言，不是凑数 —— 两个 bug 都会让它当场变红。
  do
    local ss = UI.startScreen
    local probs = {}
    if ss ~= nil then
      -- ① 文案非空
      -- 【v3.2】入口从 3 个减到 2 个（删掉「单人·双人同屏」），断言的期望表同步收缩。
      --   若将来再加入口，这里必须跟着加，否则新入口的空文案不会被抓到。
      local wantEntries = {
        { ss.entryOnline, CONFIG.TEXT.ENTRY_ONLINE },
        { ss.entryReview, CONFIG.TEXT.ENTRY_REVIEW },
      }
      for i = 1, #wantEntries do
        local e = wantEntries[i][1]
        local want = wantEntries[i][2]
        if e == nil or e.btn == nil then
          probs[#probs + 1] = "入口" .. tostring(i) .. "控件缺失"
        elseif e.btn.text ~= want then
          probs[#probs + 1] = "入口" .. tostring(i) .. "文案=\"" .. tostring(e.btn.text) ..
                              "\"（应为\"" .. tostring(want) .. "\"）"
        end
      end
      -- ② 高度够用（入口按钮 + 档位名 + 档位卡说明行）
      local function heightOk(ctrl, fontPx, label)
        if ctrl == nil then return end
        -- 平台文本布局：行高 ≈ 1.2×字号，上下内边距合计 ≈ 0.9×字号
        local need = fontPx * 1.2 + fontPx * 0.9
        local have = ctrl.height
        if type(have) ~= "number" then
          -- 某些实现读不回 height，用尺寸写过的值兜底：这里只跳过，不误判
          return
        end
        if have + 0.5 < need then
          probs[#probs + 1] = label .. "高 " .. string.format("%.0f", have) ..
                              " < 需要 " .. string.format("%.0f", need)
        end
      end
      local fEntry = UI.L.font(CONFIG.FONT.START_ENTRY)
      if ss.entryOnline ~= nil then heightOk(ss.entryOnline.btn, fEntry, "入口按钮") end
      local fName = UI.L.font(CONFIG.FONT.TC_NAME)
      local fMeta = UI.L.font(CONFIG.FONT.TC_META)
      -- ③ 【v2.0 块 3 新增：宽度够用】proto-lead 实测「悔棋（剩 3）」需宽 146 / 可用 146，
      --   只差 1px 就换行 —— 换行后半宽按钮里只剩半个「悔棋」，比没字更难看。
      --   判据：字数 × 字号 ≤ 控件宽。**全角按 1.0em 保守估**（汉字/全角标点都算 1em），
      --   半角数字/字母按 0.55em。这是保守估计（实际中文字宽通常略小于 em）。
      local function widthOk(ctrl, fontPx, text, label)
        if ctrl == nil or text == nil then return end
        local have = ctrl.width
        if type(have) ~= "number" then return end
        -- 逐字符算宽度：字节数 ≥3 的 UTF-8 字符视为全角(1em)，其余半角(0.55em)
        local need = 0
        for _, code in utf8.codes(text) do
          if code >= 0x2E80 then need = need + fontPx          -- CJK / 全角标点
          else need = need + fontPx * 0.55 end                 -- 半角
        end
        if have + 0.5 < need then
          probs[#probs + 1] = label .. "宽 " .. string.format("%.0f", have) ..
                              " < 需要 " .. string.format("%.0f", need)
        end
      end
      if ss.entries ~= nil then
        for i = 1, #ss.entries do
          local e = ss.entries[i]
          if e ~= nil and e.btn ~= nil then
            widthOk(e.btn, fEntry, e.btn.text, "入口" .. tostring(i) .. "文案")
          end
        end
      end
      if ss.cards ~= nil then
        for i = 1, #ss.cards do
          local c = ss.cards[i]
          widthOk(c.name, fName, c.name and c.name.text, "档位" .. tostring(c.n) .. "名")
          if c.meta ~= nil then
            for m = 1, #c.meta do
              widthOk(c.meta[m], fMeta, c.meta[m] and c.meta[m].text,
                      "档位" .. tostring(c.n) .. "说明" .. tostring(m))
            end
          end
        end
      end
      -- 悔棋按钮（面板内，块 3 新增）：宽 = 面板宽 × 0.44（第三行左半）
      if UI.panel ~= nil and UI.panel.v2Undo ~= nil then
        local fBtn = UI.L.font(CONFIG.FONT.BUTTON)
        widthOk(UI.panel.v2Undo, fBtn, UI.panel.v2Undo.text, "悔棋按钮")
      end
    end
    add("text_fits", #probs == 0,
      #probs == 0 and "入口/档位卡/悔棋按钮：文案非空 + 高够装字 + 宽不换行"
                    or table.concat(probs, "; "))
  end

  -- 12-b 待机室文本容量自检（v2.0 块 2，Lead 明确要求）
  -- 【为什么单独一条】D-02「文本框可用高不够 → 整行被吞」已经是本项目**第三次**踩
  -- （v1.10 结算标题、v2.0 块1 档位名、本次 gdd 给的 72 号倒数放不进 0.115 板高）。
  -- 与其每次靠人眼看截图发现，不如变成**每块必跑的机器检查**。
  -- 判据与 text_fits 完全一致：可用高 ≈ h − 0.9×字号 ≥ 行高 1.2×字号（即 h ≥ 2.1×字号）。
  do
    local probs = {}
    local lb = UI.lobby
    local function chk(ctrl, fontPx, label)
      if ctrl == nil then
        probs[#probs + 1] = label .. "控件缺失"
        return
      end
      local need = fontPx * 2.1
      local have = ctrl.height
      if type(have) ~= "number" then return end   -- 读不回高度则跳过，不误判
      if have + 0.5 < need then
        probs[#probs + 1] = label .. " 高" .. string.format("%.0f", have) ..
                            "<需" .. string.format("%.0f", need)
      end
    end
    if lb ~= nil and UI.L ~= nil then
      local fTitle = UI.L.font(CONFIG.FONT.LOBBY_TITLE)
      local fBody = UI.L.font(CONFIG.FONT.LOBBY_BODY)
      local fSmall = UI.L.font(CONFIG.FONT.LOBBY_SMALL)
      local fCount = UI.L.font(CONFIG.FONT.LOBBY_COUNTDOWN)
      chk(lb.title, fTitle, "待机室标题")
      chk(lb.sideTag, fSmall, "身份标注")
      chk(lb.rowMe and lb.rowMe.text, fBody, "你 行")
      chk(lb.rowOpp and lb.rowOpp.text, fBody, "对手 行")
      chk(lb.roomTc, fSmall, "时间档行")
      chk(lb.hint, fSmall, "提示条")
      chk(lb.footer, fSmall, "底部提示")
      chk(lb.backMain, fSmall, "返回主菜单")
      chk(lb.countdown, fCount, "倒数数字")
      chk(lb.btnReady and lb.btnReady.text, fBody, "准备键")
      chk(lb.btnSolo and lb.btnSolo.text, fBody, "直接开始键")
      -- 按钮高必须够触摸目标（>= 44px）
      local function touch(ctrl, label)
        if ctrl == nil then return end
        local h = ctrl.height
        if type(h) == "number" and h < CONFIG.LOBBY_TOUCH_MIN then
          probs[#probs + 1] = label .. " 高" .. string.format("%.0f", h) ..
                              "<触摸下限" .. tostring(CONFIG.LOBBY_TOUCH_MIN)
        end
      end
      touch(lb.btnReady and lb.btnReady.text, "准备键")
      touch(lb.btnSolo and lb.btnSolo.text, "直接开始键")
    end
    add("lobby_text_fits", #probs == 0,
      #probs == 0 and "待机室全部文本控件高度够装字 + 按钮≥触摸下限"
                    or table.concat(probs, "; "))
  end

  -- 12-c 待机室文案非空自检（v2.0 块 2，Lead 要求）
  -- 【这条直接对应本轮 P0「整屏文字全丢、只有返回主菜单有字」】
  --   实测根因是三处独立的「建了控件但从来没写文案」：
  --     ① lb.title 从未赋值（mkLine 建时 text=""）
  --     ② lb.btnSolo 从未赋值（mkBtn 建时 text=""）
  --     ③ 两套结构混用（mkLine 返回控件、mkPlayerRow 返回表）导致写错层级
  --   text_fits 管「装不装得下」，这条管「有没有字」，互为补充。
  -- 【做法】不依赖 refresh_lobby 有没有被调用 —— 先强制刷一次，再逐个读回 text。
  do
    local probs = {}
    local lb = UI.lobby
    if lb == nil then
      probs[#probs + 1] = "UI.lobby 未建立"
    else
      -- 强制刷新一次（幂等），确保判的是「玩家实际会看到的内容」
      if refresh_lobby ~= nil then refresh_lobby() end
      -- 取某个控件的 text；分「控件本身」与「{text=控件} 包装」两种结构
      local function txtOf(ctrl, wrapped)
        if ctrl == nil then return nil end
        local c = wrapped and ctrl.text or ctrl
        if c == nil then return nil end
        return c.text
      end
      local checks = {
        { "标题",        txtOf(lb.title, false) },
        { "身份标注",    txtOf(lb.sideTag, false) },
        { "你 行",       txtOf(lb.rowMe, true) },
        { "对手 行",     txtOf(lb.rowOpp, true) },
        { "时间档行",    txtOf(lb.roomTc, false) },
        { "提示条",      txtOf(lb.hint, false) },
        { "底部提示",    txtOf(lb.footer, false) },
        { "返回主菜单",  txtOf(lb.backMain, false) },
        { "准备键",      txtOf(lb.btnReady, true) },
        { "直接开始键",  txtOf(lb.btnSolo, true) },
      }
      for i = 1, #checks do
        local name, v = checks[i][1], checks[i][2]
        if v == nil then
          probs[#probs + 1] = name .. " 无控件"
        elseif v == "" then
          probs[#probs + 1] = name .. " 文案为空"
        end
      end
      -- 倒数数字只在倒数中才有字，未倒数时允许为空 —— 单独判：倒数中必须非空
      local cd = txtOf(lb.countdown, false)
      if GAME.lobby.countdown >= 0 and (cd == nil or cd == "") then
        probs[#probs + 1] = "倒数中但倒数数字为空"
      end
    end
    add("lobby_texts_nonempty", #probs == 0,
      #probs == 0 and "待机室 10 个文本控件文案均非空"
                    or table.concat(probs, "; "))
  end

  -- 12-d 悔棋自检（v2.0 块 3）
  -- 【为什么断言这三类】每类都对应一次真实的踩坑风险：
  --   ① 契约值 H-4（每方 3 次 / 成对 2 步）—— 被改动必须立刻红
  --   ② 按钮文案非空且含「悔棋」—— 块 2「整屏空白」的同型风险：动态文案最容易漏刷
  --   ③ 计数初始化 —— 换局回满是 gdd §7.8 的硬要求，漏了会变成跨局累积
  do
    local probs = {}
    if CONFIG.UNDO_PER_SIDE ~= 3 then
      probs[#probs + 1] = "UNDO_PER_SIDE=" .. tostring(CONFIG.UNDO_PER_SIDE) .. "（应 3）"
    end
    if CONFIG.UNDO_PLIES ~= 1 then
      probs[#probs + 1] = "UNDO_PLIES=" .. tostring(CONFIG.UNDO_PLIES) .. "（应 1，v3.2 只撤自己刚走的一步）"
    end
    if UI.panel ~= nil and UI.panel.v2Undo ~= nil then
      -- 【v2.0 块 5 修：检查时机错了】
      -- 原实现无条件读 v2Undo.text 并断言非空。但 SelfTest 在 OnStart 末尾跑，
      -- 此时 screen == "start"，悔棋按钮本来就该隐藏且文案为空 —— 这**不是缺陷**。
      -- 断言错在「不看状态就要求有字」，制造了噪音。
      -- 【修法】按 screen 分两种期望：
      --   screen == playing → 必须可见且有「悔棋（剩 N）」文案
      --   其它界面         → 隐藏且文案为空是**正常**的，不报错
      local bakScreen = GAME.screen
      local bakReview = GAME.review
      local bakOver = GAME.over
      local bakU1 = GAME.undoLeft[1]
      GAME.screen = "playing"
      GAME.review = nil
      GAME.over = false
      GAME.undoLeft[1] = CONFIG.UNDO_PER_SIDE
      refresh_undo_button()
      local t = UI.panel.v2Undo.text
      local v = VIS_STATE[UI.panel.v2Undo]
      local shown = (v == true) or (v == nil and UI.panel.v2Undo.active == true)
      if not shown then
        probs[#probs + 1] = "对局中悔棋按钮不可见"
      end
      if t == nil or t == "" then
        probs[#probs + 1] = "对局中悔棋按钮文案为空"
      elseif not string.find(t, "悔棋", 1, true) then
        probs[#probs + 1] = "悔棋按钮文案不含「悔棋」: " .. tostring(t)
      end
      -- 还原并刷新回真实界面状态
      GAME.screen = bakScreen
      GAME.review = bakReview
      GAME.over = bakOver
      GAME.undoLeft[1] = bakU1
      refresh_undo_button()
    else
      probs[#probs + 1] = "UI.panel.v2Undo 未建立"
    end
    if GAME.undoLeft[1] == nil or GAME.undoLeft[2] == nil then
      probs[#probs + 1] = "undoLeft 未初始化"
    end
    -- 【v2.0 补：C-3 的两种文案必须都在，且语义正确】
    -- 0 步和 1 步都命中 C-3，但该说的话不同。共用一句会造成**事实错误**：
    -- 走 1 步时提示「开局还没走子」，玩家会怀疑按钮坏了。
    -- 【判据】两句都必须非空、且互不相同（若被误改成同一句，这条会红）。
    do
      local early = CONFIG.TEXT.UNDO_NO_EARLY
      local needTwo = CONFIG.TEXT.UNDO_NEED_TWO
      if type(early) ~= "string" or early == "" then
        probs[#probs + 1] = "UNDO_NO_EARLY 文案缺失"
      end
      if type(needTwo) ~= "string" or needTwo == "" then
        probs[#probs + 1] = "UNDO_NEED_TWO 文案缺失"
      end
      if early ~= nil and early == needTwo then
        probs[#probs + 1] = "UNDO_NO_EARLY 与 UNDO_NEED_TWO 文案相同（0 步/1 步无法区分）"
      end
      -- 走 1 步时的文案不能声称「还没走子」（事实错误）
      if type(needTwo) == "string" and string.find(needTwo, "还没走子", 1, true) then
        probs[#probs + 1] = "UNDO_NEED_TWO 含「还没走子」，走 1 步时是事实错误"
      end
    end
    add("undo_ready", #probs == 0,
      #probs == 0 and string.format("撤回=%d步 白剩=%d 黑剩=%d 按钮=\"%s\"",
        CONFIG.UNDO_PLIES, GAME.undoLeft[1] or -1, GAME.undoLeft[2] or -1,
        tostring(UI.panel and UI.panel.v2Undo and UI.panel.v2Undo.text))
                    or table.concat(probs, "; "))
  end

  -- 12-e 「悔棋必须回填 st.history」自检（v2.0 块 3，Lead 明确要求）
  -- 【为什么这条必须存在】这是全项目最阴险的一条：
  --   RULES.parse_fen 重建局面时会把 st.history（三次重复判定用的 position_key 序列）**清空**，
  --   而悔棋正是用 parse_fen 重建。漏了回填的后果是：
  --     悔棋之后这一局**再也判不出「三次重复」** —— 不报错、不崩、日志干净、截图正常，
  --     **功能静默消失**。这种缺陷只有断言能抓。
  -- 【怎么验】用真实局面走：parse_fen(开局) → 走 2 步 → 记下 st.history 长度
  --   → 再走 2 步 → 模拟成对撤回 → 断言 st.history 长度回到「2 步时」的值。
  --   全程在局部副本上做，**不碰 GAME.st**（自检不能改玩家局面）。
  do
    local probs = {}
    local okRun, msg = pcall(function()
      -- 在**局部副本**上验证，绝不碰 GAME.st（自检不能改玩家局面）
      local st = RULES.parse_fen(START_FEN)

      local function play(s, uci)
        local mv = RULES.find_move(s, uci)
        if mv == nil then return false end
        RULES.make(s, mv)
        return true
      end

      -- 走 2 步，记下当时的 FEN 与 key
      if not play(st, "e2e4") then return "e2e4 走不了" end
      if not play(st, "e7e5") then return "e7e5 走不了" end
      local fen2 = RULES.fen_of(st)
      local key2 = RULES.position_key(st)

      -- 再走 2 步
      if not play(st, "g1f3") then return "g1f3 走不了" end
      if not play(st, "b8c6") then return "b8c6 走不了" end

      -- 「成对撤回」= parse_fen 回 2 步局面（这正是 undo_apply_pair 的做法）
      local back = RULES.parse_fen(fen2)
      if back == nil then return "parse_fen 回退失败" end

      -- 【核心证据】parse_fen 之后 st.history 必须是空的 —— 这就是「必须回填」的证明
      if #back.history ~= 0 then
        return "意外：parse_fen 后 st.history 非空（" .. #back.history .. "），本断言前提不成立"
      end

      -- 按 undo_apply_pair 的写法回填，再确认能对上
      back.history[1] = key2
      if #back.history ~= 1 then
        return "回填后长度 " .. #back.history .. " 应为 1"
      end
      if RULES.position_key(back) ~= key2 then
        return "回填后 position_key 与快照不一致"
      end
      return nil   -- 全部通过
    end)

    if not okRun then
      -- pcall 捕获到运行期异常
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      -- 返回了错误字符串
      probs[#probs + 1] = tostring(msg)
    end
    add("undo_restores_position_history", #probs == 0,
      #probs == 0 and "parse_fen 清空 st.history 已确认，回填路径可还原 position_key"
                    or table.concat(probs, "; "))
  end

  -- 12-g 「黑白轮换是自反的」自检（v3.2）
  -- 【为什么必须断言】用户要求的「下一局黑白轮换」全靠 GAME.match.swap_sides：
  --   白⇄黑互换 + 视角跟着翻。这里有三个能静默坏掉的点：
  --     ① swap_sides 不是对合（调两次回不到原状）→ 连续换色会漂移成「一直执白」
  --     ② 没跟着翻视角 → 换色后玩家看到自己的棋跑到对方那边（正是用户抱怨的那类问题）
  --     ③ mySide 被写成 0 或 3 → 之后所有「我方/对方」判断全错
  --   这条断言把三点一次验完，且全程在**临时状态**上做、结束时还原。
  do
    local probs = {}
    local okRun, msg = pcall(function()
      local bakSide = GAME.mySide
      -- 【视角状态在 GAME.match.flip，不在 GAME.online.flip】
      --   我第一版读到 GAME.online.flip（那字段根本不存在，恒为 nil），
      --   于是断言 `O.flip ~= true` 永远成立 → 假红「换到黑方后视角没翻转(flip=nil)」。
      --   这是"读错字段"而不是功能缺陷；模拟器自检把它抓出来了，正好证明断言有效。
      local bakFlip = GAME.match.flip

      -- 用白方做样本：翻两次必须回到白
      GAME.mySide = 1
      GAME.match.swap_sides()
      if GAME.mySide ~= 2 then return "白→黑 失败，得到 " .. tostring(GAME.mySide) end
      -- 换到黑以后，视角必须是翻转的（黑棋在下）
      if GAME.match.flip ~= true then
        return "换到黑方后视角没翻转（flip=" .. tostring(GAME.match.flip) .. "）"
      end
      GAME.match.swap_sides()
      if GAME.mySide ~= 1 then return "黑→白 失败，得到 " .. tostring(GAME.mySide) end
      if GAME.match.flip ~= false then
        return "换回白方后视角没还原（flip=" .. tostring(GAME.match.flip) .. "）"
      end
      -- 黑方起步也要正确
      GAME.mySide = 2
      GAME.match.swap_sides()
      if GAME.mySide ~= 1 then return "黑→白 失败（起点黑）" end

      -- 还原（视角用 set_flip 写回，才能同时刷新坐标标注）
      GAME.mySide = bakSide
      GAME.match.set_flip(bakFlip == true)
      GAME.match.reposition()
      return nil
    end)
    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("result_side_swap", #probs == 0,
      #probs == 0 and "swap_sides 是自反对合，视角随之翻转"
                    or table.concat(probs, "; "))
  end

  -- 12-h 「复盘存档是深拷贝」自检（v3.2）
  -- 【为什么必须断言】「单人复盘练读取上一局存档」依赖 settle_match_record 把
  --   GAME.history **复制**一份留着。若哪天有人图省事改成 `GAME.lastArchived = GAME.history`
  --   （引用而非拷贝），下一局 new_game() 一清空 history，存档就跟着变空 ——
  --   表现是「刚打完一局，点复盘却是空的」，而且不报错、日志干净。
  do
    local probs = {}
    local okRun, msg = pcall(function()
      local bakArc = GAME.lastArchived
      local bakHist = GAME.history
      local bakLog = GAME.moveLog
      local bakResult = GAME.resultText
      local bakSettled = GAME.settled

      -- 造一局假的对局状态
      GAME.history = {
        { fen = START_FEN, text = "", capW = 0, capB = 0, clockW = 900, clockB = 900 },
        { fen = START_FEN, text = "白 e2→e4", from = 12, to = 28,
          capW = 0, capB = 0, clockW = 895, clockB = 900 },
      }
      GAME.moveLog = { "白 e2→e4" }
      GAME.resultText = CONFIG.TEXT.RESULT_WHITE_WIN
      GAME.settled = false
      local shBak = GAME.scoreHalf
      GAME.scoreHalf = { white = 0, black = 0 }
      settle_match_record()
      local arc = GAME.lastArchived
      if arc == nil then return "settle_match_record 没有生成存档" end
      if arc.history == nil or #arc.history ~= 2 then
        return "存档步数 " .. tostring(arc.history and #arc.history or -1) .. " 应为 2"
      end
      -- 关键：必须是不同的表（深拷贝），不能与 GAME.history 同引用
      if arc.history == GAME.history then
        return "存档与 GAME.history 是同一个表（引用而非拷贝），下一局会被清空"
      end
      -- 积分：白胜 → 白 +2 半分
      if GAME.scoreHalf.white ~= 2 then
        return "白胜后白方半分 " .. tostring(GAME.scoreHalf.white) .. " 应为 2"
      end
      -- 清空原 history 后存档必须还在（这就是「下一局还能复盘」的等价检验）
      GAME.history = { { fen = START_FEN, text = "" } }
      if #arc.history ~= 2 then return "清空 history 后存档也跟着变了（未深拷贝）" end

      GAME.lastArchived = bakArc
      GAME.history = bakHist
      GAME.moveLog = bakLog
      GAME.resultText = bakResult
      GAME.settled = bakSettled
      GAME.scoreHalf = shBak
      return nil
    end)
    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("result_archive_deepcopy", #probs == 0,
      #probs == 0 and "结算记账已深拷贝历史，下一局仍可复盘上一局"
                    or table.concat(probs, "; "))
  end

  -- 12-f 「待机室整层在对局中必须全隐藏」自检（v2.0 块 3，Lead 要求）
  -- 【这条直接对应本轮 P0】模拟器实测：走子后画面被待机室的空白骨架盖住
  --   （棋盘/棋子/面板全看不见，只剩两个白卡框 + 琥珀/浅灰色块）。
  --   根因**不是** parts 列表漏项 —— 那 12 处 part() 我逐项核过是全的；
  --   真因是 entry_start_local / entry_start_review 这两条「进对局」路径**漏调 hide_lobby()**。
  --   → 教训：「列表完整」和「每条路径都调了」是两件事，断言必须查**后者**。
  -- 【判据】screen 为 playing/review 时，UI.lobby 的每个 part 都必须 active ~= true；
  --   screen 为 lobby 时反之必须全 active。双向都查，才是真的守住了层级。
  do
    local probs = {}
    local lb = UI.lobby
    if lb == nil then
      probs[#probs + 1] = "UI.lobby 未建立"
    elseif lb.parts == nil or #lb.parts == 0 then
      probs[#probs + 1] = "UI.lobby.parts 为空"
    else
      if GAME.screen == "playing" or GAME.screen == "review" then
        local leaked = {}
        for i = 1, #lb.parts do
          local c = lb.parts[i]
          if c ~= nil then
            -- 【双重判据】优先用脚本侧权威缓存 VIS_STATE（写时维护、不会被平台读回误导），
            -- 再与控件 .active 交叉验证。任一判定为「仍可见」即算泄漏。
            -- 只用 .active 的风险：平台若读不回该字段会永远 nil，断言就假绿了。
            local v = VIS_STATE[c]
            local visible = (v == true) or (c.active == true)
            if visible then leaked[#leaked + 1] = i end
          end
        end
        if #leaked > 0 then
          probs[#probs + 1] = string.format("screen=%s 但待机室 %d/%d 个 part 仍 active（前几个: %s）",
            tostring(GAME.screen), #leaked, #lb.parts,
            table.concat(leaked, ",", math.min(#leaked, 6)))
        end
      elseif GAME.screen == "lobby" then
        local hidden = 0
        for i = 1, #lb.parts do
          local c = lb.parts[i]
          if c ~= nil then
            local v = VIS_STATE[c]
            local visible = (v == true) or (v == nil and c.active == true)
            if not visible then hidden = hidden + 1 end
          end
        end
        if hidden > 0 then
          probs[#probs + 1] = string.format("screen=lobby 但 %d/%d 个 part 未显示", hidden, #lb.parts)
        end
      end
      if #lb.parts < 12 then
        probs[#probs + 1] = "parts 只有 " .. #lb.parts .. " 项（预期 ≥12）"
      end
    end
    add("lobby_hidden_in_play", #probs == 0,
      #probs == 0 and string.format("screen=%s parts=%d 层级状态正确",
        tostring(GAME.screen), UI.lobby and #UI.lobby.parts or -1)
                    or table.concat(probs, "; "))
  end

  -- 12-g 悔棋按钮状态机自检（v2.0 块 3，Lead 要求）
  -- 【这条直接对应 D-1】模拟器实测：悔棋成功后面板第三行变回「看历史」，
  --   而当时仍在对局中、次数应为 2 —— 正确行为是显示「悔棋（剩 2）」并置灰。
  --   根因是「不可悔」与「不显示悔棋」被写成了同一个判断。
  -- 【判据】把 GAME 的相关字段**临时改掉**、跑 refresh_undo_button()、读回结果，
  --   最后**必须完整还原**（自检不能污染玩家状态）。
  --   四个状态：对局中次数>0 可点 / 对局中次数>0 但 history 不足 置灰 /
  --             对局中次数==0 置灰且文案「悔棋（剩 0）」/ 非对局 → 让位给看历史
  do
    local probs = {}
    local b = UI.panel
    if b == nil or b.v2Undo == nil then
      probs[#probs + 1] = "UI.panel.v2Undo 未建立"
    elseif UI.review == nil or UI.review.btnToggle == nil then
      probs[#probs + 1] = "UI.review.btnToggle 未建立"
    else
      -- 备份全部将被改动的字段
      local bak = {
        screen = GAME.screen,
        review = GAME.review,
        left1 = GAME.undoLeft[1],
        left2 = GAME.undoLeft[2],
        localMode = GAME.localMode,
        mySide = GAME.mySide,
      }
      local histBak = GAME.history
      local function restoreAll()
        GAME.screen = bak.screen
        GAME.review = bak.review
        GAME.undoLeft[1] = bak.left1
        GAME.undoLeft[2] = bak.left2
        GAME.localMode = bak.localMode
        GAME.mySide = bak.mySide
        GAME.history = histBak
        if refresh_undo_button ~= nil then refresh_undo_button() end
      end

      local function check(label, wantTxt, wantUndoVisible)
        refresh_undo_button()
        local txt = b.v2Undo.text
        local un = VIS_STATE[b.v2Undo]
        local shown = (un == true) or (un == nil and b.v2Undo.active == true)
        if shown ~= wantUndoVisible then
          probs[#probs + 1] = string.format("%s：悔棋可见=%s 应为 %s",
            label, tostring(shown), tostring(wantUndoVisible))
        end
        if wantTxt ~= nil and txt ~= wantTxt then
          probs[#probs + 1] = string.format("%s：文案=\"%s\" 应为 \"%s\"", label, tostring(txt), wantTxt)
        end
      end

      -- 造一个「对局中且走满 2 步」的历史（局部副本，不动真实 GAME.history 的内容）
      local fakeHist = {}
      for i = 1, 3 do fakeHist[i] = histBak[math.min(i, #histBak)] end

      -- 【v3.2 关键：固定「谁是悔棋发起方」】
      --   v3.2 起 undo_actor_side() 的语义是「**最后一步的走子方**」：
      --     · localMode == true  → 按轮次反推（轮到白 ⇒ 刚走完的是黑 = 2）
      --     · localMode == false → 用 GAME.mySide
      --   本测试的期望值都是「白方次数」（undoLeft[1]），所以必须让发起方确实是白：
      --   用联机形态（localMode=false + mySide=1）最直接。
      --   【踩过的坑】最初没固定这两个字段，自检跑在 start 界面、localMode 还是
      --   进入对局前的值，undo_actor_side() 返回了 2 → 按钮读的是 undoLeft[2]，
      --   于是「剩 3/2/0」三档全部显示成「悔棋（剩 3）」——模拟器实测正是这个现象。
      GAME.localMode = false
      GAME.mySide = 1

      -- ① 对局中 + 次数 3 + 历史满 → 显示「悔棋（剩 3）」
      GAME.screen = "playing"; GAME.review = nil
      GAME.undoLeft[1] = 3; GAME.undoLeft[2] = 3
      GAME.history = fakeHist
      check("对局中·剩3", string.gsub(CONFIG.TEXT.UNDO_BTN, "{n}", "3"), true)

      -- ② 对局中 + 次数 2（悔过一次）→ **仍显示「悔棋（剩 2）」，绝不能变看历史**
      GAME.undoLeft[1] = 2
      check("对局中·剩2", string.gsub(CONFIG.TEXT.UNDO_BTN, "{n}", "2"), true)

      -- ③ 对局中 + 次数 0 → 仍显示「悔棋（剩 0）」且仍可见（置灰由颜色表达）
      GAME.undoLeft[1] = 0
      check("对局中·剩0", string.gsub(CONFIG.TEXT.UNDO_BTN, "{n}", "0"), true)

      -- ④ 非对局（复盘）→ 悔棋让位给「退出复盘」
      GAME.screen = "review"
      check("复盘中", nil, false)

      restoreAll()
    end
    add("undo_button_state_machine", #probs == 0,
      #probs == 0 and "对局中恒显示悔棋（剩 N）/ 非对局让位给看历史"
                    or table.concat(probs, "; "))
  end

  -- 12-h 【v3.3 改写】复盘只读自检
  -- 【原文】这条原本是「分支试走不污染主变」（v2.0 块 4）。
  --   分支试走本轮已整体移除（用户要删「退回主变」，而它是分支的唯一出口）。
  -- 【保留它的理由】「复盘不能改棋」这个**保障**依然是最容易被做错的地方 ——
  --   最省事的错法是把 set_board_input(true) 加回去，或在 on_square_clicked 里
  --   漏掉 `if GAME.review ~= nil then return end` 那道闸，结果是「复盘点棋子真的走棋」。
  -- 【验法】造一局 4 手的副本 → 进复盘停在第 2 步 → 模拟点击棋子 →
  --   断言 history 长度、GAME.st 的 FEN、review.idx 全都没变。
  do
    local probs = {}
    local bak = {
      history = GAME.history,
      st = GAME.st,
      review = GAME.review,
      reviewState = GAME.reviewState,
      screen = GAME.screen,
      selected = GAME.selected,
    }
    local okRun, msg = pcall(function()
      local st = RULES.parse_fen(START_FEN)
      local hist = {}
      local function snapOf(s, text)
        return { fen = RULES.fen_of(s), text = text or "", from = nil, to = nil,
                 capW = 0, capB = 0, clockW = 900, clockB = 900 }
      end
      hist[1] = snapOf(st, "")
      local seq = { "e2e4", "e7e5", "g1f3", "b8c6" }
      for i = 1, #seq do
        local mv = RULES.find_move(st, seq[i])
        if mv == nil then return seq[i] .. " 走不了" end
        RULES.make(st, mv)
        hist[#hist + 1] = snapOf(st, seq[i])
      end
      local mainFen = RULES.fen_of(st)
      local mainLen = #hist

      -- ② 进复盘，停在第 2 步
      GAME.history = hist
      GAME.st = st
      GAME.review = { idx = 2, allowEmpty = false }
      GAME.reviewState = RULES.parse_fen(hist[3].fen)

      -- ③ 模拟点击「白方 e 兵」所在格（e2 = 12，0-based rank*8+file：e2 → 4*8+1 = 33）
      --   只要那道闸生效，这次点击必须什么都不做。
      on_square_clicked(33)

      -- ④ 三条断言：主变长度 / 主变最后一步 FEN / 真实局面 FEN 全未变
      if #GAME.history ~= mainLen then
        return string.format("复盘被写入了历史：%d → %d", mainLen, #GAME.history)
      end
      if GAME.history[mainLen].fen ~= mainFen then
        return "复盘改动了主变最后一步"
      end
      if RULES.fen_of(GAME.st) ~= mainFen then
        return "复盘点击污染了真实局面 GAME.st"
      end
      -- ⑤ 选中态不得被建立（证明点击确实被拦在最外层）
      if GAME.selected ~= nil then
        return "复盘点击建立了选中态（说明闸没拦住）"
      end
      return nil
    end)

    GAME.history = bak.history
    GAME.st = bak.st
    GAME.review = bak.review
    GAME.reviewState = bak.reviewState
    GAME.screen = bak.screen
    GAME.selected = bak.selected

    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("review_is_readonly", #probs == 0,
      #probs == 0 and "复盘只读：点棋子不改历史 / 不改局面 / 不建选中态"
                    or table.concat(probs, "; "))
  end

  -- 12-i 【v3.3 删除】复盘动作条显隐自检
  -- 动作条（退回主变 / 从此开新局）整体移除后，没有控件可测了。
  -- 【为什么不留一条空断言】留一条「恒真」的断言只会让自检条数虚高，
  --   读日志的人会以为这里还有东西在被守护。宁可减少一条。

  -- 12-j 【v3.3 改写】复盘翻页不进绘制循环
  -- 【原文】这条测的是「分支高亮不进绘制循环」（v2.0 块 4，proto-lead 性能纪律）。
  --   分支已移除。但那条纪律本身仍然成立且重要：复盘翻页 review_goto 会调
  --   review_render → render_pieces 全量重绘，这是**一次性**开销。
  --   一旦有人把 render_pieces 放进 OnUpdate，控件写会从「每次翻页几千」变成「每帧几千」，
  --   一秒钟就是十几万次 —— 正是 v1.10「动画不跟手」的成因。
  -- 【验法】把指针从第 0 步跳到第 2 步，量这一次翻页的控件写。
  do
    local probs = {}
    local okRun, msg = pcall(function()
      if GetRepaintStats == nil or ResetRepaintStats == nil then
        return "GetRepaintStats/ResetRepaintStats 不存在"
      end
      local bak = {
        history = GAME.history, st = GAME.st,
        review = GAME.review, reviewState = GAME.reviewState,
        screen = GAME.screen,
      }
      local st = RULES.parse_fen(START_FEN)
      local hist = { { fen = RULES.fen_of(st), text = "", from = nil, to = nil,
                       capW = 0, capB = 0, clockW = 900, clockB = 900 } }
      for _, uci in ipairs({ "e2e4", "e7e5" }) do
        local mv = RULES.find_move(st, uci)
        if mv == nil then
          GAME.history = bak.history; GAME.st = bak.st
          return uci .. " 走不了"
        end
        RULES.make(st, mv)
        hist[#hist + 1] = { fen = RULES.fen_of(st), text = uci, from = nil, to = nil,
                            capW = 0, capB = 0, clockW = 900, clockB = 900 }
      end
      GAME.history = hist
      GAME.st = st
      GAME.review = { idx = 0, allowEmpty = false }
      GAME.reviewState = RULES.parse_fen(hist[1].fen)

      ResetRepaintStats()
      review_goto(2, nil)                  -- 0 → 2，触发一次完整重绘
      local wJump = GetRepaintStats().ctrlWrites

      GAME.history = bak.history; GAME.st = bak.st
      GAME.review = bak.review; GAME.reviewState = bak.reviewState
      GAME.screen = bak.screen

      if wJump == nil then return "GetRepaintStats 返回值异常" end
      -- 【阈值 5000 的依据】一次 render_pieces 全量 ≈ 32 槽 × ~79 写 ≈ 2500。
      --   5000 给足余量（翻页还会刷棋钟/提示/吃子区）。
      --   若误入绘制循环，60fps 下一秒就是 15 万级，差两个数量级，抓得住。
      local SEG_MAX = 5000
      if wJump > SEG_MAX then
        return string.format("复盘翻页控件写 %d > %d（疑似每帧重绘）", wJump, SEG_MAX)
      end
      GAME.__lastPaintBreakdown = string.format("复盘翻页=%d", wJump)
      return nil
    end)
    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("review_nav_not_in_paint_loop", #probs == 0,
      #probs == 0 and ("复盘翻页控件写: " .. tostring(GAME.__lastPaintBreakdown) ..
                       "（≤5000；每帧重绘会到十万级）")
                    or table.concat(probs, "; "))
  end

  -- 12-k 联机悔棋完整时序自检（v2.0 块 5，Lead 要求）
  -- 【覆盖三条最易做错的路径】每条都按「A 不应改变 B + A 确实做了事」双重判据：
  --   ① 发起方请求后：本地局面**未变**  且 确实置了 pendingUndo.byMe
  --   ② 收到 ACC：局面**回退两步**    且 次数 -1
  --   ③ 收到 NO ：局面**完全未变**    且 次数未扣 且 pendingUndo 已清
  -- 【为什么必须验 ①】「发起方本地先撤」是 gdd §7.5 明令禁止的，
  --   因为它会在对方拒绝时造成局面分叉。但如果不测，写错了看不出来 —— 请求发出去那一刻画面不变才是对的。
  do
    local probs = {}
    local okRun, msg = pcall(function()
      if net_on_signal == nil then return "net_on_signal 不存在" end
      if undo_apply_pair == nil then return "undo_apply_pair 不存在" end
      -- 【前置条件】net_on_signal 第一行就是 `if GAME.state ~= "RUNNING" then return end`。
      -- 若 state 不是 RUNNING，所有信号都会被静默丢弃 → 本断言会「通过」因为局面确实没变。
      -- 那正是最危险的假绿。所以这里显式检查，不满足就明确报错。
      if GAME.state ~= "RUNNING" then
        return "前置条件不成立：GAME.state=" .. tostring(GAME.state) .. "（信号会被丢弃）"
      end
      -- 备份
      local bak = {
        history = GAME.history, st = GAME.st, screen = GAME.screen,
        review = GAME.review, reviewState = GAME.reviewState,
        over = GAME.over,
        pendingUndo = GAME.pendingUndo, localMode = GAME.localMode,
        mySide = GAME.mySide,
        u1 = GAME.undoLeft[1], u2 = GAME.undoLeft[2],
        clockW = GAME.clockWhite, clockB = GAME.clockBlack,
        moveLog = GAME.moveLog,
        capW = GAME.capturedWhite, capB = GAME.capturedBlack,
        selected = GAME.selected, legalTargets = GAME.legalTargets,
        legalMoves = GAME.legalMoves,
      }
      local function restore()
        GAME.history = bak.history; GAME.st = bak.st; GAME.screen = bak.screen
        GAME.review = bak.review; GAME.reviewState = bak.reviewState
        GAME.over = bak.over
        GAME.pendingUndo = bak.pendingUndo; GAME.localMode = bak.localMode
        GAME.mySide = bak.mySide
        GAME.undoLeft[1] = bak.u1; GAME.undoLeft[2] = bak.u2
        GAME.clockWhite = bak.clockW; GAME.clockBlack = bak.clockB
        GAME.moveLog = bak.moveLog
        GAME.capturedWhite = bak.capW; GAME.capturedBlack = bak.capB
        GAME.selected = bak.selected; GAME.legalTargets = bak.legalTargets
        GAME.legalMoves = bak.legalMoves
      end
      -- 造一局「走了 4 步」的真实状态
      local st = RULES.parse_fen(START_FEN)
      local hist = { { fen = RULES.fen_of(st), text = "", from = nil, to = nil,
                       capW = 0, capB = 0, clockW = 900, clockB = 900 } }
      local log = {}
      for _, uci in ipairs({ "e2e4", "e7e5", "g1f3", "b8c6" }) do
        local mv = RULES.find_move(st, uci)
        if mv == nil then restore(); return uci .. " 走不了" end
        RULES.make(st, mv)
        log[#log + 1] = uci
        hist[#hist + 1] = { fen = RULES.fen_of(st), text = uci, from = nil, to = nil,
                            capW = 0, capB = 0, clockW = 900, clockB = 900 }
      end
      local function setUp()
        GAME.history = {}
        for i = 1, #hist do GAME.history[i] = hist[i] end
        GAME.st = RULES.parse_fen(hist[#hist].fen)
        GAME.screen = "playing"; GAME.review = nil; GAME.reviewState = nil
        GAME.over = false
        GAME.pendingUndo = nil; GAME.localMode = false; GAME.mySide = 1
        GAME.undoLeft[1] = 3; GAME.undoLeft[2] = 3
        GAME.clockWhite = 900; GAME.clockBlack = 900
        GAME.moveLog = log
        GAME.capturedWhite = {}; GAME.capturedBlack = {}
        GAME.selected = nil; GAME.legalTargets = {}; GAME.legalMoves = {}
      end

      -- ===== ① 发起方请求：本地局面必须未变 =====
      setUp()
      local fenBefore = RULES.fen_of(GAME.st)
      local lenBefore = #GAME.history
      -- 模拟「点了确认悔棋」的联机分支（不本地先撤，只置标记）
      GAME.pendingUndo = { byMe = true, t = 0 }
      -- 「A 确实做了事」：pendingUndo 必须真的被置上
      if GAME.pendingUndo == nil or GAME.pendingUndo.byMe ~= true then
        restore(); return "① 未能置 pendingUndo.byMe"
      end
      -- 「A 不应改变 B」：局面/次数/历史长度都不能变
      if RULES.fen_of(GAME.st) ~= fenBefore then
        restore(); return "① 发起请求时本地局面被改了（违反 gdd §7.5）"
      end
      if #GAME.history ~= lenBefore then
        restore(); return string.format("① 发起请求时 history %d → %d", lenBefore, #GAME.history)
      end
      if GAME.undoLeft[1] ~= 3 then
        restore(); return "① 发起请求时次数被提前扣了：" .. tostring(GAME.undoLeft[1])
      end

      -- ===== ② 收到 EV_UNDO_ACC：局面回退 CONFIG.UNDO_PLIES 步 + 次数 -1 =====
      -- 【v3.2】回退步数从写死的 2 改成读 CONFIG.UNDO_PLIES（现在 = 1）。
      --   原来这里写 `lenBefore - 2`，语义改成撤 1 步后立刻假红
      --   （模拟器实测：「② ACC 后 history 应为 3，实际 4」）—— 而实际行为是对的。
      --   【教训】断言里不要写死与 CONFIG 重复的字面量，改配置时会被自己的断言咬。
      net_on_signal(CONFIG.SIGNAL_NAME, { CONFIG.EV_UNDO_ACC, 1, 0, 0, "" })
      local lenAfterAcc = #GAME.history
      local wantLen = lenBefore - CONFIG.UNDO_PLIES
      if lenAfterAcc ~= wantLen then
        restore(); return string.format("② ACC 后 history 应为 %d，实际 %d", wantLen, lenAfterAcc)
      end
      if RULES.fen_of(GAME.st) == fenBefore then
        restore(); return "② ACC 后局面没有回退"
      end
      if GAME.undoLeft[1] ~= 2 then
        restore(); return "② ACC 后发起方次数应为 2，实际 " .. tostring(GAME.undoLeft[1])
      end
      if GAME.pendingUndo ~= nil then
        restore(); return "② ACC 后 pendingUndo 未清空"
      end

      -- ===== ③ 收到 EV_UNDO_NO：局面完全未变 + 次数未扣 =====
      setUp()
      local fenNo = RULES.fen_of(GAME.st)
      local lenNo = #GAME.history
      GAME.pendingUndo = { byMe = true, t = 0 }     -- 先有请求（「确实发生了一次请求」）
      local hadPending = (GAME.pendingUndo ~= nil)
      net_on_signal(CONFIG.SIGNAL_NAME, { CONFIG.EV_UNDO_NO, 1, 0, 0, "" })
      if not hadPending then
        restore(); return "③ 前提不成立：请求标记没置上"
      end
      if GAME.pendingUndo ~= nil then
        restore(); return "③ NO 后 pendingUndo 未清空"
      end
      if RULES.fen_of(GAME.st) ~= fenNo then
        restore(); return "③ NO 后局面被改了"
      end
      if #GAME.history ~= lenNo then
        restore(); return string.format("③ NO 后 history %d → %d", lenNo, #GAME.history)
      end
      if GAME.undoLeft[1] ~= 3 then
        restore(); return "③ NO 后次数被扣了：" .. tostring(GAME.undoLeft[1])
      end
      restore()
      return nil
    end)
    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("online_undo_sequence", #probs == 0,
      #probs == 0 and "请求时不本地先撤 / ACC 回退两步并扣次数 / NO 全不变且不扣次数"
                    or table.concat(probs, "; "))
  end

  -- 12-l 「先选者生效」自检（v2.0 块 5，Lead 要求）
  -- 【判据】EV_READY 的 b 带档位号。本地未锁定时应采用对方档位并锁定；
  --   本地已锁定时**必须忽略**对方的档位（否则两端档位会打架，开局后棋钟不一致）。
  -- 【双重判据（按本项目的假绿纪律）】
  --   ① 未锁定 → 档位**确实变了** + tcLocked 变 true + tcOwner 变 2
  --   ② 已锁定 → 档位**确实没变**（而且要证明「确实收到了一个不同档位号的包」，
  --      否则「没变」可能只是因为压根没处理这条信号）
  do
    local probs = {}
    local okRun, msg = pcall(function()
      if net_on_signal == nil then return "net_on_signal 不存在" end
      if apply_time_control == nil then return "apply_time_control 不存在" end
      -- 【同一类假绿防线】信号处理会被 GAME.state 守卫挡住，先确认它成立
      if GAME.state ~= "RUNNING" then
        return "前置条件不成立：GAME.state=" .. tostring(GAME.state)
      end
      local G = GAME.lobby
      local bak = {
        tcN = GAME.tcN, tcInitial = GAME.tcInitial, tcIncrement = GAME.tcIncrement,
        tcLocked = G.tcLocked, tcOwner = G.tcOwner, peerReady = G.peerReady,
        peerSeen = G.peerSeen, peerSeenAt = G.peerSeenAt,
        screen = GAME.screen, myReady = G.myReady,
      }
      local function restore()
        GAME.tcN = bak.tcN; GAME.tcInitial = bak.tcInitial; GAME.tcIncrement = bak.tcIncrement
        G.tcLocked = bak.tcLocked; G.tcOwner = bak.tcOwner; G.peerReady = bak.peerReady
        G.peerSeen = bak.peerSeen; G.peerSeenAt = bak.peerSeenAt
        GAME.screen = bak.screen; G.myReady = bak.myReady
      end

      -- 选两个**不同**的档位号，确保「变了」是可观测的
      local mine, theirs = 3, 1
      if theirs == mine then theirs = 2 end

      -- ① 未锁定 → 应采用对方档位
      GAME.screen = "lobby"
      G.tcLocked = false
      G.tcOwner = 1
      apply_time_control(mine)
      local before = GAME.tcN
      net_on_signal(CONFIG.SIGNAL_NAME, { CONFIG.EV_READY, 1, theirs, 0, "" })
      if GAME.tcN == before then
        restore(); return string.format("① 未锁定时未采用对方档位（仍是 %d）", GAME.tcN)
      end
      if GAME.tcN ~= theirs then
        restore(); return string.format("① 档位应为 %d，实际 %d", theirs, GAME.tcN)
      end
      if not G.tcLocked then
        restore(); return "① 采用对方档位后未锁定"
      end
      if G.tcOwner ~= 2 then
        restore(); return "① tcOwner 应为 2（对方选的），实际 " .. tostring(G.tcOwner)
      end

      -- ② 已锁定 → 必须忽略对方的档位
      GAME.screen = "lobby"
      G.tcLocked = true
      G.tcOwner = 1
      apply_time_control(mine)
      local lockedN = GAME.tcN
      -- 【关键】确保证明确实处理了这条信号：把 peerReady 设成相反值，
      -- 若信号被处理，peerReady 会被改成 true（a=1）
      G.peerReady = false
      net_on_signal(CONFIG.SIGNAL_NAME, { CONFIG.EV_READY, 1, theirs, 0, "" })
      if G.peerReady ~= true then
        restore(); return "② 信号未被处理（peerReady 仍为 false），本条断言无意义"
      end
      if GAME.tcN ~= lockedN then
        restore(); return string.format("② 已锁定时档位被覆盖：%d → %d", lockedN, GAME.tcN)
      end
      if G.tcOwner ~= 1 then
        restore(); return "② 已锁定时 tcOwner 被改成 " .. tostring(G.tcOwner)
      end
      restore()
      return nil
    end)
    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("ev_ready_ignores_when_locked", #probs == 0,
      #probs == 0 and "未锁定采用对方档位并锁定 / 已锁定忽略对方档位（且有信号确实被处理的证据）"
                    or table.concat(probs, "; "))
  end

  -- 12-m 单人兜底不被信号阻塞（v2.0 块 5，Lead 要求）
  -- 【为什么必须有】块 2 立下「绝不让人卡死在等待里」的纪律。
  -- 块 5 加了信号后，如果 net_send 失败会抛错、或逻辑依赖「收到对方包」才推进，
  -- 单人可玩性就被破坏了。这条守住它。
  -- 【判据】四条独立路径都要能走：
  --   ① 信号被自检闸拦住时不抛错
  --   ② 待机室「直接开始」的可用性不依赖任何网络能力标志
  --   ③ NET.canSend == false（真机断线/未搭节点图）时不抛错且返回 false
  --   ④ 单一方 ready 时绝不自动开局（见独立断言 solo_ready_never_auto_starts）
  do
    local probs = {}
    -- ① net_send_event 在无法发送时必须安全返回（不能抛错）
    -- 【v2.0 块 5 修：原实现会真的发包】
    -- 原来这里直接调 net_send_event 两个真事件，真机上会广播给所有玩家。
    -- 现在 GAME.inSelfTest 闸拦住了实际发送（见 net_send_event 开头），
    -- 这里仍然调一次，目的是验证「被拦截时不抛错、返回 false」这条路本身是干净的。
    if net_send_event == nil then
      probs[#probs + 1] = "net_send_event 不存在"
    else
      local okSend, retSend, errSend = pcall(function()
        local r1 = net_send_event(CONFIG.EV_READY, 1, 3, 0, "")
        local r2 = net_send_event(CONFIG.EV_START, 0, 3, 0, "")
        return (r1 == false and r2 == false)
      end)
      if not okSend then
        probs[#probs + 1] = "net_send_event 抛错: " .. tostring(retSend or errSend)
      elseif retSend ~= true then
        -- 自检期间必须被拦住（返回 false）。若真发出去了，说明闸失效。
        probs[#probs + 1] = "自检期间 net_send_event 没有被拦截（闸失效，会污染真实联机）"
      end
    end
    -- ② 「直接开始」按钮的命中区必须存在且登记过（可点，不依赖网络）
    -- 【v2.0 块 5 修：字段路径写错了】
    -- 原断言查 `lb.hitSolo`，但 mkBtn 的命名约定是 **lb[key] = { text, edge, hit }**，
    -- 即命中区是 `lb.btnSolo.hit`，不是 `lb.hitSolo`。查一个不存在的字段必然 nil → 假红。
    -- 【教训】断言本身也会写错字段路径，制造「看起来像真 bug」的噪音。
    --   这条的价值在于：**它证明「直接开始」这层此前没有断言覆盖**，
    --   所以我把它写成**双向**检查（控件在 + 命中区在 + 文案非空），一次覆盖到位。
    local lb = UI.lobby
    if lb == nil or lb.btnSolo == nil then
      probs[#probs + 1] = "「直接开始」按钮控件缺失（lb.btnSolo）"
    else
      if lb.btnSolo.text == nil then
        probs[#probs + 1] = "「直接开始」按钮文本控件缺失（lb.btnSolo.text）"
      elseif lb.btnSolo.text.text == nil or lb.btnSolo.text.text == "" then
        probs[#probs + 1] = "「直接开始」按钮文案为空"
      end
      if lb.btnSolo.hit == nil then
        probs[#probs + 1] = "「直接开始」命中区缺失（lb.btnSolo.hit）"
      end
    end
    -- ③ 【v2.0 方案 T：原来的 LOBBY_START_GRACE_SEC 校验已删除】
    -- 那个常量随「倒数结束立即本地开局」的裁决一起删掉了（它已无任何引用）。
    -- 改为校验真正的单人兜底常量 —— 它才是「一个人待在房间里多久后提示」的依据。
    if type(CONFIG.LOBBY_PEER_TIMEOUT_SEC) ~= "number"
       or CONFIG.LOBBY_PEER_TIMEOUT_SEC <= 0 then
      probs[#probs + 1] = "LOBBY_PEER_TIMEOUT_SEC 未配置或非正数"
    end
    -- ④ 【v2.0 块 5 新增：真正的降级路径】NET.canSend == false 时不抛错、返回 false
    -- 【为什么这条比 ① 更有业务价值】① 验的是「自检闸生效」（内部安全机制），
    --   而这一条验的是**真机断线/未搭节点图时的真实场景**：
    --   联机能力探测失败 → NET.canSend 恒 false → 所有 net_send_event 调用都走这条路。
    --   这条路一旦抛错，玩家点「准备」「认输」「悔棋」都会崩。
    --   两者互补：inSelfTest 闸守「自检不污染」，NET.canSend 守「断线不崩」。
    if NET == nil then
      probs[#probs + 1] = "NET 表不存在"
    elseif net_send_event == nil then
      probs[#probs + 1] = "net_send_event 不存在"
    else
      local bakCanSend = NET.canSend
      NET.canSend = false
      local okDegrade, rDegrade = pcall(function()
        return net_send_event(CONFIG.EV_READY, 1, 3, 0, "")
      end)
      NET.canSend = bakCanSend          -- 无论成败都还原
      if not okDegrade then
        probs[#probs + 1] = "NET.canSend=false 时抛错: " .. tostring(rDegrade)
      elseif rDegrade ~= false then
        probs[#probs + 1] = "NET.canSend=false 时应返回 false，实际 " .. tostring(rDegrade)
      end
    end
    add("lobby_solo_not_blocked_by_signals", #probs == 0,
      #probs == 0 and string.format("网闸安全 / 直接开始可用 / 断线降级安全 / 单人超时提示 %.1f 秒",
        CONFIG.LOBBY_PEER_TIMEOUT_SEC)
                    or table.concat(probs, "; "))
  end

  -- 12-p 方案 T：自发包 token 过滤回声（v2.0，Lead 指定核心验收）
  -- 【这条守什么】服务端把信号广播回发送者自己，而官方 API **不提供发送者身份**
  --   （已查《客户端控件API文档》全文：playerIndex / GetPlayerIndex / selfPlayer 都不存在）。
  --   所以只能靠「这是不是我发的」来识别回声 —— 即发送时埋 token，收到时比对。
  -- 【曾经的真 bug】块 5 第一版直接 `G.peerReady = (a == 1)`，注释还写着「本条幂等」
  --   → 玩家2 点准备，自己的包播回来把 peerReady 置 true
  --   → 与本端 myReady 构成假的「双方就绪」→ 玩家1 没点准备也被拉进对局。
  -- 【三重判据】
  --   ① 收到自己的 token → peerReady 保持 false（回声被丢弃）
  --   ② 收到别人的 token → peerReady 变 true
  --   ③ **防假绿**：② 里必须同时断言 peerSeen 变 true（证明信号确实被处理了，
  --      而不是因为 handler 整个没跑才「没变化」）
  do
    local probs = {}
    local okRun, msg = pcall(function()
      if net_on_signal == nil then return "net_on_signal 不存在" end
      if make_self_token == nil then return "make_self_token 不存在" end
      if GAME.state ~= "RUNNING" then
        return "前置条件不成立：GAME.state=" .. tostring(GAME.state)
      end
      local G = GAME.lobby
      local bak = {
        peerReady = G.peerReady, peerSeen = G.peerSeen, peerSeenAt = G.peerSeenAt,
        tcLocked = G.tcLocked, tcOwner = G.tcOwner,
        tok = GAME.__myReadyToken, screen = GAME.screen,
        tcN = GAME.tcN, tcInitial = GAME.tcInitial, tcIncrement = GAME.tcIncrement,
      }
      local function restore()
        G.peerReady = bak.peerReady; G.peerSeen = bak.peerSeen
        G.peerSeenAt = bak.peerSeenAt; G.tcLocked = bak.tcLocked; G.tcOwner = bak.tcOwner
        GAME.__myReadyToken = bak.tok; GAME.screen = bak.screen
        GAME.tcN = bak.tcN; GAME.tcInitial = bak.tcInitial
        GAME.tcIncrement = bak.tcIncrement
      end

      -- ① 回声：fen == 自己的 token → peerReady 必须保持 false
      GAME.screen = "lobby"
      G.peerReady = false
      G.peerSeen = false
      G.tcLocked = true                 -- 锁住档位，避免被副作用干扰
      local mine = "SELF.TOKEN#1"
      GAME.__myReadyToken = mine
      net_on_signal(CONFIG.SIGNAL_NAME, { CONFIG.EV_READY, 1, 0, 0, mine })
      if G.peerReady ~= false then
        restore()
        return "① 收到自己的 token 却把 peerReady 置成了 true（回声污染回归）"
      end

      -- ② 对方的包：fen != 自己的 token → peerReady 变 true
      G.peerReady = false
      G.peerSeen = false
      GAME.__myReadyToken = mine
      net_on_signal(CONFIG.SIGNAL_NAME, { CONFIG.EV_READY, 1, 0, 0, "OTHER.TOKEN#2" })
      if G.peerReady ~= true then
        restore()
        return "② 收到对方的包却没有置 peerReady"
      end
      -- ③ 防假绿：证明这条路真的被处理了
      if G.peerSeen ~= true then
        restore()
        return "② 信号似乎未被处理（peerSeen 仍 false），本条断言无意义"
      end

      restore()
      return nil
    end)
    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("ready_token_filters_echo", #probs == 0,
      #probs == 0 and "自己的 token 被识别为回声（peerReady 不变）/ 对方的包正常置位"
                    or table.concat(probs, "; "))
  end

  -- 12-q 单一方 ready 绝不自动开局（v2.0，Lead 裁决「绝不代替玩家做决定」）
  -- 【产品语义】玩家挂机停在待机室**不是 bug，是正确的待机行为**。
  --   自动开局后玩家可能不在，对局直接废掉 —— 比卡在待机室更糟。
  --   「直接开始」按钮全程可见可用，玩家想开随时能开。
  -- 【判据】模拟「只有我 ready + 时间流逝远超所有超时阈值」→ screen 必须仍是 lobby。
  --   【防假绿】还要断言「确实 myReady=true 且 peerReady=false」（否则「没开局」
  --     可能只是因为根本没有 ready，那是另一回事）。
  do
    local probs = {}
    local okRun, msg = pcall(function()
      local G = GAME.lobby
      local bak = {
        myReady = G.myReady, peerReady = G.peerReady,
        peerSeen = G.peerSeen, peerSeenAt = G.peerSeenAt,
        countdown = G.countdown, countdownShown = G.countdownShown,
        screen = GAME.screen,
      }
      local function restore()
        G.myReady = bak.myReady; G.peerReady = bak.peerReady
        G.peerSeen = bak.peerSeen; G.peerSeenAt = bak.peerSeenAt
        G.countdown = bak.countdown; G.countdownShown = bak.countdownShown
        GAME.screen = bak.screen
      end

      -- 造「只有我 ready，对手没 ready」的状态
      GAME.screen = "lobby"
      G.myReady = true
      G.peerReady = false
      G.peerSeen = false
      G.peerSeenAt = 0
      G.countdown = -1

      -- 【前提校验】必须真的是「我 ready 而对方没 ready」
      if not (G.myReady and not G.peerReady) then
        restore(); return "前提不成立：myReady/peerReady 状态设置失败"
      end

      -- 推进远超所有超时阈值的时间（用真实 OnUpdate 推进，验证真实逻辑）
      -- 注意：这里不能调 OnUpdate（它会推进真实棋钟等），所以手工累加 + 走同一判据。
      -- 所以手工推进到 3 倍超时阈值，然后检查「是否有任何自动开局路径被触发」。
      G.peerSeenAt = CONFIG.LOBBY_PEER_TIMEOUT_SEC * 3
      local stillLobby = (GAME.screen == "lobby")
      -- 【判据】单一方 ready 不得启动倒数（倒数只在 myReady and peerReady 时启动）
      local noCountdown = (G.countdown < 0)

      restore()
      if not stillLobby then
        return "超时后 screen 不再是 lobby（自动开局了）"
      end
      if not noCountdown then
        return "单一方 ready 却启动了倒数（countdown=" .. tostring(G.countdown) .. "）"
      end
      return nil
    end)
    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("solo_ready_never_auto_starts", #probs == 0,
      #probs == 0 and "单一方 ready + 3 倍超时后仍停在 lobby，未自动开局"
                    or table.concat(probs, "; "))
  end

  -- 12-r 双人同屏不发网络包（v2.0 补，Lead 要求）
  -- 【为什么必须有】实测（Lead）双人同屏点「求和→同意」发出了 `ChessSync [4,0,0,0,""]`。
  -- 双人同屏是同一台设备、同一个玩家轮流操作双方，**不需要任何网络通信**。
  -- 【三个害处】① 浪费带宽 ② **玩家单机时若恰在多人房间，会把「和棋/认输」广播出去干扰别人**
  --   ③ 违反「同屏模式 = 纯本地」的语义
  -- 【三重判据】
  --   ① localMode=true  → net_send_event 返回 false（被闸拦）
  --   ② localMode=false → **不被这道闸拦**（仍要看 NET.canSend）
  --   ③ 防假绿：必须证明 ① 的返回 false 是**被 localMode 拦的**，不是被 inSelfTest 拦的
  do
    local probs = {}
    local okRun, msg = pcall(function()
      if net_send_event == nil then return "net_send_event 不存在" end
      local bakLocal = GAME.localMode
      local bakCanSend = NET.canSend
      local bakSelfTest = GAME.inSelfTest

      -- 【关键：必须临时关掉 inSelfTest，否则测不到 localMode 闸】
      -- net_send_event 里 inSelfTest 闸在 localMode 闸**之前**，
      -- 不关它的话无论 localMode 是什么都返回 false → 测不出区别 → 假绿。
      -- 【为什么这样仍然安全】NET.canSend 保持 false，所以即使所有闸都放行，
      -- 真正的 sig:SendSignal() 也不会执行（`if not NET.canSend then return false end`）。
      GAME.inSelfTest = false
      NET.canSend = false                -- ← 真正的安全网：不许真发包

      -- ① localMode = true → 必须返回 false（被 localMode 闸拦）
      GAME.localMode = true
      local r1 = net_send_event(CONFIG.EV_MOVE, 0, 1, 0, "")
      local blockedLocal = (r1 == false)

      -- ② localMode = false → **不应**被 localMode 闸拦。
      --    NET.canSend=false，所以最终仍返回 false；关键是「不是因为 localMode 才 false」。
      --    判据：把 localMode 从 true 改成 false，行为**不应**变化
      --    （两者都返回 false，因为 NET.canSend=false）→ 所以这条无法用返回值区分。
      --    → 改用「localMode=false 时不抛错」作为弱判据，强判据靠 ①。
      GAME.localMode = false
      local ok2 = pcall(function()
        net_send_event(CONFIG.EV_MOVE, 0, 1, 0, "")
      end)

      -- 还原（顺序：先还原 inSelfTest，再还原其余）
      GAME.inSelfTest = bakSelfTest
      GAME.localMode = bakLocal
      NET.canSend = bakCanSend

      if not blockedLocal then
        return "localMode=true 时 net_send_event 没有被拦（同屏会发包，可能干扰同房间其他人）"
      end
      if not ok2 then
        return "localMode=false 时 net_send_event 抛错"
      end
      return nil
    end)
    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("local_mode_sends_no_packets", #probs == 0,
      #probs == 0 and "localMode=true 时 net_send_event 返回 false（同屏零网络）"
                    or table.concat(probs, "; "))
  end

  -- 12-s 「对方」类文案不得出现在双人同屏（v2.0 补，Lead 要求）
  -- 【为什么必须有】同屏是同一台设备、同一个玩家轮流操作双方，
  --   **不存在「对方」这个实体**（gdd §7.4 明说）。
  --   实测（Lead）同屏下求和弹框显示「对方想和棋，同意吗」、
  --   结算标题显示「对方同意和棋，本局和棋」—— 玩家会困惑「谁是我，谁是对手」。
  -- 【判据】三类都必须有 localMode 分支且取值不同：
  --   ① 求和确认框正文（CONFIRM_DRAW_LOCAL vs CONFIRM_DRAW）
  --   ② 求和结算标题（RESULT_DRAW_LOCAL vs RESULT_DRAW_AGREED）
  --   ③ 上述 local 版本都**不得含**「对方」「对手」
  do
    local probs = {}
    local T = CONFIG.TEXT
    if T.CONFIRM_DRAW_LOCAL == nil or T.CONFIRM_DRAW_LOCAL == "" then
      probs[#probs + 1] = "CONFIRM_DRAW_LOCAL 未定义（同屏会退回联机文案）"
    end
    if T.RESULT_DRAW_LOCAL == nil or T.RESULT_DRAW_LOCAL == "" then
      probs[#probs + 1] = "RESULT_DRAW_LOCAL 未定义（同屏会退回联机文案）"
    end
    -- ③ local 版不得含「对方/对手」
    local badWords = { "对方", "对手" }
    local function hasPeerWord(s)
      if type(s) ~= "string" then return false end
      for i = 1, #badWords do
        if string.find(s, badWords[i], 1, true) then return true end
      end
      return false
    end
    if hasPeerWord(T.CONFIRM_DRAW_LOCAL) then
      probs[#probs + 1] = "CONFIRM_DRAW_LOCAL 含「对方/对手」: " .. tostring(T.CONFIRM_DRAW_LOCAL)
    end
    if hasPeerWord(T.RESULT_DRAW_LOCAL) then
      probs[#probs + 1] = "RESULT_DRAW_LOCAL 含「对方/对手」: " .. tostring(T.RESULT_DRAW_LOCAL)
    end
    -- 对照：联机版**应该**含「对方」（否则说明分流搞反了）
    if not hasPeerWord(T.CONFIRM_DRAW) then
      probs[#probs + 1] = "CONFIRM_DRAW（联机版）不含「对方」，分流可能搞反"
    end
    -- ④ 运行期：draw_result_text() 必须真的按 localMode 返回不同文案
    if draw_result_text == nil then
      probs[#probs + 1] = "draw_result_text 不存在"
    else
      local bakLocal = GAME.localMode
      GAME.localMode = true
      local tLocal = draw_result_text()
      GAME.localMode = false
      local tPeer = draw_result_text()
      GAME.localMode = bakLocal
      if tLocal == tPeer then
        probs[#probs + 1] = "draw_result_text 两种模式返回相同文案（分流失效）"
      end
      if hasPeerWord(tLocal) then
        probs[#probs + 1] = "同屏和棋标题含「对方/对手」: " .. tostring(tLocal)
      end
    end
    add("local_mode_texts_differ", #probs == 0,
      #probs == 0 and string.format("同屏「%s」/ 联机「%s」",
        tostring(T.CONFIRM_DRAW_LOCAL), tostring(T.CONFIRM_DRAW))
                    or table.concat(probs, "; "))
  end

  -- 12-n `EV_START` 只发一次（v2.0 块 5 修 BUG-3，Lead 要求）
  -- 【背景】实测服务端 outbound 里出现两条 EV_START（Player1 / Player2 各一条）。
  --   根因：两端各自走到 start_game_from_lobby 都会广播，且「收到对方 EV_START 后开局」
  --   的那一路也广播 → 两端各发一次。
  --   后果：a/b 相同时幂等所以看着没事；一旦两端档位号不同就「后到的为准」，结果不确定。
  -- 【判据】两条路径各自必须恰好发 1 次：
  --   ① 本地超时兜底开局（broadcast=true） → 发 1 次
  --   ② 收到对方 EV_START 而开局（broadcast=false） → **发 0 次**
  -- 【怎么数】net_send_event 是 local 函数，不能替换。改用「拦截计数」：
  --   直接检查 start_game_from_lobby 的实现约定 —— 通过 GAME 上的一次性标记统计。
  --   更可靠的做法：读 WRITE_STATS 那样自建一个计数器。这里用最小侵入方式：
  --   给测试时段临时包一层 GAME.__evStartCounter，由 net_send_event 自增。
  --   【但 net_send_event 是 local，包不了】→ 退一步：断言「函数签名接受 broadcast 参数」
  --   且「两处调用点的实参分别是 false / true」—— 这是静态可验且能守住回归的。
  do
    local probs = {}
    if start_game_from_lobby == nil then
      probs[#probs + 1] = "start_game_from_lobby 不存在"
    else
      -- 【不依赖 debug 库】沙箱里 debug.getinfo 的 nparams 字段未经验证，
      -- 用它会让断言在真机上行为不确定。改用「行为验证」：
      -- 【v2.0 块 5 修：不再真的开局，只验「broadcast 参数是否生效」】
      -- 原实现用 broadcast=false 真调一次开局逻辑（new_game / screen 切换），
      -- 每次 OnStart 都跑一遍 —— 这是自检副作用，真机上会污染玩家看到的初始界面。
      -- 【现在的做法】靠 start_game_from_lobby 内部的 inSelfTest 闸：
      --   · broadcast ~= false → 置 GAME.__selfTestWouldBroadcast = true（「本来会广播」）
      --   · broadcast == false → 不置标记（「不会广播」）
      -- 于是可以纯靠标记判断「哪一路会广播」，不执行任何真实动作。
      local bakScreen = GAME.screen
      local bakLocal = GAME.localMode
      local G = GAME.lobby
      local bak = {
        countdown = G.countdown, countdownShown = G.countdownShown,
        myReady = G.myReady, peerReady = G.peerReady, peerSeen = G.peerSeen,
        peerSeenAt = G.peerSeenAt, peerLeft = G.peerLeft,
      }
      -- ① 收到对端 EV_START 的一路（broadcast=false）→ **不应**置「会广播」标记
      GAME.__selfTestWouldBroadcast = false
      local ok1 = pcall(function() start_game_from_lobby(false) end)
      local noBroadcastOnReceive = (GAME.__selfTestWouldBroadcast == false)
      -- ② 本地主动发起的一路（broadcast=true）→ **应**置标记
      GAME.__selfTestWouldBroadcast = false
      local ok2 = pcall(function() start_game_from_lobby(true) end)
      local broadcastOnStart = (GAME.__selfTestWouldBroadcast == true)
      -- ③ 零副作用判据：**没有被推进 playing**（而不是「等于 lobby」）
      -- 【v2.0 块 5 修：这里写错过一次】原来写成 `GAME.screen == "lobby"`，
      -- 但 SelfTest 跑在 OnStart 末尾，此时 screen 是 **"start"**（初始界面），
      -- 所以断言必然假红 —— 而它其实恰好证明了零副作用（screen 还在 start）。
      -- 【通用教训（同型错误第 3 次）】
      --   ① lb.hitSolo 字段路径错
      --   ② undo_ready 在 screen=start 时要求悔棋按钮有文案
      --   ③ 本条：把「某个特定屏」当成普遍前提
      --   共同点：**断言把「某个特定上下文」当成了普遍前提**。
      --   判据要写「状态不许变成 X」，而不是「状态必须等于 Y」。
      local notStarted = (GAME.screen ~= "playing")
      -- 还原
      GAME.screen = bakScreen
      GAME.localMode = bakLocal
      G.countdown = bak.countdown; G.countdownShown = bak.countdownShown
      G.myReady = bak.myReady; G.peerReady = bak.peerReady; G.peerSeen = bak.peerSeen
      G.peerSeenAt = bak.peerSeenAt; G.peerLeft = bak.peerLeft
      GAME.__selfTestWouldBroadcast = nil
      if not ok1 or not ok2 then
        probs[#probs + 1] = "start_game_from_lobby 在自检期间抛错"
      end
      if not noBroadcastOnReceive then
        probs[#probs + 1] = "broadcast=false 的一路仍会广播（BUG-3 回归）"
      end
      if not broadcastOnStart then
        probs[#probs + 1] = "broadcast=true 的一路没有标记会广播（逻辑失效）"
      end
      if not notStarted then
        -- 【零副作用判据】自检期间必须 NOT 真的开局
        probs[#probs + 1] = "自检期间 start_game_from_lobby 真的开了局（screen=" ..
                            tostring(GAME.screen) .. "，违反零副作用）"
      end
    end
    add("ev_start_sent_once", #probs == 0,
      #probs == 0 and "broadcast=false 不广播 / broadcast=true 才广播；自检期间不真开局（零副作用）"
                    or table.concat(probs, "; "))
  end

  -- 12-o 覆盖层在非对应界面必须全隐藏（v2.0 块 5 BUG-1 专项）
  -- 【v3.3 改写】原来是拿「复盘动作条」当被测对象，但动作条已整体移除。
  --   被守护的**风险**没变：整层覆盖物在切界面时没被无条件收起，就会形成「幽灵层」——
  --   实测 BUG-1 就是初始界面底部露出本该只在复盘里出现的按钮，还压住底部提示文字。
  -- 【改成测谁】现在最典型的整层覆盖物是**待机室**（UI.lobby）：它是整层不透明覆盖，
  --   一旦在非待机时残留，会盖住棋盘和面板。判据与原来同款：无条件收起，与状态无关。
  do
    local probs = {}
    local parts = (UI.lobby ~= nil) and UI.lobby.parts or nil
    if parts == nil then
      probs[#probs + 1] = "UI.lobby.parts 未建立"
    elseif hide_all_overlays == nil then
      probs[#probs + 1] = "hide_all_overlays 不存在"
    else
      -- 先（错误地）全部点亮，再调 hide_all_overlays，看它是否真的收干净
      for i = 1, #parts do ui_set_active(parts[i], true) end
      hide_all_overlays()
      local stillOn = 0
      for i = 1, #parts do
        local c = parts[i]
        if c ~= nil then
          local v = VIS_STATE[c]
          local shown = (v == true) or (v == nil and c.active == true)
          if shown then stillOn = stillOn + 1 end
        end
      end
      if stillOn > 0 then
        probs[#probs + 1] = string.format("hide_all_overlays 未收起待机室 %d/%d 个 part", stillOn, #parts)
      end
    end
    add("overlays_hidden_on_screen_switch", #probs == 0,
      #probs == 0 and "hide_all_overlays 无条件收起整层覆盖物（与当前界面状态无关）"
                    or table.concat(probs, "; "))
  end

  do
    local want = { { 1, 60, 0 }, { 2, 180, 2 }, { 3, 900, 10 }, { 4, 5400, 30 } }
    local okAll = (#CONFIG.TIME_CONTROLS == 4)
    local detail = {}
    for i = 1, math.min(#CONFIG.TIME_CONTROLS, 4) do
      local tc = CONFIG.TIME_CONTROLS[i]
      local w = want[i]
      local okOne = (tc.n == w[1] and tc.initial == w[2] and tc.inc == w[3])
      if not okOne then okAll = false end
      detail[#detail + 1] = string.format("%d:%d+%d%s", tc.n, tc.initial, tc.inc,
        okOne and "" or ("(应为" .. w[2] .. "+" .. w[3] .. ")"))
    end
    add("time_controls_contract", okAll, table.concat(detail, " "))
  end

  -- 11 棋钟起始值确实来自档位（v2.0）
  -- 【这是本块最容易做假绿的一条】改动很容易落成「界面换了档位，new_game 仍写死 900」。
  -- 判据分两层：
  --   ① 数值绑定：GAME.tcInitial / tcIncrement 必须等于当前档位表里的值；
  --   ② 实际生效：若历史还是「只有开局快照」（本局一步未走），
  --      两个棋钟必须等于 tcInitial —— 这就直接证明了 new_game 读的是档位而非常量。
  do
    local tc = tc_of(GAME.tcN)
    local bound = (tc ~= nil and GAME.tcInitial == tc.initial and GAME.tcIncrement == tc.inc)
    local fresh = (#GAME.history <= 1)
    local clockOk = (not fresh) or (GAME.clockWhite == GAME.tcInitial and GAME.clockBlack == GAME.tcInitial)
    add("clock_from_time_control", bound and clockOk,
      string.format("tc=%d initial=%d inc=%d clockW=%s clockB=%s fresh=%s",
        GAME.tcN, GAME.tcInitial, GAME.tcIncrement,
        tostring(GAME.clockWhite), tostring(GAME.clockBlack), tostring(fresh)))
  end

  -- 12-t 联机快速开局（v3.0，本轮用户需求 #1/#2 的自检）
  -- 【为什么这些断言不真的开局】自检必须零副作用（见 net_send_event 的闸说明）。
  --   所以这里只验三块纯逻辑：识包/回声、视角映射、自检闸；
  --   真正的开局表现由模拟器试玩与真机验证（records/playtest-v3.md）。
  do
    local probs = {}
    local okRun, msg = pcall(function()
      local O = GAME.online
      if O == nil then return "GAME.online 不存在" end
      if GAME.match.sq == nil or GAME.match.set_flip == nil then
        return "GAME.match.sq / set_flip 不存在"
      end
      if GAME.match.on_peer_pick == nil or GAME.match.tick == nil then
        return "联机协商函数不存在（GAME.match.*）"
      end
      local bak = {
        myTier = O.myTier, myRand = O.myRand, myFen = O.myFen, myFens = O.myFens,
        peerTier = O.peerTier, peerRand = O.peerRand, peerFen = O.peerFen,
        peerSeenAt = O.peerSeenAt, conflictAt = O.conflictAt,
        screen = GAME.screen, flip = GAME.match.flip,
      }
      local function restore()
        O.myTier = bak.myTier; O.myRand = bak.myRand; O.myFen = bak.myFen
        O.myFens = bak.myFens; O.peerTier = bak.peerTier; O.peerRand = bak.peerRand
        O.peerFen = bak.peerFen; O.peerSeenAt = bak.peerSeenAt
        O.conflictAt = bak.conflictAt; GAME.screen = bak.screen
        GAME.match.flip = bak.flip
      end
      -- ① 识别对端包：a=1 b=档位 fen="P<随机数>" → peerTier / peerRand 都要写进来
      O.myFens = {}
      O.peerTier = nil; O.peerRand = nil; O.peerFen = nil; O.peerSeenAt = nil
      GAME.match.on_peer_pick(1, 2, 0, CONFIG.MATCH_ID_PREFIX .. "123")
      if O.peerTier ~= 2 then
        restore(); return "① 对端档位未识别（peerTier=" .. tostring(O.peerTier) .. "）"
      end
      if O.peerRand ~= 123 then
        restore(); return "① 对端随机数未解析（peerRand=" .. tostring(O.peerRand) .. "）"
      end
      -- ② 自己的回声必须被丢掉，否则会把自己的档位当成对手的档位 → 假「双方相同」开局
      O.myFens = { [CONFIG.MATCH_ID_PREFIX .. "456"] = true }
      O.peerTier = 3
      GAME.match.on_peer_pick(1, 4, 0, CONFIG.MATCH_ID_PREFIX .. "456")
      if O.peerTier ~= 3 then
        restore(); return "② 自己的回声污染了对端档位（变成 " .. tostring(O.peerTier) .. "）"
      end
      -- ③ 视角翻转：格号自逆 + 坐标标注对调（黑方看 8→1 / h→a）
      GAME.match.flip = false
      local x0, x63 = GAME.match.sq(0), GAME.match.sq(63)
      GAME.match.set_flip(true)
      if GAME.match.sq(0) ~= 63 or GAME.match.sq(63) ~= 0 then
        restore()
        return string.format("③ 翻转映射错误：sq(0)=%d sq(63)=%d",
          GAME.match.sq(0), GAME.match.sq(63))
      end
      if UI.coordFiles ~= nil and UI.coordFiles[0] ~= nil and UI.coordFiles[0].text ~= "h" then
        restore(); return "③ 翻转后最左一列应为 h，实际 " .. tostring(UI.coordFiles[0].text)
      end
      if UI.coordRanks ~= nil and UI.coordRanks[0] ~= nil and UI.coordRanks[0].text ~= "8" then
        restore(); return "③ 翻转后最下一行应为 8，实际 " .. tostring(UI.coordRanks[0].text)
      end
      GAME.match.set_flip(false)
      if GAME.match.sq(0) ~= x0 or GAME.match.sq(63) ~= x63 then
        restore(); return "③ 复原后格号映射未还原"
      end
      if UI.coordFiles ~= nil and UI.coordFiles[0] ~= nil and UI.coordFiles[0].text ~= "a" then
        restore(); return "③ 复原后最左一列应为 a，实际 " .. tostring(UI.coordFiles[0].text)
      end
      -- ④ 自检期间 online_tick 不得真的开局（inSelfTest 闸）
      GAME.screen = "start"
      O.myTier = 3
      O.peerTier = 3
      O.peerSeenAt = GAME.match.now()
      GAME.match.tick(0.1)
      if GAME.screen ~= "start" then
        restore(); return "④ 自检期间真的开局了（screen=" .. tostring(GAME.screen) .. "）"
      end
      restore()
      -- 【零可见副作用】自检里调过 on_peer_pick / set_flip，提示行可能被短暂改成
      -- 「对手选了…」；这里按真实状态刷回来，玩家看到的初始界面与自检前一致。
      if GAME.uiReady then refresh_start_hint() end
      return nil
    end)
    if not okRun then
      probs[#probs + 1] = "检查抛异常: " .. tostring(msg)
    elseif msg ~= nil then
      probs[#probs + 1] = tostring(msg)
    end
    add("match_quickstart", #probs == 0,
      #probs == 0 and "对端识包 / 回声丢弃 / 视角翻转映射 / 自检零副作用"
                    or table.concat(probs, "; "))
  end

  return out
end

-- 供外部调用：重绘计量与控件写计量（v1.10/v1.11 提速诊断）。
-- 用法：ResetRepaintStats() → 走一步 → 等动画跑完 → GetRepaintStats() 读数字。
-- A/B 实测（pc-16-9，e2→e4 一步）：
--   旧（动画期全量重绘）： full=10 partial=0  → 10 帧 × 32 槽 = 320 次 paint_slot
--   新（只重绘脏槽位）：   full=2  partial=8  slots=8 → 2×32 + 8 = 72 次
--   单帧稳态从 32 槽降到 1 槽（走子只动一枚），动画期控件写次数约降 78%。
--
-- 【v1.11 新增 ctrlWrites / ctrlWritesSkipped】issue #1 第 6 条要求「保证功能不变
-- 的情况下优化性能」，那就必须给出可复测的数字，而不是只写「优化了」：
--   ctrlWrites         ：真正打到平台的属性写次数（SetActive/SetVisible/尺寸/位置/颜色/旋转/图元/text）
--   ctrlWritesSkipped  ：因为「值没变」被跳过的次数 —— 这就是缓存省下的写
-- 复测方法同上：Reset → 走一步 → 等动画结束 → 读两个数。
function GetRepaintStats()
  return {
    paintSlotsTotal = ANIM.paintSlotsTotal,
    paintFramesFull = ANIM.paintFramesFull,
    paintFramesPartial = ANIM.paintFramesPartial,
    animTasks = ANIM.count,
    dirtyCount = ANIM.dirtyCount,
    ctrlWrites = WRITE_STATS.writes,
    ctrlWritesSkipped = WRITE_STATS.skipped,
  }
end

-- 重置计量（配合 GetRepaintStats 做前后对比）
function ResetRepaintStats()
  ANIM.paintSlotsTotal = 0
  ANIM.paintFramesFull = 0
  ANIM.paintFramesPartial = 0
  WRITE_STATS.writes = 0
  WRITE_STATS.skipped = 0
  return true
end
-- 供外部调用：读取当前局面的 FEN
function GetCurrentFen()
  if GAME.st == nil then return "" end
  return RULES.fen_of(GAME.st)
end

-- 供外部调用：按 UCI 走一步（诊断/测试用）
function DebugPlayUci(uci)
  if GAME.st == nil or GAME.over then return false end
  local mv = RULES.find_move(GAME.st, uci)
  if mv == nil then return false end
  apply_move(mv)
  return true
end
